window.TRANSCRIPTS = {"knowledge-tracing-bkt-dkt":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.04,"end":2.194,"text":"Every right or wrong answer is a clue"},{"start":2.194,"end":3.725,"text":"about what a learner knows."},{"start":4.065,"end":6.503,"text":"Knowledge tracing turns those clues into a"},{"start":6.503,"end":7.467,"text":"running estimate."},{"start":7.807,"end":10.188,"text":"This video goes from the classic Bayesian"},{"start":10.188,"end":12.513,"text":"model to deep learning, and the debate"},{"start":12.513,"end":13.25,"text":"between them."},{"start":15.15,"end":17.264,"text":"A tutor sees a stream of answers for one"},{"start":17.264,"end":17.574,"text":"skill."},{"start":17.883,"end":19.894,"text":"It has to guess what the learner knows"},{"start":19.894,"end":22.111,"text":"now, and whether the next answer will be"},{"start":22.111,"end":22.421,"text":"right."},{"start":25.9,"end":28.709,"text":"Knowledge tracing, from Albert Corbett and"},{"start":28.709,"end":30.831,"text":"John Anderson in the mid nineteen"},{"start":30.831,"end":33.328,"text":"nineties, now usually called Bayesian"},{"start":33.328,"end":36.074,"text":"knowledge tracing, treats each skill as a"},{"start":36.074,"end":38.945,"text":"hidden switch: known, or not yet known."},{"start":39.77,"end":42.05,"text":"At each practice opportunity, an unknown"},{"start":42.05,"end":44.33,"text":"skill can switch to known with probability"},{"start":44.33,"end":44.701,"text":"P of T."},{"start":45.02,"end":47.247,"text":"In the classic model, it never switches"},{"start":47.247,"end":47.512,"text":"back."},{"start":48.32,"end":50.732,"text":"We never see the switch, only answers."},{"start":51.094,"end":53.626,"text":"A learner who does not know the skill can"},{"start":53.626,"end":56.219,"text":"still guess right, with probability P of"},{"start":56.219,"end":56.339,"text":"G."},{"start":56.701,"end":59.113,"text":"One who knows it can still slip, with"},{"start":59.113,"end":60.258,"text":"probability P of S."},{"start":61.17,"end":63.194,"text":"Add the chance the skill was already known"},{"start":63.194,"end":65.265,"text":"at the start, P of L zero, and you have"},{"start":65.265,"end":66.348,"text":"four numbers per skill."},{"start":68.22,"end":70.398,"text":"Let's run one update by hand, with a"},{"start":70.398,"end":72.13,"text":"starting belief of point three."},{"start":72.465,"end":74.923,"text":"The first answer is wrong, so Bayes' rule"},{"start":74.923,"end":77.04599999999999,"text":"lowers the belief to about point zero"},{"start":77.04599999999999,"end":77.325,"text":"five."},{"start":79.21000000000001,"end":81.431,"text":"Then the model adds a chance to learn from"},{"start":81.431,"end":83.496,"text":"the practice itself, which brings the"},{"start":83.496,"end":85.51,"text":"belief back up to about point one nine."},{"start":87.38,"end":89.797,"text":"Over eight answers the belief rises and"},{"start":89.797,"end":92.637,"text":"falls: each mistake pulls it down, each"},{"start":92.637,"end":94.87299999999999,"text":"success pushes it up, and a run of"},{"start":94.87299999999999,"end":96.92699999999999,"text":"successes carries it close to one."},{"start":97.81,"end":100.219,"text":"If a tutor sets a mastery threshold, say"},{"start":100.219,"end":102.51599999999999,"text":"point nine five, it can decide when to"},{"start":102.51599999999999,"end":102.964,"text":"move on."},{"start":104.9,"end":106.868,"text":"The big strength of this model is that"},{"start":106.868,"end":108.987,"text":"every number means something to a teacher."},{"start":109.28999999999999,"end":111.207,"text":"A low learning rate says the skill is"},{"start":111.207,"end":111.964,"text":"learned slowly."},{"start":112.267,"end":114.285,"text":"A high guess rate says right answers on"},{"start":114.285,"end":115.64699999999999,"text":"that skill tell you little."},{"start":117.56700000000001,"end":119.765,"text":"In two thousand fifteen, Chris Piech and"},{"start":119.765,"end":121.708,"text":"colleagues replaced the switch with a"},{"start":121.708,"end":122.986,"text":"recurrent neural network."},{"start":123.292,"end":125.286,"text":"Deep knowledge tracing reads the whole"},{"start":125.286,"end":126.82,"text":"sequence of items and answers."},{"start":127.67699999999999,"end":129.888,"text":"At each step it outputs the chance of"},{"start":129.888,"end":131.983,"text":"answering every item correctly next."},{"start":132.332,"end":134.834,"text":"No expert has to say which skill each item"},{"start":134.834,"end":135.358,"text":"measures."},{"start":137.347,"end":140.005,"text":"The paper reported a striking result: on"},{"start":140.005,"end":142.663,"text":"one benchmark, an AUC of point eight six,"},{"start":142.663,"end":144.743,"text":"against point six nine for the best"},{"start":144.743,"end":145.61,"text":"earlier result."},{"start":147.61,"end":149.694,"text":"Within a year, two papers took a closer"},{"start":149.694,"end":149.942,"text":"look."},{"start":151.94,"end":154.547,"text":"Xiaolu Xiong and colleagues found that"},{"start":154.547,"end":157.155,"text":"nearly a quarter of the benchmark rows"},{"start":157.155,"end":160.297,"text":"were duplicates, and that on cleaned data,"},{"start":160.297,"end":163.305,"text":"deep knowledge tracing still beat BKT, but"},{"start":163.305,"end":166.046,"text":"held no overall edge over another simple"},{"start":166.046,"end":167.049,"text":"model, P F A."},{"start":167.92000000000002,"end":170.06,"text":"Mohammad Khajah and colleagues extended"},{"start":170.06,"end":171.772,"text":"Bayesian knowledge tracing with"},{"start":171.772,"end":174.072,"text":"forgetting, student ability, and skill"},{"start":174.072,"end":176.211,"text":"discovery, and its performance became"},{"start":176.211,"end":178.405,"text":"indistinguishable from the deep model,"},{"start":178.405,"end":180.491,"text":"suggesting the deep model's gains came"},{"start":180.491,"end":182.791,"text":"from patterns that simpler models can also"},{"start":182.791,"end":183.219,"text":"capture."},{"start":185.133,"end":187.8,"text":"We ran our own small test: six hundred"},{"start":187.8,"end":189.981,"text":"simulated students practicing three"},{"start":189.981,"end":192.648,"text":"fraction skills, with a hidden dependency"},{"start":192.648,"end":193.86,"text":"between two of them."},{"start":194.743,"end":197.402,"text":"On the held out students, BKT reached an"},{"start":197.402,"end":200.185,"text":"AUC of point eight zero nine, and the deep"},{"start":200.185,"end":201.978,"text":"model point eight zero seven."},{"start":202.349,"end":205.008,"text":"In this one small simulation, the simple"},{"start":205.008,"end":206.492,"text":"model did about as well."},{"start":208.327,"end":211.369,"text":"Later models use attention, such as SAKT"},{"start":211.369,"end":211.935,"text":"and AKT."},{"start":212.36,"end":215.332,"text":"But the core trade off remains: deep"},{"start":215.332,"end":218.233,"text":"models can predict well on large data,"},{"start":218.233,"end":220.992,"text":"while BKT's numbers tell a teacher why."},{"start":221.877,"end":224.54,"text":"So choose a learner model by the decision"},{"start":224.54,"end":227.076,"text":"it needs to support, not by AUC alone."},{"start":229.077,"end":231.24099999999999,"text":"For the discussion board, pick one"},{"start":231.24099999999999,"end":233.698,"text":"tutoring decision, such as moving on or"},{"start":233.698,"end":236.038,"text":"alerting a teacher, and explain which"},{"start":236.038,"end":238.612,"text":"learner model you would trust for it, and"},{"start":238.612,"end":238.846,"text":"why."}]},"iEc8Dt3ePWo":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.11,"end":2.538,"text":"When a learning game adapts to a player,"},{"start":2.538,"end":5.136,"text":"it can change two very different things:"},{"start":5.136,"end":7.791,"text":"what happens right now, inside a level, or"},{"start":7.791,"end":9.711,"text":"what comes next, between levels."},{"start":10.05,"end":11.631,"text":"This video compares the two."},{"start":13.587,"end":15.914,"text":"Back in Launch Lab, player B has missed"},{"start":15.914,"end":18.075,"text":"the target three times in a row on the"},{"start":18.075,"end":18.684,"text":"same level."},{"start":20.547,"end":22.37,"text":"A game could respond in two ways."},{"start":22.702,"end":25.023,"text":"It could step in now with a hint, or it"},{"start":25.023,"end":27.289,"text":"could send player B to a different level"},{"start":27.289,"end":27.565,"text":"next."},{"start":32.767,"end":34.904,"text":"Both are adaptation, but they work on"},{"start":34.904,"end":36.935,"text":"different timescales, use different"},{"start":36.935,"end":38.966,"text":"evidence, and carry different risks."},{"start":41.087,"end":43.847,"text":"Micro adaptation happens inside a task,"},{"start":43.847,"end":47.067,"text":"from moment to moment: hints, feedback,"},{"start":47.067,"end":49.761,"text":"small changes to pacing or difficulty,"},{"start":49.761,"end":51.732,"text":"even how a character responds."},{"start":52.547,"end":54.947,"text":"Michael Kickmeier-Rust and Dietrich Albert"},{"start":54.947,"end":57.236,"text":"argued that in games, micro adaptivity"},{"start":57.236,"end":59.525,"text":"should be subtle, so that help arrives"},{"start":59.525,"end":61.032,"text":"without breaking immersion."},{"start":62.877,"end":65.583,"text":"Macro adaptation happens between tasks:"},{"start":65.583,"end":67.929,"text":"which level comes next, which path a"},{"start":67.929,"end":70.515,"text":"learner takes, and how fast the sequence"},{"start":70.515,"end":70.876,"text":"moves."},{"start":72.857,"end":74.491,"text":"The idea is older than games."},{"start":74.82900000000001,"end":77.252,"text":"Ok-Choon Park and Jung Lee described macro"},{"start":77.252,"end":79.674,"text":"adaptive instruction, which fits a whole"},{"start":79.674,"end":82.09700000000001,"text":"program to what we know about a learner,"},{"start":82.09700000000001,"end":84.351,"text":"and micro adaptive instruction, which"},{"start":84.351,"end":86.549,"text":"diagnoses needs during learning itself."},{"start":88.34700000000001,"end":90.857,"text":"Kurt VanLehn gave the same split a name in"},{"start":90.857,"end":93.542,"text":"tutoring systems: an inner loop for each"},{"start":93.542,"end":95.876,"text":"step, and an outer loop for each task."},{"start":97.91,"end":100.563,"text":"Micro adaptation acts in seconds, using"},{"start":100.563,"end":102.142,"text":"what the player just did."},{"start":102.521,"end":105.301,"text":"Macro adaptation acts over minutes, using"},{"start":105.301,"end":107.701,"text":"a learner model built from many tasks."},{"start":108.61,"end":111.59,"text":"Micro changes hints, feedback, and local"},{"start":111.59,"end":114.107,"text":"difficulty, while macro changes the"},{"start":114.107,"end":116.82300000000001,"text":"sequence, the level, and the content."},{"start":118.08,"end":119.532,"text":"Each one has its own risk."},{"start":119.86699999999999,"end":122.212,"text":"Micro help that comes too often can break"},{"start":122.212,"end":124.725,"text":"flow, or let players lean on hints instead"},{"start":124.725,"end":125.395,"text":"of thinking."},{"start":126.31,"end":128.66,"text":"Macro decisions can send a player down the"},{"start":128.66,"end":131.23,"text":"wrong path, and they react slowly, because"},{"start":131.23,"end":133.252,"text":"they wait for evidence to accumulate."},{"start":135.117,"end":137.588,"text":"To see how the two loops interact, we"},{"start":137.588,"end":140.122,"text":"simulated two thousand players in Launch"},{"start":140.122,"end":143.15,"text":"Lab under four designs: a fixed sequence,"},{"start":143.15,"end":145.436,"text":"macro only, micro only, and both."},{"start":147.447,"end":150.018,"text":"The rules are simple and stated up front:"},{"start":150.018,"end":152.317,"text":"players learn most when success is likely"},{"start":152.317,"end":154.67000000000002,"text":"but not certain, hints help them succeed"},{"start":154.67000000000002,"end":157.077,"text":"but teach a little less, and three misses"},{"start":157.077,"end":158.828,"text":"in a row can make a player quit."},{"start":165.007,"end":167.476,"text":"With a fixed sequence, fifty eight percent"},{"start":167.476,"end":169.835,"text":"of players quit early, and almost all of"},{"start":169.835,"end":171.097,"text":"the weakest third quit."},{"start":171.947,"end":174.28,"text":"Hints alone barely help: forty seven"},{"start":174.28,"end":176.724,"text":"percent still quit, because a hint cannot"},{"start":176.724,"end":178.723,"text":"rescue a level that is far too hard."},{"start":179.527,"end":182.181,"text":"Choosing the next level well matters more:"},{"start":182.181,"end":184.448,"text":"macro adaptation cuts quitting to twenty"},{"start":184.448,"end":186.66,"text":"one percent, and combining both loops"},{"start":186.66,"end":188.595,"text":"brings it down to fourteen percent."},{"start":190.627,"end":192.034,"text":"There is a catch, though."},{"start":192.346,"end":194.431,"text":"Under macro adaptation, the strongest"},{"start":194.431,"end":196.568,"text":"players learned less than with the fixed"},{"start":196.568,"end":198.548,"text":"sequence, because the learner model"},{"start":198.548,"end":200.789,"text":"started at average and took several levels"},{"start":200.789,"end":201.414,"text":"to catch up."},{"start":205.3,"end":207.449,"text":"The game Reboot Seoul twenty fifty uses"},{"start":207.449,"end":209.222,"text":"both loops in its drone missions."},{"start":209.544,"end":211.801,"text":"The macro loop moves players through five"},{"start":211.801,"end":214.003,"text":"tiers, from small grids to larger ones"},{"start":214.003,"end":215.508,"text":"with tighter command limits."},{"start":216.45,"end":218.373,"text":"The micro loop watches for repeated"},{"start":218.373,"end":220.563,"text":"trouble inside a mission and offers help"},{"start":220.563,"end":223.02,"text":"in steps: first an explanation, then a"},{"start":223.02,"end":224.195,"text":"map, then more time."},{"start":224.515,"end":226.70499999999998,"text":"Support fades once a player clears a new"},{"start":226.70499999999998,"end":227.4,"text":"tier cleanly."},{"start":229.24,"end":231.531,"text":"So when you design adaptivity for a"},{"start":231.531,"end":234.204,"text":"learning game, decide what each loop is"},{"start":234.204,"end":237.131,"text":"for: micro to keep a player productively"},{"start":237.131,"end":239.93200000000002,"text":"engaged in this task, and macro to choose"},{"start":239.93200000000002,"end":241.968,"text":"the task that teaches most next."},{"start":242.97,"end":245.516,"text":"Then check three things: does the help"},{"start":245.516,"end":248.061,"text":"protect immersion, does the learner model"},{"start":248.061,"end":250.607,"text":"have enough evidence, and can the learner"},{"start":250.607,"end":253.152,"text":"see or choose the change, which Jan Plass"},{"start":253.152,"end":255.293,"text":"and Shashank Pawar call adaptability."},{"start":257.257,"end":259.516,"text":"For the discussion board, think of a game"},{"start":259.516,"end":261.723,"text":"you know and find one micro adaptation and"},{"start":261.723,"end":263.11,"text":"one macro adaptation in it."},{"start":263.418,"end":265.677,"text":"Then ask what evidence each one uses, and"},{"start":265.677,"end":267.731,"text":"what would happen if that evidence were"},{"start":267.731,"end":268.039,"text":"wrong."}]},"aADMw1NjWKU":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.12,"end":2.351,"text":"Why do children spend hours on some games,"},{"start":2.351,"end":3.441,"text":"and minutes on others?"},{"start":3.739,"end":5.821,"text":"In nineteen eighty, Thomas Malone asked"},{"start":5.821,"end":7.903,"text":"that question about computer games, and"},{"start":7.903,"end":9.638,"text":"turned the answer into a theory of"},{"start":9.638,"end":11.473,"text":"intrinsically motivating instruction."},{"start":13.41,"end":15.977,"text":"Malone's Stanford dissertation was titled"},{"start":15.977,"end":17.872,"text":"What Makes Things Fun to Learn?"},{"start":18.239,"end":20.745,"text":"He studied which games children chose to"},{"start":20.745,"end":23.312,"text":"play, then built versions of games with"},{"start":23.312,"end":25.818,"text":"features added or removed, to see what"},{"start":25.818,"end":26.673,"text":"made them fun."},{"start":27.62,"end":29.842,"text":"In one study he took Darts, a fractions"},{"start":29.842,"end":32.276,"text":"game, and removed features one at a time,"},{"start":32.276,"end":34.763,"text":"such as scoring, music, and the fantasy of"},{"start":34.763,"end":36.033,"text":"arrows popping balloons."},{"start":37.04,"end":39.584,"text":"One finding stood out: boys liked the"},{"start":39.584,"end":42.188,"text":"version where arrows popped balloons, but"},{"start":42.188,"end":43.016,"text":"girls did not."},{"start":43.371,"end":45.382,"text":"The same fantasy did not motivate"},{"start":45.382,"end":45.915,"text":"everyone."},{"start":47.79,"end":50.137,"text":"In the journal Cognitive Science, in"},{"start":50.137,"end":52.785,"text":"nineteen eighty one, he organized what he"},{"start":52.785,"end":55.674,"text":"found into three ingredients: challenge,"},{"start":55.674,"end":57.179,"text":"fantasy, and curiosity."},{"start":59.043,"end":61.06,"text":"Challenge needs a goal whose outcome is"},{"start":61.06,"end":61.564,"text":"uncertain."},{"start":61.866,"end":64.135,"text":"If you are sure to win, or sure to lose,"},{"start":64.135,"end":66.101,"text":"there is little reason to keep playing."},{"start":66.813,"end":69.182,"text":"Malone listed ways to keep outcomes"},{"start":69.182,"end":72.34,"text":"uncertain: variable difficulty, goals at"},{"start":72.34,"end":75.235,"text":"several levels, hidden information, and"},{"start":75.235,"end":75.959,"text":"randomness."},{"start":77.873,"end":80.21600000000001,"text":"Fantasy places the player in an imagined"},{"start":80.21600000000001,"end":80.559,"text":"world."},{"start":80.901,"end":83.015,"text":"Malone's key distinction was between"},{"start":83.015,"end":85.301,"text":"extrinsic fantasy and intrinsic fantasy."},{"start":87.243,"end":89.332,"text":"In an extrinsic version of a fractions"},{"start":89.332,"end":91.688,"text":"game, you answer a question, and then a"},{"start":91.688,"end":93.991,"text":"cannon fires, whether or not the fantasy"},{"start":93.991,"end":95.812,"text":"has anything to do with fractions."},{"start":97.703,"end":100.051,"text":"In an intrinsic version, the fraction you"},{"start":100.051,"end":102.55799999999999,"text":"type is the aim: three quarters sends the"},{"start":102.55799999999999,"end":104.74600000000001,"text":"shot three quarters of the way, so the"},{"start":104.74600000000001,"end":106.293,"text":"fantasy depends on the skill."},{"start":107.093,"end":109.366,"text":"Malone argued that intrinsic fantasies are"},{"start":109.366,"end":111.163,"text":"usually more interesting and more"},{"start":111.163,"end":113.435,"text":"instructional, because every move in the"},{"start":113.435,"end":115.49600000000001,"text":"fantasy gives feedback about the skill."},{"start":117.363,"end":119.23400000000001,"text":"Curiosity comes in two kinds."},{"start":119.62100000000001,"end":122.265,"text":"Sensory curiosity is drawn by changes in"},{"start":122.265,"end":123.296,"text":"light and sound."},{"start":123.68299999999999,"end":126.392,"text":"Cognitive curiosity is drawn by the sense"},{"start":126.392,"end":128.714,"text":"that our knowledge is incomplete,"},{"start":128.714,"end":130.906,"text":"inconsistent, or unparsimonious."},{"start":131.713,"end":134.084,"text":"In the cannon game, a player who types two"},{"start":134.084,"end":136.35,"text":"quarters and then one half sees both shots"},{"start":136.35,"end":137.562,"text":"land in the same place."},{"start":137.878,"end":140.038,"text":"That small surprise invites the question"},{"start":140.038,"end":140.407,"text":"of why."},{"start":142.333,"end":145.552,"text":"Later, with Mark Lepper, Malone extended"},{"start":145.552,"end":148.913,"text":"the list: control, meaning choice and a"},{"start":148.913,"end":151.917,"text":"sense of power, and three interpersonal"},{"start":151.917,"end":155.636,"text":"motivations: cooperation, competition, and"},{"start":155.636,"end":156.494,"text":"recognition."},{"start":158.44299999999998,"end":160.778,"text":"Decades later, Jacob Habgood and Shaaron"},{"start":160.778,"end":163.112,"text":"Ainsworth tested a version of this idea,"},{"start":163.112,"end":165.446,"text":"which they called intrinsic integration,"},{"start":165.446,"end":167.618,"text":"with a math game called Zombie Division."},{"start":168.463,"end":170.642,"text":"Children learned more from the intrinsic"},{"start":170.642,"end":173.03300000000002,"text":"version under fixed time, and in free time"},{"start":173.03300000000002,"end":175.265,"text":"chose to play it about seven times longer."},{"start":176.173,"end":178.653,"text":"Later studies show a more mixed picture,"},{"start":178.653,"end":181.133,"text":"so treat intrinsic integration as a strong"},{"start":181.133,"end":183.267,"text":"design hypothesis, not a guarantee."},{"start":185.22,"end":187.368,"text":"When you design a learning game, check"},{"start":187.368,"end":189.621,"text":"whether the goal's outcome is uncertain,"},{"start":189.621,"end":191.926,"text":"whether the fantasy depends on the skill,"},{"start":191.926,"end":193.813,"text":"and whether feedback leaves players"},{"start":193.813,"end":194.756,"text":"curious about why."},{"start":196.73,"end":198.735,"text":"For the discussion board, pick an"},{"start":198.735,"end":201.073,"text":"educational game and classify its fantasy"},{"start":201.073,"end":202.52100000000002,"text":"as intrinsic or extrinsic."},{"start":202.855,"end":204.971,"text":"Then redesign one element so that the"},{"start":204.971,"end":206.92000000000002,"text":"fantasy depends on the skill being"},{"start":206.92000000000002,"end":207.36599999999999,"text":"learned."}]},"SfIj7mrAHwI":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.12,"end":2.577,"text":"Every learning design hides a guess about"},{"start":2.577,"end":3.805,"text":"how learning happens."},{"start":4.156,"end":6.496,"text":"A conjecture map, laid out by William"},{"start":6.496,"end":9.129,"text":"Sandoval in a two thousand fourteen paper,"},{"start":9.129,"end":11.41,"text":"puts those guesses on paper so you can"},{"start":11.41,"end":11.995,"text":"test them."},{"start":12.346,"end":14.569,"text":"This video builds one, step by step."},{"start":16.34,"end":18.413,"text":"Sandoval noticed that most writing on"},{"start":18.413,"end":20.595,"text":"design research described what it is,"},{"start":20.595,"end":23.049,"text":"rather than how to do it, and critics were"},{"start":23.049,"end":24.413,"text":"asking for clearer rigor."},{"start":25.37,"end":27.654,"text":"His premise is simple: any learning"},{"start":27.654,"end":29.882,"text":"environment already embodies hypotheses"},{"start":29.882,"end":32.388,"text":"about how learning happens, so researchers"},{"start":32.388,"end":34.56,"text":"should state them explicitly, and in"},{"start":34.56,"end":35.006,"text":"advance."},{"start":36.867,"end":39.157,"text":"The map reads from left to right: a high"},{"start":39.157,"end":40.949,"text":"level conjecture is embodied in the"},{"start":40.949,"end":43.139,"text":"design, the embodiment produces mediating"},{"start":43.139,"end":45.18,"text":"processes, and those processes produce"},{"start":45.18,"end":45.628,"text":"outcomes."},{"start":46.457,"end":48.676,"text":"Two kinds of arrows connect the boxes."},{"start":49.026,"end":51.479,"text":"Design conjectures run from embodiment to"},{"start":51.479,"end":52.064,"text":"processes."},{"start":52.414,"end":54.925,"text":"Theoretical conjectures run from processes"},{"start":54.925,"end":55.626,"text":"to outcomes."},{"start":56.567,"end":59.034,"text":"The middle box is the one Sandoval insists"},{"start":59.034,"end":59.206,"text":"on."},{"start":59.55,"end":61.788,"text":"A mediating process is what the design"},{"start":61.788,"end":64.37,"text":"should make happen in between, and you can"},{"start":64.37,"end":66.435,"text":"see it in interactions, or in the"},{"start":66.435,"end":67.812,"text":"artifacts learners make."},{"start":70.787,"end":71.638,"text":"Let's build one."},{"start":71.957,"end":74.352,"text":"Our example is Recipe Remix, a sixth grade"},{"start":74.352,"end":76.48,"text":"fractions lesson where students scale a"},{"start":76.48,"end":78.555,"text":"cookie recipe for different numbers of"},{"start":78.555,"end":78.92699999999999,"text":"guests."},{"start":80.81700000000001,"end":83.451,"text":"Step one, the high level conjecture:"},{"start":83.451,"end":85.188,"text":"students understand fraction"},{"start":85.188,"end":87.404,"text":"multiplication better when they must"},{"start":87.404,"end":89.979,"text":"justify their scaling to a peer, using a"},{"start":89.979,"end":91.29599999999999,"text":"visual representation."},{"start":91.655,"end":94.41,"text":"It is too general, by design, to tell you"},{"start":94.41,"end":95.727,"text":"exactly what to build."},{"start":96.56700000000001,"end":98.094,"text":"Step two, the embodiment."},{"start":98.434,"end":100.866,"text":"Sandoval names four kinds of element:"},{"start":100.866,"end":103.24199999999999,"text":"tools and materials, task structures,"},{"start":103.24199999999999,"end":105.562,"text":"participant structures, and discursive"},{"start":105.562,"end":106.12700000000001,"text":"practices."},{"start":107.06700000000001,"end":109.947,"text":"Here that means recipe cards and fraction"},{"start":109.947,"end":113.17,"text":"strips, scaling for six, nine, and three"},{"start":113.17,"end":115.913,"text":"guests with a proof sketch each time,"},{"start":115.913,"end":118.382,"text":"pairs with a Chef who scales and an"},{"start":118.382,"end":121.194,"text":"Auditor who must be convinced, and the"},{"start":121.194,"end":123.525,"text":"talk move, show me how you know."},{"start":124.42699999999999,"end":126.322,"text":"A design does not need all four."},{"start":126.678,"end":129.107,"text":"In Ann Brown's design work, reciprocal"},{"start":129.107,"end":131.536,"text":"teaching changed tasks and roles without"},{"start":131.536,"end":132.661,"text":"any new technology."},{"start":133.547,"end":135.724,"text":"Step three, the mediating processes."},{"start":136.068,"end":138.703,"text":"You can see them in two ways: observable"},{"start":138.703,"end":141.225,"text":"interactions, like an Auditor challenging"},{"start":141.225,"end":143.574,"text":"and a Chef justifying with strips, and"},{"start":143.574,"end":145.923,"text":"artifacts, like annotated recipe cards."},{"start":146.767,"end":149.637,"text":"Sandoval's analogy: an airplane flies only"},{"start":149.637,"end":151.191,"text":"because it generates lift."},{"start":151.55,"end":154.36,"text":"Designs, likewise, do not lead directly to"},{"start":154.36,"end":154.898,"text":"outcomes."},{"start":156.767,"end":159.435,"text":"Step four, the outcomes, as specific as"},{"start":159.435,"end":161.86,"text":"you can make them: better fraction"},{"start":161.86,"end":163.922,"text":"multiplication scores, and more"},{"start":163.922,"end":165.923,"text":"justification in written answers."},{"start":167.953,"end":170.15800000000002,"text":"Now write each arrow as a sentence."},{"start":170.536,"end":173.245,"text":"The design conjecture: if pairs scale"},{"start":173.245,"end":175.575,"text":"recipes in Chef and Auditor roles,"},{"start":175.575,"end":177.78,"text":"justification exchanges will occur."},{"start":178.15800000000002,"end":180.993,"text":"The theoretical conjecture: if students"},{"start":180.993,"end":183.639,"text":"regularly justify with representations,"},{"start":183.639,"end":185.465,"text":"their understanding improves."},{"start":186.403,"end":189.349,"text":"Each arrow needs its own evidence: video,"},{"start":189.349,"end":191.993,"text":"interaction, or artifact analysis for the"},{"start":191.993,"end":194.698,"text":"design conjecture, and outcome measures,"},{"start":194.698,"end":197.223,"text":"on top of that, for the theoretical one."},{"start":199.177,"end":201.323,"text":"Now the map meets a real classroom, and"},{"start":201.323,"end":203.01,"text":"the evidence starts to talk back."},{"start":204.977,"end":207.255,"text":"Suppose quiz scores barely move, and"},{"start":207.255,"end":209.475,"text":"classroom video shows Auditors mostly"},{"start":209.475,"end":210.176,"text":"saying okay."},{"start":215.30700000000002,"end":217.377,"text":"The design arrow failed: the design never"},{"start":217.377,"end":218.91899999999998,"text":"produced the justification process."},{"start":219.183,"end":221.077,"text":"When the outcome is missing, first check"},{"start":221.077,"end":222.927,"text":"whether the middle box happened at all,"},{"start":222.927,"end":224.777,"text":"because a failed design tells you nothing"},{"start":224.777,"end":225.702,"text":"yet about the theory."},{"start":226.55700000000002,"end":229.302,"text":"So you revise the embodiment: an Auditor"},{"start":229.302,"end":231.987,"text":"checklist, and a class norm that an answer"},{"start":231.987,"end":234.554,"text":"is not done until your Auditor can explain"},{"start":234.554,"end":234.733,"text":"it."},{"start":235.091,"end":237.359,"text":"Then you redraw the map and try again."},{"start":239.317,"end":242.314,"text":"Sandoval's own project followed the same"},{"start":242.314,"end":242.753,"text":"logic."},{"start":243.192,"end":246.262,"text":"Analyzing two teachers' classrooms showed"},{"start":246.262,"end":249.333,"text":"productive argument where talk focused on"},{"start":249.333,"end":252.404,"text":"building consensus, so his team revised"},{"start":252.404,"end":254.89,"text":"the map to design the classroom's"},{"start":254.89,"end":257.668,"text":"discursive practice, its social and"},{"start":257.668,"end":258.838,"text":"epistemic norms."},{"start":260.773,"end":263.378,"text":"Three cautions come from Sandoval himself:"},{"start":263.378,"end":265.332,"text":"read the map as a process, not as"},{"start":265.332,"end":267.665,"text":"variables; different studies can test"},{"start":267.665,"end":270.27,"text":"different arrows; and the map does not yet"},{"start":270.27,"end":271.51800000000003,"text":"represent context well."},{"start":273.497,"end":275.989,"text":"Your turn: write one high level"},{"start":275.989,"end":279.02,"text":"conjecture, fill the embodiment slots your"},{"start":279.02,"end":281.849,"text":"design uses, name one process you could"},{"start":281.849,"end":284.813,"text":"see, one outcome you could measure, and"},{"start":284.813,"end":287.642,"text":"write both arrows as if, then sentences."},{"start":289.473,"end":291.479,"text":"For the discussion board, share your map"},{"start":291.479,"end":293.252,"text":"and mark the arrow you are least sure"},{"start":293.252,"end":293.531,"text":"about."},{"start":293.811,"end":295.77,"text":"Then say what evidence would convince you"},{"start":295.77,"end":296.423,"text":"that it holds."}]},"GcsN8Ozqvec":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.12,"end":2.422,"text":"Two models come up whenever people design"},{"start":2.422,"end":4.67,"text":"motivating lessons or games: Thomas"},{"start":4.67,"end":6.479,"text":"Malone's theory of intrinsically"},{"start":6.479,"end":8.891,"text":"motivating instruction, and John Keller's"},{"start":8.891,"end":9.494,"text":"ARCS model."},{"start":9.823,"end":12.071,"text":"This video compares what each one is for."},{"start":13.92,"end":15.644,"text":"They answer different questions."},{"start":15.967,"end":18.176,"text":"Malone studied what makes computer games"},{"start":18.176,"end":20.223,"text":"fun, and turned it into a theory of"},{"start":20.223,"end":22.217,"text":"intrinsically motivating instruction."},{"start":23.16,"end":25.466,"text":"Keller asked how a designer can find and"},{"start":25.466,"end":27.828,"text":"fix a motivation problem in any course,"},{"start":27.828,"end":29.403,"text":"whether or not it is a game."},{"start":31.333,"end":34.117,"text":"Malone's theory has three ingredients:"},{"start":34.117,"end":36.964,"text":"challenge, built from goals with uncertain"},{"start":36.964,"end":39.875,"text":"outcomes; fantasy, which Malone argued"},{"start":39.875,"end":42.532,"text":"works better when it is tied to the skill"},{"start":42.532,"end":45.569,"text":"itself; and curiosity, sparked when what"},{"start":45.569,"end":47.214,"text":"you know feels incomplete."},{"start":48.083,"end":50.735,"text":"With Mark Lepper he later added control,"},{"start":50.735,"end":53.572,"text":"and three social motives: cooperation,"},{"start":53.572,"end":55.483,"text":"competition, and recognition."},{"start":57.313,"end":60.094,"text":"ARCS stands for attention, relevance,"},{"start":60.094,"end":62.146,"text":"confidence, and satisfaction."},{"start":62.983,"end":65.05,"text":"Keller grounded it in expectancy value"},{"start":65.05,"end":67.434,"text":"theory: we put in effort when something"},{"start":67.434,"end":69.501,"text":"matters to us and we expect to succeed."},{"start":69.819,"end":71.78,"text":"The model grew from work he began in"},{"start":71.78,"end":72.945,"text":"nineteen seventy nine."},{"start":74.773,"end":77.547,"text":"In Keller's later versions, each category"},{"start":77.547,"end":78.682,"text":"splits into three."},{"start":79.06,"end":81.582,"text":"Relevance, for example, covers goal"},{"start":81.582,"end":83.977,"text":"orientation, motive matching, and"},{"start":83.977,"end":84.73400000000001,"text":"familiarity."},{"start":85.112,"end":87.57,"text":"Note that satisfaction openly includes"},{"start":87.57,"end":88.705,"text":"extrinsic rewards."},{"start":90.65299999999999,"end":94.12100000000001,"text":"ARCS is also a design process: define,"},{"start":94.12100000000001,"end":97.363,"text":"design, develop, and evaluate, which"},{"start":97.363,"end":100.077,"text":"Keller describes as compatible with"},{"start":100.077,"end":102.791,"text":"typical instructional design models."},{"start":103.773,"end":106.19800000000001,"text":"And the first step is a check: is this"},{"start":106.19800000000001,"end":108.291,"text":"really a motivation problem, or are"},{"start":108.291,"end":109.614,"text":"learners missing skills?"},{"start":109.944,"end":111.763,"text":"ARCS is meant for the first case."},{"start":113.71000000000001,"end":114.82,"text":"Here is a toy audit."},{"start":115.154,"end":117.208,"text":"A twenty minute fractions lesson has"},{"start":117.208,"end":119.65100000000001,"text":"students serving pizza orders, like three"},{"start":119.65100000000001,"end":120.65,"text":"eighths pepperoni."},{"start":120.983,"end":123.371,"text":"Five learners rate each ARCS category from"},{"start":123.371,"end":124.037,"text":"one to five."},{"start":124.93,"end":126.174,"text":"Average each column."},{"start":126.547,"end":129.16,"text":"Attention and satisfaction are already at"},{"start":129.16,"end":129.47,"text":"four."},{"start":129.844,"end":132.643,"text":"Relevance averages two, and confidence two"},{"start":132.643,"end":133.327,"text":"point four."},{"start":134.21,"end":136.922,"text":"So against a target of four, relevance is"},{"start":136.922,"end":139.079,"text":"the biggest gap, then confidence."},{"start":139.448,"end":141.482,"text":"The game already grabs attention."},{"start":141.852,"end":144.255,"text":"Learners just do not see why fractions"},{"start":144.255,"end":146.72,"text":"matter, or feel unsure they can do it."},{"start":148.61,"end":150.965,"text":"An ARCS designer targets the gap that was"},{"start":150.965,"end":153.65699999999998,"text":"measured: use the class's own lunch orders"},{"start":153.65699999999998,"end":155.788,"text":"for relevance, and show the success"},{"start":155.788,"end":157.13400000000001,"text":"criteria for confidence."},{"start":158.01,"end":160.678,"text":"A Malone designer adds features: make the"},{"start":160.678,"end":163.232,"text":"fantasy intrinsic, so slicing the pizza is"},{"start":163.232,"end":165.787,"text":"the fraction skill, and add challenge with"},{"start":165.787,"end":167.489,"text":"hidden orders that get harder."},{"start":168.46,"end":170.73,"text":"Put simply, Malone tells you which fun"},{"start":170.73,"end":173,"text":"ingredients to add, and ARCS tells you"},{"start":173,"end":174.938,"text":"which one this audience is missing."},{"start":176.787,"end":178.035,"text":"You can see parallels."},{"start":178.375,"end":180.759,"text":"Malone's challenge sits close to Keller's"},{"start":180.759,"end":183.142,"text":"confidence, which calls for conquerable"},{"start":183.142,"end":185.468,"text":"challenge, and curiosity sits close to"},{"start":185.468,"end":186.376,"text":"inquiry arousal."},{"start":187.227,"end":188.85,"text":"But the difference matters."},{"start":189.21,"end":191.194,"text":"Malone describes features of fun"},{"start":191.194,"end":191.856,"text":"activities."},{"start":192.216,"end":194.26,"text":"ARCS is a procedure driven by the"},{"start":194.26,"end":196.845,"text":"audience, and it openly allows extrinsic"},{"start":196.845,"end":197.326,"text":"rewards."},{"start":199.32,"end":200.54,"text":"How strong is the evidence?"},{"start":200.811,"end":202.755,"text":"A meta analysis of thirty eight controlled"},{"start":202.755,"end":204.472,"text":"ARCS studies found an effect of point"},{"start":204.472,"end":206.325,"text":"seven four on achievement and point four"},{"start":206.325,"end":207.22899999999998,"text":"three on motivation."},{"start":208.06,"end":209.956,"text":"But the authors warn these numbers are"},{"start":209.956,"end":212.047,"text":"only as good as the primary studies, and"},{"start":212.047,"end":213.992,"text":"Keller's own early field tests measured"},{"start":213.992,"end":215.548,"text":"teachers' views, not learning."},{"start":217.46,"end":218.62,"text":"So use them together."},{"start":218.952,"end":220.996,"text":"Diagnose with ARCS to find what this"},{"start":220.996,"end":223.428,"text":"audience is missing, then borrow Malone's"},{"start":223.428,"end":225.804,"text":"features to fix it, and keep the fantasy"},{"start":225.804,"end":226.798,"text":"tied to the skill."},{"start":228.73,"end":231.118,"text":"For the discussion board, name the weakest"},{"start":231.118,"end":233.348,"text":"ARCS category in a lesson you know, and"},{"start":233.348,"end":235.312,"text":"one Malone feature that could fix it."}]},"GTUT49cgqQE":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.11,"end":2.033,"text":"A design works beautifully in one"},{"start":2.033,"end":2.599,"text":"classroom."},{"start":2.939,"end":5.145,"text":"Then it goes to ten, and the results"},{"start":5.145,"end":5.598,"text":"scatter."},{"start":5.937,"end":8.426,"text":"This video explains why that happens, and"},{"start":8.426,"end":10.633,"text":"how implementation research studies it"},{"start":10.633,"end":11.821,"text":"instead of hiding it."},{"start":13.773,"end":14.988,"text":"Here is a toy example."},{"start":15.32,"end":17.639,"text":"Recipe Remix, a fractions activity with"},{"start":17.639,"end":20.18,"text":"Chef and Auditor roles, began in class A,"},{"start":20.18,"end":22.555,"text":"with research support, and the mean gain"},{"start":22.555,"end":24.322,"text":"there was two point four points."},{"start":25.323,"end":27.145,"text":"Now nine more classes try it."},{"start":27.522,"end":29.909,"text":"The gains range from point two to two"},{"start":29.909,"end":32.61,"text":"point six, and the average of all ten is"},{"start":32.61,"end":35.06,"text":"one point four three, well below the"},{"start":35.06,"end":35.436,"text":"pilot."},{"start":37.393,"end":40.176,"text":"Color the classes by one thing: did the"},{"start":40.176,"end":42.093,"text":"Auditor really ask for reasons?"},{"start":42.464,"end":45.184,"text":"Where the core was enacted, the mean gain"},{"start":45.184,"end":46.545,"text":"was two point one two."},{"start":46.916,"end":48.832,"text":"Where it was not, point four."},{"start":49.753,"end":51.664,"text":"This is an association, not proof."},{"start":51.983,"end":54.159,"text":"Teachers who kept the core may differ in"},{"start":54.159,"end":55.115,"text":"other ways, too."},{"start":57.043,"end":58.846,"text":"This is not a strange accident."},{"start":59.194,"end":61.52,"text":"William Penuel and colleagues note that"},{"start":61.52,"end":63.845,"text":"the effects of nearly all programs vary"},{"start":63.845,"end":66.055,"text":"significantly from setting to setting."},{"start":66.953,"end":69.125,"text":"They also recall an older finding:"},{"start":69.125,"end":71.405,"text":"teachers' adaptations in the classroom,"},{"start":71.405,"end":73.359,"text":"not policy makers' plans, largely"},{"start":73.359,"end":75.368,"text":"determine how effective a program is."},{"start":77.31,"end":79.263,"text":"Not all adaptation is the same."},{"start":79.64099999999999,"end":81.90899999999999,"text":"Class F swapped the strips for real"},{"start":81.90899999999999,"end":84.304,"text":"measuring cups, and still asked for"},{"start":84.304,"end":84.80799999999999,"text":"reasons."},{"start":85.186,"end":87.202,"text":"That is a productive adaptation."},{"start":88.08,"end":90.58500000000001,"text":"In class G, the teacher became the Auditor"},{"start":90.58500000000001,"end":92.755,"text":"and just marked answers right or wrong."},{"start":93.089,"end":95.42699999999999,"text":"The activity survived on paper, but the"},{"start":95.42699999999999,"end":96.206,"text":"core was gone."},{"start":97.16,"end":99.44800000000001,"text":"Ann Brown and Joseph Campione brought a"},{"start":99.44800000000001,"end":101.793,"text":"name for this into educational design,"},{"start":101.793,"end":104.36699999999999,"text":"crediting Ed Haertel: a lethal mutation."},{"start":105.21000000000001,"end":107.22399999999999,"text":"So the real question is not fidelity"},{"start":107.22399999999999,"end":108.20400000000001,"text":"versus adaptation."},{"start":108.531,"end":110.81700000000001,"text":"It is knowing which parts of a design are"},{"start":110.81700000000001,"end":112.613,"text":"core, and which parts can flex."},{"start":114.56700000000001,"end":116.82,"text":"Capacity is part of the design, too."},{"start":117.175,"end":119.487,"text":"When California reduced class sizes,"},{"start":119.487,"end":121.977,"text":"smaller classes raised achievement, but"},{"start":121.977,"end":124.29,"text":"hiring many inexperienced, not fully"},{"start":124.29,"end":126.661,"text":"certified teachers dampened the benefit."},{"start":128.587,"end":130.407,"text":"This is why Cynthia Coburn argued that"},{"start":130.407,"end":132.133,"text":"scale should mean more than counting"},{"start":132.133,"end":132.507,"text":"schools."},{"start":134.297,"end":136.34199999999998,"text":"She proposed four dimensions."},{"start":136.766,"end":139.869,"text":"Depth, change in beliefs and norms, not"},{"start":139.869,"end":140.927,"text":"just materials."},{"start":141.351,"end":144.313,"text":"Sustainability, change that lasts after"},{"start":144.313,"end":145.653,"text":"extra support ends."},{"start":146.677,"end":148.688,"text":"Spread, of the principles, including"},{"start":148.688,"end":149.816,"text":"within a single school."},{"start":150.11,"end":152.17000000000002,"text":"And a shift in ownership, so the reform"},{"start":152.17000000000002,"end":154.18099999999998,"text":"belongs to the teachers and schools that"},{"start":154.18099999999998,"end":154.622,"text":"carry it."},{"start":158.11,"end":160.372,"text":"Two research approaches were built for"},{"start":160.372,"end":160.662,"text":"this."},{"start":161.00900000000001,"end":163.155,"text":"Design based implementation research"},{"start":163.155,"end":165.591,"text":"treats implementation itself as something"},{"start":165.591,"end":167.736,"text":"to design and theorize, and builds"},{"start":167.736,"end":169.302,"text":"capacity to sustain change."},{"start":170.14,"end":172.737,"text":"Improvement science asks us to attend to"},{"start":172.737,"end":175.903,"text":"variability: not just what works, but what"},{"start":175.903,"end":178.183,"text":"works, for whom, and under what"},{"start":178.183,"end":178.88,"text":"conditions."},{"start":180.887,"end":183.077,"text":"So when you scale a design, study the"},{"start":183.077,"end":185.376,"text":"variation instead of averaging it away,"},{"start":185.376,"end":187.676,"text":"name your core components, redesign the"},{"start":187.676,"end":189.975,"text":"supports where the core broke, and plan"},{"start":189.975,"end":192.439,"text":"for depth, sustainability, spread, and"},{"start":192.439,"end":193.698,"text":"ownership from day one."},{"start":195.54,"end":197.593,"text":"For the discussion board, pick a design"},{"start":197.593,"end":198.912,"text":"you know and name its core."},{"start":199.206,"end":201.307,"text":"Then describe what a lethal mutation of it"},{"start":201.307,"end":203.067,"text":"would look like in a real classroom."}]},"Navj1yDN5-Q":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":5.762,"end":7.453,"text":"Put on a headset, and your room"},{"start":7.453,"end":8,"text":"disappears."},{"start":8.298,"end":9.989,"text":"You are standing inside a glowing"},{"start":9.989,"end":11.878,"text":"chemistry lab, and it feels amazing."},{"start":12.177,"end":14.265,"text":"But does feeling amazing mean you learned"},{"start":14.265,"end":14.514,"text":"more?"},{"start":16.775,"end":19.018,"text":"Meet two friends who study the same"},{"start":19.018,"end":20.389,"text":"virtual chemistry lab."},{"start":20.763,"end":22.32,"text":"Jordan works on a laptop."},{"start":22.694,"end":24.252,"text":"Riley wears a VR headset."},{"start":30.519,"end":32.268,"text":"Most people would bet on Riley."},{"start":32.607,"end":34.75,"text":"A real experiment tested exactly this"},{"start":34.75,"end":35.371,"text":"comparison."},{"start":37.289,"end":39.833,"text":"In twenty nineteen, Guido Makransky,"},{"start":39.833,"end":42.378,"text":"Thomas Terkildsen and Richard Mayer gave"},{"start":42.378,"end":44.798,"text":"fifty two university students the same"},{"start":44.798,"end":47.156,"text":"science lab simulation, either on a"},{"start":47.156,"end":49.266,"text":"desktop screen or in a VR headset."},{"start":51.375,"end":53.699,"text":"Here are the results, as effect sizes."},{"start":54.048,"end":56.604,"text":"Arrows to the right mean higher in VR;"},{"start":56.604,"end":58.696,"text":"arrows to the left mean lower in VR."},{"start":59.979,"end":61.104,"text":"First, presence."},{"start":61.479,"end":63.918,"text":"Students in VR felt far more like they"},{"start":63.918,"end":66.67,"text":"were really there, with an effect size of"},{"start":66.67,"end":67.67,"text":"one point three."},{"start":68.045,"end":69.233,"text":"That is very large."},{"start":72.57300000000001,"end":75.288,"text":"Presence is the felt sense of being inside"},{"start":75.288,"end":76.425,"text":"the virtual place."},{"start":76.803,"end":77.814,"text":"VR delivered it."},{"start":79.941,"end":81.445,"text":"Second, the learning test."},{"start":81.767,"end":84.13,"text":"The VR group scored lower, with an effect"},{"start":84.13,"end":86.17099999999999,"text":"size of zero point eight in the wrong"},{"start":86.17099999999999,"end":86.708,"text":"direction."},{"start":87.975,"end":89.451,"text":"Third, a brain measure."},{"start":89.805,"end":92.286,"text":"An E E G headband showed higher cognitive"},{"start":92.286,"end":94.707,"text":"load in VR, meaning working memory was"},{"start":94.707,"end":95.12,"text":"busier."},{"start":97.425,"end":100.158,"text":"The paper's title says it plainly: more"},{"start":100.158,"end":101.97999999999999,"text":"presence, but less learning."},{"start":105.509,"end":106.57300000000001,"text":"Why would this happen?"},{"start":106.863,"end":108.94200000000001,"text":"Picture working memory as a small backpack"},{"start":108.94200000000001,"end":110.344,"text":"you carry through the lesson."},{"start":110.63499999999999,"end":111.699,"text":"It only holds so much."},{"start":112.535,"end":114.53999999999999,"text":"On a desktop, the virtual world takes a"},{"start":114.53999999999999,"end":116.642,"text":"little space, which leaves plenty of room"},{"start":116.642,"end":117.358,"text":"for the lesson."},{"start":118.607,"end":121.201,"text":"In VR, the sights, the sounds and the new"},{"start":121.201,"end":122.555,"text":"controls take much more."},{"start":122.893,"end":125.036,"text":"The lesson gets squeezed into what is"},{"start":125.036,"end":125.318,"text":"left."},{"start":128.495,"end":130.275,"text":"It is a bit like trying to study for an"},{"start":130.275,"end":132.055,"text":"exam while you stand in the middle of a"},{"start":132.055,"end":132.768,"text":"busy theme park."},{"start":140.47899999999998,"end":141.236,"text":"Not at all."},{"start":141.648,"end":144.332,"text":"A meta analysis of forty eight studies"},{"start":144.332,"end":147.566,"text":"found that, on average, immersive VR has a"},{"start":147.566,"end":149.906,"text":"small positive effect on learning."},{"start":151.027,"end":153.258,"text":"But an average hides both wins and losses,"},{"start":153.258,"end":154.498,"text":"like the one we just saw."},{"start":154.796,"end":156.829,"text":"What decides which one you get is design."},{"start":159.589,"end":161.824,"text":"So how do we design for learning?"},{"start":162.231,"end":165.008,"text":"First, use VR where being there really"},{"start":165.008,"end":168.328,"text":"matters, such as space, scale, the body,"},{"start":168.328,"end":170.292,"text":"or places too risky to visit."},{"start":173.301,"end":175.734,"text":"Second, keep the virtual world calm when"},{"start":175.734,"end":178.167,"text":"the content is hard, so the scenery does"},{"start":178.167,"end":179.751,"text":"not compete with the lesson."},{"start":182.589,"end":184.285,"text":"Third, add a thinking task."},{"start":184.636,"end":186.917,"text":"Jocelyn Parong and Richard Mayer found"},{"start":186.917,"end":189.257,"text":"that asking learners to summarize after"},{"start":189.257,"end":191.597,"text":"each segment of a VR lesson helped them"},{"start":191.597,"end":191.948,"text":"learn."},{"start":194.852,"end":196.511,"text":"Back to our two friends."},{"start":196.926,"end":198.032,"text":"Riley felt more."},{"start":198.447,"end":199.82999999999998,"text":"Jordan learned more."},{"start":200.245,"end":202.457,"text":"Both things can be true at once."},{"start":203.48,"end":206.05,"text":"So remember: wow is a feeling, and"},{"start":206.05,"end":207.763,"text":"learning is a design result."},{"start":210.692,"end":212.39600000000002,"text":"These are the studies behind this video."}]},"LKY8wo6KoDw":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.12,"end":2.012,"text":"In part A, play became evidence."},{"start":2.345,"end":4.682,"text":"Part B shows how a Bayesian network turns"},{"start":4.682,"end":6.796,"text":"that evidence into beliefs about each"},{"start":6.796,"end":7.686,"text":"player's skills."},{"start":9.44,"end":11.441,"text":"Start with the Q matrix from part A."},{"start":11.774,"end":14.219,"text":"Each skill becomes a node at the top, and"},{"start":14.219,"end":16.109,"text":"each one in the matrix becomes an"},{"start":16.109,"end":18.554,"text":"observable node below, with an arrow from"},{"start":18.554,"end":19.777,"text":"the skill it measures."},{"start":20.82,"end":23.043,"text":"Skills can also depend on each other."},{"start":23.403,"end":25.866,"text":"Here, interpreting graphs makes causal"},{"start":25.866,"end":28.268,"text":"explanations more likely, so one more"},{"start":28.268,"end":29.29,"text":"arrow joins them."},{"start":30.08,"end":32.409,"text":"That picture, plus a probability table at"},{"start":32.409,"end":34.262,"text":"each node, is a Bayesian network."},{"start":36.243,"end":38.04,"text":"Each observable has a small table."},{"start":38.357,"end":40.629,"text":"A player who has mastered variable control"},{"start":40.629,"end":43.112,"text":"shows it eighty five percent of the time;"},{"start":43.112,"end":45.12,"text":"one who has not still shows it thirty"},{"start":45.12,"end":46.176,"text":"percent of the time."},{"start":46.983,"end":48.727,"text":"Those two errors have names."},{"start":49.101,"end":51.716,"text":"A slip is when a skilled player misses,"},{"start":51.716,"end":54.207,"text":"and a guess is when an unskilled player"},{"start":54.207,"end":56.76,"text":"gets lucky, like player B's lucky shot."},{"start":58.653,"end":60.172,"text":"Now watch one belief update."},{"start":60.498,"end":62.885,"text":"Before any play, we are fifty fifty about"},{"start":62.885,"end":64.838,"text":"whether player A controls variables."},{"start":65.703,"end":68.286,"text":"In level two, the evidence rule fires: one"},{"start":68.286,"end":69.164,"text":"slider at a time."},{"start":69.474,"end":71.695,"text":"Bayes' rule moves the belief to zero point"},{"start":71.695,"end":72.263,"text":"seven four."},{"start":77.383,"end":79.74,"text":"In level five it happens again, and the"},{"start":79.74,"end":81.929,"text":"belief rises to about zero point eight"},{"start":81.929,"end":82.21000000000001,"text":"nine."},{"start":82.547,"end":84.96000000000001,"text":"Evidence accumulates, like a detective's"},{"start":84.96000000000001,"end":85.297,"text":"notes."},{"start":87.07300000000001,"end":89.41,"text":"After all five levels, here is what the"},{"start":89.41,"end":90.355,"text":"network believes."},{"start":90.689,"end":92.97,"text":"Player A looks strong on all four skills."},{"start":93.923,"end":96.689,"text":"Player B is strong at reading graphs, but"},{"start":96.689,"end":99.518,"text":"weak at controlling variables, revising,"},{"start":99.518,"end":100.9,"text":"and explaining causes."},{"start":101.27799999999999,"end":103.60300000000001,"text":"Same three stars, a very different"},{"start":103.60300000000001,"end":104.106,"text":"profile."},{"start":106.02000000000001,"end":108.096,"text":"Where do numbers like zero point eight"},{"start":108.096,"end":110.012,"text":"five and zero point three come from?"},{"start":110.331,"end":112.513,"text":"With pilot data, a cognitive diagnosis"},{"start":112.513,"end":113.78999999999999,"text":"model can estimate them."},{"start":114.11,"end":116.345,"text":"Here we simulate two thousand players and"},{"start":116.345,"end":116.771,"text":"fit one."},{"start":117.67,"end":120.184,"text":"Most estimates land near the true values."},{"start":120.552,"end":122.944,"text":"But variable control and revision have"},{"start":122.944,"end":125.703,"text":"only two observables each in the Q matrix,"},{"start":125.703,"end":127.359,"text":"and their estimates wobble."},{"start":127.727,"end":129.812,"text":"Thin evidence gives shaky numbers."},{"start":130.77,"end":132.833,"text":"This also shows that cognitive diagnosis"},{"start":132.833,"end":134.795,"text":"models and Bayesian networks are close"},{"start":134.795,"end":135.298,"text":"relatives."},{"start":137.293,"end":139.125,"text":"Players also learn while they play."},{"start":139.44,"end":141.53300000000002,"text":"A dynamic Bayesian network carries each"},{"start":141.53300000000002,"end":143.889,"text":"belief from level to level, adding a small"},{"start":143.889,"end":145.459,"text":"chance of learning in between."},{"start":146.303,"end":148.602,"text":"Player A's belief climbs as the evidence"},{"start":148.602,"end":149.106,"text":"comes in."},{"start":149.442,"end":151.853,"text":"Player B's sinks, because each chance to"},{"start":151.853,"end":153.927,"text":"control variables goes by without it."},{"start":158.41,"end":160.667,"text":"The beliefs then drive the game."},{"start":161.09,"end":164.264,"text":"In a four process loop, the system selects"},{"start":164.264,"end":167.367,"text":"the next level, presents it, identifies"},{"start":167.367,"end":169.977,"text":"evidence, and accumulates it again."},{"start":170.94,"end":172.918,"text":"For player B, the weakest skill is causal"},{"start":172.918,"end":174.895,"text":"explanation, so the next level could be a"},{"start":174.895,"end":175.929,"text":"surprise that asks why."},{"start":176.199,"end":178.132,"text":"This is stealth assessment: measuring"},{"start":178.132,"end":179.3,"text":"without stopping the game."},{"start":182.167,"end":184.551,"text":"Before trusting these numbers, validate"},{"start":184.551,"end":186.992,"text":"the Q matrix, learn the tables from real"},{"start":186.992,"end":189.149,"text":"pilot data, compare with an outside"},{"start":189.149,"end":191.64600000000002,"text":"measure, and check fairness across groups."},{"start":193.597,"end":196.445,"text":"Here is the whole pipeline: claims shape"},{"start":196.445,"end":199.356,"text":"levels, the Q matrix links them to skills,"},{"start":199.356,"end":202.143,"text":"evidence rules turn logs into observables,"},{"start":202.143,"end":204.93,"text":"the network updates beliefs, and decisions"},{"start":204.93,"end":207.345,"text":"feed back into the game and its design."},{"start":208.177,"end":209.245,"text":"And our two players?"},{"start":209.566,"end":211.65,"text":"Same three stars, but very different"},{"start":211.65,"end":213.253,"text":"evidence about how they think."},{"start":213.573,"end":215.871,"text":"That is what a game can tell us, when it"},{"start":215.871,"end":217.046,"text":"is designed to listen."}]},"XC_5YE2YYoY":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.04,"end":2.168,"text":"How can a game tell us what a learner"},{"start":2.168,"end":4.688,"text":"knows, without stopping the game to give a"},{"start":4.688,"end":4.968,"text":"test?"},{"start":5.304,"end":7.712,"text":"This is part one of a two part story about"},{"start":7.712,"end":8.944,"text":"game based assessment."},{"start":10.873,"end":13.084,"text":"Meet Launch Lab, a small physics game."},{"start":13.416,"end":16.125,"text":"Players set the angle, speed, and gravity,"},{"start":16.125,"end":17.562,"text":"and try to hit the target."},{"start":18.443,"end":20.749,"text":"Player A changes only the angle, misses"},{"start":20.749,"end":23.22,"text":"short, changes the angle again, and hits"},{"start":23.22,"end":23.824,"text":"the target."},{"start":26.753,"end":29.03,"text":"Player B changes all three sliders at"},{"start":29.03,"end":31.486,"text":"once, overshoots, changes everything"},{"start":31.486,"end":32.984,"text":"again, and hits it too."},{"start":39.143,"end":40.66,"text":"Same stars, same score."},{"start":41.025,"end":43.634,"text":"But only player A tested one variable at a"},{"start":43.634,"end":43.937,"text":"time."},{"start":44.302,"end":46.668,"text":"Game based assessment is about reading"},{"start":46.668,"end":47.639,"text":"that difference."},{"start":49.653,"end":52.191,"text":"The design idea behind this is evidence"},{"start":52.191,"end":54.919,"text":"centered design, or E C D, from Robert"},{"start":54.919,"end":56.378,"text":"Mislevy and colleagues."},{"start":56.759,"end":59.614,"text":"It starts with a claim, asks what evidence"},{"start":59.614,"end":62.405,"text":"would support it, and only then designs a"},{"start":62.405,"end":62.723,"text":"task."},{"start":63.723,"end":65.394,"text":"A road test works the same way."},{"start":65.717,"end":67.98,"text":"To claim someone drives safely, we look"},{"start":67.98,"end":70.35,"text":"for mirror checks before lane changes, so"},{"start":70.35,"end":72.28999999999999,"text":"the route must include lane changes."},{"start":73.253,"end":75.627,"text":"So an assessment is an argument, from what"},{"start":75.627,"end":77.737,"text":"learners do to what we claim about them."},{"start":79.687,"end":82.212,"text":"E C D organizes this into three linked"},{"start":82.212,"end":85.255,"text":"models: a competency model, an evidence"},{"start":85.255,"end":86.938,"text":"model, and a task model."},{"start":87.81700000000001,"end":90.481,"text":"In Launch Lab, the competency model is"},{"start":90.481,"end":93.729,"text":"causal reasoning, broken into four skills:"},{"start":93.729,"end":96.523,"text":"controlling variables, revising ideas,"},{"start":96.523,"end":98.99199999999999,"text":"interpreting graphs, and explaining"},{"start":98.99199999999999,"end":99.447,"text":"causes."},{"start":100.34700000000001,"end":102.672,"text":"These are latent skills: we cannot see"},{"start":102.672,"end":104.89099999999999,"text":"them, only infer them from what players"},{"start":104.89099999999999,"end":105.05,"text":"do."},{"start":106.94,"end":109.055,"text":"The task model shapes the levels."},{"start":109.44,"end":112.068,"text":"Each level has features chosen to make a"},{"start":112.068,"end":114.375,"text":"particular kind of thinking visible."},{"start":115.39,"end":118.017,"text":"For example, level four deliberately"},{"start":118.017,"end":120.712,"text":"produces a surprising result, because"},{"start":120.712,"end":123.339,"text":"revising an idea only shows up after a"},{"start":123.339,"end":123.946,"text":"surprise."},{"start":125.997,"end":128.181,"text":"The bridge between levels and skills is"},{"start":128.181,"end":128.891,"text":"the Q matrix."},{"start":129.219,"end":131.731,"text":"Each row is a level, each column a skill,"},{"start":131.731,"end":133.971,"text":"and a one means the level gives evidence"},{"start":133.971,"end":134.899,"text":"about that skill."},{"start":135.827,"end":138.406,"text":"Level four, for instance, informs three"},{"start":138.406,"end":140.692,"text":"skills at once: revision, graph"},{"start":140.692,"end":143.095,"text":"interpretation, and causal explanation."},{"start":148.267,"end":148.423,"text":"No."},{"start":148.736,"end":150.821,"text":"Its variable control cell is zero, so"},{"start":150.821,"end":152.803,"text":"nothing a player does there counts as"},{"start":152.803,"end":154.054,"text":"evidence for that skill."},{"start":154.857,"end":157.091,"text":"A Q matrix is a claim in itself, so it"},{"start":157.091,"end":158.017,"text":"must be defended."},{"start":158.344,"end":160.633,"text":"Turning on cells without a reason makes a"},{"start":160.633,"end":162.976,"text":"diagnosis look more precise than it really"},{"start":162.976,"end":163.14,"text":"is."},{"start":165.083,"end":166.53,"text":"Now the evidence model."},{"start":166.90699999999998,"end":169.674,"text":"Underneath the game, every action becomes"},{"start":169.674,"end":172.379,"text":"a row in a log: predictions, slider"},{"start":172.379,"end":174.768,"text":"changes, runs, graph views, and"},{"start":174.768,"end":175.586,"text":"explanations."},{"start":176.383,"end":178.623,"text":"Evidence rules turn those rows into a few"},{"start":178.623,"end":179.903,"text":"meaningful observations."},{"start":180.223,"end":182.41,"text":"Changing only one slider before each run"},{"start":182.41,"end":184.383,"text":"becomes evidence of variable control."},{"start":186.323,"end":188.464,"text":"Each one in the Q matrix becomes one such"},{"start":188.464,"end":189.024,"text":"observable."},{"start":189.33,"end":191.47,"text":"Recording clicks without rules like these"},{"start":191.47,"end":193.814,"text":"is just logging; the rules are what make"},{"start":193.814,"end":194.528,"text":"it assessment."},{"start":196.53,"end":199.61599999999999,"text":"So far we have claims, tasks, a Q matrix,"},{"start":199.61599999999999,"end":200.837,"text":"and evidence rules."},{"start":201.223,"end":204.051,"text":"In part B, a Bayesian network turns those"},{"start":204.051,"end":206.623,"text":"observations into updated beliefs about"},{"start":206.623,"end":207.394,"text":"each player."}]},"Cn2KU6ooubI":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.11,"end":2.055,"text":"Design based research almost always"},{"start":2.055,"end":3.027,"text":"involves partners."},{"start":3.351,"end":5.62,"text":"Two words describe that partnership, co"},{"start":5.62,"end":7.997,"text":"design and participatory design, and they"},{"start":7.997,"end":10.211,"text":"are often used as if they meant the same"},{"start":10.211,"end":12.156,"text":"thing, although they do not quite."},{"start":14.16,"end":16.484,"text":"Picture the team designing an A I feedback"},{"start":16.484,"end":17.889,"text":"tool for a writing course."},{"start":18.213,"end":20.644,"text":"Who sits at the design table, and who gets"},{"start":20.644,"end":22.536,"text":"to decide what the problem even is?"},{"start":24.56,"end":27.018,"text":"In one version, teachers join facilitated"},{"start":27.018,"end":29.196,"text":"sessions in defined roles to shape the"},{"start":29.196,"end":29.475,"text":"tool."},{"start":29.81,"end":32.324,"text":"In another, students and community members"},{"start":32.324,"end":34.446,"text":"help decide the problem itself, who"},{"start":34.446,"end":36.345,"text":"benefits, and who owns the data."},{"start":42.36,"end":44.694,"text":"Scenario A is typical of co design, and"},{"start":44.694,"end":46.639,"text":"scenario B of participatory design."},{"start":46.973,"end":49.418,"text":"The difference is less about who attends,"},{"start":49.418,"end":51.641,"text":"and more about who holds power over the"},{"start":51.641,"end":52.197,"text":"decisions."},{"start":54,"end":56.295,"text":"Participatory design began in Scandinavian"},{"start":56.295,"end":58.164,"text":"workplace projects of the nineteen"},{"start":58.164,"end":60.513,"text":"seventies and eighties, where workers and"},{"start":60.513,"end":62.595,"text":"their unions helped shape the computer"},{"start":62.595,"end":64.57,"text":"systems that would change their jobs."},{"start":65.56,"end":67.887,"text":"Its core commitment is political as well"},{"start":67.887,"end":70.554,"text":"as practical: people affected by a design"},{"start":70.554,"end":72.825,"text":"should have a real say in it, through"},{"start":72.825,"end":74.981,"text":"mutual learning and shared power over"},{"start":74.981,"end":76.059,"text":"goals and outcomes."},{"start":78.01,"end":80.202,"text":"Co design is a broader term from design"},{"start":80.202,"end":80.696,"text":"practice."},{"start":81.025,"end":83.327,"text":"Elizabeth Sanders and Pieter Jan Stappers"},{"start":83.327,"end":85.574,"text":"describe it as the collective creativity"},{"start":85.574,"end":87.711,"text":"of designers and people not trained in"},{"start":87.711,"end":89.191,"text":"design, working together."},{"start":90.11,"end":93.069,"text":"In education, Jeremy Roschelle, William"},{"start":93.069,"end":96.02799999999999,"text":"Penuel, and Nicole Shechtman described co"},{"start":96.02799999999999,"end":99.055,"text":"design as a highly facilitated, team based"},{"start":99.055,"end":102.283,"text":"process, where teachers, researchers, and"},{"start":102.283,"end":104.70400000000001,"text":"developers work in defined roles to"},{"start":104.70400000000001,"end":107.327,"text":"design, prototype, and evaluate an"},{"start":107.327,"end":108.066,"text":"innovation."},{"start":109.07,"end":111.294,"text":"The emphasis here is fit to real"},{"start":111.294,"end":113.652,"text":"classrooms, drawing on teachers'"},{"start":113.652,"end":116.41499999999999,"text":"expertise, rather than a commitment to"},{"start":116.41499999999999,"end":117.696,"text":"redistribute power."},{"start":119.61,"end":121.56,"text":"It helps to picture participation as a"},{"start":121.56,"end":123.26,"text":"ladder, rather than a yes or no."},{"start":125.05,"end":127.285,"text":"Allison Druin described four roles"},{"start":127.285,"end":130.351,"text":"children can play in designing technology:"},{"start":130.351,"end":133.033,"text":"user, tester, informant, and design"},{"start":133.033,"end":135.907,"text":"partner, each with more influence than the"},{"start":135.907,"end":136.227,"text":"last."},{"start":137.14,"end":139.394,"text":"Co design usually sits from tester to"},{"start":139.394,"end":140.284,"text":"design partner."},{"start":140.64,"end":143.309,"text":"Participatory design aims for the top, and"},{"start":143.309,"end":145.86,"text":"adds a real say over goals and outcomes,"},{"start":145.86,"end":147.224,"text":"not just over features."},{"start":149.207,"end":152.454,"text":"Side by side, co design grew from design"},{"start":152.454,"end":154.796,"text":"practice and research practice"},{"start":154.796,"end":158.04399999999998,"text":"partnerships, and values fit to practice."},{"start":158.497,"end":161.594,"text":"Participatory design grew from workplace"},{"start":161.594,"end":164.69,"text":"democracy, and values voice and shared"},{"start":164.69,"end":165.143,"text":"power."},{"start":166.117,"end":168.41,"text":"The sharpest difference is who sets the"},{"start":168.41,"end":168.754,"text":"goals."},{"start":169.098,"end":171.793,"text":"Each also has its own risk: co design can"},{"start":171.793,"end":174.144,"text":"become consultation that only looks like"},{"start":174.144,"end":176.667,"text":"partnership, and participatory design can"},{"start":176.667,"end":178.273,"text":"be slow and hard to sustain."},{"start":180.21,"end":182.493,"text":"Inside design based research, the"},{"start":182.493,"end":184.775,"text":"participatory tradition shows up as"},{"start":184.775,"end":187.629,"text":"participatory design research, which Megan"},{"start":187.629,"end":190.038,"text":"Bang and Shirin Vossoughi describe as"},{"start":190.038,"end":192.955,"text":"attending to power, history, and who gets"},{"start":192.955,"end":194.16,"text":"to define learning."},{"start":195.13,"end":197.464,"text":"Whichever label you use, report it"},{"start":197.464,"end":200.493,"text":"honestly by answering three questions: who"},{"start":200.493,"end":203.269,"text":"defined the problem, who could change the"},{"start":203.269,"end":206.108,"text":"design and the goals, and who benefits and"},{"start":206.108,"end":206.99099999999999,"text":"owns the data."},{"start":208.897,"end":211.101,"text":"For the discussion board, find a study"},{"start":211.101,"end":212.768,"text":"that says it used co design or"},{"start":212.768,"end":215.133,"text":"participatory design, and decide where on"},{"start":215.133,"end":217.552,"text":"the ladder its partners really were, based"},{"start":217.552,"end":219.004,"text":"on what the authors report."}]},"pR--9zWzm30":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.12,"end":2.03,"text":"Learning sciences and the science of"},{"start":2.03,"end":4.249,"text":"learning sound almost the same, but they"},{"start":4.249,"end":6.313,"text":"grew from different communities and ask"},{"start":6.313,"end":7.81,"text":"different kinds of questions."},{"start":8.12,"end":10.287,"text":"This video traces how each one evolved,"},{"start":10.287,"end":11.99,"text":"and why one of them ends in an s."},{"start":13.913,"end":15.871,"text":"Imagine two researchers who both care"},{"start":15.871,"end":17.674,"text":"about how children learn fractions."},{"start":18.533,"end":20.658,"text":"One asks whether spacing out practice"},{"start":20.658,"end":22.28,"text":"improves recall a week later."},{"start":22.616,"end":24.965,"text":"The other asks how a redesigned classroom"},{"start":24.965,"end":27.146,"text":"activity changes the way a whole class"},{"start":27.146,"end":28.488,"text":"reasons over a semester."},{"start":33.633,"end":35.499,"text":"The first question is typical of the"},{"start":35.499,"end":37.769,"text":"science of learning, and the second of the"},{"start":37.769,"end":38.676,"text":"learning sciences."},{"start":38.979,"end":41.097,"text":"To see why, it helps to follow how each"},{"start":41.097,"end":41.551,"text":"one grew."},{"start":43.407,"end":45.399,"text":"The learning sciences took shape around"},{"start":45.399,"end":47.541,"text":"nineteen ninety one, when the Journal of"},{"start":47.541,"end":49.335,"text":"the Learning Sciences and the first"},{"start":49.335,"end":51.178,"text":"international conference appeared,"},{"start":51.178,"end":52.722,"text":"building on a new institute at"},{"start":52.722,"end":53.918,"text":"Northwestern University."},{"start":54.817,"end":56.821,"text":"Its founders came largely from cognitive"},{"start":56.821,"end":58.923,"text":"science and artificial intelligence, but"},{"start":58.923,"end":60.781,"text":"they wanted to study learning in real"},{"start":60.781,"end":62.932,"text":"settings, and to learn by designing tools"},{"start":62.932,"end":63.763,"text":"and environments."},{"start":64.687,"end":66.687,"text":"In two thousand two, the International"},{"start":66.687,"end":68.687,"text":"Society of the Learning Sciences brought"},{"start":68.687,"end":70.833,"text":"the conferences and the journal together,"},{"start":70.833,"end":72.589,"text":"and in two thousand six a Cambridge"},{"start":72.589,"end":74.394,"text":"handbook gave the field a shared map."},{"start":76.337,"end":77.15,"text":"So why the s?"},{"start":77.525,"end":80.02799999999999,"text":"The name is plural because the field is"},{"start":80.02799999999999,"end":82.906,"text":"plural: cognitive science, educational"},{"start":82.906,"end":85.033,"text":"psychology, computer science,"},{"start":85.033,"end":87.911,"text":"anthropology, and more, each bringing its"},{"start":87.911,"end":88.661,"text":"own methods."},{"start":89.517,"end":91.589,"text":"Read the plural as a statement about"},{"start":91.589,"end":93.99799999999999,"text":"method: no single discipline owns the"},{"start":93.99799999999999,"end":95.175,"text":"question of learning."},{"start":95.511,"end":97.807,"text":"That is also why you will often hear the"},{"start":97.807,"end":100.21600000000001,"text":"learning sciences is, a plural name used"},{"start":100.21600000000001,"end":101.001,"text":"for one field."},{"start":102.987,"end":105.18299999999999,"text":"The science of learning grew along a"},{"start":105.18299999999999,"end":106.074,"text":"different path."},{"start":106.43,"end":108.686,"text":"In two thousand three, the National"},{"start":108.686,"end":111.06,"text":"Science Foundation announced Science of"},{"start":111.06,"end":113.672,"text":"Learning Centers, large centers that were"},{"start":113.672,"end":115.69,"text":"first funded in two thousand four."},{"start":116.547,"end":119.025,"text":"In two thousand nine, Andrew Meltzoff,"},{"start":119.025,"end":121.331,"text":"Patricia Kuhl, Javier Movellan, and"},{"start":121.331,"end":123.809,"text":"Terrence Sejnowski described a new science"},{"start":123.809,"end":126.172,"text":"of learning in the journal Science:"},{"start":126.172,"end":128.535,"text":"learning is computational, learning is"},{"start":128.535,"end":130.783,"text":"social, and it is supported by brain"},{"start":130.783,"end":133.031,"text":"circuits linking perception and action."},{"start":133.987,"end":136.007,"text":"Here the singular signals a goal of"},{"start":136.007,"end":138.308,"text":"convergence: several fields, from"},{"start":138.308,"end":140.497,"text":"psychology to neuroscience and machine"},{"start":140.497,"end":142.85399999999998,"text":"learning, working toward one account of"},{"start":142.85399999999998,"end":143.92000000000002,"text":"how learning works."},{"start":144.777,"end":147.673,"text":"For teachers, this tradition often arrives"},{"start":147.673,"end":150.569,"text":"as principles, like retrieval practice and"},{"start":150.569,"end":153.401,"text":"spacing, summarized in guides such as the"},{"start":153.401,"end":156.105,"text":"Deans for Impact report, The Science of"},{"start":156.105,"end":158.55,"text":"Learning, from two thousand fifteen."},{"start":160.453,"end":162.548,"text":"Put side by side, the science of learning"},{"start":162.548,"end":164.547,"text":"asks how learning works, mostly through"},{"start":164.547,"end":166.689,"text":"controlled experiments, while the learning"},{"start":166.689,"end":168.641,"text":"sciences ask how to make learning happen"},{"start":168.641,"end":170.688,"text":"in a real setting, mostly through design"},{"start":170.688,"end":171.688,"text":"and study in context."},{"start":172.583,"end":174.945,"text":"The science of learning usually studies"},{"start":174.945,"end":177.13,"text":"the individual mind and brain, and"},{"start":177.13,"end":178.784,"text":"produces general principles."},{"start":179.138,"end":181.5,"text":"The learning sciences study people with"},{"start":181.5,"end":184.275,"text":"tools, in groups and settings, and produce"},{"start":184.275,"end":186.519,"text":"designs with theories tied to context."},{"start":187.473,"end":188.903,"text":"Each one has a blind spot."},{"start":189.232,"end":191.211,"text":"A lab principle can fail in a noisy"},{"start":191.211,"end":193.575,"text":"classroom, and a classroom design can be"},{"start":193.575,"end":195.664,"text":"hard to generalize beyond the setting"},{"start":195.664,"end":196.434,"text":"where it grew."},{"start":198.387,"end":200.309,"text":"In practice the two traditions meet more"},{"start":200.309,"end":202.325,"text":"and more, and some of the best work sits"},{"start":202.325,"end":203.215,"text":"right between them."},{"start":204.977,"end":207.475,"text":"The Pittsburgh Science of Learning Center,"},{"start":207.475,"end":209.862,"text":"led by Kenneth Koedinger, ran controlled"},{"start":209.862,"end":212.305,"text":"experiments inside real courses, which it"},{"start":212.305,"end":213.804,"text":"called in vivo experiments."},{"start":214.90699999999998,"end":217.535,"text":"Another center, LIFE, studied learning in"},{"start":217.535,"end":219.877,"text":"informal and formal environments, from"},{"start":219.877,"end":221.534,"text":"homes and museums to schools."},{"start":222.517,"end":224.418,"text":"So a principle from the lab can become a"},{"start":224.418,"end":226.36599999999999,"text":"design conjecture in a classroom, and a"},{"start":226.36599999999999,"end":228.314,"text":"pattern noticed in a classroom can become"},{"start":228.314,"end":229.798,"text":"a hypothesis to test in the lab."},{"start":230.667,"end":233.56,"text":"For our two fraction researchers, that"},{"start":233.56,"end":236.382,"text":"means the spacing study could shape the"},{"start":236.382,"end":239.275,"text":"pizza activity, and the pizza activity"},{"start":239.275,"end":241.533,"text":"could reveal when spacing helps."},{"start":243.53,"end":245.552,"text":"For the discussion board, pick one claim"},{"start":245.552,"end":246.728,"text":"from this week's reading."},{"start":247.01,"end":249.032,"text":"Decide whether its evidence comes from the"},{"start":249.032,"end":250.725,"text":"science of learning or the learning"},{"start":250.725,"end":252.841,"text":"sciences, and ask what the other tradition"},{"start":252.841,"end":254.628,"text":"would want to see before believing it."}]},"NdaVj7XmiEU":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.12,"end":2.458,"text":"What does a design based research project"},{"start":2.458,"end":4.963,"text":"actually look like, from the first meeting"},{"start":4.963,"end":6.021,"text":"to the final paper?"},{"start":6.355,"end":8.582,"text":"This video walks through the journey,"},{"start":8.582,"end":10.976,"text":"stage by stage, with one running example."},{"start":12.86,"end":15.636,"text":"Most accounts share five broad stages:"},{"start":15.636,"end":17.781,"text":"ground the problem, prepare the"},{"start":17.781,"end":20.684,"text":"experiment, run design cycles, analyze in"},{"start":20.684,"end":23.081,"text":"retrospect, and report and redesign."},{"start":23.97,"end":26.671,"text":"The arrow back matters: each report feeds"},{"start":26.671,"end":27.533,"text":"the next cycle."},{"start":27.878,"end":30.291,"text":"Our example is an A I feedback tool for a"},{"start":30.291,"end":31.785,"text":"first year writing course."},{"start":35.893,"end":37.544,"text":"Stage one grounds the problem."},{"start":37.874,"end":40.571,"text":"You meet partners, observe, and interview,"},{"start":40.571,"end":42.717,"text":"and read the research, to learn what"},{"start":42.717,"end":44.643,"text":"actually happens to feedback today."},{"start":45.543,"end":47.489,"text":"You leave with a problem of practice"},{"start":47.489,"end":49.803,"text":"stated together with partners: here,"},{"start":49.803,"end":51.96,"text":"students read feedback but rarely revise"},{"start":51.96,"end":52.328,"text":"deeply."},{"start":54.207,"end":56.031,"text":"Stage two prepares the experiment."},{"start":56.353,"end":58.768,"text":"You set learning goals, describe students'"},{"start":58.768,"end":61.021,"text":"starting points, and write a high level"},{"start":61.021,"end":63.704,"text":"conjecture: feedback that asks a question,"},{"start":63.704,"end":66.012,"text":"instead of giving a fix, leads to deeper"},{"start":66.012,"end":66.495,"text":"revision."},{"start":67.337,"end":69.248,"text":"William Sandoval's conjecture map makes"},{"start":69.248,"end":71.35,"text":"this testable: the design's embodiment"},{"start":71.35,"end":73.404,"text":"should produce mediating processes you can"},{"start":73.404,"end":75.553,"text":"observe, which should lead to the outcomes"},{"start":75.553,"end":76.27,"text":"you care about."},{"start":77.247,"end":79.906,"text":"You also plan the data that will show each"},{"start":79.906,"end":82.751,"text":"arrow, such as drafts, tool logs, class"},{"start":82.751,"end":84.236,"text":"video, and interviews."},{"start":86.32300000000001,"end":88.557,"text":"Stage three runs the design in a real"},{"start":88.557,"end":88.968,"text":"course."},{"start":89.321,"end":91.907,"text":"Each full enactment is a macro cycle, and"},{"start":91.907,"end":94.435,"text":"inside it run many mini cycles of debriefs"},{"start":94.435,"end":95.61099999999999,"text":"and small revisions."},{"start":96.60300000000001,"end":98.697,"text":"Keep a design log of every change and why"},{"start":98.697,"end":100.441,"text":"you made it, because the changes"},{"start":100.441,"end":102.485,"text":"themselves are data about how the design"},{"start":102.485,"end":102.78399999999999,"text":"works."},{"start":104.843,"end":105.965,"text":"Stage four steps back."},{"start":106.27199999999999,"end":108.51599999999999,"text":"After the enactment ends, you analyze the"},{"start":108.51599999999999,"end":110.607,"text":"whole body of data systematically, not"},{"start":110.607,"end":112.137,"text":"just the moments you remember."},{"start":114.063,"end":116.47399999999999,"text":"You test each arrow of the conjecture map."},{"start":116.818,"end":119.458,"text":"In our example, students did write plans,"},{"start":119.458,"end":121.811,"text":"but deeper revision followed only when a"},{"start":121.811,"end":124.05,"text":"plan named a specific change, so the"},{"start":124.05,"end":125.829,"text":"conjecture itself gets revised."},{"start":129.407,"end":132.13400000000001,"text":"Stage five reports what was learned: a"},{"start":132.13400000000001,"end":134.737,"text":"humble theory of how the design worked,"},{"start":134.737,"end":137.34,"text":"design principles others can try, and a"},{"start":137.34,"end":139.385,"text":"better design for the next cycle."},{"start":140.347,"end":142.60399999999998,"text":"To be trusted, the report needs a clear"},{"start":142.60399999999998,"end":144.538,"text":"design narrative and claims tied to"},{"start":144.538,"end":146.956,"text":"evidence, and it generalizes by explaining"},{"start":146.956,"end":149.375,"text":"why the design worked, so others can judge"},{"start":149.375,"end":150.664,"text":"where it might transfer."},{"start":152.587,"end":154.81799999999998,"text":"For the discussion board, write a high"},{"start":154.81799999999998,"end":156.941,"text":"level conjecture for a project of your"},{"start":156.941,"end":159.391,"text":"own, sketch its conjecture map, and name"},{"start":159.391,"end":161.35,"text":"the data that would show each arrow."}]},"XN29cK9FYMY":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.12,"end":2.747,"text":"Design based research, educational design"},{"start":2.747,"end":5.075,"text":"research, and design and development"},{"start":5.075,"end":7.523,"text":"research all study learning by designing"},{"start":7.523,"end":8.12,"text":"something."},{"start":8.478,"end":10.866,"text":"This video compares where each one came"},{"start":10.866,"end":13.254,"text":"from, what it aims for, and what it"},{"start":13.254,"end":13.792,"text":"produces."},{"start":15.583,"end":17.607,"text":"Imagine a team building an A I feedback"},{"start":17.607,"end":19.48,"text":"tool for a first year writing course."},{"start":20.523,"end":22.746,"text":"They could ask how feedback timing shapes"},{"start":22.746,"end":24.809,"text":"revision, what design works in these"},{"start":24.809,"end":26.979,"text":"courses, or whether their design model"},{"start":26.979,"end":28.196,"text":"produced a usable tool."},{"start":33.333,"end":35.586,"text":"Roughly, the first leans toward design"},{"start":35.586,"end":37.563,"text":"based research, the second toward"},{"start":37.563,"end":40.036,"text":"educational design research, and the third"},{"start":40.036,"end":42.178,"text":"toward design and development research."},{"start":42.508,"end":44.925,"text":"All three share a core, but their centers"},{"start":44.925,"end":45.914,"text":"of gravity differ."},{"start":47.743,"end":50.018,"text":"Design based research grew in the learning"},{"start":50.018,"end":51.923,"text":"sciences, from Ann Brown's design"},{"start":51.923,"end":54.198,"text":"experiments and Allan Collins's call for a"},{"start":54.198,"end":56.261,"text":"design science of education, and was"},{"start":56.261,"end":58.43,"text":"popularized by the Design Based Research"},{"start":58.43,"end":60.176,"text":"Collective in two thousand three."},{"start":60.943,"end":62.746,"text":"Its hallmark is iteration in real"},{"start":62.746,"end":65.132,"text":"classrooms, where each version of a design"},{"start":65.132,"end":67.517,"text":"tests a conjecture about learning, and the"},{"start":67.517,"end":69.691,"text":"main contribution is a theory of how and"},{"start":69.691,"end":71.175,"text":"why learning happened there."},{"start":72.053,"end":73.878,"text":"Paul Cobb and colleagues called these"},{"start":73.878,"end":75.99,"text":"humble theories, because they are tied to"},{"start":75.99,"end":77.67099999999999,"text":"a domain and a setting rather than"},{"start":77.67099999999999,"end":79.015,"text":"claiming to hold everywhere."},{"start":80.953,"end":83,"text":"Educational design research is often used"},{"start":83,"end":85.04599999999999,"text":"as an umbrella term for this whole family."},{"start":85.339,"end":87.385,"text":"Susan McKenney and Thomas Reeves describe"},{"start":87.385,"end":89.383,"text":"it as solving a real problem in practice"},{"start":89.383,"end":91.381,"text":"while producing knowledge others can use."},{"start":92.283,"end":94.875,"text":"Its generic model has four phases, from"},{"start":94.875,"end":97.529,"text":"analysis and exploration to implementation"},{"start":97.529,"end":100.306,"text":"and spread, and it aims for two outputs at"},{"start":100.306,"end":103.083,"text":"once: an intervention that works, and"},{"start":103.083,"end":105.737,"text":"theoretical understanding, often written"},{"start":105.737,"end":107.033,"text":"as design principles."},{"start":110.55,"end":112.987,"text":"Design and development research comes from"},{"start":112.987,"end":115.02799999999999,"text":"instructional design and technology."},{"start":115.368,"end":117.805,"text":"Rita Richey and James Klein describe it as"},{"start":117.805,"end":119.733,"text":"the systematic study of design,"},{"start":119.733,"end":122,"text":"development, and evaluation processes."},{"start":122.95,"end":125.809,"text":"They distinguish two types: product and"},{"start":125.809,"end":128.731,"text":"tool research, which studies one product,"},{"start":128.731,"end":131.526,"text":"program, or tool, and model research,"},{"start":131.526,"end":134.13,"text":"which builds or validates a design model"},{"start":134.13,"end":134.829,"text":"or process."},{"start":135.92,"end":138.23,"text":"Here the knowledge produced is mainly"},{"start":138.23,"end":140.845,"text":"about designing and developing instruction"},{"start":140.845,"end":143.459,"text":"itself, so methods like expert review,"},{"start":143.459,"end":145.77,"text":"case studies, and Delphi panels are"},{"start":145.77,"end":146.195,"text":"common."},{"start":148.097,"end":150.769,"text":"Side by side, the differences are mostly"},{"start":150.769,"end":153.566,"text":"differences of emphasis: where each one"},{"start":153.566,"end":156.176,"text":"grew up, and what it treats as the main"},{"start":156.176,"end":156.984,"text":"contribution."},{"start":157.977,"end":160.21699999999998,"text":"Design based research puts a theory of"},{"start":160.21699999999998,"end":161.079,"text":"learning first."},{"start":161.424,"end":163.895,"text":"Educational design research puts a working"},{"start":163.895,"end":166.078,"text":"solution plus design principles first."},{"start":166.423,"end":168.779,"text":"Design and development research puts the"},{"start":168.779,"end":170.962,"text":"design process and its products first."},{"start":171.827,"end":174.482,"text":"What they share matters just as much:"},{"start":174.482,"end":177.26,"text":"iteration, real settings, design treated"},{"start":177.26,"end":179.236,"text":"as inquiry, and mixed methods."},{"start":181.397,"end":182.538,"text":"So how do you choose?"},{"start":182.864,"end":185.2,"text":"Ask what your main contribution will be,"},{"start":185.2,"end":186.831,"text":"and let that decide the frame."},{"start":188.777,"end":191.307,"text":"If it is a claim about how people learn,"},{"start":191.307,"end":192.897,"text":"design based research fits."},{"start":193.25,"end":195.722,"text":"If it is a solution to a practice problem"},{"start":195.722,"end":198.135,"text":"and its principles, educational design"},{"start":198.135,"end":198.959,"text":"research fits."},{"start":199.312,"end":202.196,"text":"If it is a design model, process, or tool,"},{"start":202.196,"end":204.374,"text":"design and development research fits."},{"start":205.387,"end":207.615,"text":"Whichever you choose, avoid the common"},{"start":207.615,"end":209.626,"text":"trap of only reporting that a design"},{"start":209.626,"end":210.006,"text":"worked."},{"start":210.332,"end":212.234,"text":"Design research also says what was"},{"start":212.234,"end":213.811,"text":"learned, and why it worked."},{"start":215.773,"end":218.129,"text":"For the discussion board, take one project"},{"start":218.129,"end":220.222,"text":"idea of your own and write its research"},{"start":220.222,"end":221.269,"text":"question three ways."},{"start":221.583,"end":223.46699999999998,"text":"Then decide which version you would"},{"start":223.46699999999998,"end":225.299,"text":"actually defend, and explain why."}]},"A0xi0-qjIMA":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.06,"end":2.456,"text":"The final part of this series is network"},{"start":2.456,"end":4.618,"text":"meta analysis, which compares many"},{"start":4.618,"end":7.13,"text":"treatments at once, even pairs that were"},{"start":7.13,"end":8.649,"text":"never tested head to head."},{"start":10.46,"end":13.005,"text":"Our example has 24 trials of four ways to"},{"start":13.005,"end":16.034,"text":"help people quit smoking: no contact, self"},{"start":16.034,"end":18.64,"text":"help, individual counseling, and group"},{"start":18.64,"end":19.306,"text":"counseling."},{"start":20.148,"end":22.984,"text":"Each line is a direct comparison, thicker"},{"start":22.984,"end":24.659,"text":"when more studies made it."},{"start":25.046,"end":27.624,"text":"Individual counseling versus no contact"},{"start":27.624,"end":30.073,"text":"was tested fifteen times, but group"},{"start":30.073,"end":32.651,"text":"counseling versus no contact only twice."},{"start":33.515,"end":35.826,"text":"Results are odds ratios, where a value"},{"start":35.826,"end":37.687,"text":"above one means more people quit."},{"start":39.493,"end":41.585,"text":"The key idea is indirect evidence."},{"start":41.954,"end":44.476,"text":"If we know how group counseling compares"},{"start":44.476,"end":46.814,"text":"with individual counseling, and how"},{"start":46.814,"end":49.213,"text":"individual counseling compares with no"},{"start":49.213,"end":51.674,"text":"contact, we can chain them to compare"},{"start":51.674,"end":53.704,"text":"group counseling with no contact."},{"start":54.55,"end":56.852,"text":"This rests on two assumptions:"},{"start":56.852,"end":59.218,"text":"transitivity, that the studies are"},{"start":59.218,"end":62.096000000000004,"text":"comparable, and consistency, that direct"},{"start":62.096000000000004,"end":63.887,"text":"and indirect evidence agree."},{"start":65.717,"end":68.322,"text":"Combining direct and indirect evidence,"},{"start":68.322,"end":70.989,"text":"every active treatment beats no contact on"},{"start":70.989,"end":71.485,"text":"average."},{"start":71.857,"end":74.09,"text":"Group counseling roughly doubles to"},{"start":74.09,"end":76.324,"text":"triples the odds of quitting, and"},{"start":76.324,"end":78.494,"text":"individual counseling doubles them."},{"start":79.324,"end":81.701,"text":"For self help, though, the interval"},{"start":81.701,"end":84.257,"text":"crosses one, so its benefit is uncertain."},{"start":85.1,"end":87.481,"text":"Heterogeneity is large, with I squared"},{"start":87.481,"end":89.979,"text":"near 89 percent, which is one reason the"},{"start":89.979,"end":91.082,"text":"intervals are wide."},{"start":97.12700000000001,"end":99.307,"text":"Take group versus individual counseling."},{"start":99.63499999999999,"end":101.924,"text":"Studies that compared them directly found"},{"start":101.924,"end":104.16,"text":"almost no difference, but the indirect"},{"start":104.16,"end":106.45,"text":"route suggests group counseling is better."},{"start":107.214,"end":110.15,"text":"That gap is not statistically clear on its"},{"start":110.15,"end":112.745,"text":"own, with p of zero point two eight."},{"start":113.155,"end":115.818,"text":"But across the whole network, a test"},{"start":115.818,"end":118.071,"text":"between study designs flags some"},{"start":118.071,"end":121.008,"text":"inconsistency, with p of zero point zero"},{"start":121.008,"end":124.081,"text":"three three, a warning to read the results"},{"start":124.081,"end":124.764,"text":"with care."},{"start":126.637,"end":128.808,"text":"Network meta analyses often rank the"},{"start":128.808,"end":129.454,"text":"treatments."},{"start":129.806,"end":132.388,"text":"Here group counseling ranks first, with a"},{"start":132.388,"end":134.325,"text":"P score of zero point eight four."},{"start":135.115,"end":137.103,"text":"But rankings hide uncertainty."},{"start":137.5,"end":139.952,"text":"Group and individual counseling have"},{"start":139.952,"end":142.736,"text":"heavily overlapping intervals, so first"},{"start":142.736,"end":144.857,"text":"and second place are not really"},{"start":144.857,"end":145.917,"text":"distinguishable."},{"start":147.827,"end":150.628,"text":"Report the shape of the network, how you"},{"start":150.628,"end":152.712,"text":"judged transitivity and checked"},{"start":152.712,"end":155.188,"text":"consistency, and effects with their"},{"start":155.188,"end":157.207,"text":"uncertainty before any ranking."},{"start":157.598,"end":160.334,"text":"That completes our step by step series on"},{"start":160.334,"end":161.246,"text":"meta analysis."}]},"xrfvYZc6XIY":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.06,"end":2.241,"text":"Part four repeats the random effects"},{"start":2.241,"end":4.894,"text":"analysis the Bayesian way, which answers a"},{"start":4.894,"end":6.426,"text":"question a p value cannot."},{"start":8.303,"end":11.295,"text":"In part two, the average effect was zero"},{"start":11.295,"end":14.148,"text":"point zero eight, with p of zero point"},{"start":14.148,"end":14.427,"text":"one."},{"start":14.844,"end":17.767,"text":"That tells us the data are not unusual if"},{"start":17.767,"end":19.576,"text":"the true effect were zero."},{"start":20.55,"end":22.922,"text":"It does not tell us how likely it is that"},{"start":22.922,"end":24.22,"text":"the effect is positive."},{"start":24.559,"end":25.801,"text":"Bayesian analysis can."},{"start":27.65,"end":29.612,"text":"Bayes' rule says the posterior is"},{"start":29.612,"end":31.69,"text":"proportional to the prior times the"},{"start":31.69,"end":34.229,"text":"likelihood: what we believed before,"},{"start":34.229,"end":36.134,"text":"updated by what the studies show."},{"start":36.947,"end":39.681,"text":"A prior is belief before the data, and a"},{"start":39.681,"end":41.525,"text":"posterior is belief after it."},{"start":43.427,"end":45.397,"text":"We need priors for two things."},{"start":45.791,"end":48.681,"text":"For tau, the spread of true effects, we"},{"start":48.681,"end":51.505,"text":"use a gentle half normal prior that allows"},{"start":51.505,"end":53.673,"text":"values from zero up to about one."},{"start":54.555,"end":56.967,"text":"After seeing the nineteen studies, the"},{"start":56.967,"end":59.497,"text":"posterior for tau concentrates around zero"},{"start":59.497,"end":62.145,"text":"point one four, very close to the estimate"},{"start":62.145,"end":62.852,"text":"in part two."},{"start":64.68299999999999,"end":67.673,"text":"For mu, the average effect, we use a very"},{"start":67.673,"end":70.403,"text":"wide prior, so the studies speak almost"},{"start":70.403,"end":71.963,"text":"entirely for themselves."},{"start":76.97,"end":80.078,"text":"The shaded area is the answer: about 94"},{"start":80.078,"end":82.90899999999999,"text":"percent of the posterior lies above zero."},{"start":83.32300000000001,"end":86.01599999999999,"text":"The effect is probably positive, but"},{"start":86.01599999999999,"end":88.986,"text":"small, and the data cannot rule out zero."},{"start":89.877,"end":92.432,"text":"The ninety five percent credible interval,"},{"start":92.432,"end":94.759,"text":"from minus zero point zero three to zero"},{"start":94.759,"end":97.2,"text":"point two one, can be read directly as a"},{"start":97.2,"end":99.69800000000001,"text":"probability statement, which a confidence"},{"start":99.69800000000001,"end":100.606,"text":"interval cannot."},{"start":102.42699999999999,"end":105.237,"text":"For a new, similar study, the Bayesian"},{"start":105.237,"end":107.982,"text":"predictive interval runs from about minus"},{"start":107.982,"end":110.596,"text":"zero point two eight to zero point four"},{"start":110.596,"end":113.47200000000001,"text":"seven, a little wider than in part two,"},{"start":113.47200000000001,"end":116.152,"text":"because uncertainty about tau is carried"},{"start":116.152,"end":116.675,"text":"through."},{"start":117.564,"end":120.137,"text":"With only nineteen studies, the prior for"},{"start":120.137,"end":122.419,"text":"tau can shift the results, so a good"},{"start":122.419,"end":124.759,"text":"Bayesian meta analysis reruns the model"},{"start":124.759,"end":127.157,"text":"with other reasonable priors and reports"},{"start":127.157,"end":128.503,"text":"how much things change."},{"start":130.327,"end":132.996,"text":"Report your priors and why, the posterior"},{"start":132.996,"end":135.362,"text":"summaries and probabilities, and how"},{"start":135.362,"end":137.364,"text":"sensitive they are to the priors."},{"start":137.728,"end":139.912,"text":"In the last part, we compare many"},{"start":139.912,"end":142.157,"text":"treatments at once with network meta"},{"start":142.157,"end":142.703,"text":"analysis."}]},"r_tqNkORPeo":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.06,"end":2.544,"text":"This is the final part of our series on"},{"start":2.544,"end":5.09,"text":"sequential analytics: hidden Markov"},{"start":5.09,"end":5.524,"text":"models."},{"start":5.897,"end":8.443,"text":"The idea is that the codes we see may be"},{"start":8.443,"end":10.367,"text":"driven by states we cannot see."},{"start":12.193,"end":15.106,"text":"In session P001, we observe one code per"},{"start":15.106,"end":15.445,"text":"turn."},{"start":15.851,"end":18.764,"text":"A hidden Markov model assumes that beneath"},{"start":18.764,"end":21.609,"text":"each code sits a hidden state, which we"},{"start":21.609,"end":23.167,"text":"never observe directly."},{"start":24.041,"end":26.667,"text":"For a beginner, think of a hidden state as"},{"start":26.667,"end":29.06,"text":"a mode the conversation is in, such as"},{"start":29.06,"end":31.394,"text":"questioning or explaining, that shows"},{"start":31.394,"end":33.844,"text":"itself only through the codes it tends to"},{"start":33.844,"end":34.311,"text":"produce."},{"start":36.093,"end":38.046,"text":"The model describes those unseen"},{"start":38.046,"end":39.82,"text":"influences with three sets of"},{"start":39.82,"end":40.648,"text":"probabilities."},{"start":41.461,"end":43.767,"text":"Initial probabilities say how sessions"},{"start":43.767,"end":44.122,"text":"start."},{"start":44.477,"end":46.664,"text":"Transition probabilities say how one"},{"start":46.664,"end":48.497,"text":"hidden state leads to the next."},{"start":48.852,"end":51.157,"text":"Emission probabilities say which codes"},{"start":51.157,"end":53.227,"text":"each hidden state tends to produce."},{"start":54.029,"end":56.366,"text":"The word emission simply means the code a"},{"start":56.366,"end":57.256,"text":"state gives off."},{"start":59.06,"end":61.391,"text":"The probabilities are estimated with the E"},{"start":61.391,"end":63.559,"text":"M algorithm, which alternates between"},{"start":63.559,"end":65.727,"text":"guessing the hidden states and updating"},{"start":65.727,"end":67.895,"text":"the probabilities until nothing changes."},{"start":68.67699999999999,"end":71.289,"text":"E M can stop at a local peak, so we start"},{"start":71.289,"end":73.01,"text":"it from twenty random places."},{"start":73.366,"end":76.037,"text":"For the 6 state model, every start reached"},{"start":76.037,"end":78.293,"text":"the same log likelihood, a sign the"},{"start":78.293,"end":79.42099999999999,"text":"solution is stable."},{"start":81.275,"end":83.754,"text":"How many hidden states should there be?"},{"start":84.135,"end":86.742,"text":"We fit models with two to ten states and"},{"start":86.742,"end":89.475,"text":"compare them with the Bayesian information"},{"start":89.475,"end":90.873,"text":"criterion, or B I C."},{"start":98.893,"end":100.614,"text":"B I C is lowest at 6 states."},{"start":100.983,"end":103.565,"text":"More states keep improving the raw fit,"},{"start":103.565,"end":106.148,"text":"but the penalty for extra parameters wins"},{"start":106.148,"end":106.824,"text":"after that."},{"start":108.693,"end":111.15100000000001,"text":"Here are the emissions of the 6 states."},{"start":111.529,"end":114.113,"text":"Each row is a state, and its strongest"},{"start":114.113,"end":116.445,"text":"cells tell us what that state mostly"},{"start":116.445,"end":119.09100000000001,"text":"produces: one state is almost always"},{"start":119.09100000000001,"end":121.675,"text":"explain, another almost always example."},{"start":122.55,"end":125.7,"text":"The transitions reveal something striking."},{"start":126.15,"end":129.075,"text":"The states fall into two closed groups"},{"start":129.075,"end":132.075,"text":"that never pass into each other: a"},{"start":132.075,"end":135.45,"text":"question and answer loop, and a chain from"},{"start":135.45,"end":137.85,"text":"explain to example to elaborate."},{"start":139.793,"end":142.836,"text":"For any session, the model can recover the"},{"start":142.836,"end":145.81,"text":"single most likely path of hidden states,"},{"start":145.81,"end":147.433,"text":"called the Viterbi path."},{"start":147.838,"end":150.678,"text":"Here it is for P001, one turn at a time."},{"start":156.06,"end":158.883,"text":"This session never leaves the chain group:"},{"start":158.883,"end":161.412,"text":"explain leads to example, and example to"},{"start":161.412,"end":163.117,"text":"elaborate, turn after turn."},{"start":164.927,"end":167.361,"text":"The model was never told which group each"},{"start":167.361,"end":168.404,"text":"session came from."},{"start":168.751,"end":171.011,"text":"Yet every control session stays in the"},{"start":171.011,"end":173.561,"text":"question and answer loop, while 38 of the"},{"start":173.561,"end":175.879,"text":"50 treatment sessions stay in the chain."},{"start":176.684,"end":179.034,"text":"So the hidden states sort the sessions in"},{"start":179.034,"end":181.385,"text":"a way that matches the real groups eighty"},{"start":181.385,"end":183.008,"text":"eight times out of a hundred."},{"start":184.81,"end":185.99,"text":"A word of caution."},{"start":186.383,"end":188.677,"text":"These data were simulated from two"},{"start":188.677,"end":191.233,"text":"ordinary Markov chains, one for each"},{"start":191.233,"end":193.658,"text":"group, with no hidden minds inside."},{"start":194.052,"end":196.214,"text":"The six states recover those two"},{"start":196.214,"end":199.29500000000002,"text":"processes, which is useful, but a state is"},{"start":199.29500000000002,"end":202.113,"text":"a modeling choice, not a discovery about"},{"start":202.113,"end":203.227,"text":"how people think."},{"start":205.127,"end":207.4,"text":"When you report a hidden Markov model,"},{"start":207.4,"end":209.895,"text":"state how the number of states was chosen,"},{"start":209.895,"end":212.28,"text":"whether the restarts agreed, and how the"},{"start":212.28,"end":214.054,"text":"states were labeled and checked."},{"start":215.827,"end":218.405,"text":"That completes the series: five lenses on"},{"start":218.405,"end":220.654,"text":"one stream of events, each answering a"},{"start":220.654,"end":222.79399999999998,"text":"different question about the same data."},{"start":223.123,"end":225.591,"text":"Pick the lens by your question, not by the"},{"start":225.591,"end":227.018,"text":"method that is in fashion."}]},"s0HYoN8dfIM":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.06,"end":2.755,"text":"This series explains meta analysis step by"},{"start":2.755,"end":5.073,"text":"step, starting from the statistics."},{"start":5.449,"end":8.144,"text":"Part one covers effect sizes, the common"},{"start":8.144,"end":10.65,"text":"currency that lets different studies be"},{"start":10.65,"end":11.214,"text":"combined."},{"start":13.103,"end":15.928,"text":"Our running example is a classic: nineteen"},{"start":15.928,"end":18.399,"text":"studies of whether teachers' expectations"},{"start":18.399,"end":20.812,"text":"raise pupils' I Q scores, collected by"},{"start":20.812,"end":21.93,"text":"Stephen Raudenbush."},{"start":22.71,"end":24.99,"text":"A meta analysis is a study of studies."},{"start":25.35,"end":27.99,"text":"Before we can combine them, we need every"},{"start":27.99,"end":30.33,"text":"study to report its result on the same"},{"start":30.33,"end":30.69,"text":"scale."},{"start":32.527,"end":35.095,"text":"The studies used different tests, so raw"},{"start":35.095,"end":37.304,"text":"score differences cannot be compared"},{"start":37.304,"end":37.842,"text":"directly."},{"start":38.2,"end":40.888,"text":"Instead, we divide the difference in means"},{"start":40.888,"end":42.858,"text":"by the pooled standard deviation."},{"start":43.734,"end":46.993,"text":"The result, d, says how far apart the two"},{"start":46.993,"end":49.968,"text":"groups are, in standard deviation units."},{"start":50.86,"end":52.907,"text":"The standard deviation works here as a"},{"start":52.907,"end":54.796,"text":"common ruler that every test shares."},{"start":56.593,"end":58.972,"text":"Rosenthal and Jacobson's famous study"},{"start":58.972,"end":60.913,"text":"reported d of zero point three."},{"start":61.288,"end":63.166,"text":"Picture the two groups' score"},{"start":63.166,"end":65.42,"text":"distributions and slide one by that"},{"start":65.42,"end":65.858,"text":"amount."},{"start":73.38,"end":75.348,"text":"The curves still overlap heavily."},{"start":75.705,"end":78.03,"text":"Yet about 62 percent of the expectancy"},{"start":78.03,"end":80.355,"text":"group scores above the average control"},{"start":80.355,"end":82.383,"text":"pupil, instead of fifty percent."},{"start":83.237,"end":85.243,"text":"Cohen's rough labels would call this"},{"start":85.243,"end":85.568,"text":"small."},{"start":85.894,"end":88.44200000000001,"text":"In education, though, context matters more"},{"start":88.44200000000001,"end":90.882,"text":"than labels, because a cheap change with a"},{"start":90.882,"end":92.94200000000001,"text":"small effect can still be worth a lot."},{"start":94.737,"end":97.22,"text":"In small samples, d slightly overstates"},{"start":97.22,"end":98.402,"text":"the true difference."},{"start":98.757,"end":101.239,"text":"Hedges' correction shrinks it a little,"},{"start":101.239,"end":103.072,"text":"giving an effect size called g."},{"start":103.945,"end":107.44800000000001,"text":"The shrinkage is small: about two percent"},{"start":107.44800000000001,"end":110.35499999999999,"text":"for a study of 33 pupils, and almost"},{"start":110.35499999999999,"end":111.547,"text":"nothing for 457."},{"start":112.423,"end":114.80799999999999,"text":"This is a correction for bias, a tilt in"},{"start":114.80799999999999,"end":117.027,"text":"one direction, rather than for random"},{"start":117.027,"end":117.36,"text":"noise."},{"start":119.137,"end":121.17,"text":"Every effect size also comes with a"},{"start":121.17,"end":123.429,"text":"variance, which depends mostly on the"},{"start":123.429,"end":124.163,"text":"sample sizes."},{"start":124.502,"end":126.648,"text":"Bigger groups give a smaller variance."},{"start":127.454,"end":129.92,"text":"For Rosenthal and Jacobson, with sixty"},{"start":129.92,"end":132.446,"text":"five and two hundred fifty five pupils,"},{"start":132.446,"end":134.972,"text":"the variance is about zero point zero one"},{"start":134.972,"end":135.273,"text":"nine."},{"start":136.1,"end":138.906,"text":"Its square root is the standard error, and"},{"start":138.906,"end":141.088,"text":"the ninety five percent confidence"},{"start":141.088,"end":143.644,"text":"interval runs from about zero point zero"},{"start":143.644,"end":145.576,"text":"three to zero point five seven."},{"start":147.47,"end":149.958,"text":"Now every study becomes an estimate with"},{"start":149.958,"end":150.686,"text":"an interval."},{"start":151.05,"end":153.537,"text":"Big studies have short intervals and big"},{"start":153.537,"end":156.14600000000002,"text":"squares; small studies have long ones."},{"start":156.987,"end":159.992,"text":"Compare Fleming and Anttonen, with 457"},{"start":159.992,"end":163.436,"text":"pupils, to Pellegrini and Hicks, with only"},{"start":163.436,"end":166.80700000000002,"text":"33: the larger study is far more precise."},{"start":173.917,"end":176.551,"text":"So each study enters a meta analysis as"},{"start":176.551,"end":179.251,"text":"two numbers: an effect size and its"},{"start":179.251,"end":179.844,"text":"variance."},{"start":180.239,"end":182.807,"text":"In part two, we use the variances to"},{"start":182.807,"end":185.442,"text":"decide how much each study should count."}]},"spTunL0povM":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.07,"end":2.653,"text":"In part one, each study became an effect"},{"start":2.653,"end":3.914,"text":"size with a variance."},{"start":4.275,"end":6.978,"text":"Part two asks how to combine them, and how"},{"start":6.978,"end":8.72,"text":"much each study should count."},{"start":10.583,"end":12.849,"text":"The standard answer is to weight each"},{"start":12.849,"end":15.412,"text":"study by the inverse of its variance, so"},{"start":15.412,"end":17.678,"text":"precise studies count more than noisy"},{"start":17.678,"end":17.976,"text":"ones."},{"start":19.77,"end":22.024,"text":"With these weights, the largest study"},{"start":22.024,"end":24.335,"text":"carries about 15 percent of the total,"},{"start":24.335,"end":26.701,"text":"while the smallest carries well under one"},{"start":26.701,"end":27.152,"text":"percent."},{"start":27.97,"end":30.674,"text":"If we assume every study estimates one and"},{"start":30.674,"end":33.504,"text":"the same true effect, the weighted average"},{"start":33.504,"end":36.208,"text":"is zero point zero six, with an interval"},{"start":36.208,"end":37.403,"text":"that includes zero."},{"start":42.407,"end":43.911,"text":"The Q test answers this."},{"start":44.287,"end":46.858,"text":"If only sampling noise were at work, Q"},{"start":46.858,"end":48.299,"text":"would be near eighteen."},{"start":48.676,"end":51.371,"text":"It is thirty five point eight, with p of"},{"start":51.371,"end":54.192,"text":"zero point zero zero seven: the studies"},{"start":54.192,"end":56.261,"text":"disagree more than chance allows."},{"start":59.07,"end":61.089,"text":"A random effects model drops that"},{"start":61.089,"end":61.742,"text":"assumption."},{"start":62.098,"end":64.354,"text":"Each study has its own true effect,"},{"start":64.354,"end":66.432,"text":"scattered around an average with a"},{"start":66.432,"end":68.985,"text":"standard deviation called tau, estimated"},{"start":68.985,"end":71.004,"text":"here at about zero point one four."},{"start":72.787,"end":75.488,"text":"Adding tau squared to every variance makes"},{"start":75.488,"end":78.439,"text":"the weights more equal: the largest study"},{"start":78.439,"end":80.952,"text":"now carries about 10 percent instead of"},{"start":80.952,"end":81.14,"text":"15."},{"start":83.017,"end":84.681,"text":"Here is the full forest plot."},{"start":85.025,"end":87.149,"text":"The blue diamond is the fixed effect"},{"start":87.149,"end":89.444,"text":"estimate, and the teal diamond is the"},{"start":89.444,"end":91.912,"text":"random effects estimate, zero point zero"},{"start":91.912,"end":94.265,"text":"eight four, with a wider interval that"},{"start":94.265,"end":95.412,"text":"still includes zero."},{"start":96.244,"end":98.11,"text":"The I squared statistic puts this"},{"start":98.11,"end":100.636,"text":"heterogeneity in proportion: about forty"},{"start":100.636,"end":102.997,"text":"two percent of the variation reflects real"},{"start":102.997,"end":104.53399999999999,"text":"differences between studies."},{"start":105.28,"end":107.646,"text":"The yellow line is the prediction"},{"start":107.646,"end":110.708,"text":"interval, from about minus zero point two"},{"start":110.708,"end":113.7,"text":"to plus zero point three seven: a new"},{"start":113.7,"end":116.761,"text":"study's true effect could be negative, or"},{"start":116.761,"end":118.15299999999999,"text":"moderately positive."},{"start":120.05,"end":122.077,"text":"Report the model and how tau was"},{"start":122.077,"end":124.658,"text":"estimated, the pooled estimate with its"},{"start":124.658,"end":127.545,"text":"interval, and the heterogeneity, including"},{"start":127.545,"end":129.02,"text":"the prediction interval."},{"start":129.388,"end":131.968,"text":"In part three, we ask why these studies"},{"start":131.968,"end":132.52100000000002,"text":"disagree."}]},"9gPGEZsnIPg":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.07,"end":2.81,"text":"In part two, the studies disagreed more"},{"start":2.81,"end":4.05,"text":"than chance allows."},{"start":4.441,"end":7.116,"text":"Part three asks why they disagree, and"},{"start":7.116,"end":9.269,"text":"whether some results are missing."},{"start":11.16,"end":12.698,"text":"Raudenbush had a hypothesis."},{"start":13.028,"end":15.225,"text":"Telling teachers that some pupils would"},{"start":15.225,"end":17.587,"text":"bloom should matter most when the teachers"},{"start":17.587,"end":19.07,"text":"barely knew the pupils yet."},{"start":19.898,"end":22.521,"text":"Each bubble is a study, placed by how many"},{"start":22.521,"end":24.969,"text":"weeks the teachers had known the class,"},{"start":24.969,"end":26.368,"text":"and sized by its weight."},{"start":32.376,"end":34.545,"text":"The large positive effects all come from"},{"start":34.545,"end":36.503,"text":"studies where teachers had known the"},{"start":36.503,"end":37.878,"text":"pupils for a week or less."},{"start":38.633,"end":40.897,"text":"A study feature that changes the size of"},{"start":40.897,"end":43.217,"text":"an effect, like this one, is called a"},{"start":43.217,"end":45.591,"text":"moderator, and it can be tested formally."},{"start":47.383,"end":49.806,"text":"Splitting the studies tells a clear story."},{"start":50.152,"end":52.344,"text":"With a week or less of contact, the"},{"start":52.344,"end":54.709,"text":"average effect is about zero point three"},{"start":54.709,"end":55.055,"text":"seven."},{"start":55.401,"end":57.939,"text":"With two weeks or more, it is essentially"},{"start":57.939,"end":58.227,"text":"zero."},{"start":59.001,"end":61.176,"text":"A meta regression with this moderator"},{"start":61.176,"end":63.008,"text":"explains essentially all of the"},{"start":63.008,"end":65.583,"text":"heterogeneity: the leftover tau squared"},{"start":65.583,"end":66.728,"text":"drops to about zero."},{"start":67.489,"end":70.252,"text":"One caution: studies were not randomly"},{"start":70.252,"end":72.953,"text":"assigned to their moderator values, so a"},{"start":72.953,"end":75.653,"text":"moderator finding is an association across"},{"start":75.653,"end":77.662,"text":"studies, not proof of a cause."},{"start":79.56,"end":81.92699999999999,"text":"To check for missing results, we draw a"},{"start":81.92699999999999,"end":84.631,"text":"funnel plot: big, precise studies at the"},{"start":84.631,"end":86.773,"text":"top, small ones spreading out below."},{"start":87.111,"end":89.30799999999999,"text":"Without bias, the points should look"},{"start":89.30799999999999,"end":89.872,"text":"symmetric."},{"start":90.678,"end":93.493,"text":"Here the small studies lean to the right,"},{"start":93.493,"end":95.988,"text":"and Egger's regression test flags that"},{"start":95.988,"end":98.738,"text":"asymmetry, with p of zero point zero one"},{"start":98.738,"end":98.994,"text":"two."},{"start":99.805,"end":101.957,"text":"Trim and fill imagines the 3 missing"},{"start":101.957,"end":104.458,"text":"studies that would restore symmetry, and"},{"start":104.458,"end":106.726,"text":"the adjusted estimate shrinks to about"},{"start":106.726,"end":108.006,"text":"zero point zero three."},{"start":108.793,"end":110.45400000000001,"text":"Notice the colors, though."},{"start":110.81,"end":113.47999999999999,"text":"The small, positive studies are mostly the"},{"start":113.47999999999999,"end":116.031,"text":"early contact ones, so the asymmetry may"},{"start":116.031,"end":118.523,"text":"reflect the moderator rather than missing"},{"start":118.523,"end":118.99799999999999,"text":"studies."},{"start":119.354,"end":121.787,"text":"Funnel asymmetry has more than one cause."},{"start":123.66,"end":125.947,"text":"Report which moderators you planned to"},{"start":125.947,"end":128.704,"text":"test, how much heterogeneity they explain,"},{"start":128.704,"end":131.049,"text":"and how you checked for missing studies."},{"start":131.401,"end":133.806,"text":"In part four, we redo the analysis the"},{"start":133.806,"end":134.568,"text":"Bayesian way."}]},"k9izMqIyRXw":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.06,"end":2.315,"text":"Here is a question calculus was built to"},{"start":2.315,"end":2.7,"text":"answer."},{"start":3.158,"end":5.384,"text":"Take a pair of axes, and draw the curve x"},{"start":5.384,"end":6.244,"text":"squared over two."},{"start":6.665,"end":9.01,"text":"How much space lies under it, from zero to"},{"start":9.01,"end":9.322,"text":"three?"},{"start":9.753,"end":12.151,"text":"Curves are hard, but rectangles are easy."},{"start":12.486,"end":14.828,"text":"Fill the region with three of them, and"},{"start":14.828,"end":15.888,"text":"add up their areas."},{"start":16.37,"end":18.315,"text":"Make them thinner, and the gaps shrink."},{"start":19.043,"end":21.482,"text":"Thinner still, and the sum creeps closer."},{"start":21.901,"end":24.367,"text":"In the limit, the rectangles become the"},{"start":24.367,"end":26.658,"text":"curve itself, and the sum becomes an"},{"start":26.658,"end":28.948,"text":"integral: exactly four and a half."},{"start":29.398,"end":31.88,"text":"The area under a curve is just infinitely"},{"start":31.88,"end":33.593,"text":"many thin slices, added up."}]},"dqrWUnItTi4":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.06,"end":2.411,"text":"This is part three of our series on"},{"start":2.411,"end":5.415,"text":"sequential analytics: transition network"},{"start":5.415,"end":8.354,"text":"analysis, or T N A, with a focus on what"},{"start":8.354,"end":10.966,"text":"each number means and how reliable each"},{"start":10.966,"end":11.488,"text":"edge is."},{"start":13.297,"end":15.58,"text":"Transition network analysis starts from"},{"start":15.58,"end":18.035,"text":"the same lag one transitions we counted in"},{"start":18.035,"end":20.319,"text":"part one, four thousand thirty six of"},{"start":20.319,"end":20.604,"text":"them."},{"start":21.404,"end":23.889,"text":"Instead of comparing counts with chance,"},{"start":23.889,"end":26.489,"text":"it divides each row by its total, so every"},{"start":26.489,"end":28.8,"text":"row becomes a set of probabilities that"},{"start":28.8,"end":29.667,"text":"adds up to one."},{"start":30.431,"end":32.919,"text":"So ask is followed by explain with a"},{"start":32.919,"end":35.879,"text":"probability of zero point five three, the"},{"start":35.879,"end":37.897,"text":"same value we saw in part one."},{"start":38.768,"end":41.407,"text":"This is a first order Markov model: the"},{"start":41.407,"end":43.928,"text":"next code is assumed to depend only on the"},{"start":43.928,"end":46.216,"text":"current one, not on anything earlier."},{"start":48.005,"end":50.614,"text":"Drawn as a network, each code is a node,"},{"start":50.614,"end":53.106,"text":"and each transition is an arrow, thicker"},{"start":53.106,"end":54.439,"text":"when it is more likely."},{"start":54.787,"end":57.048,"text":"The rings show a code following itself."},{"start":57.872,"end":60.783,"text":"The strongest path is ask to explain, at"},{"start":60.783,"end":63.829,"text":"zero point five three, followed by example"},{"start":63.829,"end":67.01,"text":"to elaborate, at zero point three six, and"},{"start":67.01,"end":69.92,"text":"explain back to ask, at zero point three"},{"start":69.92,"end":70.326,"text":"three."},{"start":71.229,"end":73.734,"text":"The model also records how sessions begin:"},{"start":73.734,"end":75.926,"text":"fifty four percent of them start with ask."},{"start":76.666,"end":79.072,"text":"Centrality measures summarize the role of"},{"start":79.072,"end":81.592,"text":"each node, and explain has the highest in"},{"start":81.592,"end":84.112,"text":"strength, one point two one, because it"},{"start":84.112,"end":86.345,"text":"receives the most probability from the"},{"start":86.345,"end":87.032,"text":"other codes."},{"start":88.804,"end":90.262,"text":"Is each edge reliable?"},{"start":90.66,"end":93.444,"text":"T N A resamples the sessions one thousand"},{"start":93.444,"end":96.295,"text":"times, refits the model each time, and"},{"start":96.295,"end":98.416,"text":"checks how much each edge moves."},{"start":99.301,"end":101.86099999999999,"text":"An edge is called stable when its weight"},{"start":101.86099999999999,"end":104.42099999999999,"text":"stays within seventy five to one hundred"},{"start":104.42099999999999,"end":106.669,"text":"twenty five percent of the original."},{"start":107.043,"end":109.479,"text":"Twenty three of twenty five edges pass."},{"start":109.85300000000001,"end":112.663,"text":"The two that do not are weak edges, ask to"},{"start":112.663,"end":114.536,"text":"example and example to itself."},{"start":115.378,"end":117.713,"text":"The bootstrap also gives intervals."},{"start":118.114,"end":120.65,"text":"For ask to explain, the ninety five"},{"start":120.65,"end":123.519,"text":"percent interval runs from zero point four"},{"start":123.519,"end":125.387,"text":"nine to zero point five six."},{"start":127.266,"end":130.359,"text":"To compare groups, T N A fits one network"},{"start":130.359,"end":133.24099999999999,"text":"per group, using the same nodes in the"},{"start":133.24099999999999,"end":134.084,"text":"same places."},{"start":134.953,"end":137.663,"text":"The largest difference is explain followed"},{"start":137.663,"end":140.69,"text":"by ask: zero point five zero in control,"},{"start":140.69,"end":143.274,"text":"but only zero point one one in treatment."},{"start":145.09,"end":147.672,"text":"A permutation test shuffles whole sessions"},{"start":147.672,"end":150.13400000000001,"text":"between the groups one thousand times,"},{"start":150.13400000000001,"end":152.837,"text":"refits both networks, and asks how often a"},{"start":152.837,"end":155.239,"text":"difference this large appears by chance."},{"start":156.036,"end":158.559,"text":"Seventeen of twenty five edges differ at p"},{"start":158.559,"end":160.788,"text":"below zero point zero five, and all"},{"start":160.788,"end":162.841,"text":"seventeen remain after a Benjamini"},{"start":162.841,"end":164.014,"text":"Hochberg correction."},{"start":164.863,"end":167.648,"text":"With one thousand shuffles, the smallest p"},{"start":167.648,"end":170.123,"text":"value the test can report is about zero"},{"start":170.123,"end":172.845,"text":"point zero zero one, so use more shuffles"},{"start":172.845,"end":174.392,"text":"if you need finer values."},{"start":176.261,"end":178.434,"text":"When you report a transition network"},{"start":178.434,"end":180.725,"text":"analysis, state how transitions were"},{"start":180.725,"end":183.309,"text":"counted, the probabilities and how stable"},{"start":183.309,"end":185.482,"text":"each edge was, and how groups were"},{"start":185.482,"end":187.773,"text":"compared, under a first order Markov"},{"start":187.773,"end":188.419,"text":"assumption."},{"start":189.238,"end":191.36599999999999,"text":"Next in the series is ordered network"},{"start":191.36599999999999,"end":193.718,"text":"analysis, which looks back over a wider"},{"start":193.718,"end":194.11,"text":"window."},{"start":194.446,"end":196.798,"text":"The companion guide has the code for this"},{"start":196.798,"end":197.582,"text":"analysis in R."}]},"0P0xOb9frbA":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.07,"end":2.771,"text":"This is part one of a series on sequential"},{"start":2.771,"end":3.4,"text":"analytics."},{"start":3.777,"end":6.604,"text":"We begin with lag sequential analysis, the"},{"start":6.604,"end":9.242,"text":"approach popularized by Roger Bakeman and"},{"start":9.242,"end":12.006,"text":"his colleagues, with a focus on what each"},{"start":12.006,"end":12.823,"text":"number means."},{"start":14.667,"end":17.127,"text":"Lag sequential analysis asks a simple"},{"start":17.127,"end":20.365,"text":"question: given one code, how often does a"},{"start":20.365,"end":22.048,"text":"particular code come next?"},{"start":23.915,"end":25.818,"text":"The data points are transitions."},{"start":26.175,"end":28.673,"text":"Each pair of neighboring turns is one lag"},{"start":28.673,"end":31.052,"text":"one transition, counted only within a"},{"start":31.052,"end":31.528,"text":"session."},{"start":32.312,"end":34.925,"text":"So four thousand one hundred thirty six"},{"start":34.925,"end":37.538,"text":"turns in one hundred sessions give four"},{"start":37.538,"end":40.347,"text":"thousand thirty six transitions, because"},{"start":40.347,"end":42.895,"text":"no transition crosses from one session"},{"start":42.895,"end":43.81,"text":"into the next."},{"start":45.64,"end":48.124,"text":"Tallying them gives a five by five table:"},{"start":48.124,"end":50.186,"text":"the rows are the given code, and the"},{"start":50.186,"end":52.142,"text":"columns are the code that comes next."},{"start":52.938,"end":55.385,"text":"Ask was followed by explain four hundred"},{"start":55.385,"end":57.952,"text":"seventy eight times, out of nine hundred"},{"start":57.952,"end":60.22,"text":"six transitions that started with ask."},{"start":60.578,"end":63.145,"text":"That is a transitional probability of zero"},{"start":63.145,"end":64.159,"text":"point five three."},{"start":65.026,"end":67.205,"text":"But explain is common in general: it"},{"start":67.205,"end":69.281,"text":"follows about twenty six percent of all"},{"start":69.281,"end":69.592,"text":"turns."},{"start":69.904,"end":72.084,"text":"A high probability alone does not tell us"},{"start":72.084,"end":73.744,"text":"whether the sequence is special."},{"start":75.464,"end":78.021,"text":"So we ask what independence would predict."},{"start":78.386,"end":80.944,"text":"The expected count is the row total times"},{"start":80.944,"end":83.075,"text":"the column total, divided by all"},{"start":83.075,"end":85.693,"text":"transitions: about two hundred thirty"},{"start":85.693,"end":86.05799999999999,"text":"eight."},{"start":86.92,"end":89.592,"text":"Bakeman and Quera recommend the adjusted"},{"start":89.592,"end":92.26400000000001,"text":"residual, which scales the gap between"},{"start":92.26400000000001,"end":94.74000000000001,"text":"observed and expected by its standard"},{"start":94.74000000000001,"end":95.131,"text":"error."},{"start":95.52199999999999,"end":98.259,"text":"For ask then explain, z is twenty point"},{"start":98.259,"end":98.519,"text":"six."},{"start":99.337,"end":101.733,"text":"Doing this for every cell gives a map of"},{"start":101.733,"end":104.069,"text":"which transitions occur more often than"},{"start":104.069,"end":106.757,"text":"chance, in red, and less often, in blue."},{"start":108.58500000000001,"end":111.413,"text":"With twenty five cells, some will pass one"},{"start":111.413,"end":113.36099999999999,"text":"point nine six by chance alone."},{"start":113.738,"end":114.869,"text":"Eighteen cells do."},{"start":115.24600000000001,"end":117.949,"text":"With a Bonferroni criterion of three point"},{"start":117.949,"end":119.708,"text":"zero nine, sixteen remain."},{"start":121.582,"end":123.749,"text":"There is one important catch in this"},{"start":123.749,"end":124.1,"text":"table."},{"start":124.451,"end":126.793,"text":"It pools four thousand transitions from"},{"start":126.793,"end":128.901,"text":"one hundred sessions, as if every"},{"start":128.901,"end":131.536,"text":"transition were independent, and with that"},{"start":131.536,"end":133.468,"text":"many, almost any pattern looks"},{"start":133.468,"end":134.171,"text":"significant."},{"start":134.959,"end":137.531,"text":"Bakeman and colleagues therefore suggest"},{"start":137.531,"end":140.29,"text":"computing an index for each session, such"},{"start":140.29,"end":143.05,"text":"as Yule's Q, which runs from minus one to"},{"start":143.05,"end":145.12,"text":"plus one, with zero meaning no"},{"start":145.12,"end":145.873,"text":"association."},{"start":147.716,"end":150.034,"text":"Now each session contributes one number."},{"start":150.382,"end":152.75900000000001,"text":"Ask followed by explain is clearly above"},{"start":152.75900000000001,"end":153.918,"text":"zero in both groups."},{"start":154.774,"end":157.40699999999998,"text":"Comparing the groups tells a quieter"},{"start":157.40699999999998,"end":157.834,"text":"story."},{"start":158.261,"end":161.393,"text":"The control mean is zero point six three,"},{"start":161.393,"end":164.383,"text":"and the treatment mean is zero point five"},{"start":164.383,"end":167.514,"text":"three, a Welch t of one point nine two,"},{"start":167.514,"end":170.077,"text":"with p of zero point zero five nine."},{"start":170.942,"end":173.251,"text":"The pooled z scores, fifteen point nine"},{"start":173.251,"end":175.505,"text":"and eleven point four, would have made"},{"start":175.505,"end":177.869,"text":"this difference look far more certain than"},{"start":177.869,"end":178.199,"text":"it is."},{"start":178.528,"end":180.947,"text":"The session, not the transition, is the"},{"start":180.947,"end":181.992,"text":"unit for inference."},{"start":183.78,"end":186.431,"text":"When you report a lag sequential analysis,"},{"start":186.431,"end":188.72899999999998,"text":"state the lag and how transitions were"},{"start":188.72899999999998,"end":191.381,"text":"counted, the residuals and how you handled"},{"start":191.381,"end":193.855,"text":"many cells, and the session level index"},{"start":193.855,"end":195.446,"text":"you used to compare groups."},{"start":196.267,"end":198.721,"text":"Next in the series is sequential pattern"},{"start":198.721,"end":201.236,"text":"mining, which looks beyond a single lag."},{"start":201.595,"end":204.109,"text":"The companion guide has the code for this"},{"start":204.109,"end":204.947,"text":"analysis in R."}]},"V5HiWnlkp5E":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.07,"end":2.182,"text":"This video explains ordered network"},{"start":2.182,"end":4.822,"text":"analysis, or O N A, with a focus on what"},{"start":4.822,"end":7.169,"text":"each number means and which data points"},{"start":7.169,"end":8.108,"text":"stand behind it."},{"start":9.957,"end":12.674,"text":"O N A starts from an event log, with one"},{"start":12.674,"end":15.517,"text":"coded turn per row, ordered in time within"},{"start":15.517,"end":16.338,"text":"each session."},{"start":17.154,"end":19.607,"text":"Here we have four thousand one hundred"},{"start":19.607,"end":21.871,"text":"thirty six turns, but one hundred"},{"start":21.871,"end":22.437,"text":"sessions."},{"start":22.814,"end":25.582,"text":"Each session is one unit of analysis, and"},{"start":25.582,"end":27.972,"text":"it will become one point in the final"},{"start":27.972,"end":28.286,"text":"plot."},{"start":30.161,"end":33.054,"text":"The most important setting is the window:"},{"start":33.054,"end":35.639,"text":"each turn is treated as a response, and"},{"start":35.639,"end":38.101,"text":"the four turns before it are its ground."},{"start":38.889,"end":41.34,"text":"For every ground code, the model adds one"},{"start":41.34,"end":43.736,"text":"count to a directed connection, from the"},{"start":43.736,"end":45.574,"text":"ground code to the response code."},{"start":47.325,"end":49.394,"text":"Sliding the window across the whole"},{"start":49.394,"end":52.151,"text":"session fills a five by five table: twenty"},{"start":52.151,"end":54.507,"text":"five directed connections, including a"},{"start":54.507,"end":55.771,"text":"code following itself."},{"start":56.622,"end":59.099,"text":"Order is what makes the network ordered."},{"start":59.471,"end":62.071,"text":"Agree followed by elaborate and elaborate"},{"start":62.071,"end":64.858,"text":"followed by agree are separate cells, with"},{"start":64.858,"end":66.901,"text":"12 and 18 counts in this session."},{"start":68.75,"end":70.945,"text":"Longer sessions produce larger counts."},{"start":71.292,"end":73.66,"text":"So each session's twenty five counts are"},{"start":73.66,"end":75.855,"text":"divided by the length of that list of"},{"start":75.855,"end":78.282,"text":"counts, the square root of their summed"},{"start":78.282,"end":78.744,"text":"squares."},{"start":79.56700000000001,"end":81.828,"text":"The counts become weights, and every"},{"start":81.828,"end":84.379,"text":"session now has the same total length, so"},{"start":84.379,"end":86.582,"text":"sessions are compared by the shape of"},{"start":86.582,"end":89.017,"text":"their connections, not by how long they"},{"start":89.017,"end":89.249,"text":"ran."},{"start":91.044,"end":93.189,"text":"A singular value decomposition then"},{"start":93.189,"end":95.691,"text":"reduces the twenty five dimensions to two"},{"start":95.691,"end":95.989,"text":"axes."},{"start":96.34700000000001,"end":97.777,"text":"Each dot is one session."},{"start":98.582,"end":101.194,"text":"The first axis captures 52 percent of the"},{"start":101.194,"end":103.557,"text":"variance, and the second 11 percent."},{"start":103.93,"end":106.729,"text":"The codes are placed in the same space, so"},{"start":106.729,"end":109.27799999999999,"text":"a session's dot sits toward the codes it"},{"start":109.27799999999999,"end":110.149,"text":"connects most."},{"start":110.989,"end":113.239,"text":"The squares are the treatment mean and the"},{"start":113.239,"end":115.384,"text":"control mean, with ninety five percent"},{"start":115.384,"end":116.483,"text":"confidence intervals."},{"start":116.797,"end":118.89,"text":"The two groups sit on opposite sides of"},{"start":118.89,"end":119.675,"text":"the first axis."},{"start":120.437,"end":122.891,"text":"Averaging the weights within each group"},{"start":122.891,"end":124.18,"text":"gives a mean network."},{"start":124.548,"end":126.695,"text":"The subtracted network shows their"},{"start":126.695,"end":129.457,"text":"difference: teal arrows are stronger in"},{"start":129.457,"end":132.218,"text":"treatment, and gold arrows are stronger in"},{"start":132.218,"end":132.709,"text":"control."},{"start":133.554,"end":136.386,"text":"In treatment, example leads to elaborate"},{"start":136.386,"end":137.439,"text":"much more often."},{"start":137.834,"end":140.14,"text":"In control, explain leads to ask."},{"start":140.535,"end":143.301,"text":"These are differences in structure, not"},{"start":143.301,"end":144.289,"text":"just in volume."},{"start":146.162,"end":148.238,"text":"To test the separation, take each"},{"start":148.238,"end":150.372,"text":"session's position on the first axis."},{"start":150.718,"end":152.96699999999998,"text":"The treatment mean is minus zero point"},{"start":152.96699999999998,"end":155.447,"text":"three five, and the control mean is plus"},{"start":155.447,"end":156.716,"text":"zero point three five."},{"start":157.54,"end":160.347,"text":"A Welch t test on that axis gives t of"},{"start":160.347,"end":163.515,"text":"twenty point one, p well below zero point"},{"start":163.515,"end":166.46699999999998,"text":"zero zero one, and a Cohen's d of four"},{"start":166.46699999999998,"end":168.914,"text":"point zero, a very large effect."},{"start":169.346,"end":172.442,"text":"On the second axis, d is only zero point"},{"start":172.442,"end":175.538,"text":"two seven, with p of zero point one nine."},{"start":176.426,"end":178.139,"text":"A permutation test makes fewer"},{"start":178.139,"end":178.802,"text":"assumptions."},{"start":179.133,"end":181.509,"text":"Shuffle the condition labels five thousand"},{"start":181.509,"end":183.94,"text":"times, recompute the distance between the"},{"start":183.94,"end":186.094,"text":"two means each time, and compare the"},{"start":186.094,"end":187.807,"text":"observed distance to that null"},{"start":187.807,"end":188.525,"text":"distribution."},{"start":189.303,"end":191.855,"text":"The observed distance of zero point seven"},{"start":191.855,"end":194.224,"text":"is far beyond anything chance produced."},{"start":194.589,"end":197.07999999999998,"text":"Keep in mind that these synthetic groups"},{"start":197.07999999999998,"end":199.632,"text":"were built to differ, so real data will"},{"start":199.632,"end":201.029,"text":"rarely look this clean."},{"start":202.881,"end":205.242,"text":"When you report ordered network analysis,"},{"start":205.242,"end":207.442,"text":"state the unit and the window, how the"},{"start":207.442,"end":209.803,"text":"counts were normalized and projected, and"},{"start":209.803,"end":212.164,"text":"how the group difference was tested, with"},{"start":212.164,"end":212.969,"text":"an effect size."},{"start":213.75900000000001,"end":216.167,"text":"The companion guide runs the same model in"},{"start":216.167,"end":216.279,"text":"R."},{"start":216.614,"end":218.85399999999998,"text":"Try a smaller or a larger window, and"},{"start":218.85399999999998,"end":220.53300000000002,"text":"watch how the network changes."}]},"KHzwP0eMwTk":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.06,"end":2.285,"text":"This video explains sequential pattern"},{"start":2.285,"end":4.738,"text":"mining, with a focus on what each number"},{"start":4.738,"end":7.077,"text":"means and which data points stand behind"},{"start":7.077,"end":7.248,"text":"it."},{"start":9.068,"end":11.295,"text":"Everything starts from an event log."},{"start":11.666,"end":14.635,"text":"Each row is one coded turn: a session, a"},{"start":14.635,"end":17.047,"text":"turn number, a speaker, and a code."},{"start":17.885,"end":19.93,"text":"Sorting the rows by turn turns each"},{"start":19.93,"end":22.033,"text":"session into one ordered sequence of"},{"start":22.033,"end":22.374,"text":"codes."},{"start":23.172,"end":25.531,"text":"In our synthetic example there are four"},{"start":25.531,"end":27.772,"text":"thousand one hundred thirty six coded"},{"start":27.772,"end":30.425,"text":"turns, but only one hundred sessions:"},{"start":30.425,"end":32.902,"text":"fifty in a treatment group and fifty in a"},{"start":32.902,"end":33.728,"text":"control group."},{"start":34.53,"end":36.053,"text":"That difference matters."},{"start":36.434,"end":39.227,"text":"In pattern mining, the session, not the"},{"start":39.227,"end":41.639,"text":"turn, is the unit that gets counted."},{"start":43.457,"end":46.692,"text":"To see how counting works, take five short"},{"start":46.692,"end":50.36,"text":"sessions, and one candidate pattern: ask,"},{"start":50.36,"end":52.445,"text":"then explain, then example."},{"start":53.394,"end":55.556,"text":"A session contains the pattern if the"},{"start":55.556,"end":57.889,"text":"three codes appear in that order, even"},{"start":57.889,"end":59.481,"text":"with other turns in between."},{"start":59.823,"end":62.098,"text":"Sessions one, two, and five qualify."},{"start":62.44,"end":64.203,"text":"Sessions three and four do not."},{"start":64.982,"end":67.492,"text":"Session two contains the pattern twice,"},{"start":67.492,"end":69.284,"text":"but it still counts only once."},{"start":70.11,"end":72.478,"text":"So the support of the pattern is three out"},{"start":72.478,"end":74.57,"text":"of five sessions, or zero point six."},{"start":76.31700000000001,"end":78.902,"text":"Support describes how common a pattern is."},{"start":79.271,"end":82.226,"text":"Confidence asks a conditional question: of"},{"start":82.226,"end":84.872,"text":"the sessions with ask then explain, what"},{"start":84.872,"end":86.47200000000001,"text":"share go on to an example?"},{"start":86.842,"end":88.688,"text":"Here, zero point seven five."},{"start":89.544,"end":91.73400000000001,"text":"But a high confidence can mislead."},{"start":92.12100000000001,"end":94.697,"text":"An example appears in eighty percent of"},{"start":94.697,"end":97.14500000000001,"text":"all sessions anyway, so the lift,"},{"start":97.14500000000001,"end":99.91499999999999,"text":"confidence divided by that base rate, is"},{"start":99.91499999999999,"end":101.654,"text":"about zero point nine four."},{"start":102.041,"end":104.811,"text":"Ask and explain do not make an example any"},{"start":104.811,"end":106.80799999999999,"text":"more likely than it already is."},{"start":108.632,"end":109.944,"text":"Back to the real data."},{"start":110.30199999999999,"end":112.806,"text":"When any number of turns may separate the"},{"start":112.806,"end":115.43,"text":"codes, almost every short pattern appears"},{"start":115.43,"end":116.86099999999999,"text":"in nearly every session."},{"start":117.219,"end":119.902,"text":"Support hits the ceiling, and it no longer"},{"start":119.902,"end":121.154,"text":"tells patterns apart."},{"start":121.989,"end":123.913,"text":"Requiring the codes to occur in"},{"start":123.913,"end":126.19800000000001,"text":"consecutive turns restores the spread."},{"start":126.559,"end":129.265,"text":"That gap rule is a modeling choice, and it"},{"start":129.265,"end":130.828,"text":"should always be reported."},{"start":132.677,"end":135.551,"text":"The minimum support threshold is a second"},{"start":135.551,"end":136.03,"text":"choice."},{"start":136.44,"end":139.383,"text":"At zero point one, one hundred forty two"},{"start":139.383,"end":140.34,"text":"patterns pass."},{"start":140.751,"end":143.556,"text":"At zero point five, only thirty two do."},{"start":145.444,"end":146.865,"text":"Now a group question."},{"start":147.27100000000002,"end":150.114,"text":"The pattern example, explain, example"},{"start":150.114,"end":152.753,"text":"appears in thirty percent of treatment"},{"start":152.753,"end":155.799,"text":"sessions, and in twelve percent of control"},{"start":155.799,"end":156.40800000000002,"text":"sessions."},{"start":157.302,"end":159.93099999999998,"text":"Is a gap of eighteen points larger than"},{"start":159.93099999999998,"end":160.392,"text":"chance?"},{"start":160.786,"end":162.824,"text":"Turns within a session are not"},{"start":162.824,"end":165.585,"text":"independent, so a standard test on turn"},{"start":165.585,"end":168.017,"text":"counts would overstate the certainty."},{"start":168.9,"end":171.339,"text":"A permutation test keeps every session"},{"start":171.339,"end":173.715,"text":"intact, and shuffles only the group"},{"start":173.715,"end":176.529,"text":"labels, five thousand times, recomputing"},{"start":176.529,"end":177.655,"text":"the gap each time."},{"start":178.507,"end":181.058,"text":"This is the resulting null distribution."},{"start":181.44,"end":184.183,"text":"Our observed gap sits in its tail, for a"},{"start":184.183,"end":186.861,"text":"two sided p value of zero point zero four"},{"start":186.861,"end":187.244,"text":"seven."},{"start":188.114,"end":190.75900000000001,"text":"But we tested ninety two patterns, not"},{"start":190.75900000000001,"end":191.017,"text":"one."},{"start":191.404,"end":194.308,"text":"After a Benjamini Hochberg correction, the"},{"start":194.308,"end":196.889,"text":"adjusted value is zero point zero seven"},{"start":196.889,"end":199.405,"text":"eight, so this pattern should not be"},{"start":199.405,"end":201.276,"text":"called a reliable difference."},{"start":203.121,"end":205.528,"text":"When you report sequential pattern mining,"},{"start":205.528,"end":207.828,"text":"state the unit of analysis, the gap rule"},{"start":207.828,"end":210.128,"text":"and the support threshold, and how group"},{"start":210.128,"end":212.161,"text":"differences were tested and corrected."},{"start":212.978,"end":214.913,"text":"And remember that frequent patterns"},{"start":214.913,"end":216.148,"text":"describe what happened."},{"start":216.471,"end":218.942,"text":"They do not, on their own, explain why it"},{"start":218.942,"end":219.426,"text":"happened."},{"start":220.175,"end":222.452,"text":"The companion guide walks through the same"},{"start":222.452,"end":222.981,"text":"data in R."},{"start":223.299,"end":225.099,"text":"Try changing the gap rule and the"},{"start":225.099,"end":227.21699999999998,"text":"threshold, and watch how the patterns"},{"start":227.21699999999998,"end":227.588,"text":"change."}]},"Poo-UGoTyhw":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.06,"end":2.354,"text":"In this short video, we look at how people"},{"start":2.354,"end":4.597,"text":"learn from words and pictures, and at the"},{"start":4.597,"end":6.534,"text":"design principles that follow from it."},{"start":8.277,"end":10.263,"text":"Richard Mayer's cognitive theory of"},{"start":10.263,"end":12.194,"text":"multimedia learning rests on three"},{"start":12.194,"end":12.856,"text":"assumptions."},{"start":13.625,"end":15.448,"text":"First, we take in spoken words and"},{"start":15.448,"end":17.369,"text":"pictures through two separate channels."},{"start":18.112,"end":20.54,"text":"Second, each channel can hold only a"},{"start":20.54,"end":23.28,"text":"little at a time, so working memory fills"},{"start":23.28,"end":23.778,"text":"quickly."},{"start":24.609,"end":26.059,"text":"Third, learning is active."},{"start":26.37,"end":28.701,"text":"We connect the words and the pictures, and"},{"start":28.701,"end":30.618,"text":"we link them to what we already know."},{"start":32.417,"end":34.569,"text":"Because that capacity is limited, Mayer"},{"start":34.569,"end":36.67,"text":"describes three kinds of processing that"},{"start":36.67,"end":37.439,"text":"compete for it."},{"start":38.193,"end":40.704,"text":"Extraneous processing is effort wasted on"},{"start":40.704,"end":41.422,"text":"poor design."},{"start":41.781,"end":44.232,"text":"Essential processing represents the core"},{"start":44.232,"end":44.71,"text":"content."},{"start":45.069,"end":47.46,"text":"And generative processing is the deeper"},{"start":47.46,"end":49.075,"text":"work of making sense of it."},{"start":49.88,"end":51.791,"text":"In a cluttered lesson, extraneous"},{"start":51.791,"end":54.021,"text":"processing crowds out the generative work"},{"start":54.021,"end":55.242,"text":"that leads to learning."},{"start":56.047,"end":58.638,"text":"Good design reduces the extraneous load,"},{"start":58.638,"end":61.108,"text":"manages the essential load, and leaves"},{"start":61.108,"end":62.976,"text":"room for generative processing."},{"start":64.805,"end":66.805,"text":"Mayer's design principles can be grouped"},{"start":66.805,"end":68.122,"text":"by the demand they address."},{"start":68.892,"end":71.504,"text":"To reduce extraneous processing, cut what"},{"start":71.504,"end":74.116,"text":"is not needed, highlight what is, avoid"},{"start":74.116,"end":76.787,"text":"repeating the narration as on-screen text,"},{"start":76.787,"end":79.102,"text":"and place words near the pictures they"},{"start":79.102,"end":79.636,"text":"describe."},{"start":80.49,"end":83.106,"text":"To manage essential processing, break the"},{"start":83.106,"end":85.723,"text":"lesson into learner-paced segments, teach"},{"start":85.723,"end":88.339,"text":"the key terms first, and present words as"},{"start":88.339,"end":90.123,"text":"narration rather than as text."},{"start":90.908,"end":93.413,"text":"To foster generative processing, use a"},{"start":93.413,"end":96.28399999999999,"text":"conversational style, a natural voice, and"},{"start":96.28399999999999,"end":98.667,"text":"an on-screen guide who gestures toward"},{"start":98.667,"end":99.461,"text":"what matters."},{"start":101.285,"end":103.688,"text":"This video tries to follow its own advice."},{"start":104.031,"end":106.319,"text":"Most words are spoken, not printed,"},{"start":106.319,"end":108.72200000000001,"text":"highlights point to what matters, and a"},{"start":108.72200000000001,"end":110.782,"text":"guide gestures toward the key ideas."},{"start":111.602,"end":113.857,"text":"One principle deserves a closer look."},{"start":114.22200000000001,"end":116.904,"text":"The voice principle favors a human voice,"},{"start":116.904,"end":118.854,"text":"yet this narration is synthetic."},{"start":119.219,"end":121.84,"text":"Some studies suggest that modern synthetic"},{"start":121.84,"end":124.582,"text":"voices can work nearly as well, which is a"},{"start":124.582,"end":126.106,"text":"question worth examining."},{"start":127.899,"end":130.304,"text":"To put this into practice, pick a short"},{"start":130.304,"end":132.824,"text":"instructional video you have used, decide"},{"start":132.824,"end":135.114,"text":"which principle it follows and which it"},{"start":135.114,"end":137.405,"text":"breaks, and redesign one minute of it."},{"start":138.215,"end":140.192,"text":"Bring your example and your redesign to"},{"start":140.192,"end":142.36599999999999,"text":"the discussion board, and we will compare"},{"start":142.36599999999999,"end":142.959,"text":"notes there."}]},"es-10-question-frameworks":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.96,"text":"Meet Maya, our made up doctoral student."},{"start":3.51,"end":6.98,"text":"Her topic is AI chatbot feedback on"},{"start":6.98,"end":8.26,"text":"undergraduate writing."},{"start":8.62,"end":11.68,"text":"In Review Families, she picks a kind of"},{"start":11.68,"end":11.92,"text":"review."},{"start":12.18,"end":15,"text":"But her topic isn't a question yet."},{"start":15.78,"end":19.46,"text":"Today's one idea: pick your framework by"},{"start":19.46,"end":20.5,"text":"the kind of question."},{"start":21.04,"end":24.02,"text":"Every element you keep gets checked at"},{"start":24.02,"end":27.16,"text":"screening, usually as a rule for who gets"},{"start":27.16,"end":27.4,"text":"in."},{"start":27.84,"end":29.78,"text":"That's an eligibility clause."},{"start":30,"end":33.6,"text":"Only some become search blocks, the words"},{"start":33.6,"end":34.08,"text":"you type."},{"start":34.767,"end":37.447,"text":"A question framework is a checklist of"},{"start":37.447,"end":39.327,"text":"what your question must pin down."},{"start":39.967,"end":42.307,"text":"The best known is PICO."},{"start":42.307,"end":45.207,"text":"It grew from the well built clinical"},{"start":45.207,"end":45.847,"text":"question."},{"start":46.637,"end":47.777,"text":"Let's fill it in for Maya."},{"start":47.997,"end":51.317,"text":"P is the population, undergraduates."},{"start":51.457,"end":55.017,"text":"I is the intervention, chatbot feedback on"},{"start":55.017,"end":55.557,"text":"drafts."},{"start":56.037,"end":59.757,"text":"C is the comparison, instructor, peer, or"},{"start":59.757,"end":60.397,"text":"no feedback."},{"start":61.137,"end":64.037,"text":"And O is the outcome, writing quality."},{"start":64.777,"end":67.317,"text":"Put together, it's an answerable question."},{"start":68.1,"end":70.88,"text":"Now watch what each element turns into."},{"start":71.4,"end":73.92,"text":"First, all four become eligibility"},{"start":73.92,"end":74.64,"text":"clauses."},{"start":75.72,"end":78,"text":"Undergraduates becomes undergraduate"},{"start":78,"end":80.36,"text":"students in credit bearing courses."},{"start":81,"end":83.58,"text":"The chatbot becomes a chatbot giving"},{"start":83.58,"end":85.82,"text":"feedback on the student's own draft."},{"start":86.52,"end":88.64,"text":"The other two get clauses too."},{"start":89.45,"end":91.91,"text":"Second, only some become search blocks."},{"start":92.65,"end":95.13,"text":"Population and intervention do, since"},{"start":95.13,"end":96.45,"text":"authors name them up front."},{"start":97.23,"end":100.25,"text":"Comparison and outcome usually stay screen"},{"start":100.25,"end":100.67,"text":"only."},{"start":100.83,"end":103.27,"text":"A person checks them in each study."},{"start":103.27,"end":106.85,"text":"Cochrane explains why: they may not be"},{"start":106.85,"end":108.49,"text":"well described in an abstract."},{"start":109.45,"end":110.67,"text":"Watch for one trap."},{"start":111.21,"end":113.13,"text":"Writing shows up twice."},{"start":113.43,"end":116.65,"text":"As the topic, every relevant study names"},{"start":116.65,"end":118.03,"text":"it, so it's searched."},{"start":118.25,"end":121.19,"text":"As the outcome, it's what got measured,"},{"start":121.19,"end":123.79,"text":"like rubric scores, checked at screening."},{"start":123.79,"end":126.93,"text":"Cochrane says outcomes are rarely"},{"start":126.93,"end":127.97,"text":"eligibility rules."},{"start":128.61,"end":131.19,"text":"A study without the numbers stays in."},{"start":131.49,"end":134.65,"text":"One that never measured writing can go."},{"start":135.467,"end":136.967,"text":"PICO has a family."},{"start":137.207,"end":140.347,"text":"Each member adds or swaps one letter."},{"start":140.507,"end":144.747,"text":"Add an S for study design, a T for time,"},{"start":144.747,"end":147.087,"text":"or a second C, for context."},{"start":147.647,"end":150.607,"text":"Time and context usually get screened."},{"start":150.947,"end":152.607,"text":"Design is different."},{"start":153.287,"end":155.727,"text":"Cochrane's typical search includes a"},{"start":155.727,"end":158.067,"text":"design block, but test it first."},{"start":158.927,"end":162.547,"text":"PECO swaps the intervention for an"},{"start":162.547,"end":165.567,"text":"exposure: something students already do"},{"start":165.567,"end":168.447,"text":"that nobody assigned, like heavy chatbot"},{"start":168.447,"end":168.707,"text":"use."},{"start":169.047,"end":172.267,"text":"It asks if heavy use goes with stronger"},{"start":172.267,"end":174.887,"text":"writing confidence, not whether it causes"},{"start":174.887,"end":175.167,"text":"it."},{"start":175.527,"end":178.767,"text":"Drop the comparison, and you get PEO."},{"start":179.633,"end":182.613,"text":"Now meet Omar, Maya's made up screening"},{"start":182.613,"end":183.033,"text":"partner."},{"start":183.253,"end":184.753,"text":"His question is different."},{"start":185.373,"end":187.793,"text":"How do undergraduate writers experience"},{"start":187.793,"end":190.353,"text":"chatbot feedback on their drafts?"},{"start":190.713,"end":191.853,"text":"Does PICO fit?"},{"start":197.783,"end":198.343,"text":"Not really."},{"start":198.783,"end":201.763,"text":"Nothing's compared, and no outcome is"},{"start":201.763,"end":202.163,"text":"measured."},{"start":202.163,"end":205.723,"text":"Cochrane's handbook says PICO is"},{"start":205.723,"end":207.683,"text":"generally not suitable for questions"},{"start":207.683,"end":209.123,"text":"around qualitative data."},{"start":209.303,"end":212.243,"text":"So Omar uses SPIDER instead."},{"start":213.193,"end":216.013,"text":"S is the sample, undergraduate writers."},{"start":216.353,"end":219.453,"text":"PI is the phenomenon of interest, here"},{"start":219.453,"end":221.453,"text":"their experience of chatbot feedback."},{"start":221.953,"end":225.053,"text":"D is design, how the data were gathered,"},{"start":225.053,"end":225.733,"text":"like interviews."},{"start":226.153,"end":229.513,"text":"E is evaluation, like trust, or whether"},{"start":229.513,"end":230.133,"text":"they used it."},{"start":230.313,"end":233.493,"text":"And R is research type, qualitative or"},{"start":233.493,"end":234.093,"text":"mixed methods."},{"start":234.513,"end":235.893,"text":"Which would you search?"},{"start":241.793,"end":243.573,"text":"Every letter gets screened."},{"start":243.573,"end":246.693,"text":"But only the sample and the phenomenon get"},{"start":246.693,"end":247.073,"text":"searched."},{"start":247.293,"end":249.733,"text":"The other three usually aren't."},{"start":250.253,"end":253.673,"text":"One team thinks requiring qualitative plus"},{"start":253.673,"end":256.413,"text":"a named method might be too restrictive."},{"start":257.153,"end":259.553,"text":"Some studies they missed only said"},{"start":259.553,"end":259.993,"text":"interviews."},{"start":259.993,"end":264.833,"text":"JBI uses a close cousin: population,"},{"start":264.833,"end":267.433,"text":"phenomenon of interest, and context."},{"start":268.367,"end":270.567,"text":"So the kind of question picks the"},{"start":270.567,"end":270.907,"text":"framework."},{"start":271.327,"end":274.887,"text":"Effects get the PICO family, exposures"},{"start":274.887,"end":278.467,"text":"get PECO, and experiences get SPIDER."},{"start":278.727,"end":282.127,"text":"To map a field in a scoping review, JBI"},{"start":282.127,"end":286.807,"text":"suggests PCC: population, concept, and"},{"start":286.807,"end":287.207,"text":"context."},{"start":287.507,"end":290.867,"text":"In Maya's map, the concept is chatbot"},{"start":290.867,"end":292.147,"text":"feedback on writing."},{"start":294.517,"end":297.937,"text":"Service questions can use SPICE, built for"},{"start":297.937,"end":299.937,"text":"library work outside health."},{"start":300.837,"end":303.297,"text":"Picture a writing center adding chatbot"},{"start":303.297,"end":305.117,"text":"feedback as a first pass."},{"start":306.097,"end":308.477,"text":"Setting and intervention get searched."},{"start":308.717,"end":311.397,"text":"The rest is usually screened."},{"start":313.667,"end":316.747,"text":"Policy questions can use ECLIPSE, built"},{"start":316.747,"end":318.507,"text":"for health policy and management."},{"start":319.107,"end":322.127,"text":"Imagine a program director drafting a"},{"start":322.127,"end":323.007,"text":"chatbot policy."},{"start":323.807,"end":326.207,"text":"Its authors said this of the older"},{"start":326.207,"end":329.667,"text":"version, CLIP: not every element fits"},{"start":329.667,"end":333.187,"text":"every search, but think about each one at"},{"start":333.187,"end":333.627,"text":"the start."},{"start":336.057,"end":338.997,"text":"How and why questions can use CIMO,"},{"start":338.997,"end":340.337,"text":"from management research."},{"start":341.197,"end":343.117,"text":"Picture big first year sections."},{"start":343.617,"end":346.477,"text":"Chatbot feedback plus a reflection task"},{"start":346.477,"end":349.797,"text":"might prompt self regulated revision, and"},{"start":349.797,"end":351.877,"text":"then more substantive revisions."},{"start":352.197,"end":355.437,"text":"That middle step is the mechanism, often"},{"start":355.437,"end":357.377,"text":"found only in the full text."},{"start":359.847,"end":361.967,"text":"One rapid review counted thirty eight"},{"start":361.967,"end":362.507,"text":"frameworks."},{"start":363.187,"end":366.027,"text":"One called PerSPEcTiF suits qualitative"},{"start":366.027,"end":368.167,"text":"reviews of complex interventions."},{"start":368.907,"end":371.507,"text":"BeHEMoTh helps when you're searching for"},{"start":371.507,"end":371.807,"text":"theory."},{"start":372.567,"end":374.007,"text":"Don't collect acronyms."},{"start":374.107,"end":377.527,"text":"A framework is a scaffold, not a cage."},{"start":378.367,"end":380.587,"text":"Does the framework change what you find?"},{"start":381.207,"end":384.087,"text":"One team ran the same qualitative review"},{"start":384.087,"end":386.767,"text":"three ways, same search terms."},{"start":386.767,"end":389.667,"text":"PICO pulled in nearly twenty four"},{"start":389.667,"end":390.787,"text":"thousand records."},{"start":390.787,"end":394.307,"text":"PICOS found about four hundred fifty,"},{"start":394.307,"end":397.167,"text":"and SPIDER only about two hundred forty."},{"start":398.287,"end":400.367,"text":"But look at the eighteen studies that"},{"start":400.367,"end":400.707,"text":"belonged."},{"start":400.707,"end":403.167,"text":"PICO found all eighteen."},{"start":403.567,"end":407.147,"text":"The other two found thirteen each, none"},{"start":407.147,"end":408.147,"text":"that PICO missed."},{"start":408.467,"end":411.507,"text":"Their precision was higher, so more of"},{"start":411.507,"end":413.107,"text":"what they found was relevant."},{"start":413.967,"end":417.207,"text":"So the team recommends PICO for a fully"},{"start":417.207,"end":418.327,"text":"comprehensive search."},{"start":418.867,"end":419.987,"text":"Two cautions, though."},{"start":420.427,"end":422.767,"text":"It was one health topic, and the"},{"start":422.767,"end":424.807,"text":"frameworks used different numbers of"},{"start":424.807,"end":425.007,"text":"blocks."},{"start":425.647,"end":428.887,"text":"A study has to match every block, so each"},{"start":428.887,"end":430.567,"text":"one you add can lose studies."},{"start":431.107,"end":434.087,"text":"That's why Omar searches only two letters."},{"start":434.307,"end":437.127,"text":"And another review found just three"},{"start":437.127,"end":439.667,"text":"studies testing PICO for searching."},{"start":442.067,"end":442.727,"text":"Let's recap."},{"start":443.187,"end":446.347,"text":"First, pick the framework by the kind of"},{"start":446.347,"end":446.707,"text":"question."},{"start":447.127,"end":450.287,"text":"Second, every element you keep gets"},{"start":450.287,"end":452.847,"text":"checked at screening, usually as an"},{"start":452.847,"end":453.827,"text":"eligibility clause."},{"start":454.347,"end":458.307,"text":"Third, only elements authors reliably name"},{"start":458.307,"end":459.667,"text":"become search blocks."},{"start":460.047,"end":462.907,"text":"Test them against studies you know belong."},{"start":463.867,"end":464.407,"text":"What's next?"},{"start":465.167,"end":467.987,"text":"Review Families helps you pick the kind of"},{"start":467.987,"end":468.247,"text":"review."},{"start":469.007,"end":472.487,"text":"Criteria on Trial turns kept elements into"},{"start":472.487,"end":472.947,"text":"criteria."},{"start":473.887,"end":476.767,"text":"Search Strings turns search elements into"},{"start":476.767,"end":477.687,"text":"concept blocks."},{"start":478.507,"end":479.707,"text":"Now try it yourself."},{"start":480.247,"end":482.867,"text":"Write your question in a framework, and"},{"start":482.867,"end":485.367,"text":"mark each element search or screen."},{"start":486.067,"end":488.367,"text":"Then check a published review on your"},{"start":488.367,"end":488.727,"text":"topic."},{"start":489.387,"end":491.227,"text":"Which elements did it search?"}]},"es-01-review-families":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":0.54,"text":"Meet Maya."},{"start":0.84,"end":2.92,"text":"She's a made up doctoral student."},{"start":3.28,"end":5.64,"text":"She's found a review that changed her"},{"start":5.64,"end":5.88,"text":"mind."},{"start":6.3,"end":8.72,"text":"Its title calls it a systematic review."},{"start":9.2,"end":12.2,"text":"Before she relies on it, she wants to know"},{"start":12.2,"end":13.92,"text":"what kind it really is."},{"start":14.28,"end":16.34,"text":"That's called its review family."},{"start":16.84,"end":18.44,"text":"Should she trust the title?"},{"start":18.78,"end":20.56,"text":"One simple move helps."},{"start":21.08,"end":23.1,"text":"The purpose gives a first guess."},{"start":23.36,"end":25.9,"text":"The methods get the final say."},{"start":26.7,"end":29.38,"text":"A review is a paper that pulls together"},{"start":29.38,"end":31.48,"text":"many studies on one topic."},{"start":32.21,"end":35.16,"text":"A review family is a type of review,"},{"start":35.16,"end":37.48,"text":"sorted by the job it does."},{"start":37.96,"end":39.62,"text":"We'll use five."},{"start":40.2,"end":43.22,"text":"We'll try each one on Maya's topic."},{"start":44.14,"end":47.12,"text":"A systematic review answers one focused"},{"start":47.12,"end":47.7,"text":"question."},{"start":47.9,"end":50.68,"text":"Its steps are planned ahead and reported,"},{"start":50.68,"end":52.76,"text":"so others could repeat them."},{"start":52.96,"end":56.34,"text":"On Maya's topic, it might ask whether"},{"start":56.34,"end":59.44,"text":"chatbot feedback improves essay revisions,"},{"start":59.44,"end":61.5,"text":"versus teacher feedback alone."},{"start":62.37,"end":65.01,"text":"A scoping review maps what exists."},{"start":65.35,"end":68.41,"text":"It might ask which studies on chatbot"},{"start":68.41,"end":70.81,"text":"feedback exist, and what they measure."},{"start":71.23,"end":74.93,"text":"Notice it doesn't ask whether chatbots"},{"start":74.93,"end":75.11,"text":"work."},{"start":76.02,"end":79.34,"text":"A narrative review argues a view, built"},{"start":79.34,"end":80.94,"text":"from the author's own reading."},{"start":81.36,"end":84.4,"text":"Picture an expert's overview that makes a"},{"start":84.4,"end":86.78,"text":"case for how classes should change."},{"start":87.63,"end":90.29,"text":"An integrative review combines different"},{"start":90.29,"end":91.41,"text":"kinds of evidence."},{"start":91.97,"end":95.51,"text":"Think experiments, surveys, and theory"},{"start":95.51,"end":95.89,"text":"papers."},{"start":96.51,"end":99.31,"text":"It would ask what they say together."},{"start":100.23,"end":103.33,"text":"A qualitative meta synthesis interprets"},{"start":103.33,"end":106.47,"text":"findings across qualitative studies, like"},{"start":106.47,"end":107.33,"text":"interview studies."},{"start":107.65,"end":110.53,"text":"You'll also hear it called qualitative"},{"start":110.53,"end":111.93,"text":"evidence synthesis."},{"start":112.33,"end":115.55,"text":"It might ask how students experience"},{"start":115.55,"end":117.17,"text":"chatbot feedback."},{"start":118.03,"end":121.15,"text":"A quick test: what job is the purpose"},{"start":121.15,"end":122.03,"text":"sentence doing?"},{"start":122.27,"end":125.59,"text":"Is it answering, mapping, arguing,"},{"start":125.59,"end":127.43,"text":"combining, or interpreting?"},{"start":127.89,"end":130.29,"text":"Real papers use other words, though."},{"start":131.05,"end":134.07,"text":"Examining an effect, for example, is an"},{"start":134.07,"end":134.69,"text":"answer job."},{"start":135.55,"end":138.59,"text":"Two researchers, Grant and Booth, compared"},{"start":138.59,"end":140.15,"text":"fourteen review types."},{"start":140.85,"end":143.71,"text":"They suggest judging a review by whether"},{"start":143.71,"end":146.49,"text":"it fits its purpose, not one gold"},{"start":146.49,"end":146.85,"text":"standard."},{"start":147.63,"end":149.33,"text":"Families also overlap."},{"start":150.05,"end":152.85,"text":"If a review sits between two, name the"},{"start":152.85,"end":153.59,"text":"closest one."},{"start":154.267,"end":156.907,"text":"Titles can be wrong, so we check the"},{"start":156.907,"end":157.247,"text":"methods."},{"start":157.967,"end":160.687,"text":"Grant and Booth look at four processes."},{"start":161.677,"end":164.957,"text":"Search is which databases they used, and"},{"start":164.957,"end":166.697,"text":"the exact words they typed."},{"start":167.237,"end":168.837,"text":"Those are search strings."},{"start":169.657,"end":172.437,"text":"Appraisal asks whether they judged each"},{"start":172.437,"end":173.237,"text":"study's quality."},{"start":173.817,"end":176.577,"text":"Synthesis is how they combined the"},{"start":176.577,"end":179.177,"text":"findings, like a table or themes."},{"start":179.817,"end":182.217,"text":"Analysis is what they conclude."},{"start":183.117,"end":184.837,"text":"Keep these four words handy."},{"start":185.277,"end":187.717,"text":"Check the purpose and all four."},{"start":188.337,"end":191.137,"text":"The more you check, the stronger your"},{"start":191.137,"end":191.437,"text":"case."},{"start":192.267,"end":195.307,"text":"Let's try one on Maya's card, with a made"},{"start":195.307,"end":196.307,"text":"up warm up review."},{"start":196.667,"end":199.847,"text":"Its purpose sentence says it aims to map"},{"start":199.847,"end":202.627,"text":"chatbot feedback research, and where the"},{"start":202.627,"end":203.147,"text":"gaps are."},{"start":203.487,"end":205.587,"text":"It's often near the end of the"},{"start":205.587,"end":205.927,"text":"introduction."},{"start":206.867,"end":207.987,"text":"Start with the purpose."},{"start":208.367,"end":212.607,"text":"Its job is to map and find gaps, so our"},{"start":212.607,"end":214.327,"text":"first guess is scoping."},{"start":215.107,"end":216.307,"text":"Now the methods."},{"start":216.587,"end":219.907,"text":"The search used four databases and"},{"start":219.907,"end":221.487,"text":"reported its full strings."},{"start":222.347,"end":224.507,"text":"Systematic reviews do that too."},{"start":225.047,"end":227.067,"text":"Scoping doesn't mean sloppy."},{"start":227.347,"end":229.007,"text":"There's no appraisal."},{"start":229.067,"end":230.147,"text":"That fits."},{"start":230.707,"end":233.947,"text":"Scoping reviews map studies and rarely"},{"start":233.947,"end":234.627,"text":"judge them."},{"start":234.947,"end":238.207,"text":"The synthesis is tables that count studies"},{"start":238.207,"end":241.287,"text":"by research design, like how many"},{"start":241.287,"end":242.827,"text":"experiments and surveys."},{"start":243.107,"end":246.307,"text":"The analysis gives a list of gaps."},{"start":247.237,"end":250.057,"text":"All four fit, and the title agrees."},{"start":250.577,"end":252.157,"text":"It's a scoping review."},{"start":253.067,"end":255.927,"text":"Your turn, with Maya's own review."},{"start":256.147,"end":258.987,"text":"Its purpose says it aims to show teachers"},{"start":258.987,"end":261.927,"text":"why chatbots belong in every writing"},{"start":261.927,"end":262.227,"text":"class."},{"start":263.497,"end":266.437,"text":"From the purpose alone, what's your first"},{"start":266.437,"end":266.777,"text":"guess?"},{"start":267.377,"end":268.997,"text":"Pause and decide."},{"start":275.547,"end":276.567,"text":"Look at the verb."},{"start":277.247,"end":279.147,"text":"Show why chatbots belong."},{"start":279.867,"end":281.567,"text":"That's arguing a case."},{"start":281.747,"end":284.387,"text":"It doesn't answer a focused question."},{"start":285.067,"end":288.487,"text":"So Maya's first guess is narrative, even"},{"start":288.487,"end":290.347,"text":"though the title says systematic."},{"start":291.397,"end":292.297,"text":"Now the methods."},{"start":292.817,"end":295.537,"text":"We'll check each row against Grant and"},{"start":295.537,"end":297.817,"text":"Booth's entry for systematic reviews."},{"start":298.597,"end":301.757,"text":"The search used Google Scholar and papers"},{"start":301.757,"end":302.517,"text":"the author knew."},{"start":302.877,"end":304.737,"text":"No strings were reported."},{"start":305.297,"end":308.437,"text":"A systematic review tries to find every"},{"start":308.437,"end":311.737,"text":"relevant study, so this row is a miss."},{"start":312.507,"end":313.027,"text":"Appraisal?"},{"start":313.247,"end":314.467,"text":"None is reported."},{"start":314.847,"end":318.007,"text":"In a systematic review, appraisal can"},{"start":318.007,"end":319.787,"text":"decide which studies stay in."},{"start":320.187,"end":321.227,"text":"Another miss."},{"start":321.507,"end":324.747,"text":"The synthesis goes study by study, with a"},{"start":324.747,"end":325.427,"text":"summary table."},{"start":326.227,"end":328.547,"text":"Systematic reviews typically use prose"},{"start":328.547,"end":330.907,"text":"plus tables, so that fits."},{"start":331.827,"end":334.067,"text":"The analysis argues for chatbots."},{"start":334.307,"end":337.427,"text":"A systematic review may recommend things"},{"start":337.427,"end":337.787,"text":"too."},{"start":338.207,"end":341.847,"text":"But it also says what's still unknown, and"},{"start":341.847,"end":342.907,"text":"how certain it is."},{"start":343.407,"end":345.087,"text":"This one never does."},{"start":345.627,"end":347.367,"text":"That's one fit out of four."},{"start":348.127,"end":351.387,"text":"Which should win, the label or the"},{"start":351.387,"end":351.767,"text":"methods?"},{"start":352.747,"end":354.647,"text":"Decide before we go on."},{"start":360.867,"end":362.067,"text":"The methods win."},{"start":362.687,"end":365.267,"text":"Grant and Booth say checking the four"},{"start":365.267,"end":368.187,"text":"processes closely is the only pragmatic"},{"start":368.187,"end":370.067,"text":"way to classify a review."},{"start":370.487,"end":373.067,"text":"The purpose gives a first guess."},{"start":373.687,"end":375.867,"text":"The methods get the final say."},{"start":376.127,"end":379.647,"text":"If they disagree, say so in your write up."},{"start":380.317,"end":382.417,"text":"Now compare a narrative review."},{"start":382.937,"end":385.537,"text":"Grant and Booth file it under literature"},{"start":385.537,"end":387.017,"text":"review, a looser entry."},{"start":387.477,"end":389.837,"text":"Search may or may not be thorough."},{"start":390.617,"end":392.677,"text":"Appraisal may or may not happen."},{"start":393.277,"end":395.397,"text":"Synthesis is typically prose."},{"start":395.777,"end":399.017,"text":"The analysis argues a view, the narrative"},{"start":399.017,"end":399.317,"text":"job."},{"start":399.617,"end":401.137,"text":"So nothing conflicts."},{"start":402.117,"end":403.217,"text":"Be careful, though."},{"start":403.357,"end":406.677,"text":"An entry that loose fits almost anything."},{"start":406.977,"end":410.417,"text":"The real evidence is the purpose, plus"},{"start":410.417,"end":413.037,"text":"three misses against systematic."},{"start":413.217,"end":416.577,"text":"So Maya's verdict is a narrative review,"},{"start":416.577,"end":418.957,"text":"labelled systematic."},{"start":419.677,"end":420.477,"text":"Was it convincing?"},{"start":420.777,"end":423.717,"text":"A narrative review isn't second rate by"},{"start":423.717,"end":424.057,"text":"default."},{"start":424.457,"end":426.917,"text":"One group of authors argues that"},{"start":426.917,"end":429.417,"text":"systematic doesn't mean high quality."},{"start":429.717,"end":432.897,"text":"But this one claims a method it didn't"},{"start":432.897,"end":433.157,"text":"use."},{"start":433.337,"end":436.197,"text":"And its thin search may have missed"},{"start":436.197,"end":437.537,"text":"studies that disagree."},{"start":438.517,"end":440.297,"text":"Maya writes down her verdict."},{"start":440.877,"end":442.957,"text":"She ends her notes with one method"},{"start":442.957,"end":443.297,"text":"question."},{"start":444.117,"end":447.157,"text":"Why only Google Scholar, and how were"},{"start":447.157,"end":447.817,"text":"studies picked?"},{"start":448.667,"end":449.407,"text":"To sum up."},{"start":449.447,"end":451.947,"text":"The purpose gives a first guess."},{"start":452.107,"end":455.647,"text":"The methods get the final say, so check"},{"start":455.647,"end":456.307,"text":"all four."},{"start":456.567,"end":458.827,"text":"The label isn't the family."},{"start":459.367,"end":462.527,"text":"Families overlap, and none is"},{"start":462.527,"end":463.587,"text":"automatically best."},{"start":464.447,"end":465.527,"text":"Now try it yourself."},{"start":466.427,"end":469.447,"text":"Pick a review that shaped your field, and"},{"start":469.447,"end":470.587,"text":"do what Maya did."},{"start":471.007,"end":472.367,"text":"Did it convince you?"},{"start":472.807,"end":474.547,"text":"Write one method question."},{"start":475.337,"end":477.597,"text":"Start by copying its purpose sentence."},{"start":477.997,"end":480.497,"text":"Then fill in all four method rows."},{"start":480.877,"end":484.297,"text":"Then ask yourself: do its methods earn its"},{"start":484.297,"end":484.597,"text":"label?"}]},"es-08-six-ways-to-synthesize":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":1.08,"text":"Meet Maya again."},{"start":1.44,"end":4.24,"text":"She's a made up doctoral student studying"},{"start":4.24,"end":7.02,"text":"AI feedback on undergraduates' writing."},{"start":7.4,"end":10.86,"text":"This is her pile, twelve made up studies."},{"start":11.42,"end":15.18,"text":"They range from trials to interviews to a"},{"start":15.18,"end":15.74,"text":"theory paper."},{"start":16.57,"end":19.67,"text":"Today we zoom in on the synthesis step,"},{"start":19.67,"end":21.51,"text":"where findings get combined."},{"start":22.31,"end":26.01,"text":"The big idea: each kind of synthesis does"},{"start":26.01,"end":28.29,"text":"something different to the same pile."},{"start":28.45,"end":31.43,"text":"So you pick by what you need to combine,"},{"start":31.43,"end":32.39,"text":"and how."},{"start":32.81,"end":36.83,"text":"We'll meet six, four review types and two"},{"start":36.83,"end":37.91,"text":"statistical methods."},{"start":38.9,"end":40.82,"text":"First, a narrative review."},{"start":41.64,"end":44.2,"text":"Maya hand picks the studies she thinks"},{"start":44.2,"end":44.9,"text":"matter most."},{"start":45.54,"end":48.94,"text":"Then she argues a view: AI feedback"},{"start":48.94,"end":52.5,"text":"should support teachers, not replace them."},{"start":53.16,"end":56.36,"text":"One team calls this review's goal an"},{"start":56.36,"end":57.68,"text":"authoritative argument."},{"start":58.5,"end":59.86,"text":"But there's a risk."},{"start":60.44,"end":63.64,"text":"Two other authors warn that writers may"},{"start":63.64,"end":66.22,"text":"pick only studies backing their view."},{"start":66.92,"end":68.64,"text":"See the nine she left out?"},{"start":69.367,"end":70.827,"text":"Now a scoping review."},{"start":71.327,"end":73.727,"text":"This time Maya doesn't argue."},{"start":74.087,"end":77.427,"text":"She places every study on a grid, by"},{"start":77.427,"end":79.527,"text":"design and by what it measured."},{"start":79.867,"end":82.627,"text":"The whole pile goes on the map."},{"start":83.417,"end":85.677,"text":"Six intervention studies measured writing"},{"start":85.677,"end":86.097,"text":"quality."},{"start":86.317,"end":88.617,"text":"But none of them measured what students"},{"start":88.617,"end":89.717,"text":"think of the feedback."},{"start":90.177,"end":92.557,"text":"That empty cell is a gap."},{"start":93.037,"end":95.517,"text":"Mapping what's out there is what scoping"},{"start":95.517,"end":95.857,"text":"is for."},{"start":96.457,"end":99.177,"text":"Notice she counted studies but never"},{"start":99.177,"end":100.957,"text":"formally appraised their quality."},{"start":101.8,"end":104.54,"text":"Number three, the systematic review."},{"start":104.78,"end":107.16,"text":"It answers one focused question."},{"start":107.48,"end":110.66,"text":"Does AI feedback improve writing quality,"},{"start":110.66,"end":112.66,"text":"compared with teacher feedback?"},{"start":112.96,"end":115.62,"text":"This time Maya doesn't pick."},{"start":116.16,"end":118.18,"text":"Criteria set in advance do."},{"start":118.36,"end":122.04,"text":"The first keeps studies comparing AI with"},{"start":122.04,"end":122.44,"text":"teachers."},{"start":122.68,"end":125.72,"text":"The second keeps those measuring writing"},{"start":125.72,"end":126.22,"text":"quality."},{"start":127.03,"end":128.45,"text":"Three trials pass."},{"start":128.99,"end":131.43,"text":"Next, she appraises each one."},{"start":131.67,"end":134.91,"text":"She judges how much its design or conduct"},{"start":134.91,"end":136.37,"text":"could bias the result."},{"start":136.97,"end":139.13,"text":"Study one has some concerns."},{"start":139.41,"end":141.73,"text":"The other two have low concerns."},{"start":142.27,"end":145.25,"text":"Then she answers the question in prose,"},{"start":145.25,"end":146.27,"text":"with a table."},{"start":146.49,"end":150.03,"text":"The appraisal shapes how sure that answer"},{"start":150.03,"end":150.67,"text":"can sound."},{"start":151.433,"end":153.613,"text":"Next, an integrative review."},{"start":154.413,"end":155.913,"text":"Now the question is bigger."},{"start":156.493,"end":159.313,"text":"How does AI feedback work for students?"},{"start":159.933,"end":163.373,"text":"Maya pieces together one picture, a made"},{"start":163.373,"end":163.773,"text":"up model."},{"start":164.673,"end":167.153,"text":"Students engage with the comments, they"},{"start":167.153,"end":169.533,"text":"revise, and their writing changes."},{"start":170.523,"end":173.003,"text":"The survey and an interview show how"},{"start":173.003,"end":173.883,"text":"students engage."},{"start":174.643,"end":176.863,"text":"The revision studies fill the middle."},{"start":177.343,"end":179.703,"text":"The writing quality studies sit at the"},{"start":179.703,"end":180.003,"text":"end."},{"start":180.523,"end":182.983,"text":"The theory paper explains the links."},{"start":183.623,"end":187.183,"text":"Two authors describe this kind of mix:"},{"start":187.183,"end":189.763,"text":"experimental and non experimental"},{"start":189.763,"end":192.323,"text":"research, plus data and theory."},{"start":193.033,"end":194.613,"text":"Now meta analysis."},{"start":194.693,"end":197.293,"text":"Doing one takes statistical training this"},{"start":197.293,"end":199.753,"text":"series doesn't cover, so just the ideas."},{"start":200.313,"end":202.653,"text":"Back to the three trials from her"},{"start":202.653,"end":203.553,"text":"systematic review."},{"start":203.893,"end":206.453,"text":"Each one reports an effect size."},{"start":206.913,"end":209.713,"text":"That's the gap between the groups, in"},{"start":209.713,"end":211.193,"text":"standard deviation units."},{"start":211.553,"end":213.833,"text":"That sets each block's place."},{"start":214.613,"end":217.113,"text":"A meta analysis pools them into one"},{"start":217.113,"end":218.053,"text":"weighted average."},{"start":218.693,"end":221.273,"text":"Bigger, more precise studies get more"},{"start":221.273,"end":221.593,"text":"weight."},{"start":222.073,"end":225.373,"text":"Study two is the big one, at sixty three"},{"start":225.373,"end":225.773,"text":"percent."},{"start":225.773,"end":229.513,"text":"On this seesaw, the pooled answer is the"},{"start":229.513,"end":230.173,"text":"balance point."},{"start":230.923,"end":233.853,"text":"Try the plain average, zero point three,"},{"start":233.853,"end":236.193,"text":"where every study counts the same."},{"start":243.123,"end":245.283,"text":"See how it tips toward the big study?"},{"start":245.563,"end":248.623,"text":"The balance point slides to about zero"},{"start":248.623,"end":249.403,"text":"point two."},{"start":250.203,"end":251.483,"text":"That's pooling."},{"start":251.743,"end":254.703,"text":"But it only works when studies are similar"},{"start":254.703,"end":257.663,"text":"enough: in who took part, what was"},{"start":257.663,"end":259.603,"text":"compared, and what was measured."},{"start":259.923,"end":263.143,"text":"So trials four and five stay off this"},{"start":263.143,"end":265.983,"text":"beam, since they compared teachers with"},{"start":265.983,"end":266.283,"text":"peers."},{"start":266.723,"end":269.363,"text":"So does trial twelve, which measured"},{"start":269.363,"end":269.923,"text":"revising."},{"start":270.633,"end":273.153,"text":"Last, network meta analysis."},{"start":273.453,"end":276.353,"text":"Now Maya wonders which feedback works"},{"start":276.353,"end":279.733,"text":"best: AI, teacher, or peer."},{"start":280.193,"end":283.713,"text":"In a network diagram, each circle is a"},{"start":283.713,"end":284.493,"text":"type of feedback."},{"start":284.773,"end":287.933,"text":"Each line stands for trials that compared"},{"start":287.933,"end":289.493,"text":"two of them head to head."},{"start":290.193,"end":293.153,"text":"Three trials compared AI with teachers."},{"start":293.773,"end":297.093,"text":"Pooled, AI was ahead by zero point two."},{"start":297.663,"end":300.453,"text":"Two trials compared teachers with peers."},{"start":301.243,"end":303.493,"text":"Teachers were ahead by zero point one"},{"start":303.493,"end":303.753,"text":"five."},{"start":304.563,"end":307.773,"text":"But no trial ever compared AI with peers."},{"start":308.403,"end":309.913,"text":"Can she still compare them?"},{"start":315.743,"end":318.703,"text":"Yes, indirectly, by going through the"},{"start":318.703,"end":319.003,"text":"teacher."},{"start":319.553,"end":321.523,"text":"It's the common comparator both sets"},{"start":321.523,"end":321.863,"text":"share."},{"start":322.493,"end":325.503,"text":"Add the two steps: zero point two plus"},{"start":325.503,"end":326.443,"text":"zero point one five."},{"start":327.293,"end":329.863,"text":"So AI is about zero point three five"},{"start":329.863,"end":331.063,"text":"ahead of peers."},{"start":331.813,"end":334.663,"text":"But indirect evidence is usually weaker"},{"start":334.663,"end":335.883,"text":"than a direct trial."},{"start":336.123,"end":339.423,"text":"A network meta analysis combines both"},{"start":339.423,"end":341.163,"text":"kinds in a single analysis."},{"start":342.143,"end":342.783,"text":"There's a condition."},{"start":343.243,"end":346.383,"text":"The route only holds if both sets of"},{"start":346.383,"end":348.743,"text":"trials are similar, on average, in"},{"start":348.743,"end":351.263,"text":"everything important except the feedback."},{"start":351.923,"end":353.383,"text":"That's transitivity."},{"start":353.863,"end":356.683,"text":"Suppose teacher feedback meant one quick"},{"start":356.683,"end":359.163,"text":"comment in the first set, and a full"},{"start":359.163,"end":360.463,"text":"conference in the second."},{"start":360.863,"end":362.823,"text":"Then the route may not hold."},{"start":363.083,"end":366.323,"text":"If a trial ever compares AI with peers"},{"start":366.323,"end":369.423,"text":"directly, it should come out near zero"},{"start":369.423,"end":372.903,"text":"point three five, and that check is called"},{"start":372.903,"end":373.483,"text":"consistency."},{"start":374.633,"end":375.793,"text":"So how do you choose?"},{"start":376.313,"end":378.153,"text":"Ask what you need to combine."},{"start":378.893,"end":381.433,"text":"An argument from hand picked reading is"},{"start":381.433,"end":381.853,"text":"narrative."},{"start":382.173,"end":384.613,"text":"A map of everything is scoping."},{"start":384.993,"end":388.033,"text":"One answer from appraised studies is"},{"start":388.033,"end":388.493,"text":"systematic."},{"start":389.523,"end":392.283,"text":"One picture from mixed designs and theory"},{"start":392.283,"end":393.563,"text":"is integrative."},{"start":394.203,"end":397.083,"text":"One weighted estimate is meta analysis."},{"start":397.903,"end":400.323,"text":"Links among three or more options is"},{"start":400.323,"end":401.823,"text":"network meta analysis."},{"start":402.503,"end":405.003,"text":"Those last two build on a systematic"},{"start":405.003,"end":405.503,"text":"review."},{"start":406.303,"end":408.803,"text":"You'd only do them with methods training,"},{"start":408.803,"end":410.663,"text":"and often a statistician."},{"start":410.703,"end":413.243,"text":"So they're beyond this series."},{"start":414.013,"end":414.533,"text":"Your turn."},{"start":414.733,"end":417.553,"text":"Maya asks how students' views and the"},{"start":417.553,"end":419.013,"text":"trial results fit together."},{"start":419.373,"end":420.953,"text":"Which synthesis is that?"},{"start":426.943,"end":428.043,"text":"It's integrative."},{"start":428.123,"end":431.543,"text":"She's bringing different designs into one"},{"start":431.543,"end":432.043,"text":"picture."},{"start":432.867,"end":433.387,"text":"Let's recap."},{"start":433.787,"end":436.967,"text":"First, the same pile can become six"},{"start":436.967,"end":439.727,"text":"different things, from an argument to a"},{"start":439.727,"end":440.107,"text":"network."},{"start":440.587,"end":443.447,"text":"Second, pick by what you need to combine,"},{"start":443.447,"end":444.547,"text":"and how."},{"start":445.007,"end":448.107,"text":"Third, pooling needs comparable studies."},{"start":448.747,"end":451.547,"text":"Indirect routes need similar trial sets."},{"start":452.397,"end":453.137,"text":"Try it yourself."},{"start":453.457,"end":455.977,"text":"Pick one published review in your area."},{"start":456.197,"end":457.877,"text":"What did it combine, and how?"},{"start":458.157,"end":459.717,"text":"Which of the six is it?"},{"start":459.997,"end":462.537,"text":"Then check whether that synthesis fits its"},{"start":462.537,"end":464.817,"text":"question, its evidence, and its claim."},{"start":465.337,"end":467.977,"text":"Last, one sentence for your own topic."},{"start":468.617,"end":471.497,"text":"Maya's goes like this: my review combines"},{"start":471.497,"end":474.357,"text":"surveys, interviews, and trials by"},{"start":474.357,"end":475.457,"text":"building one picture."},{"start":475.797,"end":478.317,"text":"Now write your own sentence like that one."}]},"es-03-criteria-on-trial":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":3.02,"text":"Meet Maya and Omar, two made up reviewers."},{"start":3.68,"end":6.88,"text":"Maya's doctoral review is on AI feedback"},{"start":6.88,"end":8.5,"text":"for undergraduate writing."},{"start":9.06,"end":10.8,"text":"Omar is her screening partner."},{"start":11.16,"end":13.02,"text":"They've read the same abstract."},{"start":13.78,"end":15.14,"text":"Maya says include."},{"start":15.86,"end":17.4,"text":"Omar says exclude."},{"start":18.16,"end":19.3,"text":"Nobody's careless."},{"start":19.88,"end":22.18,"text":"Their criterion is just vague."},{"start":22.44,"end":25.7,"text":"A criterion is the rule for which studies"},{"start":25.7,"end":26.24,"text":"get in."},{"start":26.95,"end":30.39,"text":"We'll turn a vague criterion into a"},{"start":30.39,"end":33.71,"text":"checkable one, then put it on trial."},{"start":34.6,"end":37.14,"text":"First, where does a criterion live?"},{"start":37.38,"end":40.72,"text":"In the review's plan, written before the"},{"start":40.72,"end":41.02,"text":"search."},{"start":41.3,"end":43.84,"text":"That plan is called a protocol."},{"start":44.18,"end":47.42,"text":"A checklist called PRISMA P wants it"},{"start":47.42,"end":48.96,"text":"clearly written down first."},{"start":49.24,"end":51.18,"text":"It has seventeen items."},{"start":51.52,"end":53.84,"text":"We'll zoom in on eligibility."},{"start":54.95,"end":56.27,"text":"Why does that matter?"},{"start":56.99,"end":59.97,"text":"Say Maya glimpses a result: platform"},{"start":59.97,"end":61.77,"text":"comment studies look great."},{"start":62.13,"end":64.01,"text":"She's tempted to let them in."},{"start":64.51,"end":67.31,"text":"The Cochrane handbook says decisions like"},{"start":67.31,"end":70.47,"text":"that should not depend on the findings, as"},{"start":70.47,"end":71.39,"text":"far as possible."},{"start":72.133,"end":73.473,"text":"Now the key idea."},{"start":73.473,"end":77.013,"text":"A good criterion is a rule you can check"},{"start":77.013,"end":78.953,"text":"against the abstract's own words."},{"start":79.693,"end":81.973,"text":"That's called an operational criterion."},{"start":81.973,"end":85.613,"text":"For example: a chatbot makes the feedback."},{"start":86.113,"end":88.493,"text":"An abstract either says that or it"},{"start":88.493,"end":88.893,"text":"doesn't."},{"start":88.893,"end":91.153,"text":"Technology enhanced fails."},{"start":91.153,"end":93.413,"text":"Enhanced how, exactly?"},{"start":93.413,"end":96.893,"text":"A simple test: would two strangers make"},{"start":96.893,"end":97.553,"text":"the same call?"},{"start":98.3,"end":99.32,"text":"So let's test it."},{"start":99.9,"end":102.82,"text":"Maya and Omar each screen fourteen made up"},{"start":102.82,"end":104.98,"text":"records on their own: in or out."},{"start":105.44,"end":108.4,"text":"A record is one database entry: a title"},{"start":108.4,"end":109.12,"text":"and abstract."},{"start":109.56,"end":112.02,"text":"This small trial run is a pilot."},{"start":112.38,"end":115,"text":"Maya reads the rule broadly: any"},{"start":115,"end":115.98,"text":"technology counts."},{"start":116.72,"end":119.28,"text":"Omar reads it narrowly: the technology"},{"start":119.28,"end":121.28,"text":"must shape the feedback itself."},{"start":122.25,"end":125.17,"text":"How many of the fourteen do they agree on?"},{"start":125.59,"end":127.61,"text":"Pause and pick a number."},{"start":133.94,"end":135.2,"text":"Let's count the matches."},{"start":135.7,"end":138.52,"text":"That's nine of fourteen, about sixty four"},{"start":138.52,"end":138.98,"text":"percent."},{"start":139.36,"end":142.3,"text":"The five splits sit near the edge of the"},{"start":142.3,"end":142.52,"text":"rule."},{"start":142.96,"end":144.96,"text":"Those are called boundary cases."},{"start":145.64,"end":148.52,"text":"Maya writes them down in a decision log."},{"start":149.32,"end":151.9,"text":"But some of that agreement is just luck."},{"start":152.36,"end":154.74,"text":"Cohen's kappa takes the luck out."},{"start":155.34,"end":158.48,"text":"Step one: imagine both guessing blindly,"},{"start":158.48,"end":160,"text":"at their own rates."},{"start":160.62,"end":163.8,"text":"Maya says in twelve times out of fourteen."},{"start":164.26,"end":166.78,"text":"Omar says in seven times."},{"start":167.04,"end":170.24,"text":"The chance they both say in by luck is"},{"start":170.24,"end":173.88,"text":"Maya's rate times Omar's, about zero point"},{"start":173.88,"end":174.44,"text":"four three."},{"start":174.94,"end":178.38,"text":"Both out works the same way: about zero"},{"start":178.38,"end":179.22,"text":"point zero seven."},{"start":180.08,"end":182.98,"text":"Add them, and luck agrees half the time."},{"start":183.71,"end":184.21,"text":"Step two."},{"start":184.51,"end":187.35,"text":"Picture a line from zero to one."},{"start":187.67,"end":191.29,"text":"Zero means no better than luck, and one"},{"start":191.29,"end":192.41,"text":"means perfect."},{"start":193.29,"end":196.39,"text":"Luck already covers half, so the room"},{"start":196.39,"end":198.33,"text":"above luck is the other half."},{"start":198.73,"end":201.95,"text":"Their sixty four percent goes just zero"},{"start":201.95,"end":204.47,"text":"point one four three into that room."},{"start":204.89,"end":207.877,"text":"Divide by one half, and you get zero point"},{"start":207.877,"end":208.37,"text":"two nine."},{"start":209.17,"end":210.43,"text":"That's kappa."},{"start":210.55,"end":212.97,"text":"It isn't twenty nine percent agreement."},{"start":213.71,"end":216.19,"text":"They used just under a third of the room,"},{"start":216.19,"end":217.47,"text":"and that's low."},{"start":218.233,"end":220.693,"text":"Retrain them, or rewrite the rule?"},{"start":221.513,"end":224.293,"text":"Rewrite, because every split comes from"},{"start":224.293,"end":225.313,"text":"one vague phrase."},{"start":226.133,"end":227.333,"text":"Ask three questions."},{"start":228.053,"end":229.093,"text":"Who makes the feedback?"},{"start":229.593,"end":231.433,"text":"AI, like a chatbot."},{"start":231.913,"end":232.813,"text":"What's it about?"},{"start":233.113,"end":234.833,"text":"The student's own draft."},{"start":235.613,"end":237.133,"text":"Who sees it, and when?"},{"start":237.413,"end":240.413,"text":"The student, directly, during the task."},{"start":241.213,"end":243.853,"text":"Feedback an instructor or peer wrote is"},{"start":243.853,"end":244.173,"text":"out."},{"start":244.983,"end":245.683,"text":"Your turn."},{"start":246.003,"end":248.503,"text":"Run record two through the clauses."},{"start":248.903,"end":252.523,"text":"Is it in or out, and which clause decides?"},{"start":259.163,"end":259.543,"text":"It's out."},{"start":259.763,"end":262.863,"text":"An instructor wrote it, so clause one"},{"start":262.863,"end":263.363,"text":"fails."},{"start":263.743,"end":267.103,"text":"They rescreen with version two, and four"},{"start":267.103,"end":268.223,"text":"splits vanish."},{"start":268.863,"end":271.023,"text":"Watch rows seven and thirteen."},{"start":271.623,"end":273.443,"text":"Both flip to out."},{"start":274.163,"end":275.223,"text":"Same math again."},{"start":275.223,"end":278.303,"text":"Luck now gives fifty two percent."},{"start":278.303,"end":282.123,"text":"They agree on thirteen of fourteen, so"},{"start":282.123,"end":284.023,"text":"kappa is zero point eight five."},{"start":284.423,"end":287.483,"text":"In this made up example, only the words"},{"start":287.483,"end":287.903,"text":"changed."},{"start":288.303,"end":292.283,"text":"In a real pilot, test version two on fresh"},{"start":292.283,"end":292.703,"text":"records."},{"start":293.567,"end":295.787,"text":"Side by side, both numbers jump."},{"start":296.327,"end":296.967,"text":"So what?"},{"start":297.207,"end":300.167,"text":"Here, clearer words gave consistent"},{"start":300.167,"end":300.667,"text":"decisions."},{"start":301.147,"end":303.727,"text":"But agreeing doesn't make them right."},{"start":304.427,"end":304.787,"text":"Watch."},{"start":305.667,"end":307.667,"text":"Let's put version two on trial."},{"start":308.347,"end":309.627,"text":"Take record thirteen."},{"start":310.207,"end":312.967,"text":"An AI flags errors for the instructor,"},{"start":312.967,"end":314.847,"text":"who passes them on to students."},{"start":315.307,"end":318.047,"text":"Clause three says the student sees it"},{"start":318.047,"end":320.367,"text":"directly, so both say out."},{"start":320.987,"end":324.387,"text":"Yet under version one, they both said in."},{"start":324.927,"end":328.067,"text":"The sharper rule made them wrongly exclude"},{"start":328.067,"end":329.467,"text":"a plausible study."},{"start":330.237,"end":332.097,"text":"Record twelve still splits them."},{"start":332.477,"end":335.197,"text":"Does a simulated audience reacting to a"},{"start":335.197,"end":336.737,"text":"draft count as feedback?"},{"start":337.477,"end":339.877,"text":"That's the ambiguity to test with a"},{"start":339.877,"end":340.157,"text":"partner."},{"start":340.867,"end":342.407,"text":"How should Maya settle thirteen?"},{"start":342.887,"end":346.467,"text":"She could edit clause three, or narrow her"},{"start":346.467,"end":349.607,"text":"question to on-screen feedback so the old"},{"start":349.607,"end":350.367,"text":"clause fits."},{"start":351.147,"end":352.787,"text":"Which fix is honest?"},{"start":359.247,"end":360.487,"text":"It's fix A."},{"start":361.407,"end":363.627,"text":"Narrowing the question to ease screening"},{"start":363.627,"end":365.867,"text":"is redesigning it for convenience."},{"start":365.867,"end":369.087,"text":"Cochrane makes a similar point about"},{"start":369.087,"end":370.067,"text":"choosing participants."},{"start":371.047,"end":373.647,"text":"Criteria should be broad enough to cover"},{"start":373.647,"end":376.227,"text":"the likely diversity of studies, yet"},{"start":376.227,"end":378.907,"text":"narrow enough to give a meaningful answer."},{"start":379.427,"end":380.787,"text":"Same balance here."},{"start":381.507,"end":384.187,"text":"Fix A keeps Maya's question whole."},{"start":385.067,"end":388.087,"text":"Changing a criterion is allowed if you log"},{"start":388.087,"end":389.267,"text":"it and say why."},{"start":389.847,"end":392.847,"text":"Clause three now says the feedback reaches"},{"start":392.847,"end":395.567,"text":"the student in the task, directly or"},{"start":395.567,"end":396.407,"text":"through the instructor."},{"start":396.747,"end":399.887,"text":"It came from the pilot, not from peeking"},{"start":399.887,"end":400.287,"text":"at findings."},{"start":400.587,"end":403.867,"text":"So Maya puts it in her amendment log, not"},{"start":403.867,"end":404.727,"text":"her decision log."},{"start":405.187,"end":407.567,"text":"Record thirteen now passes."},{"start":408.367,"end":409.047,"text":"To recap."},{"start":409.267,"end":412.787,"text":"First, write criteria into the protocol"},{"start":412.787,"end":414.467,"text":"before any results."},{"start":415.487,"end":418.687,"text":"Second, make every clause checkable, and"},{"start":418.687,"end":420.027,"text":"test it with a partner."},{"start":420.767,"end":424.067,"text":"Third, agreeing isn't the same as being"},{"start":424.067,"end":424.427,"text":"right."},{"start":425.067,"end":427.867,"text":"Fix the criterion to fit your question,"},{"start":427.867,"end":429.127,"text":"not the reverse."},{"start":430.067,"end":431.447,"text":"Now try it yourself."},{"start":431.987,"end":434.907,"text":"Write a draft question and one checkable"},{"start":434.907,"end":435.307,"text":"criterion."},{"start":435.967,"end":438.827,"text":"Defend it: is it needed, and is it neither"},{"start":438.827,"end":440.567,"text":"too broad nor too narrow?"},{"start":441.007,"end":443.787,"text":"Name one study it might wrongly exclude."},{"start":444.147,"end":446.607,"text":"Write down one ambiguity to test."},{"start":446.847,"end":449.627,"text":"Then have a colleague try it on a boundary"},{"start":449.627,"end":452.967,"text":"case, and revise if the call is unclear."},{"start":453.917,"end":456.817,"text":"A good next step: pilot your criterion"},{"start":456.817,"end":459.577,"text":"with a real partner on six to eight"},{"start":459.577,"end":459.997,"text":"records."},{"start":459.997,"end":464.177,"text":"Mix clear ins, clear outs, and doubtful"},{"start":464.177,"end":464.417,"text":"ones."},{"start":464.417,"end":468.277,"text":"With so few, watch the splits more than"},{"start":468.277,"end":468.657,"text":"kappa."},{"start":468.657,"end":472.017,"text":"Then ask yourself: would two strangers"},{"start":472.017,"end":473.417,"text":"make the same call?"}]},"es-04-search-strings":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.8,"text":"A search string is something you can test."},{"start":3.12,"end":5.92,"text":"Today you'll check yours against studies"},{"start":5.92,"end":8.88,"text":"you already know, then improve it with"},{"start":8.88,"end":9.52,"text":"what you find."},{"start":9.98,"end":13.36,"text":"Search guides recommend this exact check."},{"start":14.2,"end":14.7,"text":"Meet Maya."},{"start":15,"end":17.22,"text":"She's a made up doctoral student."},{"start":17.4,"end":20.56,"text":"Her question: does AI chatbot feedback"},{"start":20.56,"end":22.66,"text":"improve undergraduates' writing?"},{"start":22.84,"end":26.62,"text":"Her first string: chatbot, AND writing,"},{"start":26.62,"end":28.06,"text":"AND undergraduate."},{"start":29.19,"end":32.18,"text":"She runs it in a made up database of three"},{"start":32.18,"end":33.13,"text":"hundred records."},{"start":33.86,"end":35.31,"text":"She gets twelve hits."},{"start":35.94,"end":36.73,"text":"Is that good?"},{"start":37.09,"end":39.77,"text":"The number alone can't tell you."},{"start":40.433,"end":43.453,"text":"Before she searched, Maya collected ten"},{"start":43.453,"end":45.993,"text":"studies she knows belong in her review."},{"start":46.213,"end":48.273,"text":"We'll call them known studies."},{"start":48.513,"end":51.513,"text":"A good string should find all of them."},{"start":52.173,"end":53.353,"text":"Let's run the test."},{"start":54.133,"end":57.353,"text":"Her string finds only four of the ten."},{"start":58.193,"end":60.993,"text":"Out of all the relevant studies, the share"},{"start":60.993,"end":63.113,"text":"your search finds is called recall."},{"start":63.933,"end":65.533,"text":"It's also called sensitivity."},{"start":66.693,"end":69.853,"text":"Nobody knows every relevant study, so we"},{"start":69.853,"end":72.153,"text":"estimate recall on the ones we know."},{"start":72.153,"end":76.013,"text":"Here that's four out of ten, or point"},{"start":76.013,"end":76.313,"text":"four."},{"start":77.023,"end":77.943,"text":"Now the cost."},{"start":78.643,"end":81.503,"text":"Every hit is a record someone has to read."},{"start":82.203,"end":84.363,"text":"We call those records to screen."},{"start":85.123,"end":88.003,"text":"Precision is the share of hits that turn"},{"start":88.003,"end":88.643,"text":"out relevant."},{"start":89.323,"end":91.763,"text":"You only learn it after screening."},{"start":92.583,"end":93.743,"text":"Let's put this on a chart."},{"start":94.203,"end":96.363,"text":"Records to screen go across."},{"start":97.043,"end":99.263,"text":"Known studies found go up."},{"start":99.723,"end":103.023,"text":"Version one is cheap, but it misses six."},{"start":103.833,"end":105.073,"text":"Why so many misses?"},{"start":105.833,"end":108.993,"text":"Each line of Maya's string holds one idea"},{"start":108.993,"end":110.033,"text":"from her question."},{"start":110.473,"end":112.573,"text":"That's called a concept block."},{"start":113.293,"end":116.313,"text":"Right now each block has just one word."},{"start":116.853,"end":119.473,"text":"But authors say the same thing in"},{"start":119.473,"end":120.113,"text":"different ways."},{"start":120.963,"end":123.903,"text":"Inside a block, join the wordings with OR."},{"start":124.243,"end":127.283,"text":"Either word counts, so the block gets"},{"start":127.283,"end":127.743,"text":"wider."},{"start":128.203,"end":130.423,"text":"Between blocks, use AND."},{"start":130.903,"end":134.223,"text":"Every idea has to show up, so the results"},{"start":134.223,"end":135.403,"text":"get narrower."},{"start":136.267,"end":138.467,"text":"Maya's first fix goes big."},{"start":138.667,"end":142.247,"text":"She adds conversational agent, and broad"},{"start":142.247,"end":144.747,"text":"words like AI and technology."},{"start":145.107,"end":147.767,"text":"She adds essay and composition."},{"start":148.407,"end":150.407,"text":"She drops the who block."},{"start":151.087,"end":152.667,"text":"More hits or fewer?"},{"start":153.067,"end":154.907,"text":"Decide before we go on."},{"start":161.167,"end":163.727,"text":"Hits jump to two hundred thirty four."},{"start":164.367,"end":166.387,"text":"All ten known studies are in there."},{"start":166.787,"end":169.087,"text":"Version two sits far right."},{"start":169.747,"end":170.447,"text":"Is she done?"},{"start":176.807,"end":177.307,"text":"Not yet."},{"start":177.687,"end":179.027,"text":"Look at the cost."},{"start":179.527,"end":182.707,"text":"Many of those records are noise, like AI"},{"start":182.707,"end":184.327,"text":"essay scoring in high schools."},{"start":185.027,"end":187.727,"text":"The Cochrane Handbook says to get as much"},{"start":187.727,"end":190.187,"text":"recall as you can, while aiming for"},{"start":190.187,"end":191.087,"text":"reasonable precision."},{"start":192.033,"end":194.453,"text":"In version three, she trims."},{"start":194.453,"end":198.693,"text":"She drops AI and technology, and puts the"},{"start":198.693,"end":199.713,"text":"who block back."},{"start":200.573,"end":204.173,"text":"Now she gets forty one hits, and nine of"},{"start":204.173,"end":205.473,"text":"ten known studies."},{"start":206.283,"end":207.083,"text":"Much cheaper."},{"start":207.323,"end":210.763,"text":"But one known study is missing, number"},{"start":210.763,"end":211.083,"text":"ten."},{"start":211.343,"end":215.183,"text":"Its title says: a conversational agent for"},{"start":215.183,"end":217.963,"text":"essay revision, with university students."},{"start":218.383,"end":220.323,"text":"Which block let it slip?"},{"start":226.7,"end":230.06,"text":"Bramer and colleagues suggest this: test"},{"start":230.06,"end":232.26,"text":"the missed record against each block."},{"start":232.7,"end":234.56,"text":"Block A is the tool."},{"start":235.3,"end":237.48,"text":"Conversational agent is there, so it"},{"start":237.48,"end":237.8,"text":"matches."},{"start":238.28,"end":240.26,"text":"Block B is the outcome."},{"start":240.8,"end":242.24,"text":"Essay matches too."},{"start":242.78,"end":244.42,"text":"Block C is who."},{"start":244.8,"end":248.36,"text":"The record says university, and that word"},{"start":248.36,"end":249.42,"text":"isn't in the block."},{"start":249.82,"end":252.24,"text":"Block C is the one that failed."},{"start":252.95,"end":256.07,"text":"Each block you add is one more place a"},{"start":256.07,"end":257.27,"text":"study can slip through."},{"start":258.03,"end":260.89,"text":"Keep only the blocks your question needs."},{"start":261.76,"end":265.12,"text":"Block C still matters, so Maya fixes it."},{"start":265.22,"end":268.66,"text":"She cuts university to its stem and adds"},{"start":268.66,"end":269.56,"text":"an asterisk."},{"start":269.78,"end":271.62,"text":"That's called truncation."},{"start":271.9,"end":275.42,"text":"It matches university, universities, and"},{"start":275.42,"end":276.18,"text":"similar endings."},{"start":277.133,"end":278.273,"text":"She reruns it."},{"start":278.373,"end":282.513,"text":"Version four gets forty nine hits, and ten"},{"start":282.513,"end":284.153,"text":"out of ten known studies."},{"start":285.023,"end":287.083,"text":"So what did that change buy her?"},{"start":287.343,"end":290.843,"text":"It gained one known study, and it cost"},{"start":290.843,"end":292.243,"text":"eight more records."},{"start":293.023,"end":295.963,"text":"Her earlier trim changed two things at"},{"start":295.963,"end":296.283,"text":"once."},{"start":296.663,"end":299.303,"text":"Together they cut almost two hundred"},{"start":299.303,"end":299.963,"text":"records."},{"start":300.803,"end":303.683,"text":"Alone, each change cuts well over a"},{"start":303.683,"end":303.983,"text":"hundred."},{"start":304.343,"end":307.483,"text":"That adds up to more than the total, so"},{"start":307.483,"end":308.623,"text":"the changes overlap."},{"start":309.323,"end":312.763,"text":"Only one change at a time shows which did"},{"start":312.763,"end":313.023,"text":"what."},{"start":313.813,"end":317.713,"text":"Ten out of ten is a check, not proof."},{"start":318.693,"end":321.473,"text":"Other relevant studies may still be"},{"start":321.473,"end":321.793,"text":"missing."},{"start":322.533,"end":326.073,"text":"The Cochrane Handbook calls it one simple"},{"start":326.073,"end":326.513,"text":"test."},{"start":327.367,"end":330.667,"text":"Next, translate your string; don't just"},{"start":330.667,"end":331.307,"text":"paste it."},{"start":331.847,"end":334.967,"text":"ERIC is a database, a collection of"},{"start":334.967,"end":335.327,"text":"records."},{"start":336.227,"end":339.367,"text":"EBSCOhost and ProQuest are platforms,"},{"start":339.367,"end":341.367,"text":"websites where you search it."},{"start":341.867,"end":343.587,"text":"Each has its own rules."},{"start":344.397,"end":346.977,"text":"A field code tells the platform where to"},{"start":346.977,"end":347.237,"text":"look."},{"start":347.237,"end":351.417,"text":"TI means title, and AB means abstract."},{"start":352.057,"end":355.677,"text":"On EBSCOhost, Maya has to type block C"},{"start":355.677,"end":356.257,"text":"twice."},{"start":356.997,"end":360.417,"text":"On ProQuest, one combined code covers"},{"start":360.417,"end":360.797,"text":"both."},{"start":361.597,"end":364.897,"text":"Everything Maya typed so far is free text."},{"start":365.537,"end":368.677,"text":"Each database also tags records with its"},{"start":368.677,"end":369.857,"text":"own subject labels."},{"start":370.517,"end":372.837,"text":"Those are called controlled vocabulary."},{"start":373.517,"end":376.977,"text":"The Cochrane Handbook says to search with"},{"start":376.977,"end":377.317,"text":"both."},{"start":378.077,"end":379.957,"text":"Watch out for a missing OR."},{"start":380.657,"end":383.617,"text":"In many interfaces, two words with nothing"},{"start":383.617,"end":385.477,"text":"between them get joined with AND."},{"start":385.817,"end":388.757,"text":"If an AI tool translates your string,"},{"start":388.757,"end":390.957,"text":"test it like one you wrote."},{"start":391.497,"end":394.057,"text":"Bramer and colleagues advise checking"},{"start":394.057,"end":395.457,"text":"searches for recall."},{"start":396.367,"end":398.127,"text":"Last, she logs it."},{"start":398.487,"end":402.127,"text":"PRISMA-S is an extension of PRISMA for"},{"start":402.127,"end":403.007,"text":"reporting searches."},{"start":403.787,"end":405.667,"text":"It lists sixteen items."},{"start":406.407,"end":409.327,"text":"Here are four, from Maya's made up log."},{"start":410.167,"end":412.627,"text":"She notes the database and platform, and"},{"start":412.627,"end":413.067,"text":"the date."},{"start":413.507,"end":416.587,"text":"She pastes the full string exactly as she"},{"start":416.587,"end":416.947,"text":"ran it."},{"start":417.387,"end":420.127,"text":"Then the records she found: forty nine."},{"start":420.987,"end":423.627,"text":"In your own log, add a note: forty one"},{"start":423.627,"end":426.467,"text":"before, forty nine after, and why."},{"start":427.333,"end":431.773,"text":"First, build concept blocks: OR inside,"},{"start":431.773,"end":433.113,"text":"AND between."},{"start":433.613,"end":436.313,"text":"Second, test on known studies."},{"start":437.113,"end":439.813,"text":"Weigh known study recall against records"},{"start":439.813,"end":440.553,"text":"to screen."},{"start":441.373,"end":445.233,"text":"Third, change one thing at a time, and log"},{"start":445.233,"end":445.893,"text":"the counts."},{"start":446.743,"end":447.443,"text":"Now you try."},{"start":447.843,"end":450.503,"text":"Pick a published review on your topic."},{"start":450.823,"end":453.043,"text":"The included studies that fit your"},{"start":453.043,"end":455.063,"text":"question are your known studies."},{"start":455.463,"end":458.763,"text":"If your string misses one, test it block"},{"start":458.763,"end":461.283,"text":"by block, and change one thing."},{"start":461.963,"end":464.063,"text":"Write down the counts before and after,"},{"start":464.063,"end":466.643,"text":"and what you gained and may have lost."},{"start":467.403,"end":468.443,"text":"One last question."},{"start":469.043,"end":471.743,"text":"Run your string on three or more studies"},{"start":471.743,"end":472.983,"text":"you know are relevant."},{"start":473.483,"end":474.823,"text":"How many does it find?"},{"start":475.263,"end":478.483,"text":"If it misses one, which block let it slip?"}]},"es-05-screening-calibration":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":3.3,"text":"Two people read the same abstract and"},{"start":3.3,"end":4.36,"text":"decide differently."},{"start":4.98,"end":8.98,"text":"Today's one idea: calibrate before you"},{"start":8.98,"end":10.02,"text":"count."},{"start":10.02,"end":13.38,"text":"Fix your screening rules on a small pilot,"},{"start":13.38,"end":14.96,"text":"then measure agreement."},{"start":15.89,"end":19.65,"text":"It's a habit worth building whenever two"},{"start":19.65,"end":20.45,"text":"people screen."},{"start":21.4,"end":23.62,"text":"Maya has already sharpened her criterion."},{"start":23.62,"end":27.08,"text":"Before seeing any findings, she updated"},{"start":27.08,"end":27.72,"text":"her question."},{"start":28.3,"end":30.9,"text":"Do chatbot or language model comments"},{"start":30.9,"end":33.08,"text":"improve undergraduate writing?"},{"start":33.08,"end":36.02,"text":"Now she and Omar put it to work."},{"start":36.84,"end":38.94,"text":"Screening has two stages."},{"start":39.16,"end":42.92,"text":"In stage one, you judge the record, just a"},{"start":42.92,"end":44.08,"text":"title and abstract."},{"start":44.4,"end":47.78,"text":"In stage two, you check the full report"},{"start":47.78,"end":49.66,"text":"against every criterion."},{"start":50.61,"end":51.97,"text":"Take one of Maya's records."},{"start":52.39,"end":54.83,"text":"It's an automated grammar checker in a"},{"start":54.83,"end":56.01,"text":"first year writing course."},{"start":56.55,"end":58.35,"text":"Is that AI feedback?"},{"start":58.95,"end":61.37,"text":"From two lines, she can't tell."},{"start":62.08,"end":63.92,"text":"Keep it, or drop it?"},{"start":69.87,"end":70.87,"text":"She keeps it."},{"start":71.11,"end":74.59,"text":"The Cochrane Handbook advises being over"},{"start":74.59,"end":75.53,"text":"inclusive here."},{"start":75.91,"end":79.45,"text":"A wrong drop at stage one never gets a"},{"start":79.45,"end":80.03,"text":"second look."},{"start":80.49,"end":83.91,"text":"A wrong keep costs one more full text"},{"start":83.91,"end":84.21,"text":"check."},{"start":85,"end":88.42,"text":"Now a pilot: a small practice batch."},{"start":88.84,"end":92.72,"text":"Maya and Omar each screen the same forty"},{"start":92.72,"end":94.52,"text":"made up records, independently."},{"start":95.92,"end":98.86,"text":"They both kept eight and both excluded"},{"start":98.86,"end":99.7,"text":"twenty two."},{"start":100.42,"end":104.58,"text":"Maya alone kept six, and Omar alone kept"},{"start":104.58,"end":104.96,"text":"four."},{"start":105.79,"end":107.21,"text":"How often did they agree?"},{"start":107.92,"end":111.35,"text":"Eight plus twenty two out of forty, which"},{"start":111.35,"end":112.69,"text":"is seventy five percent."},{"start":112.69,"end":114.91,"text":"That's percent agreement."},{"start":115.85,"end":117.15,"text":"Some of that is luck."},{"start":117.97,"end":120.13,"text":"Maya keeps fourteen of forty."},{"start":120.79,"end":122.15,"text":"Omar keeps twelve."},{"start":122.67,"end":125.73,"text":"If they voted at random at those rates,"},{"start":125.73,"end":129.05,"text":"they'd match by luck fifty six percent of"},{"start":129.05,"end":129.41,"text":"the time."},{"start":130.11,"end":131.73,"text":"That's chance agreement."},{"start":132.65,"end":134.63,"text":"Next, Cohen's kappa."},{"start":134.89,"end":138.21,"text":"Picture agreement as a bar from zero to"},{"start":138.21,"end":138.43,"text":"one."},{"start":138.43,"end":141.67,"text":"Grey is what luck gives for free."},{"start":142.49,"end":145.59,"text":"Kappa asks how much of the room above luck"},{"start":145.59,"end":146.45,"text":"they reached."},{"start":146.77,"end":150.25,"text":"That's seventy five minus fifty six, over"},{"start":150.25,"end":151.67,"text":"one minus fifty six."},{"start":152.43,"end":156.27,"text":"That's zero point four three, a bit under"},{"start":156.27,"end":156.61,"text":"half."},{"start":157.467,"end":158.807,"text":"Should Maya report it?"},{"start":159.147,"end":160.087,"text":"Not yet."},{"start":160.327,"end":163.567,"text":"The Cochrane Handbook says a pilot helps"},{"start":163.567,"end":165.827,"text":"refine and clarify the criteria."},{"start":166.387,"end":169.807,"text":"So treat this first number as a diagnosis."},{"start":170.877,"end":172.377,"text":"They split on ten."},{"start":172.737,"end":176.557,"text":"Six came from an unclear rule, like R07."},{"start":177.237,"end":179.217,"text":"That's criterion ambiguity."},{"start":180.217,"end":183.217,"text":"Three were slips, where someone missed a"},{"start":183.217,"end":186.297,"text":"clear rule, like the year limit in R22."},{"start":186.757,"end":189.397,"text":"One was a real judgement call."},{"start":189.577,"end":193.777,"text":"In R31 the rule's clear, but they weighed"},{"start":193.777,"end":194.737,"text":"the evidence differently."},{"start":195.597,"end":197.717,"text":"Each kind gets its own fix."},{"start":198.437,"end":201.677,"text":"For an unclear rule, revise the criterion."},{"start":202.457,"end":205.877,"text":"For a slip, add a note, like check the"},{"start":205.877,"end":206.497,"text":"year first."},{"start":206.897,"end":210.237,"text":"For a judgement call, a third reviewer"},{"start":210.237,"end":210.517,"text":"decides."},{"start":211.377,"end":214.517,"text":"That's adjudication, and the rule stays."},{"start":215.633,"end":218.473,"text":"Version one said the feedback is made by"},{"start":218.473,"end":218.973,"text":"software."},{"start":218.973,"end":222.653,"text":"Version two says a chatbot or language"},{"start":222.653,"end":225.273,"text":"model writes comments on the student's own"},{"start":225.273,"end":225.633,"text":"draft."},{"start":225.633,"end":229.553,"text":"It adds a boundary: tools that only flag"},{"start":229.553,"end":232.233,"text":"spelling or grammar are out at full text."},{"start":232.233,"end":235.793,"text":"And it keeps the default: unsure at stage"},{"start":235.793,"end":236.813,"text":"one, keep."},{"start":237.723,"end":240.003,"text":"Every disagreement goes into a decision"},{"start":240.003,"end":242.663,"text":"log, so every call is traceable."},{"start":243.063,"end":244.103,"text":"Here's the slip."},{"start":244.643,"end":246.063,"text":"And here's the judgement call."},{"start":246.703,"end":249.303,"text":"The third reviewer kept it, using the"},{"start":249.303,"end":249.583,"text":"default."},{"start":250.467,"end":254.227,"text":"Then they pilot again, on forty fresh made"},{"start":254.227,"end":257.287,"text":"up records with a similar mix, so nobody"},{"start":257.287,"end":258.367,"text":"remembers answers."},{"start":259.047,"end":260.267,"text":"Here's the new table."},{"start":261.297,"end":261.877,"text":"Your turn."},{"start":262.317,"end":265.697,"text":"Use the same three steps: agreement,"},{"start":265.697,"end":267.877,"text":"chance, then kappa."},{"start":268.337,"end":270.137,"text":"Pause and work it out."},{"start":278.067,"end":279.9,"text":"Agreement is ninety two and a half"},{"start":279.9,"end":283.367,"text":"percent, chance about sixty one, and kappa"},{"start":283.367,"end":284.667,"text":"zero point eight one."},{"start":285.687,"end":288.547,"text":"Disagreements fell from ten to three on a"},{"start":288.547,"end":291.607,"text":"similar mix, so the clearer rule is ready"},{"start":291.607,"end":292.027,"text":"to use."},{"start":292.867,"end":294.807,"text":"Now a more typical case."},{"start":295.187,"end":298.027,"text":"Usually, most records a search finds are"},{"start":298.027,"end":300.207,"text":"off topic, like this made up set."},{"start":300.547,"end":303.607,"text":"They both exclude thirty six of forty,"},{"start":303.607,"end":306.887,"text":"both keep one, and split on three."},{"start":307.677,"end":310.497,"text":"Agreement is ninety two and a half percent"},{"start":310.497,"end":310.857,"text":"again."},{"start":311.397,"end":312.697,"text":"Is kappa the same?"},{"start":318.547,"end":318.727,"text":"No."},{"start":319.067,"end":322.907,"text":"Imagine Omar excluded all forty unread."},{"start":322.907,"end":326.487,"text":"He'd still match Maya on thirty seven, the"},{"start":326.487,"end":327.207,"text":"same score."},{"start":328.097,"end":330.587,"text":"Luck's grey bar fills almost the whole"},{"start":330.587,"end":333.994,"text":"ruler, so kappa drops to zero point three"},{"start":333.994,"end":334.267,"text":"six."},{"start":335.407,"end":338.167,"text":"Two researchers called this high agreement"},{"start":338.167,"end":339.667,"text":"but low kappa."},{"start":340.287,"end":343.447,"text":"Here it happens because keeps are rare."},{"start":344.047,"end":347.827,"text":"How common keeps are is called prevalence,"},{"start":347.827,"end":349.927,"text":"so it's the prevalence trap."},{"start":350.787,"end":351.607,"text":"Is kappa broken?"},{"start":352.107,"end":352.747,"text":"No."},{"start":353.087,"end":355.007,"text":"It's warning you about the keeps."},{"start":355.447,"end":358.207,"text":"When one says keep, does the other agree?"},{"start":358.827,"end":362.767,"text":"Maya kept three and Omar two, five keep"},{"start":362.767,"end":363.087,"text":"votes."},{"start":363.647,"end":366.607,"text":"Only two match, on the one record both"},{"start":366.607,"end":366.967,"text":"kept."},{"start":367.367,"end":370.107,"text":"Two out of five is zero point four."},{"start":370.847,"end":373.867,"text":"The excludes look great: seventy two of"},{"start":373.867,"end":376.654,"text":"seventy five votes match, zero point nine"},{"start":376.654,"end":376.907,"text":"six."},{"start":377.327,"end":379.967,"text":"So report both, with kappa."},{"start":380.597,"end":383.557,"text":"Your own pilot will probably look like"},{"start":383.557,"end":387.017,"text":"this, so kappa may come out modest."},{"start":387.237,"end":389.817,"text":"The keeps show where to work."},{"start":389.937,"end":393.237,"text":"And don't lean on labels like substantial."},{"start":394.017,"end":396.737,"text":"Sources set the cut offs differently."},{"start":397.7,"end":399.4,"text":"The rule carries forward."},{"start":400.14,"end":403.02,"text":"Version two becomes a field in Maya's"},{"start":403.02,"end":403.94,"text":"extraction form."},{"start":404.46,"end":406.92,"text":"Her field definitions make up her"},{"start":406.92,"end":407.46,"text":"codebook."},{"start":408.16,"end":410.54,"text":"Anyone following it should get the same"},{"start":410.54,"end":411.04,"text":"answer."},{"start":411.84,"end":415.64,"text":"Maya applies it to study S14, Omar does"},{"start":415.64,"end":417.3,"text":"too, and they agree."},{"start":418.11,"end":421.13,"text":"A screening app can record each person's"},{"start":421.13,"end":422.97,"text":"vote and flag conflicts."},{"start":423.78,"end":427.23,"text":"A safe default is to let tools help with"},{"start":427.23,"end":429.83,"text":"the work, and let people make the"},{"start":429.83,"end":430.19,"text":"decisions."},{"start":431.133,"end":434.893,"text":"First, screen in two stages, and when"},{"start":434.893,"end":437.113,"text":"unsure at stage one, keep."},{"start":437.793,"end":441.793,"text":"Second, pilot, sort the disagreements, fix"},{"start":441.793,"end":444.313,"text":"the rule, and measure again on fresh"},{"start":444.313,"end":444.713,"text":"records."},{"start":445.233,"end":449.293,"text":"Third, report the table, agreement, kappa,"},{"start":449.293,"end":450.933,"text":"and agreement on keeps."},{"start":451.763,"end":454.603,"text":"Before you screen, write your plan down."},{"start":455.273,"end":458.123,"text":"One part is an exclusion reason hierarchy."},{"start":458.993,"end":461.923,"text":"That means ranking your criteria, and"},{"start":461.923,"end":464.203,"text":"logging the first one a study fails."},{"start":464.823,"end":467.523,"text":"Cochrane also asks you to decide in"},{"start":467.523,"end":469.663,"text":"advance how to settle disagreements."},{"start":470.443,"end":471.443,"text":"Now try it yourself."},{"start":471.943,"end":474.183,"text":"Find a colleague or study partner."},{"start":474.443,"end":476.963,"text":"You each screen the same twenty records"},{"start":476.963,"end":477.703,"text":"from your search."},{"start":478.323,"end":480.243,"text":"Fill the table before you talk."},{"start":480.443,"end":484.103,"text":"Then work out agreement, chance, kappa,"},{"start":484.103,"end":485.663,"text":"and agreement on keeps."},{"start":486.323,"end":488.183,"text":"Last, pick one split."},{"start":488.763,"end":491.423,"text":"Which kind is it, and which fix does it"},{"start":491.423,"end":491.603,"text":"need?"}]},"es-06-table-to-claim":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.86,"text":"Meet Maya, a made up doctoral student."},{"start":3.54,"end":6.16,"text":"She wants to know if AI chatbot feedback"},{"start":6.16,"end":8.5,"text":"improves undergraduates' writing."},{"start":9.02,"end":12,"text":"She's put nine studies into an extraction"},{"start":12,"end":15.16,"text":"table, and now she needs a claim."},{"start":15.96,"end":19.2,"text":"Today's idea: build the claim from the"},{"start":19.2,"end":22.76,"text":"table, question by question, not study by"},{"start":22.76,"end":23.08,"text":"study."},{"start":23.5,"end":24.88,"text":"One limit first."},{"start":25.48,"end":28.5,"text":"A study's effect size is how big its"},{"start":28.5,"end":29.14,"text":"result is."},{"start":29.14,"end":32.74,"text":"We won't average effect sizes into one"},{"start":32.74,"end":33.1,"text":"number."},{"start":33.94,"end":36.88,"text":"That's meta-analysis, and it's outside"},{"start":36.88,"end":37.56,"text":"this video."},{"start":38.367,"end":40.947,"text":"Maya's first draft goes like this."},{"start":41.327,"end":43.487,"text":"Study one found a gain."},{"start":43.687,"end":46.127,"text":"Study two favoured the comparison."},{"start":46.927,"end":49.067,"text":"That's a summary, study by study."},{"start":49.267,"end":52.487,"text":"A synthesis goes question by question."},{"start":53.127,"end":54.887,"text":"Which way do the results point?"},{"start":55.087,"end":56.087,"text":"For whom?"},{"start":56.247,"end":58.247,"text":"How sure are we?"},{"start":58.967,"end":60.327,"text":"Here's her made up table."},{"start":60.847,"end":64.147,"text":"The setting is first year composition, or"},{"start":64.147,"end":66.287,"text":"an upper level course like biology."},{"start":67.187,"end":68.467,"text":"Next is design."},{"start":69.047,"end":72.447,"text":"In a randomized trial, chance decides who"},{"start":72.447,"end":73.587,"text":"gets AI feedback."},{"start":74.227,"end":77.567,"text":"A quasi experiment compares groups that"},{"start":77.567,"end":78.307,"text":"weren't randomized."},{"start":79.007,"end":81.927,"text":"A pre post study measures one group,"},{"start":81.927,"end":83.547,"text":"before and after."},{"start":84.167,"end":86.207,"text":"Size is the number of students."},{"start":86.207,"end":89.007,"text":"Next, the direction of the effect."},{"start":89.007,"end":92.507,"text":"Up means students wrote better with AI"},{"start":92.507,"end":94.627,"text":"feedback than a comparison group."},{"start":94.627,"end":98.547,"text":"In a pre post study, up means better than"},{"start":98.547,"end":98.847,"text":"before."},{"start":98.847,"end":101.927,"text":"Down means the comparison group did"},{"start":101.927,"end":102.207,"text":"better."},{"start":102.917,"end":103.957,"text":"Then significance."},{"start":104.337,"end":107.657,"text":"A result is statistically significant when"},{"start":107.657,"end":109.637,"text":"it would be rare if there were no real"},{"start":109.637,"end":109.977,"text":"effect."},{"start":110.417,"end":113.297,"text":"Here that means p below point oh five."},{"start":113.897,"end":115.677,"text":"Last is appraisal."},{"start":115.977,"end":118.997,"text":"Maya rated how much each study's design or"},{"start":118.997,"end":121.057,"text":"conduct could have biased its result."},{"start":121.417,"end":124.697,"text":"Take study five: thirty students, measured"},{"start":124.697,"end":125.917,"text":"before and after."},{"start":126.297,"end":129.017,"text":"Plenty else could explain that gain, so"},{"start":129.017,"end":129.797,"text":"it's high concern."},{"start":130.237,"end":132.577,"text":"Study three randomized two hundred twenty"},{"start":132.577,"end":134.857,"text":"students, so it's low."},{"start":135.6,"end":137.26,"text":"Now a tempting shortcut."},{"start":137.98,"end":140.5,"text":"Each study gets one vote, and you count"},{"start":140.5,"end":140.84,"text":"them up."},{"start":141.04,"end":142.8,"text":"That's called vote counting."},{"start":143.08,"end":145.78,"text":"Here, the vote is: was it significant?"},{"start":146.6,"end":148.22,"text":"Only two of nine were."},{"start":148.96,"end":151.7,"text":"So does AI feedback mostly fail?"},{"start":157.63,"end":157.87,"text":"No."},{"start":157.91,"end":159.23,"text":"Look at the sizes."},{"start":159.51,"end":162.63,"text":"Five studies had thirty to sixty students,"},{"start":162.63,"end":164.57,"text":"and all five point up."},{"start":165.05,"end":167.81,"text":"Studies that small often can't reach"},{"start":167.81,"end":170.81,"text":"significance, even when the gain is real."},{"start":171.19,"end":175.33,"text":"So not significant doesn't mean no effect."},{"start":175.75,"end":178.79,"text":"A standard guide, the Cochrane Handbook,"},{"start":178.79,"end":181.99,"text":"warns that counting by significance can"},{"start":181.99,"end":183.39,"text":"lead to the wrong conclusion."},{"start":184.27,"end":187.21,"text":"A better way is to keep counting votes,"},{"start":187.21,"end":188.85,"text":"but vote on direction."},{"start":189.53,"end":192.93,"text":"Seven of nine point up, and two point"},{"start":192.93,"end":193.35,"text":"down."},{"start":193.73,"end":196.71,"text":"That answers question one: which way?"},{"start":197.5,"end":201.7,"text":"A reporting checklist called SW i M names"},{"start":201.7,"end":202.4,"text":"this method."},{"start":203.2,"end":206.04,"text":"It's for synthesis without meta-analysis."},{"start":206.68,"end":209.38,"text":"The Cochrane Handbook accepts it when"},{"start":209.38,"end":211.2,"text":"effect sizes can't be combined."},{"start":211.96,"end":214.78,"text":"But it ignores how big the effects are."},{"start":215.36,"end":218.44,"text":"And with few studies, you can't be very"},{"start":218.44,"end":218.74,"text":"sure."},{"start":219.533,"end":222.853,"text":"Step one is to sort the studies into sets"},{"start":222.853,"end":224.113,"text":"that share a feature."},{"start":224.493,"end":226.273,"text":"That's called grouping."},{"start":226.273,"end":231.293,"text":"SW i M's first item asks you to justify"},{"start":231.293,"end":232.153,"text":"your groups."},{"start":232.993,"end":234.953,"text":"Maya groups by setting."},{"start":235.493,"end":239.353,"text":"Her reason: a general chatbot may handle"},{"start":239.353,"end":241.893,"text":"writing in a specific field less well."},{"start":242.653,"end":243.453,"text":"Watch the rows."},{"start":245.403,"end":248.143,"text":"No number changed, only the arrangement."},{"start":248.683,"end":250.543,"text":"Maya marks the groups."},{"start":251.353,"end":254.553,"text":"In first year composition, all five point"},{"start":254.553,"end":254.933,"text":"up."},{"start":255.253,"end":258.393,"text":"In upper level courses, only two of four"},{"start":258.393,"end":258.613,"text":"do."},{"start":258.993,"end":261.953,"text":"That answers question two, for whom."},{"start":262.493,"end":263.393,"text":"Is it the setting?"},{"start":263.713,"end":264.393,"text":"Maybe."},{"start":264.993,"end":267.593,"text":"A pattern in one grouping can be another"},{"start":267.593,"end":268.293,"text":"in disguise."},{"start":268.773,"end":271.553,"text":"And studies that aren't randomized can"},{"start":271.553,"end":272.533,"text":"overstate effects."},{"start":273.013,"end":276.253,"text":"So step two is to regroup by design."},{"start":276.733,"end":279.033,"text":"What will the randomized trials show?"},{"start":285.383,"end":286.523,"text":"Watch them regroup."},{"start":287.203,"end":291.023,"text":"The randomized trials split: two of four"},{"start":291.023,"end":291.903,"text":"point up."},{"start":292.483,"end":295.983,"text":"The rest all point up, five of five."},{"start":296.403,"end":299.463,"text":"Those two down arrows are the same studies"},{"start":299.463,"end":302.263,"text":"as before: the upper level trials."},{"start":303.123,"end":304.823,"text":"Setting, or design?"},{"start":305.733,"end":306.333,"text":"Step three."},{"start":306.533,"end":309.613,"text":"Write each explanation as an if, then"},{"start":309.613,"end":310.153,"text":"statement."},{"start":310.733,"end":313.693,"text":"First, if it's the setting, the trials"},{"start":313.693,"end":315.633,"text":"should point up for first year writers."},{"start":315.973,"end":318.213,"text":"They shouldn't for upper level ones."},{"start":318.853,"end":321.913,"text":"Second, if it's the design, the trials"},{"start":321.913,"end":323.853,"text":"shouldn't point up in either setting."},{"start":324.213,"end":326.113,"text":"Now look where they predict different"},{"start":326.113,"end":326.433,"text":"things."},{"start":327.053,"end":328.973,"text":"The first year trials point up."},{"start":328.993,"end":331.753,"text":"So design alone can't explain it."},{"start":332.433,"end":335.233,"text":"In upper level courses, both explanations"},{"start":335.233,"end":338.393,"text":"say the trials won't point up, and they"},{"start":338.393,"end":338.833,"text":"don't."},{"start":339.053,"end":342.573,"text":"So this table can't separate setting from"},{"start":342.573,"end":342.933,"text":"design."},{"start":343.673,"end":344.253,"text":"What could?"},{"start":344.733,"end":347.793,"text":"More upper level trials with low concerns."},{"start":348.213,"end":351.473,"text":"If those point down too, it's likely the"},{"start":351.473,"end":351.753,"text":"setting."},{"start":352.033,"end":355.273,"text":"If they point up, studies two and eight"},{"start":355.273,"end":356.473,"text":"may have been chance."},{"start":357.367,"end":360.487,"text":"Step four is writing the claim, and it has"},{"start":360.487,"end":361.287,"text":"three parts."},{"start":361.547,"end":364.127,"text":"The claim says what you conclude."},{"start":364.807,"end":367.567,"text":"The evidence names the cells behind it."},{"start":368.067,"end":371.427,"text":"The boundary says where it stops, and why."},{"start":372.327,"end":374.907,"text":"Maya re-sorts by setting first."},{"start":376.297,"end":377.377,"text":"Here's her claim."},{"start":377.597,"end":380.717,"text":"In first year composition, AI feedback"},{"start":380.717,"end":383.017,"text":"was associated with better writing."},{"start":383.617,"end":385.917,"text":"She doesn't claim it caused the gain,"},{"start":385.917,"end":387.937,"text":"since three of the five weren't"},{"start":387.937,"end":388.277,"text":"randomized."},{"start":388.717,"end":390.517,"text":"Nor does she claim a size."},{"start":390.757,"end":394.077,"text":"Her evidence is five of five pointing up."},{"start":394.417,"end":397.477,"text":"Two are low concern randomized trials."},{"start":398.137,"end":400.557,"text":"That answers question three, how sure."},{"start":401.097,"end":404.037,"text":"Maya lets those two trials carry the"},{"start":404.037,"end":404.297,"text":"claim."},{"start":404.457,"end":407.257,"text":"The other three point the same way, but"},{"start":407.257,"end":408.297,"text":"couldn't carry it alone."},{"start":409.007,"end":409.867,"text":"Then the boundary."},{"start":410.187,"end":414.127,"text":"In upper level courses, results split, and"},{"start":414.127,"end":416.887,"text":"both low concern trials point down."},{"start":417.367,"end":418.627,"text":"Setting or design?"},{"start":419.027,"end":420.707,"text":"That needs more trials."},{"start":420.987,"end":422.427,"text":"See what this does."},{"start":423.087,"end":426.067,"text":"The disagreement stays in the paragraph,"},{"start":426.067,"end":428.627,"text":"named and open, but not vague."},{"start":429.467,"end":429.987,"text":"Let's recap."},{"start":430.327,"end":433.787,"text":"First, answer three questions: which way,"},{"start":433.787,"end":435.307,"text":"for whom, how sure."},{"start":435.867,"end":438.487,"text":"Second, vote by direction, not"},{"start":438.487,"end":440.807,"text":"significance, and justify your grouping."},{"start":441.287,"end":444.287,"text":"Third, write the claim, evidence, and"},{"start":444.287,"end":445.607,"text":"boundary from the cells."},{"start":446.467,"end":447.627,"text":"Now try it yourself."},{"start":448.107,"end":450.627,"text":"Pick a published review, or your own"},{"start":450.627,"end":453.087,"text":"studies, where findings seem to disagree."},{"start":453.767,"end":456.107,"text":"Put them in one table, like the card"},{"start":456.107,"end":456.327,"text":"shows."},{"start":456.747,"end":458.367,"text":"Try two groupings."},{"start":458.447,"end":461.327,"text":"Write two explanations, and the evidence"},{"start":461.327,"end":462.267,"text":"that would tell them apart."},{"start":462.747,"end":466.127,"text":"Then draft one paragraph from the cells:"},{"start":466.127,"end":468.647,"text":"claim, evidence, boundary."},{"start":469.367,"end":472.687,"text":"Finally, ask yourself: does your boundary"},{"start":472.687,"end":474.947,"text":"keep the disagreement open, without"},{"start":474.947,"end":476.007,"text":"becoming vague?"}]},"es-09-synthesis-writing":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":1,"text":"Meet Maya again."},{"start":1.42,"end":3.7,"text":"She's our made up doctoral student,"},{"start":3.7,"end":6.32,"text":"reviewing AI chatbot feedback on"},{"start":6.32,"end":7.4,"text":"undergraduates' writing."},{"start":7.74,"end":10.36,"text":"In another video, she turned her table"},{"start":10.36,"end":11.98,"text":"into one careful claim."},{"start":12.46,"end":14.24,"text":"Now she writes the review."},{"start":14.44,"end":17.68,"text":"Organize it by meaning, and add an insight"},{"start":17.68,"end":18.32,"text":"of your own."},{"start":18.86,"end":21.52,"text":"Keep that insight in the Discussion, apart"},{"start":21.52,"end":22.26,"text":"from the Results."},{"start":23.167,"end":24.447,"text":"This is her first draft."},{"start":24.987,"end":28.027,"text":"Study A found students revised more,"},{"start":28.027,"end":29.687,"text":"mostly surface edits."},{"start":30.107,"end":32.087,"text":"Study B found the same."},{"start":32.487,"end":36.027,"text":"Study C found deeper revisions after a"},{"start":36.027,"end":36.687,"text":"class discussion."},{"start":37.167,"end":40.467,"text":"And on it goes, study by study."},{"start":41.247,"end":43.307,"text":"Every sentence starts with an author."},{"start":43.527,"end":44.727,"text":"That's a summary."},{"start":44.927,"end":47.947,"text":"A synthesis says what the studies show"},{"start":47.947,"end":48.427,"text":"together."},{"start":49.067,"end":51.647,"text":"Webster and Watson call this author"},{"start":51.647,"end":52.087,"text":"centric."},{"start":52.347,"end":54.947,"text":"They say it fails to synthesize the"},{"start":54.947,"end":55.247,"text":"literature."},{"start":55.627,"end":59.027,"text":"The fix is to write concept centric."},{"start":59.267,"end":62.847,"text":"Each paragraph is about one idea, with the"},{"start":62.847,"end":63.907,"text":"authors in parentheses."},{"start":65.033,"end":68.273,"text":"Step one is a grid called a concept"},{"start":68.273,"end":68.753,"text":"matrix."},{"start":69.593,"end":72.353,"text":"Webster and Watson suggest filling it in"},{"start":72.353,"end":73.953,"text":"as you read each article."},{"start":74.733,"end":77.913,"text":"Maya puts the ideas down the side, and the"},{"start":77.913,"end":79.533,"text":"studies across the top."},{"start":80.093,"end":82.913,"text":"A concept is an idea that more than one"},{"start":82.913,"end":84.113,"text":"study speaks to."},{"start":84.843,"end":86.583,"text":"Watch her read study A."},{"start":86.963,"end":89.723,"text":"More revising, mostly surface edits."},{"start":89.943,"end":93.083,"text":"No deeper revision, no class discussion."},{"start":93.583,"end":95.823,"text":"Then B, a lot like A."},{"start":96.223,"end":97.103,"text":"Then C."},{"start":97.583,"end":99.623,"text":"There the class talked the feedback"},{"start":99.623,"end":102.183,"text":"through, and the revisions went deeper."},{"start":102.443,"end":105.343,"text":"D and E fill in the same way."},{"start":106.033,"end":108.573,"text":"Step two is where the synthesis happens."},{"start":108.933,"end":111.733,"text":"Read across a row, not down a column."},{"start":112.233,"end":114.953,"text":"Four of five studies found students"},{"start":114.953,"end":115.893,"text":"revised more."},{"start":116.353,"end":118.753,"text":"That's what they agree on, the common"},{"start":118.753,"end":119.133,"text":"meaning."},{"start":119.373,"end":122.193,"text":"And all three studies that checked the"},{"start":122.193,"end":125.173,"text":"kind of edit found mostly surface edits."},{"start":126.023,"end":127.843,"text":"In the third row, it splits."},{"start":128.723,"end":131.883,"text":"Two studies found deeper revision, and two"},{"start":131.883,"end":132.523,"text":"didn't."},{"start":132.963,"end":135.683,"text":"That's a tension, and you don't hide it."},{"start":136.063,"end":139.603,"text":"Now look at C and E, the two with deeper"},{"start":139.603,"end":139.983,"text":"revision."},{"start":140.563,"end":142.023,"text":"What else do they share?"},{"start":147.913,"end":149.273,"text":"Look at the last row."},{"start":149.653,"end":152.813,"text":"Only C and E had students discuss the"},{"start":152.813,"end":153.853,"text":"feedback in class."},{"start":154.533,"end":157.913,"text":"A and B had no discussion, and no deeper"},{"start":157.913,"end":158.273,"text":"revision."},{"start":158.853,"end":161.893,"text":"That's a pattern across studies, and you"},{"start":161.893,"end":164.033,"text":"can point to every cell behind it."},{"start":164.733,"end":167.273,"text":"Now let's rewrite the draft, live."},{"start":167.613,"end":170.213,"text":"The first sentence starts with the idea,"},{"start":170.213,"end":171.733,"text":"not with Study A."},{"start":172.513,"end":174.933,"text":"In most studies, students did more"},{"start":174.933,"end":176.793,"text":"revising with AI feedback."},{"start":177.413,"end":180.013,"text":"The studies behind it drop into the"},{"start":180.013,"end":180.313,"text":"parentheses."},{"start":181.383,"end":183.503,"text":"The second row becomes the second"},{"start":183.503,"end":185.683,"text":"sentence, about surface edits."},{"start":186.343,"end":189.323,"text":"The third keeps the split in plain sight."},{"start":189.823,"end":193.323,"text":"Same facts, now organized by meaning."},{"start":194.1,"end":197.5,"text":"Step three adds an insight, the part most"},{"start":197.5,"end":198.36,"text":"drafts skip."},{"start":198.74,"end":202.2,"text":"No single study compared discussion with"},{"start":202.2,"end":202.9,"text":"no discussion."},{"start":203.26,"end":206.34,"text":"Each one either had it or didn't."},{"start":206.44,"end":209.58,"text":"The link only shows when you read the rows"},{"start":209.58,"end":209.92,"text":"together."},{"start":210.6,"end":213.86,"text":"So Maya writes it down, as a hypothesis."},{"start":214.52,"end":218.38,"text":"Maybe AI feedback gets students revising,"},{"start":218.38,"end":221.16,"text":"and talking it through may take them"},{"start":221.16,"end":221.54,"text":"deeper."},{"start":222.26,"end":225.26,"text":"Thomas and Harden describe a similar move."},{"start":225.46,"end":228.16,"text":"In a method called thematic synthesis,"},{"start":228.16,"end":230.66,"text":"reviewers go beyond the studies they're"},{"start":230.66,"end":231,"text":"reviewing."},{"start":231.58,"end":234.88,"text":"They build new themes and report them as"},{"start":234.88,"end":235.36,"text":"findings."},{"start":236.16,"end":237.82,"text":"But look at Maya's label."},{"start":238.52,"end":241.46,"text":"Hers is an untested guess about why."},{"start":242.16,"end":244.66,"text":"So a safe default is the Discussion."},{"start":245.467,"end":247.147,"text":"Step four is the line."},{"start":247.307,"end":251.007,"text":"On the left is Results, what the evidence"},{"start":251.007,"end":251.427,"text":"shows."},{"start":251.687,"end":255.407,"text":"On the right is Discussion, what Maya"},{"start":255.407,"end":256.327,"text":"thinks it means."},{"start":256.627,"end":259.167,"text":"Her insight goes straight there."},{"start":259.847,"end":262.587,"text":"PRISMA twenty twenty keeps the two apart"},{"start":262.587,"end":262.947,"text":"too."},{"start":263.267,"end":265.647,"text":"It's the reporting guideline for"},{"start":265.647,"end":266.627,"text":"systematic reviews."},{"start":267.047,"end":270.627,"text":"It puts interpretation, limitations, and"},{"start":270.627,"end":272.507,"text":"implications in the Discussion."},{"start":273.367,"end":274.207,"text":"Try a quick test."},{"start":274.687,"end":276.747,"text":"If you can point to the studies behind"},{"start":276.747,"end":278.607,"text":"every word, it's a result."},{"start":279.087,"end":280.267,"text":"Try this sentence."},{"start":280.947,"end":283.967,"text":"Four of five studies found more revising,"},{"start":283.967,"end":285.587,"text":"and D didn't."},{"start":285.867,"end":287.367,"text":"Which side does it go on?"},{"start":293.177,"end":293.897,"text":"It's a result."},{"start":294.217,"end":297.217,"text":"You can point to a study for every part of"},{"start":297.217,"end":297.357,"text":"it."},{"start":297.657,"end":300.297,"text":"The surface edit sentence goes there too,"},{"start":300.297,"end":303.217,"text":"and so does the split on deeper revision."},{"start":304.077,"end":306.497,"text":"Maya's insight is already on the right."},{"start":306.737,"end":308.257,"text":"It's her own explanation."},{"start":308.817,"end":311.397,"text":"What it might mean for teaching goes there"},{"start":311.397,"end":311.637,"text":"too."},{"start":312.517,"end":315.217,"text":"Instructors might pair AI feedback with a"},{"start":315.217,"end":315.997,"text":"short conversation."},{"start":316.517,"end":317.997,"text":"So does a limitation."},{"start":318.497,"end":321.977,"text":"C and E may differ in other ways too, so"},{"start":321.977,"end":324.717,"text":"this is a hypothesis to test, not a"},{"start":324.717,"end":324.977,"text":"finding."},{"start":325.767,"end":327.887,"text":"One last sentence, about the pattern."},{"start":328.607,"end":331.607,"text":"Both studies with deeper revision built in"},{"start":331.607,"end":334.857,"text":"discussion, which shows discussion makes A"},{"start":334.857,"end":336.027,"text":"I feedback work."},{"start":336.747,"end":338.807,"text":"Something's leaking across the line."},{"start":339.247,"end":340.327,"text":"Can you spot where?"},{"start":346.287,"end":347.627,"text":"The first half is fine."},{"start":347.827,"end":350.587,"text":"You can point to C and E, so it's a"},{"start":350.587,"end":350.887,"text":"result."},{"start":351.407,"end":354.567,"text":"But no study tested whether discussion is"},{"start":354.567,"end":355.407,"text":"what makes it work."},{"start":355.827,"end":359.307,"text":"It's Maya's own explanation, said as if"},{"start":359.307,"end":359.687,"text":"proven."},{"start":359.927,"end":361.687,"text":"So she cuts it there."},{"start":362.397,"end":365.617,"text":"The first half joins the Results, and the"},{"start":365.617,"end":368.297,"text":"part that goes too far crosses the line."},{"start":368.937,"end":371.137,"text":"Her insight already says it there,"},{"start":371.137,"end":372.937,"text":"honestly, as a maybe."},{"start":373.667,"end":374.207,"text":"Let's recap."},{"start":374.647,"end":378.007,"text":"First, build the matrix, then organize by"},{"start":378.007,"end":380.147,"text":"meaning, one idea per paragraph."},{"start":380.747,"end":383.147,"text":"Second, read across the rows for"},{"start":383.147,"end":385.167,"text":"agreement, tension, and patterns."},{"start":385.607,"end":388.247,"text":"Then add your insight, labelled as yours."},{"start":388.827,"end":390.467,"text":"Third, draw the line."},{"start":390.607,"end":393.147,"text":"The common meaning you can point to goes"},{"start":393.147,"end":393.667,"text":"in Results."},{"start":394.127,"end":396.227,"text":"Your insight goes in Discussion."},{"start":396.767,"end":397.787,"text":"Catch the leaks."},{"start":398.567,"end":400.627,"text":"Now try it on a published review."},{"start":401.467,"end":404.147,"text":"Pick one in your area and copy three"},{"start":404.147,"end":405.767,"text":"sentences from its Results."},{"start":406.487,"end":409.267,"text":"Can you point to the studies behind every"},{"start":409.267,"end":409.607,"text":"word?"},{"start":409.987,"end":411.907,"text":"Then read its Discussion."},{"start":412.527,"end":415.387,"text":"Is any untested why written as"},{"start":415.387,"end":417.607,"text":"interpretation, not as a finding?"},{"start":418.227,"end":419.347,"text":"That's the line."},{"start":419.907,"end":424.087,"text":"Last, hunt for leaks, a shows or proves in"},{"start":424.087,"end":426.227,"text":"the Results that no study tested."},{"start":427.077,"end":428.597,"text":"One more thing to try."},{"start":429.317,"end":431.937,"text":"Take a paragraph of yours that goes author"},{"start":431.937,"end":432.577,"text":"by author."},{"start":433.377,"end":436.757,"text":"Build a small matrix and rewrite it, one"},{"start":436.757,"end":438.257,"text":"idea per sentence."},{"start":439.137,"end":442.837,"text":"Mark each sentence R for Results or D for"},{"start":442.837,"end":443.257,"text":"Discussion."},{"start":443.677,"end":446.637,"text":"If an R sentence says something you can't"},{"start":446.637,"end":448.737,"text":"point to, you've found a leak."}]},"es-07-prisma-flow-and-tool-audit":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.98,"text":"PRISMA twenty twenty recommends a flow"},{"start":2.98,"end":3.38,"text":"diagram."},{"start":3.82,"end":7.02,"text":"It's a chart of boxes and arrows showing"},{"start":7.02,"end":7.98,"text":"what got cut."},{"start":8.22,"end":10.54,"text":"The main idea is simple."},{"start":11.17,"end":14.26,"text":"Every box is a count you can rebuild from"},{"start":14.26,"end":16.52,"text":"your logs, the spreadsheets you keep."},{"start":17.4,"end":19.7,"text":"Reconciling means making those counts"},{"start":19.7,"end":21.5,"text":"agree before you draw."},{"start":22.267,"end":25.367,"text":"This is Maya, a made up doctoral student."},{"start":25.747,"end":28.567,"text":"Her review asks whether AI chatbot"},{"start":28.567,"end":31.287,"text":"feedback helps undergraduates revise their"},{"start":31.287,"end":31.587,"text":"essays."},{"start":32.007,"end":35.047,"text":"It's a systematic review, so she reports"},{"start":35.047,"end":36.547,"text":"it with PRISMA twenty twenty."},{"start":37.087,"end":39.907,"text":"It's a twenty seven item checklist that"},{"start":39.907,"end":41.147,"text":"includes the flow diagram."},{"start":42.137,"end":45.337,"text":"It tells you what to report, not how good"},{"start":45.337,"end":46.177,"text":"your review is."},{"start":46.577,"end":49.477,"text":"For a scoping review, she'd add the"},{"start":49.477,"end":50.777,"text":"scoping extension too."},{"start":51.6,"end":54.06,"text":"PRISMA counts three different things."},{"start":54.3,"end":58.26,"text":"A record is one title and abstract in one"},{"start":58.26,"end":58.7,"text":"database."},{"start":58.98,"end":62.4,"text":"A report is a document, like an article."},{"start":62.58,"end":66.48,"text":"A study is the project itself, with a"},{"start":66.48,"end":69.28,"text":"defined group, an intervention, and"},{"start":69.28,"end":69.72,"text":"outcomes."},{"start":70.72,"end":73.28,"text":"Take one made up classroom trial from"},{"start":73.28,"end":73.98,"text":"Maya's search."},{"start":74.2,"end":77.68,"text":"It produced two reports, an article and a"},{"start":77.68,"end":78.32,"text":"conference paper."},{"start":78.6,"end":81.2,"text":"The databases returned three records."},{"start":81.7,"end":84.16,"text":"How many get removed as duplicates?"},{"start":90.05,"end":90.65,"text":"Just one."},{"start":90.97,"end":94.01,"text":"ERIC and Scopus point to the same article,"},{"start":94.01,"end":96.95,"text":"so Maya keeps one and removes the other."},{"start":97.46,"end":99.29,"text":"The conference paper is a different"},{"start":99.29,"end":100.77,"text":"report, so it stays."},{"start":101.33,"end":104.91,"text":"So that's three records, two reports, one"},{"start":104.91,"end":105.29,"text":"study."},{"start":106.067,"end":109.527,"text":"Now let's build Maya's diagram, one box at"},{"start":109.527,"end":110.007,"text":"a time."},{"start":110.587,"end":112.627,"text":"Step one is her search log."},{"start":112.927,"end":116.067,"text":"She got one hundred forty two records from"},{"start":116.067,"end":119.467,"text":"ERIC, a hundred eighteen from PsycINFO,"},{"start":119.467,"end":121.787,"text":"and ninety six from Scopus."},{"start":122.527,"end":125.427,"text":"Add them up: three hundred fifty six."},{"start":126.337,"end":128.877,"text":"Step two removes duplicates."},{"start":129.277,"end":130.677,"text":"Eighty eight came out."},{"start":131.157,"end":134.557,"text":"No automation tool removed anything, so"},{"start":134.557,"end":136.157,"text":"that line says zero."},{"start":136.937,"end":137.977,"text":"Remember that zero."},{"start":138.817,"end":142.217,"text":"Three fifty six minus eighty eight leaves"},{"start":142.217,"end":144.017,"text":"two sixty eight to screen."},{"start":144.847,"end":146.627,"text":"Step three is screening."},{"start":146.867,"end":150.247,"text":"She reads each title and abstract and"},{"start":150.247,"end":151.547,"text":"keeps or drops it."},{"start":151.667,"end":155.342,"text":"She dropped two forty one, and two sixty"},{"start":155.342,"end":157.677,"text":"eight minus two forty one leaves twenty"},{"start":157.677,"end":157.987,"text":"seven."},{"start":158.447,"end":162.567,"text":"Now the boxes count reports, documents she"},{"start":162.567,"end":163.227,"text":"has to find."},{"start":163.947,"end":165.947,"text":"In step four, she looks for them."},{"start":166.427,"end":169.767,"text":"Two couldn't be found, so twenty five were"},{"start":169.767,"end":172.147,"text":"read in full against her criteria."},{"start":172.887,"end":175.007,"text":"That's what assessed for eligibility"},{"start":175.007,"end":175.927,"text":"means."},{"start":178.127,"end":180.607,"text":"Step five is the full text log."},{"start":180.967,"end":183.607,"text":"Every exclusion there gets a reason."},{"start":184.047,"end":187.587,"text":"Six had the wrong population, five had no"},{"start":187.587,"end":190.547,"text":"AI feedback, and four weren't empirical."},{"start":191.367,"end":193.627,"text":"That leaves ten reports included."},{"start":193.967,"end":195.707,"text":"How many studies is that?"},{"start":201.637,"end":202.117,"text":"It's eight."},{"start":202.497,"end":204.917,"text":"Step six is the linking table."},{"start":205.197,"end":207.977,"text":"It matches each report to its study."},{"start":207.977,"end":211.917,"text":"S three is our classroom trial, one study"},{"start":211.917,"end":212.917,"text":"with two reports."},{"start":212.917,"end":215.157,"text":"S six is the same."},{"start":215.397,"end":219.557,"text":"Two extra reports, so ten minus two is"},{"start":219.557,"end":219.777,"text":"eight."},{"start":220.457,"end":221.737,"text":"Report both numbers."},{"start":222.533,"end":223.633,"text":"Rewind a week."},{"start":224.033,"end":227.213,"text":"Maya drew this draft before screening was"},{"start":227.213,"end":227.593,"text":"finished."},{"start":227.913,"end":231.233,"text":"It says two hundred thirty six excluded."},{"start":231.873,"end":233.653,"text":"Let's check it like a reader."},{"start":233.873,"end":237.213,"text":"At each subtraction, what goes in should"},{"start":237.213,"end":240.213,"text":"match what comes out, or a note should say"},{"start":240.213,"end":240.473,"text":"why."},{"start":241.133,"end":242.993,"text":"That's what reconciling means."},{"start":243.533,"end":245.073,"text":"Which step fails?"},{"start":251.133,"end":254.053,"text":"Two sixty eight minus two thirty six is"},{"start":254.053,"end":254.453,"text":"thirty two."},{"start":254.453,"end":257.473,"text":"But the next box says twenty seven."},{"start":257.473,"end":260.793,"text":"So one of these three boxes is wrong."},{"start":260.793,"end":263.173,"text":"The math can't say which."},{"start":263.173,"end":265.273,"text":"The screening log can."},{"start":265.273,"end":268.853,"text":"Back then, five records were still marked"},{"start":268.853,"end":269.093,"text":"maybe."},{"start":269.093,"end":272.413,"text":"Later, all five were excluded."},{"start":273.373,"end":276.313,"text":"So the excluded box was just out of date."},{"start":277.033,"end":279.853,"text":"Two thirty six plus five is two forty one,"},{"start":279.853,"end":282.473,"text":"and now every subtraction balances."},{"start":283.433,"end":285.653,"text":"Reconcile first, then draw."},{"start":286.467,"end":288.487,"text":"Now Maya packs it all up."},{"start":288.807,"end":291.387,"text":"Every log you just saw can go in your"},{"start":291.387,"end":294.107,"text":"appendix, so a stranger could rebuild"},{"start":294.107,"end":294.927,"text":"every box."},{"start":295.487,"end":298.807,"text":"Add your search strings, exactly as run."},{"start":299.187,"end":302.047,"text":"Add your extraction and appraisal tables."},{"start":302.447,"end":305.647,"text":"And add a read me file that says which"},{"start":305.647,"end":307.567,"text":"file rebuilds which box."},{"start":309.467,"end":311.907,"text":"Remember the zero on the automation line?"},{"start":312.507,"end":313.667,"text":"It could change here."},{"start":314.027,"end":316.727,"text":"Maya tries a made up AI screening"},{"start":316.727,"end":319.507,"text":"assistant that suggests include or"},{"start":319.507,"end":319.967,"text":"exclude."},{"start":320.667,"end":323.907,"text":"If you can't rebuild what it did, don't"},{"start":323.907,"end":324.387,"text":"trust it."},{"start":324.987,"end":327.667,"text":"So let's check it with five quick tests."},{"start":328.607,"end":331.927,"text":"Exportability is fine: she can export a"},{"start":331.927,"end":332.267,"text":"spreadsheet."},{"start":332.867,"end":335.687,"text":"Auditability asks if someone could check"},{"start":335.687,"end":336.567,"text":"its work later."},{"start":336.867,"end":339.467,"text":"By itself, this tool fails."},{"start":340.047,"end":343.347,"text":"It doesn't log which AI version ran, or"},{"start":343.347,"end":343.687,"text":"when."},{"start":343.947,"end":348.147,"text":"So Maya keeps a use log, a diary of each"},{"start":348.147,"end":348.407,"text":"run."},{"start":348.927,"end":352.047,"text":"On privacy, she sends nothing confidential"},{"start":352.047,"end":354.807,"text":"or restricted to an unapproved service."},{"start":355.667,"end":357.427,"text":"Accessibility is still open."},{"start":357.567,"end":359.827,"text":"She hasn't tried a screen reader yet."},{"start":360.307,"end":361.987,"text":"Next is accuracy."},{"start":362.547,"end":365.247,"text":"Maya had already screened forty records"},{"start":365.247,"end":366.427,"text":"and kept six."},{"start":366.727,"end":370.307,"text":"The tool flagged five of those six, plus"},{"start":370.307,"end":371.107,"text":"four extras."},{"start":371.407,"end":374.547,"text":"But it missed one, and misses are"},{"start":374.547,"end":374.987,"text":"dangerous."},{"start":375.917,"end":378.897,"text":"If the tool had excluded on its own, that"},{"start":378.897,"end":380.757,"text":"eligible record would vanish."},{"start":380.957,"end":384.297,"text":"The box would show a count, not which one"},{"start":384.297,"end":384.877,"text":"was lost."},{"start":385.517,"end":389.397,"text":"A safe default: the tool may sort, but"},{"start":389.397,"end":390.417,"text":"never exclude."},{"start":391.097,"end":394.277,"text":"Final eligibility and interpretation stay"},{"start":394.277,"end":397.977,"text":"with a person, so that zero stays zero."},{"start":398.457,"end":401.697,"text":"If a tool does exclude, PRISMA's"},{"start":401.697,"end":404.977,"text":"explanation paper says to report how many."},{"start":405.707,"end":408.967,"text":"Four big review groups agree that AI"},{"start":408.967,"end":410.407,"text":"needs human oversight."},{"start":410.867,"end":413.967,"text":"When you write it up, name the tool and"},{"start":413.967,"end":414.547,"text":"its version."},{"start":415.067,"end":418.167,"text":"Say when, for what task, and how you"},{"start":418.167,"end":418.627,"text":"checked it."},{"start":419.367,"end":422.967,"text":"First, records, reports, and studies are"},{"start":422.967,"end":425.807,"text":"different units, so label every box."},{"start":426.347,"end":429.567,"text":"Second, every box is a count from a log,"},{"start":429.567,"end":432.427,"text":"so reconcile first and draw second."},{"start":432.927,"end":436.467,"text":"Third, a tool has to show its work, and"},{"start":436.467,"end":438.427,"text":"eligibility stays human."},{"start":439.197,"end":440.037,"text":"Try it yourself."},{"start":440.847,"end":443.337,"text":"Pick a published systematic review with a"},{"start":443.337,"end":444.357,"text":"PRISMA flow diagram."},{"start":445.227,"end":446.797,"text":"Check every subtraction."},{"start":447.187,"end":449.617,"text":"Does each arrow balance, or does a note"},{"start":449.617,"end":450.117,"text":"say why?"},{"start":450.557,"end":452.117,"text":"Then ask two things."},{"start":452.577,"end":455.097,"text":"Does it give both studies and reports?"},{"start":455.597,"end":458.557,"text":"And if it used AI, how many did that"},{"start":458.557,"end":458.897,"text":"exclude?"},{"start":459.417,"end":462.437,"text":"Write down one gap, and the log that would"},{"start":462.437,"end":462.897,"text":"close it."},{"start":463.257,"end":464.897,"text":"Then look at your own logs."},{"start":465.487,"end":467.877,"text":"Could a stranger rebuild every box from"},{"start":467.877,"end":468.057,"text":"them?"}]},"es-02-review-autopsy":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0.02,"end":2.465,"text":"Let's do an autopsy on a review."},{"start":2.923,"end":6.132,"text":"That means taking it apart to see what it"},{"start":6.132,"end":6.973,"text":"really did."},{"start":7.431,"end":10.335,"text":"Remember Maya, our made up doctoral"},{"start":10.335,"end":10.946,"text":"student?"},{"start":11.404,"end":14.231,"text":"Her last review turned out narrative."},{"start":14.69,"end":17.593,"text":"This audit is built for systematic or"},{"start":17.593,"end":20.726,"text":"scoping reviews, so she's picked a new"},{"start":20.726,"end":21.032,"text":"one."},{"start":22.14,"end":24.479,"text":"One idea runs through this video."},{"start":24.904,"end":27.385,"text":"Every judgment in your audit needs"},{"start":27.385,"end":30.646,"text":"evidence from the review: a sentence you"},{"start":30.646,"end":33.694,"text":"can quote, or a number you can recompute."},{"start":34.119,"end":36.955,"text":"Maya's sheet will hold one in every row."},{"start":37.92,"end":39.826,"text":"The audit has five moves."},{"start":40.283,"end":43.714,"text":"First, name the question or purpose, and"},{"start":43.714,"end":45.087,"text":"the review family."},{"start":45.544,"end":48.899,"text":"Second, check whether the family fits the"},{"start":48.899,"end":51.72,"text":"question, using the actual methods."},{"start":52.177,"end":54.617,"text":"Third, audit transparency and"},{"start":54.617,"end":58.048,"text":"reproducibility, from the plan to the flow"},{"start":58.048,"end":58.658,"text":"diagram."},{"start":59.115,"end":61.86,"text":"Fourth, find one strength and one"},{"start":61.86,"end":63.613,"text":"limitation that matter."},{"start":64.071,"end":67.502,"text":"Fifth, suggest one concrete improvement,"},{"start":67.502,"end":69.713,"text":"backed by published guidance."},{"start":71.92,"end":73.746,"text":"This is one worked audit."},{"start":74.184,"end":76.302,"text":"Yours will use the same rows."},{"start":77.33,"end":78.889,"text":"This is her new review."},{"start":79.295,"end":82.345,"text":"It's made up too, and its title calls it a"},{"start":82.345,"end":83.362,"text":"scoping review."},{"start":83.768,"end":86.683,"text":"Its purpose is to map the kinds of chatbot"},{"start":86.683,"end":89.732,"text":"feedback studied, the outcomes measured,"},{"start":89.732,"end":90.613,"text":"and the gaps."},{"start":91.51,"end":92.244,"text":"Move one."},{"start":92.733,"end":95.914,"text":"A review family is a type of review,"},{"start":95.914,"end":98.768,"text":"defined by its purpose and methods."},{"start":99.257,"end":102.356,"text":"A systematic review answers a focused"},{"start":102.356,"end":105.292,"text":"question, often, does this work?"},{"start":105.781,"end":109.451,"text":"A scoping review maps what's been studied,"},{"start":109.451,"end":110.511,"text":"and the gaps."},{"start":111.6,"end":115.36,"text":"Maya writes down the purpose, to map, and"},{"start":115.36,"end":117.68,"text":"the authors' own label, scoping."},{"start":118.51,"end":119.077,"text":"Move two."},{"start":119.455,"end":121.597,"text":"Does that family fit the question?"},{"start":121.975,"end":123.046,"text":"Open the methods."},{"start":123.424,"end":126.07,"text":"They say studies were charted by feedback"},{"start":126.07,"end":127.961,"text":"type, outcome, and design."},{"start":128.339,"end":130.733,"text":"Charting means sorting studies into a"},{"start":130.733,"end":131.111,"text":"table."},{"start":131.489,"end":133.442,"text":"That's what mapping looks like."},{"start":134.38,"end":137.386,"text":"But another sentence says the studies were"},{"start":137.386,"end":139.833,"text":"appraised with a published quality"},{"start":139.833,"end":140.532,"text":"checklist."},{"start":140.951,"end":143.747,"text":"Appraisal means judging how trustworthy"},{"start":143.747,"end":144.726,"text":"each study is."},{"start":145.146,"end":147.243,"text":"So is it systematic after all?"},{"start":147.662,"end":148.851,"text":"Pause and decide."},{"start":156.43,"end":156.65,"text":"No."},{"start":157.091,"end":160.031,"text":"A guidance paper by Munn and colleagues"},{"start":160.031,"end":163.044,"text":"says appraisal is required in systematic"},{"start":163.044,"end":166.204,"text":"reviews, but optional in scoping reviews."},{"start":166.645,"end":169.217,"text":"Scoping authors may still appraise."},{"start":169.658,"end":172.009,"text":"So appraisal alone can't decide."},{"start":173.36,"end":175.728,"text":"Charting suits a mapping question."},{"start":176.146,"end":179.001,"text":"And one scoping purpose Munn lists is to"},{"start":179.001,"end":181.857,"text":"identify the types of available evidence"},{"start":181.857,"end":183.041,"text":"in a given field."},{"start":183.458,"end":186.035,"text":"So Maya writes that scoping fits the"},{"start":186.035,"end":186.662,"text":"question."},{"start":187.91,"end":189.78,"text":"Move three is the audit."},{"start":190.248,"end":193.521,"text":"A review is transparent when it tells you"},{"start":193.521,"end":194.456,"text":"what it did."},{"start":194.924,"end":198.197,"text":"It's reproducible when someone else could"},{"start":198.197,"end":198.821,"text":"redo it."},{"start":199.288,"end":201.003,"text":"Maya checks four rows."},{"start":201.47,"end":204.899,"text":"She marks each one reported, partly, or"},{"start":204.899,"end":205.912,"text":"not reported."},{"start":207.01,"end":210.308,"text":"Her yardstick is PRISMA twenty twenty, a"},{"start":210.308,"end":213.223,"text":"twenty seven item reporting checklist."},{"start":213.683,"end":215.447,"text":"Keep one limit in mind."},{"start":215.907,"end":218.055,"text":"It checks what was reported."},{"start":218.515,"end":221.43,"text":"It doesn't judge how well it was done."},{"start":222.45,"end":225.21,"text":"First comes protocol or registration."},{"start":225.57,"end":229.35,"text":"A protocol is the review's plan, written"},{"start":229.35,"end":230.67,"text":"before it starts."},{"start":231.45,"end":234.27,"text":"Registration means posting the key parts"},{"start":234.27,"end":236.71,"text":"of that plan publicly, with a date."},{"start":237.48,"end":240.184,"text":"Maya searches the methods and finds"},{"start":240.184,"end":240.784,"text":"nothing."},{"start":241.235,"end":244.014,"text":"PRISMA asks authors to say where the"},{"start":244.014,"end":247.243,"text":"protocol is, name the register, or say"},{"start":247.243,"end":248.219,"text":"there's none."},{"start":248.67,"end":250.247,"text":"So it's not reported."},{"start":250.698,"end":253.176,"text":"That doesn't mean it wasn't done."},{"start":253.627,"end":255.579,"text":"A reader just can't check."},{"start":256.6,"end":258.039,"text":"Next, the search."},{"start":258.493,"end":261.447,"text":"The methods say how many databases and"},{"start":261.447,"end":265.006,"text":"which month, but no names, and only sample"},{"start":265.006,"end":265.46,"text":"terms."},{"start":265.914,"end":269.171,"text":"PRISMA asks for the full search strategies"},{"start":269.171,"end":270.534,"text":"for all databases."},{"start":270.988,"end":272.806,"text":"So it's partly reported."},{"start":274.3,"end":277.5,"text":"Then screening, deciding which studies are"},{"start":277.5,"end":278.211,"text":"in or out."},{"start":278.637,"end":281.695,"text":"Two reviewers independently screened every"},{"start":281.695,"end":284.183,"text":"title, abstract, and full text."},{"start":284.61,"end":287.809,"text":"That's what PRISMA asks about: how many"},{"start":287.809,"end":290.298,"text":"reviewers, working independently."},{"start":290.725,"end":291.933,"text":"So it's reported."},{"start":293.33,"end":295.613,"text":"Last comes the flow diagram."},{"start":296.103,"end":299.528,"text":"A record is one title and abstract that a"},{"start":299.528,"end":300.914,"text":"database returns."},{"start":301.403,"end":304.665,"text":"The diagram counts records at each step."},{"start":305.154,"end":306.541,"text":"Let's rebuild it."},{"start":307.56,"end":310.128,"text":"The search found twelve hundred forty"},{"start":310.128,"end":310.668,"text":"records."},{"start":311.074,"end":313.574,"text":"Three hundred eighty were duplicates."},{"start":313.979,"end":316.547,"text":"So screening should start with twelve"},{"start":316.547,"end":319.452,"text":"forty minus three eighty, which is eight"},{"start":319.452,"end":320.398,"text":"hundred sixty."},{"start":320.804,"end":321.615,"text":"And it does."},{"start":322.57,"end":325.869,"text":"Then seven hundred thirty were excluded at"},{"start":325.869,"end":326.637,"text":"screening."},{"start":327.097,"end":330.32,"text":"That leaves one hundred thirty full texts."},{"start":331.55,"end":332.15,"text":"Last step."},{"start":332.57,"end":335.79,"text":"Eighty-two full texts were excluded, and"},{"start":335.79,"end":338.25,"text":"the review reports fifty-two included."},{"start":338.63,"end":339.99,"text":"Does that add up?"},{"start":340.39,"end":341.85,"text":"Pause and check."},{"start":349.3,"end":350.02,"text":"It doesn't."},{"start":350.4,"end":352.82,"text":"One hundred thirty minus eighty-two is"},{"start":352.82,"end":353.24,"text":"forty-eight."},{"start":353.56,"end":355.74,"text":"So four appear from nowhere."},{"start":356.22,"end":359.24,"text":"Maybe they came from reference lists, but"},{"start":359.24,"end":360.64,"text":"the diagram never says."},{"start":361.26,"end":364.2,"text":"Maya marks it partly, noting the exact"},{"start":364.2,"end":364.64,"text":"numbers."},{"start":365.51,"end":367.941,"text":"Move four is one strength and one"},{"start":367.941,"end":368.727,"text":"limitation."},{"start":369.156,"end":370.729,"text":"Pick ones that matter."},{"start":371.158,"end":374.59,"text":"A simple test: does it change how much you"},{"start":374.59,"end":376.377,"text":"can trust the conclusion?"},{"start":376.806,"end":378.951,"text":"Take this review's conclusion."},{"start":379.99,"end":382.4,"text":"The strength is the screening."},{"start":382.882,"end":386.016,"text":"PRISMA's explanation paper says double"},{"start":386.016,"end":389.23,"text":"screening may be more reliable than one"},{"start":389.23,"end":392.684,"text":"reviewer, though it takes reviewers more"},{"start":392.684,"end":393.086,"text":"time."},{"start":393.568,"end":396.621,"text":"So inclusion rests less on one person."},{"start":397.103,"end":398.148,"text":"Maya adds it."},{"start":399.29,"end":402.437,"text":"The limitation hides in the headline:"},{"start":402.437,"end":405.364,"text":"chatbot feedback improves undergraduate"},{"start":405.364,"end":405.949,"text":"writing."},{"start":406.388,"end":408.437,"text":"That's a does it work claim."},{"start":408.876,"end":412.096,"text":"But in Munn's comparison, scoping reviews"},{"start":412.096,"end":414.437,"text":"don't synthesize study findings."},{"start":414.876,"end":417.584,"text":"So the headline claims more than the"},{"start":417.584,"end":418.901,"text":"question supports."},{"start":420.22,"end":423.401,"text":"Move five is one improvement, in three"},{"start":423.401,"end":423.867,"text":"steps."},{"start":424.333,"end":427.592,"text":"First, rewrite the headline as a map of"},{"start":427.592,"end":428.911,"text":"what was studied."},{"start":429.376,"end":432.48,"text":"Next, turn the claim into an open gap."},{"start":432.946,"end":435.817,"text":"Then point to a follow up systematic"},{"start":435.817,"end":436.36,"text":"review."},{"start":436.826,"end":439.774,"text":"That's one scoping purpose Munn lists."},{"start":441.07,"end":442.927,"text":"Maya's argument is simple."},{"start":443.355,"end":445.927,"text":"One decision, keeping the scoping"},{"start":445.927,"end":448.426,"text":"question, drives all three steps."},{"start":448.855,"end":451.783,"text":"The protocol and flow problems are still"},{"start":451.783,"end":452.211,"text":"there."},{"start":453.34,"end":455.191,"text":"Three things to remember."},{"start":455.635,"end":458.967,"text":"First, every row needs a quote or a number"},{"start":458.967,"end":460.152,"text":"from the review."},{"start":460.596,"end":463.928,"text":"Second, if the review is silent, call it"},{"start":463.928,"end":464.89,"text":"not reported."},{"start":465.334,"end":467.63,"text":"That's different from not done."},{"start":468.074,"end":470.739,"text":"Third, recompute the flow numbers"},{"start":470.739,"end":471.406,"text":"yourself."},{"start":472.47,"end":473.902,"text":"Now try it yourself."},{"start":474.331,"end":477.123,"text":"Pick a published systematic or scoping"},{"start":477.123,"end":479.486,"text":"review on a topic you care about."},{"start":479.915,"end":482.85,"text":"Copy Maya's nine rows onto a blank sheet."},{"start":483.9,"end":486.828,"text":"Fill every row with a quote or a number"},{"start":486.828,"end":488.146,"text":"you can recompute."},{"start":488.586,"end":490.636,"text":"Redo the flow math yourself."},{"start":491.075,"end":493.71,"text":"Then write down one strength, one"},{"start":493.71,"end":496.932,"text":"limitation, and one improvement backed by"},{"start":496.932,"end":497.591,"text":"a source."},{"start":498.53,"end":500.49,"text":"One last question to think about."},{"start":500.846,"end":503.222,"text":"Does what you found change how much you"},{"start":503.222,"end":505.004,"text":"trust the review's conclusion?"}]},"es-short-title-is-not-the-family":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.44,"text":"Maya keeps rereading one review."},{"start":3.25,"end":5,"text":"She's a made up doctoral student."},{"start":5.63,"end":8.76,"text":"Its title says it's a systematic review of"},{"start":8.76,"end":10.6,"text":"chatbots in writing instruction."},{"start":11.55,"end":13.19,"text":"So that settles it, right?"},{"start":13.85,"end":14.73,"text":"Hold that thought."},{"start":15.43,"end":17.35,"text":"Review labels are slippery."},{"start":17.83,"end":20.61,"text":"Two researchers compared fourteen review"},{"start":20.61,"end":20.95,"text":"types."},{"start":21.71,"end":24.57,"text":"Few had clear, set methods, they found,"},{"start":24.57,"end":26.53,"text":"and many overlap."},{"start":27.53,"end":28.99,"text":"So don't trust the label."},{"start":29.6,"end":32.33,"text":"Check four processes instead, they say."},{"start":32.75,"end":36.41,"text":"Search, appraisal, synthesis, and"},{"start":36.41,"end":36.79,"text":"analysis."},{"start":37.8,"end":38.32,"text":"Let's check."},{"start":38.56,"end":42,"text":"A systematic review tries to find every"},{"start":42,"end":42.88,"text":"relevant study."},{"start":43.16,"end":46.44,"text":"This one used Google Scholar and papers"},{"start":46.44,"end":47.82,"text":"the authors already knew."},{"start":48.32,"end":50.62,"text":"It reports no search strings."},{"start":51.02,"end":54.4,"text":"Those are the exact words you type into a"},{"start":54.4,"end":54.66,"text":"database."},{"start":55.56,"end":58.48,"text":"A systematic review also judges each"},{"start":58.48,"end":59.32,"text":"study's quality."},{"start":59.7,"end":61.86,"text":"That's called appraisal."},{"start":62.38,"end":64.54,"text":"This one reports no appraisal."},{"start":64.82,"end":66.58,"text":"That's a second miss."},{"start":67.43,"end":68.81,"text":"Two misses so far."},{"start":69.29,"end":71.15,"text":"How many of the four will fit?"},{"start":72.01,"end":73.51,"text":"Decide before we go on."},{"start":78.41,"end":78.95,"text":"Just one."},{"start":79.15,"end":82.29,"text":"The synthesis goes study by study, with a"},{"start":82.29,"end":82.99,"text":"summary table."},{"start":83.43,"end":86.47,"text":"That's typical of systematic reviews, so"},{"start":86.47,"end":86.85,"text":"it fits."},{"start":87.66,"end":90.54,"text":"But the analysis just argues for chatbots,"},{"start":90.54,"end":92.84,"text":"saying nothing about what's still unknown."},{"start":93.67,"end":95.52,"text":"One fit out of four."},{"start":96.27,"end":97.59,"text":"Now read its purpose."},{"start":98.31,"end":101.27,"text":"It aims to show teachers why chatbots"},{"start":101.27,"end":103.03,"text":"belong in every writing class."},{"start":103.69,"end":104.93,"text":"That's an argument."},{"start":105.69,"end":108.49,"text":"Arguing a view is a narrative review's"},{"start":108.49,"end":108.69,"text":"job."},{"start":109.58,"end":112.8,"text":"So the purpose and those three misses are"},{"start":112.8,"end":113.56,"text":"your evidence."},{"start":114.4,"end":117.2,"text":"This is a narrative review wearing a"},{"start":117.2,"end":118.24,"text":"systematic label."},{"start":118.98,"end":120.16,"text":"That's not an insult."},{"start":120.76,"end":123.26,"text":"Narrative reviews have their own job."},{"start":124.02,"end":126.48,"text":"One group of researchers argues that"},{"start":126.48,"end":129.5,"text":"systematic doesn't mean high quality."},{"start":130.33,"end":133.37,"text":"The real problem is claiming a method it"},{"start":133.37,"end":134.05,"text":"didn't use."},{"start":134.75,"end":137.61,"text":"So read past the title, and let the"},{"start":137.61,"end":139.41,"text":"methods have the final say."},{"start":140.23,"end":142.85,"text":"The full video walks through the whole"},{"start":142.85,"end":143.23,"text":"check."},{"start":143.57,"end":145.63,"text":"One question to take with you."},{"start":145.91,"end":149.09,"text":"Does a review you've cited match its"},{"start":149.09,"end":149.43,"text":"label?"}]},"es-short-choosing-a-review":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.6,"text":"Maya is a made up doctoral student."},{"start":3.12,"end":5.96,"text":"She studies AI feedback on undergraduate"},{"start":5.96,"end":6.66,"text":"writing."},{"start":7.26,"end":8.94,"text":"Which review should she do?"},{"start":9.6,"end":12.02,"text":"It's tempting to pick the one that sounds"},{"start":12.02,"end":12.94,"text":"most rigorous."},{"start":13.92,"end":15.78,"text":"Start from her question instead."},{"start":16.28,"end":17.78,"text":"The question decides."},{"start":18.72,"end":20.38,"text":"Let's walk her down the path."},{"start":21.2,"end":23.88,"text":"Say she asks whether it works, and for"},{"start":23.88,"end":24.2,"text":"whom."},{"start":24.5,"end":26.4,"text":"That needs a focused answer."},{"start":26.62,"end":28.9,"text":"It points to a systematic review."},{"start":29.42,"end":32.04,"text":"Say she'd rather map what's been studied,"},{"start":32.04,"end":33,"text":"and the gaps."},{"start":33.42,"end":35.86,"text":"Then a scoping review fits."},{"start":36.84,"end":39.32,"text":"Scoping isn't the easy option, though."},{"start":39.48,"end":42.46,"text":"It still needs rigorous, transparent"},{"start":42.46,"end":43.2,"text":"methods."},{"start":44.11,"end":45.53,"text":"Three more forks."},{"start":45.89,"end":48.33,"text":"Say she wants to argue a view from her"},{"start":48.33,"end":48.65,"text":"reading."},{"start":49.35,"end":50.91,"text":"That's a narrative review."},{"start":51.37,"end":53.77,"text":"What if she wants to make sense of what"},{"start":53.77,"end":56.19,"text":"students said across interview studies?"},{"start":61.24,"end":63.4,"text":"That's a qualitative meta synthesis."},{"start":64.08,"end":67.06,"text":"What if she wants trials, surveys, and"},{"start":67.06,"end":68.56,"text":"theory in one picture?"},{"start":69.33,"end":72.1,"text":"Two researchers describe the integrative"},{"start":72.1,"end":73.56,"text":"review for that mix."},{"start":74.44,"end":76.3,"text":"Say she takes the systematic path."},{"start":76.7,"end":79.68,"text":"Her trials are similar enough in who took"},{"start":79.68,"end":82.26,"text":"part, what was compared, and what was"},{"start":82.26,"end":82.6,"text":"measured."},{"start":83.08,"end":85.58,"text":"Then a meta analysis could pool their"},{"start":85.58,"end":86.5,"text":"results statistically."},{"start":87.18,"end":89.48,"text":"What if she wants to compare three or more"},{"start":89.48,"end":90.26,"text":"kinds of feedback?"},{"start":90.84,"end":92.82,"text":"Some were never tested head to head."},{"start":93.62,"end":95.74,"text":"That's a network meta analysis."},{"start":96.44,"end":99.66,"text":"Both usually build on a systematic review."},{"start":100.25,"end":102.02,"text":"Both are beyond this series."},{"start":102.67,"end":104.7,"text":"I'd only try them with methods training,"},{"start":104.7,"end":106.76,"text":"and often a statistician."},{"start":107.23,"end":110.3,"text":"This series stays with synthesis that"},{"start":110.3,"end":111.34,"text":"doesn't pool results."},{"start":112.29,"end":114.77,"text":"So no type of review is automatically"},{"start":114.77,"end":115.29,"text":"best."},{"start":115.99,"end":118.21,"text":"The best one fits the job."},{"start":118.93,"end":121.45,"text":"One paper on review types calls this"},{"start":121.45,"end":123.03,"text":"fitness for purpose."},{"start":123.55,"end":126.59,"text":"Write your question first, then let it"},{"start":126.59,"end":127.19,"text":"pick the path."},{"start":128.03,"end":131.25,"text":"To go deeper, watch Review Families and"},{"start":131.25,"end":132.87,"text":"Six Ways to Synthesize."},{"start":133.21,"end":134.83,"text":"Last, a question."},{"start":135.21,"end":138.29,"text":"What do you need your own review to do?"}]},"es-short-high-agreement-low-kappa":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":3.06,"text":"Maya and Omar are two made up reviewers."},{"start":3.42,"end":6.56,"text":"They screen the same forty records without"},{"start":6.56,"end":7.1,"text":"talking."},{"start":7.9,"end":10.38,"text":"They agree on thirty seven of them."},{"start":10.68,"end":13.54,"text":"That's ninety two point five percent"},{"start":13.54,"end":14.04,"text":"agreement."},{"start":15.05,"end":17.79,"text":"But their kappa score is only zero point"},{"start":17.79,"end":18.31,"text":"three six."},{"start":18.99,"end":20.09,"text":"What happened?"},{"start":20.85,"end":22.99,"text":"Kappa asks how much of that agreement"},{"start":22.99,"end":23.85,"text":"beats luck."},{"start":24.29,"end":26.87,"text":"Picture them both voting at random, at"},{"start":26.87,"end":27.83,"text":"their usual rates."},{"start":28.23,"end":29.81,"text":"They'd still match sometimes."},{"start":30.63,"end":32.15,"text":"That's chance agreement."},{"start":33.03,"end":35.67,"text":"Take the room left above luck."},{"start":36.25,"end":39.55,"text":"Kappa is how much of it a pair fills."},{"start":40.45,"end":41.19,"text":"Here's their table."},{"start":41.91,"end":45.85,"text":"Maya kept three, Omar kept two, and they"},{"start":45.85,"end":46.95,"text":"both kept one."},{"start":47.59,"end":50.39,"text":"They both excluded the other thirty six."},{"start":51.47,"end":54.65,"text":"When nearly everything is an exclude, two"},{"start":54.65,"end":57.53,"text":"people match a lot just by luck."},{"start":58.35,"end":61.53,"text":"Here, chance agreement is about zero point"},{"start":61.53,"end":64.91,"text":"eight eight, mostly from both excluding by"},{"start":64.91,"end":65.21,"text":"luck."},{"start":65.51,"end":68.75,"text":"That leaves a sliver of room above luck."},{"start":68.99,"end":73.37,"text":"They filled just over a third, so kappa is"},{"start":73.37,"end":74.55,"text":"zero point three six."},{"start":75.67,"end":79.19,"text":"Imagine Omar excluded all forty unread."},{"start":79.73,"end":82.13,"text":"He'd still agree with Maya thirty seven"},{"start":82.13,"end":82.93,"text":"times."},{"start":83.77,"end":86.39,"text":"Now take a set where keeps are common."},{"start":86.77,"end":89.457,"text":"Agreement is the same, ninety two point"},{"start":89.457,"end":90.23,"text":"five percent."},{"start":90.91,"end":92.11,"text":"Same kappa too?"},{"start":92.69,"end":93.69,"text":"Make your guess."},{"start":98.72,"end":99.52,"text":"Not even close."},{"start":99.9,"end":103.107,"text":"Here, chance is only about zero point six"},{"start":103.107,"end":103.36,"text":"one."},{"start":103.66,"end":106.32,"text":"So kappa is zero point eight one."},{"start":107.27,"end":109.93,"text":"What changed is how common keeps are."},{"start":110.23,"end":112.01,"text":"That's called prevalence."},{"start":112.43,"end":116.55,"text":"Rare keeps push chance up and drag kappa"},{"start":116.55,"end":116.81,"text":"down."},{"start":117.11,"end":120.51,"text":"Two researchers named this high agreement"},{"start":120.51,"end":122.09,"text":"but low kappa."},{"start":122.77,"end":124.35,"text":"So kappa isn't broken."},{"start":124.67,"end":128.25,"text":"It shows where they disagree: the rare"},{"start":128.25,"end":128.79,"text":"keeps."},{"start":129.13,"end":132.27,"text":"Of five keep votes, only two matched."},{"start":133.03,"end":135.65,"text":"Exclude votes matched almost every time."},{"start":136.34,"end":140.3,"text":"So report kappa, the table, and both of"},{"start":140.3,"end":140.86,"text":"those agreements."},{"start":141.77,"end":144.37,"text":"The full video shows the whole pilot."},{"start":144.37,"end":146.87,"text":"Think about your own screening."},{"start":146.87,"end":149.41,"text":"How rare are the keeps?"}]},"es-short-vote-counting":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.44,"text":"Maya is a made up doctoral student."},{"start":2.84,"end":5.84,"text":"She has nine made up studies on AI"},{"start":5.84,"end":8.2,"text":"feedback and undergraduate writing."},{"start":8.46,"end":12.24,"text":"A friend suggests a shortcut: vote"},{"start":12.24,"end":12.58,"text":"counting."},{"start":13.4,"end":16.42,"text":"Each study gets one vote: was it"},{"start":16.42,"end":16.82,"text":"significant?"},{"start":17.26,"end":19.62,"text":"Only two of nine were."},{"start":20.32,"end":22.78,"text":"So does AI feedback mostly fail?"},{"start":23.54,"end":24.84,"text":"Pause and decide."},{"start":30.98,"end":31.8,"text":"Not so fast."},{"start":32.44,"end":35.06,"text":"Significant means the result would be rare"},{"start":35.06,"end":36.76,"text":"if there were no real effect."},{"start":37.56,"end":39.9,"text":"Small studies often can't reach that bar."},{"start":40.32,"end":43.66,"text":"Look at the five smallest, thirty to sixty"},{"start":43.66,"end":44.4,"text":"students each."},{"start":44.4,"end":47.74,"text":"Every one points up, but none is"},{"start":47.74,"end":48.14,"text":"significant."},{"start":48.76,"end":51.78,"text":"Not significant doesn't mean no effect."},{"start":52.66,"end":55.4,"text":"The Cochrane Handbook, a standard guide,"},{"start":55.4,"end":56.96,"text":"warns about this trap."},{"start":57.68,"end":60.76,"text":"Counting votes by significance can lead to"},{"start":60.76,"end":61.66,"text":"the wrong conclusion."},{"start":62.76,"end":65.06,"text":"Small studies that can't rule out an"},{"start":65.06,"end":67.64,"text":"important effect get counted as not"},{"start":67.64,"end":68.4,"text":"showing benefit."},{"start":69.18,"end":72.64,"text":"So two of nine doesn't mean it mostly"},{"start":72.64,"end":73.14,"text":"fails."},{"start":74,"end":75.08,"text":"So change the vote."},{"start":75.62,"end":77.24,"text":"Don't ask if it's significant."},{"start":77.52,"end":79.22,"text":"Ask which way it points."},{"start":79.52,"end":82,"text":"Now it's seven up and two down."},{"start":82.16,"end":85.88,"text":"A reporting guideline called SW i M names"},{"start":85.88,"end":86.58,"text":"this method."},{"start":87.1,"end":89.36,"text":"Cochrane accepts it when effect sizes"},{"start":89.36,"end":90.38,"text":"can't be combined."},{"start":91.25,"end":92.97,"text":"But be honest about its limits."},{"start":93.33,"end":95.79,"text":"It can't show how big the effect is."},{"start":95.91,"end":97.65,"text":"It ignores study size."},{"start":98.03,"end":101.43,"text":"And with only nine studies, uncertainty is"},{"start":101.43,"end":101.79,"text":"large."},{"start":102.25,"end":104.79,"text":"So seven of nine proves nothing."},{"start":105.21,"end":108.17,"text":"It shows which way the evidence leans."},{"start":108.9,"end":110.88,"text":"Now the real synthesis starts."},{"start":111.66,"end":114.68,"text":"Maya sorts the studies by setting and asks"},{"start":114.68,"end":115.54,"text":"where they split."},{"start":116.16,"end":119.56,"text":"In first year courses, all five point up."},{"start":119.76,"end":123,"text":"In upper level courses, two of four do."},{"start":123.5,"end":126.16,"text":"Both down arrows are upper level"},{"start":126.16,"end":127.1,"text":"randomized trials."},{"start":127.74,"end":129.68,"text":"Setting, or design?"},{"start":130.55,"end":133.47,"text":"Count direction, then ask where the"},{"start":133.47,"end":134.15,"text":"studies split."},{"start":134.84,"end":137.41,"text":"The full Table to Claim video picks up"},{"start":137.41,"end":137.83,"text":"from there."},{"start":138.5,"end":140.35,"text":"Before you go, think back."},{"start":141,"end":143.29,"text":"Did the last review you read count"},{"start":143.29,"end":144.29,"text":"significant results?"}]},"es-short-prisma-is-not-quality":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.48,"text":"You've probably read a sentence like this."},{"start":3.2,"end":5.96,"text":"This review followed PRISMA, so you can"},{"start":5.96,"end":6.46,"text":"trust it."},{"start":6.96,"end":8.98,"text":"It sounds like a stamp of quality."},{"start":9.34,"end":10.14,"text":"Is it?"},{"start":10.84,"end":12.58,"text":"Decide before we go on."},{"start":18.44,"end":19,"text":"It isn't."},{"start":19.46,"end":21.6,"text":"PRISMA itself says so."},{"start":22.34,"end":24.84,"text":"PRISMA twenty twenty is a reporting"},{"start":24.84,"end":25.32,"text":"guideline."},{"start":26.08,"end":28.56,"text":"It's a checklist of twenty seven things to"},{"start":28.56,"end":29.26,"text":"tell your readers."},{"start":29.9,"end":32.04,"text":"They include your full search strategies"},{"start":32.04,"end":34.96,"text":"and how many people screened each record."},{"start":35.66,"end":38.84,"text":"Also how studies moved from the search to"},{"start":38.84,"end":39.6,"text":"the final set."},{"start":40.37,"end":41.83,"text":"Its own authors are clear."},{"start":42.25,"end":44.69,"text":"They write that it should not be used to"},{"start":44.69,"end":47.29,"text":"assess how a review was done, or its"},{"start":47.29,"end":47.69,"text":"quality."},{"start":48.11,"end":50.45,"text":"Other tools exist for this purpose."},{"start":51.28,"end":53.38,"text":"So you're really asking two questions."},{"start":54.02,"end":54.92,"text":"Was it reported?"},{"start":55.12,"end":56.58,"text":"And was it done well?"},{"start":57.22,"end":59.7,"text":"Say a review clearly reports that it"},{"start":59.7,"end":61.18,"text":"searched just one database."},{"start":61.86,"end":64.46,"text":"That's great reporting of what's likely a"},{"start":64.46,"end":65.04,"text":"thin search."},{"start":65.36,"end":66.96,"text":"It works the other way too."},{"start":67.42,"end":70.14,"text":"Say another review never mentions its"},{"start":70.14,"end":70.52,"text":"protocol."},{"start":71.1,"end":73.2,"text":"That's its plan, written in advance."},{"start":73.78,"end":75.62,"text":"That doesn't prove it had none."},{"start":75.78,"end":77.98,"text":"It just means you can't check."},{"start":78.76,"end":80.72,"text":"So what is PRISMA good for?"},{"start":81.82,"end":82.54,"text":"Transparency."},{"start":82.76,"end":85.34,"text":"It's a yardstick for what a reader can"},{"start":85.34,"end":85.68,"text":"check."},{"start":85.9,"end":88.76,"text":"Take a made up review that Maya audited."},{"start":88.92,"end":91.34,"text":"It assessed a hundred and thirty full"},{"start":91.34,"end":91.78,"text":"texts."},{"start":92,"end":95.69,"text":"It excluded eighty two, and included fifty"},{"start":95.69,"end":96.04,"text":"two."},{"start":96.5,"end":99.1,"text":"But a hundred and thirty minus eighty two"},{"start":99.1,"end":100.3,"text":"is forty eight."},{"start":100.74,"end":104.72,"text":"So four full texts have no path, and the"},{"start":104.72,"end":107.24,"text":"diagram never says where they came from."},{"start":107.92,"end":109.66,"text":"So keep the two questions apart."},{"start":110.43,"end":111.26,"text":"Was it reported?"},{"start":111.82,"end":113.06,"text":"That's PRISMA's job."},{"start":113.46,"end":114.74,"text":"Was it done well?"},{"start":115.18,"end":117.5,"text":"That's appraisal, and it needs its own"},{"start":117.5,"end":117.88,"text":"tools."},{"start":118.2,"end":121.26,"text":"The full Review Autopsy video shows you"},{"start":121.26,"end":121.46,"text":"how."},{"start":121.88,"end":124.78,"text":"Then try the reporting check yourself on a"},{"start":124.78,"end":125.42,"text":"published review."},{"start":125.94,"end":128.02,"text":"Does it report everything on the card?"},{"start":128.44,"end":130.02,"text":"Write down what's missing."}]},"es-short-known-study-recall":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.88,"text":"This is Maya, a made up doctoral student."},{"start":3.18,"end":5.86,"text":"She knows ten studies that she's sure"},{"start":5.86,"end":6.86,"text":"belong in her review."},{"start":7.34,"end":10.12,"text":"She tests her search string, and it finds"},{"start":10.12,"end":10.86,"text":"all ten."},{"start":11.42,"end":12.66,"text":"Ten out of ten."},{"start":13.2,"end":14.52,"text":"Is her search done?"},{"start":15.24,"end":16.72,"text":"Decide before we go on."},{"start":23,"end":23.48,"text":"Not yet."},{"start":24.28,"end":27.2,"text":"Recall is the share your search finds of"},{"start":27.2,"end":29.12,"text":"all the relevant studies out there."},{"start":29.46,"end":31.46,"text":"But nobody knows them all."},{"start":31.78,"end":34.56,"text":"So you estimate it from the ones you do"},{"start":34.56,"end":34.8,"text":"know."},{"start":35.36,"end":37.6,"text":"That's called known-study recall."},{"start":38.06,"end":41,"text":"It's a small sample, not the whole field."},{"start":41.767,"end":43.567,"text":"Now compare two strings."},{"start":43.927,"end":47.007,"text":"Her broad one pulls in two hundred thirty"},{"start":47.007,"end":49.247,"text":"four records and finds all ten."},{"start":49.467,"end":52.227,"text":"Her tighter one pulls in forty nine."},{"start":52.707,"end":54.787,"text":"It also finds all ten."},{"start":55.187,"end":58.887,"text":"Same score, but almost five times the"},{"start":58.887,"end":59.227,"text":"screening."},{"start":59.567,"end":62.167,"text":"Ten out of ten can't tell them apart."},{"start":63.033,"end":64.633,"text":"There's a deeper catch, too."},{"start":64.913,"end":68.313,"text":"A known study only tests the words it"},{"start":68.313,"end":68.773,"text":"uses."},{"start":69.233,"end":72.473,"text":"Now imagine a made up study that calls the"},{"start":72.473,"end":74.293,"text":"chatbot a writing assistant."},{"start":74.873,"end":77.793,"text":"Say none of your ten known studies uses"},{"start":77.793,"end":78.453,"text":"that phrase."},{"start":78.893,"end":81.813,"text":"Then ten out of ten can't tell you that"},{"start":81.813,"end":82.613,"text":"study is missing."},{"start":83.367,"end":85.727,"text":"So treat it the way the Cochrane Handbook"},{"start":85.727,"end":88.027,"text":"does, as one simple test."},{"start":88.727,"end":90.387,"text":"Then add more checks."},{"start":91.107,"end":94.007,"text":"One review of search guidance suggests a"},{"start":94.007,"end":97.027,"text":"thorough search needs both databases and"},{"start":97.027,"end":97.867,"text":"other methods."},{"start":98.407,"end":100.487,"text":"Checking reference lists is one."},{"start":100.687,"end":103.507,"text":"And it's worth having someone peer review"},{"start":103.507,"end":104.287,"text":"your string."},{"start":105.067,"end":106.207,"text":"And write it all down."},{"start":106.507,"end":107.627,"text":"Try it yourself."},{"start":108.247,"end":111.247,"text":"Run your string against studies you know"},{"start":111.247,"end":111.607,"text":"belong."},{"start":112.167,"end":115.047,"text":"Log the count and every change you make."},{"start":115.367,"end":117.847,"text":"Ten out of ten is a good start."},{"start":118.247,"end":120.127,"text":"It's just not the finish line."},{"start":120.367,"end":123.727,"text":"The full video on search strings shows the"},{"start":123.727,"end":124.347,"text":"whole test."},{"start":124.947,"end":126.047,"text":"Last question."},{"start":126.427,"end":129.287,"text":"Which relevant studies might your words"},{"start":129.287,"end":129.607,"text":"miss?"}]},"es-short-ai-tools-dont-exclude":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":3.16,"text":"Maya is trying out a made up AI screening"},{"start":3.16,"end":3.58,"text":"assistant."},{"start":4.04,"end":6.6,"text":"It reads her titles and abstracts."},{"start":6.72,"end":9.52,"text":"Then it offers to throw out the ones that"},{"start":9.52,"end":10.02,"text":"don't fit."},{"start":10.46,"end":12.26,"text":"That could save her hours."},{"start":12.68,"end":13.88,"text":"Can she let it?"},{"start":14.5,"end":17.74,"text":"First, she tests it on forty records she"},{"start":17.74,"end":19.2,"text":"already screened by hand."},{"start":19.38,"end":21.02,"text":"She'd included six."},{"start":21.34,"end":24.02,"text":"The tool flags nine as relevant."},{"start":24.4,"end":25.94,"text":"Did it catch all six?"},{"start":26.42,"end":27.78,"text":"Make your guess now."},{"start":34.13,"end":34.65,"text":"Not quite."},{"start":34.99,"end":38.53,"text":"It flagged five of her six, plus four"},{"start":38.53,"end":38.97,"text":"others."},{"start":39.23,"end":42.71,"text":"So one study she included slipped past it."},{"start":43.4,"end":45.66,"text":"Now imagine she'd let it exclude."},{"start":46.6,"end":49.42,"text":"Every record it didn't flag would vanish,"},{"start":49.42,"end":50.68,"text":"including that one."},{"start":51.16,"end":54.04,"text":"The PRISMA flow diagram has a box for"},{"start":54.04,"end":56.36,"text":"records marked ineligible by automation"},{"start":56.36,"end":56.9,"text":"tools."},{"start":57.46,"end":58.96,"text":"So she'd report a count."},{"start":59.58,"end":62.76,"text":"But a count can't tell anyone which study"},{"start":62.76,"end":63.56,"text":"was lost."},{"start":64.4,"end":66,"text":"So here's a safe default."},{"start":66.3,"end":69.4,"text":"Tools support the work, but they don't own"},{"start":69.4,"end":69.94,"text":"the decision."},{"start":70.54,"end":73.18,"text":"Four evidence synthesis groups, including"},{"start":73.18,"end":75.76,"text":"Cochrane and Campbell, put out a joint"},{"start":75.76,"end":76.18,"text":"statement."},{"start":76.46,"end":79.94,"text":"It says AI and automation should be used"},{"start":79.94,"end":81.02,"text":"with human oversight."},{"start":81.46,"end":84.7,"text":"It also says reviewers are ultimately"},{"start":84.7,"end":87.78,"text":"responsible for their synthesis, including"},{"start":87.78,"end":89.76,"text":"the choice to use AI."},{"start":90.6,"end":93.58,"text":"Under that default, the tool has one job."},{"start":93.86,"end":96.82,"text":"It sorts, and it never excludes."},{"start":97.23,"end":100.28,"text":"The nine records it flags go to the top of"},{"start":100.28,"end":100.62,"text":"the pile."},{"start":101.2,"end":104.58,"text":"Maya still reads all forty, so she catches"},{"start":104.58,"end":105.44,"text":"the one it missed."},{"start":105.74,"end":109.54,"text":"She sees likely includes first, and every"},{"start":109.54,"end":111.76,"text":"eligibility call stays human."},{"start":112.567,"end":113.327,"text":"And write it down."},{"start":113.607,"end":116.627,"text":"The same statement asks for full, open"},{"start":116.627,"end":119.807,"text":"reporting of any AI or automation that"},{"start":119.807,"end":121.727,"text":"makes or suggests judgments."},{"start":122.507,"end":125.087,"text":"It asks for the tool's name and version,"},{"start":125.087,"end":128.067,"text":"the dates, the purpose, and how you"},{"start":128.067,"end":128.887,"text":"checked its output."},{"start":129.587,"end":131.307,"text":"The full video goes further."},{"start":131.987,"end":133.007,"text":"Then ask yourself."},{"start":133.727,"end":136.167,"text":"Which calls in your review should stay"},{"start":136.167,"end":136.627,"text":"human?"}]},"es-short-disclosing-ai-use":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.42,"text":"Maya is a made up doctoral student."},{"start":2.76,"end":6.36,"text":"An AI tool helped her find synonyms and"},{"start":6.36,"end":7.74,"text":"poke holes in a draft."},{"start":8.2,"end":9.74,"text":"What should she disclose?"},{"start":10.2,"end":12.28,"text":"And how should she say it?"},{"start":12.96,"end":16.08,"text":"One publishing guide, from the ICMJE,"},{"start":16.08,"end":17.46,"text":"covers AI."},{"start":18.12,"end":20.84,"text":"It says to disclose which tool you used,"},{"start":20.84,"end":22.26,"text":"and for what purpose."},{"start":22.78,"end":25.62,"text":"Humans are ultimately responsible for"},{"start":25.62,"end":28.2,"text":"reviewing what it produces and making sure"},{"start":28.2,"end":29.04,"text":"it's accurate."},{"start":29.72,"end":32.66,"text":"And AI shouldn't be listed as an author."},{"start":33.36,"end":36.98,"text":"For a systematic or scoping review, is the"},{"start":36.98,"end":39.28,"text":"tool and its purpose enough?"},{"start":44.37,"end":44.81,"text":"Maybe not."},{"start":45.35,"end":48.01,"text":"Evidence synthesis groups have their own"},{"start":48.01,"end":48.77,"text":"joint statement."},{"start":49.11,"end":52.43,"text":"Four groups put it out, including Cochrane"},{"start":52.43,"end":53.27,"text":"and Campbell."},{"start":53.45,"end":56.35,"text":"It says reviewers stay ultimately"},{"start":56.35,"end":59.79,"text":"responsible, and AI should be used with"},{"start":59.79,"end":60.71,"text":"human oversight."},{"start":60.89,"end":63.91,"text":"And any use that makes or suggests"},{"start":63.91,"end":67.07,"text":"judgments should be reported fully and"},{"start":67.07,"end":67.47,"text":"openly."},{"start":68.24,"end":70.8,"text":"A table in the statement lists what to"},{"start":70.8,"end":71.14,"text":"report."},{"start":71.56,"end":74.44,"text":"That includes the tool's name, version,"},{"start":74.44,"end":77.38,"text":"and dates, its purpose, and how it was"},{"start":77.38,"end":77.84,"text":"validated."},{"start":78.06,"end":80.82,"text":"And the steps you took to check its"},{"start":80.82,"end":81.12,"text":"output."},{"start":81.95,"end":83.75,"text":"Watch the disclosure grow."},{"start":84.44,"end":88.55,"text":"The ICMJE asks for the tool and its"},{"start":88.55,"end":88.97,"text":"purpose."},{"start":89.58,"end":92.49,"text":"For a review, the joint statement adds"},{"start":92.49,"end":95.77,"text":"more, like the version, the dates, the"},{"start":95.77,"end":98.15,"text":"validation, and how you checked the"},{"start":98.15,"end":98.41,"text":"output."},{"start":99.3,"end":102.1,"text":"Here's a made up example for Maya's draft"},{"start":102.1,"end":102.58,"text":"critique."},{"start":102.72,"end":106.22,"text":"It names the tool, its version, and the"},{"start":106.22,"end":106.52,"text":"purpose."},{"start":107.39,"end":109.93,"text":"Her made up note for the synonyms is"},{"start":109.93,"end":112.05,"text":"longer, because it's for a review."},{"start":112.23,"end":114.37,"text":"But you can check every part."},{"start":115.66,"end":118.4,"text":"Keep it short, specific, and checkable."},{"start":118.54,"end":121.32,"text":"The full video on the PRISMA flow and tool"},{"start":121.32,"end":122.32,"text":"audit goes further."},{"start":122.86,"end":124.48,"text":"Ask yourself one thing."},{"start":125.04,"end":127.02,"text":"What's allowed where your work will go?"},{"start":127.5,"end":129.96,"text":"Check your journal's, funder's, or"},{"start":129.96,"end":131.08,"text":"institution's policy."}]},"es-short-framework-pico":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.74,"text":"PICO is probably the best known question"},{"start":2.74,"end":3.28,"text":"framework."},{"start":4.06,"end":6.58,"text":"The skill is knowing what each letter"},{"start":6.58,"end":7.26,"text":"turns into."},{"start":8.08,"end":11.62,"text":"Meet Maya, a made up doctoral student who"},{"start":11.62,"end":14.22,"text":"studies AI chatbot feedback on"},{"start":14.22,"end":15.44,"text":"undergraduate writing."},{"start":16.2,"end":18.78,"text":"P is the population, who it's for."},{"start":19.1,"end":22.18,"text":"I is the intervention, what they get."},{"start":22.52,"end":26.22,"text":"O is the outcome, how you'd measure if it"},{"start":26.22,"end":26.56,"text":"worked."},{"start":26.82,"end":30.06,"text":"C is the comparison, and it's optional."},{"start":30.867,"end":34.327,"text":"It began in medicine, as the well built"},{"start":34.327,"end":36.547,"text":"clinical question of nineteen ninety five."},{"start":37.927,"end":41.187,"text":"Booth says its job is to turn a vague need"},{"start":41.187,"end":43.267,"text":"into an answerable question."},{"start":44.087,"end":46.747,"text":"PRISMA suggests it for effects questions."},{"start":46.747,"end":51.127,"text":"Cochrane says it's generally not suited to"},{"start":51.127,"end":52.047,"text":"qualitative ones."},{"start":54,"end":57.06,"text":"For Maya, that's undergraduates, chatbot"},{"start":57.06,"end":59.14,"text":"feedback on drafts, compared with"},{"start":59.14,"end":62.3,"text":"instructor, peer, or no feedback, and"},{"start":62.3,"end":63.96,"text":"writing quality on revision."},{"start":64.84,"end":67.84,"text":"Each element you keep becomes a rule for"},{"start":67.84,"end":69.02,"text":"which studies get in."},{"start":69.5,"end":71.38,"text":"That's an eligibility clause."},{"start":72.14,"end":75.4,"text":"So undergraduates becomes students in"},{"start":75.4,"end":77.86,"text":"credit bearing courses, and so on."},{"start":78.67,"end":81.59,"text":"Only some become search blocks, the words"},{"start":81.59,"end":82.69,"text":"you type into a database."},{"start":83.61,"end":85.67,"text":"Population and intervention do."},{"start":86.47,"end":89.39,"text":"Comparison and outcome usually stay screen"},{"start":89.39,"end":89.79,"text":"only."},{"start":90.35,"end":92.37,"text":"A person checks them while reading."},{"start":92.37,"end":95.81,"text":"Cochrane's reason: abstracts may not"},{"start":95.81,"end":96.65,"text":"describe them well."},{"start":98,"end":101.98,"text":"Now try a new question, about Grade seven"},{"start":101.98,"end":102.4,"text":"math."},{"start":103.23,"end":106.3,"text":"Which parts would you search, and which"},{"start":106.3,"end":107.1,"text":"would you screen?"},{"start":113.25,"end":115.01,"text":"Search the students and the videos."},{"start":115.37,"end":117.67,"text":"Screen the practice and the scores."},{"start":118.25,"end":119.89,"text":"That's a safe default."},{"start":120.69,"end":123.31,"text":"Searching every letter is the classic"},{"start":123.31,"end":123.71,"text":"slip."},{"start":124.27,"end":126.83,"text":"Cochrane says it's usually unnecessary,"},{"start":126.83,"end":129.79,"text":"and may even be a bad idea."},{"start":130.43,"end":134.43,"text":"And JBI notes outcomes don't always make"},{"start":134.43,"end":134.95,"text":"the abstract."},{"start":135.9,"end":136.5,"text":"To recap."},{"start":136.72,"end":139.96,"text":"Four slots, and C is optional."},{"start":140.2,"end":142.9,"text":"Every element you keep becomes an"},{"start":142.9,"end":143.94,"text":"eligibility clause."},{"start":144.62,"end":148.24,"text":"Of the four, usually only population and"},{"start":148.24,"end":149.76,"text":"intervention get searched."},{"start":150.02,"end":153.08,"text":"The full Question Frameworks video goes"},{"start":153.08,"end":153.44,"text":"deeper."}]},"es-short-framework-picos-picot-picoc":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":1.1,"text":"PICO has cousins."},{"start":1.1,"end":6.08,"text":"PICOS, PICOT, and PICOC each add"},{"start":6.08,"end":6.82,"text":"one letter."},{"start":7.26,"end":8.66,"text":"When is it worth it?"},{"start":9.4,"end":11.16,"text":"S is study design."},{"start":11.98,"end":15.04,"text":"The older PRISMA checklist asked for it in"},{"start":15.04,"end":15.78,"text":"the review question."},{"start":16.67,"end":18.13,"text":"T is time."},{"start":18.35,"end":21.71,"text":"One team, writing for clinicians planning"},{"start":21.71,"end":24.75,"text":"studies, calls it how long data collection"},{"start":24.75,"end":25.31,"text":"lasts."},{"start":25.77,"end":29.15,"text":"Others use T for when the outcome is"},{"start":29.15,"end":29.59,"text":"measured."},{"start":30.33,"end":33.83,"text":"The extra C is context, where the"},{"start":33.83,"end":35.01,"text":"intervention happens."},{"start":35.25,"end":38.57,"text":"It traces to a guide on social science"},{"start":38.57,"end":38.97,"text":"reviews."},{"start":39.967,"end":41.387,"text":"Add them to Maya's question."},{"start":41.967,"end":44.947,"text":"Each becomes an eligibility clause, a rule"},{"start":44.947,"end":46.287,"text":"for which studies get in."},{"start":46.667,"end":49.747,"text":"Design becomes randomized or quasi"},{"start":49.747,"end":50.887,"text":"experimental studies."},{"start":51.427,"end":54.427,"text":"Time becomes writing measured in the same"},{"start":54.427,"end":54.807,"text":"term."},{"start":55.487,"end":57.927,"text":"Context becomes first year composition"},{"start":57.927,"end":59.847,"text":"classes that allow AI."},{"start":60.707,"end":62.627,"text":"Do they also become search blocks?"},{"start":63.027,"end":64.927,"text":"Those are the words you type in."},{"start":65.667,"end":68.207,"text":"Cochrane's typical search has a block for"},{"start":68.207,"end":68.927,"text":"study design."},{"start":69.867,"end":71.907,"text":"Not for time or context."},{"start":72.707,"end":75.507,"text":"So screen those two by default, while"},{"start":75.507,"end":76.567,"text":"reading each study."},{"start":77.333,"end":79.593,"text":"Does a design block cost anything?"},{"start":79.813,"end":83.133,"text":"In one health review, a qualitative design"},{"start":83.133,"end":86.153,"text":"block cut about twenty four thousand hits"},{"start":86.153,"end":87.813,"text":"to about four hundred fifty."},{"start":88.533,"end":91.673,"text":"Did it still find all eighteen relevant"},{"start":91.673,"end":92.113,"text":"articles?"},{"start":98.233,"end":99.993,"text":"No, only thirteen."},{"start":100.933,"end":103.393,"text":"Screening took hours, not weeks."},{"start":103.673,"end":106.753,"text":"But five relevant articles were lost."},{"start":107.073,"end":110.813,"text":"So the authors suggest PICOS only when"},{"start":110.813,"end":111.613,"text":"time is short."},{"start":111.953,"end":114.753,"text":"Their block was for qualitative studies,"},{"start":114.753,"end":117.973,"text":"not a trial filter like Maya's, and it's"},{"start":117.973,"end":119.113,"text":"untested in education."},{"start":119.573,"end":122.233,"text":"Test yours against studies you know"},{"start":122.233,"end":122.573,"text":"belong."},{"start":123.533,"end":124.313,"text":"One more trap."},{"start":124.673,"end":127.973,"text":"T is not a limit on publication dates."},{"start":128.473,"end":129.653,"text":"Need a date limit?"},{"start":130.153,"end":131.893,"text":"Give it its own reason."},{"start":135.4,"end":135.92,"text":"To recap."},{"start":136.14,"end":139.54,"text":"An extra letter almost always means an"},{"start":139.54,"end":140.3,"text":"extra clause."},{"start":141.08,"end":143.68,"text":"Only S sometimes gets a search block,"},{"start":143.68,"end":144.94,"text":"after testing."},{"start":145.24,"end":147.5,"text":"T is not a date limit."},{"start":148.06,"end":150.62,"text":"The full Question Frameworks video goes"},{"start":150.62,"end":150.98,"text":"further."}]},"es-short-framework-peco-peo":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0.02,"end":1.722,"text":"Maya's noticed something."},{"start":2.131,"end":4.581,"text":"Students in her courses already use"},{"start":4.581,"end":7.1,"text":"chatbots for writing, on their own."},{"start":7.509,"end":8.939,"text":"Nobody assigned that."},{"start":9.347,"end":11.322,"text":"Is it really an intervention?"},{"start":12.21,"end":13.07,"text":"Not really."},{"start":13.539,"end":14.868,"text":"It's an exposure."},{"start":15.337,"end":18.465,"text":"Booth says E replaces I when the action"},{"start":18.465,"end":20.576,"text":"wasn't planned or intended."},{"start":21.045,"end":24.72,"text":"The four letters are population, exposure,"},{"start":24.72,"end":26.831,"text":"comparator, and outcomes."},{"start":27.78,"end":30.447,"text":"One environmental health group found"},{"start":30.447,"end":32.825,"text":"little guidance on writing these"},{"start":32.825,"end":33.546,"text":"questions."},{"start":33.978,"end":37.149,"text":"JBI has a three letter cousin, PEO,"},{"start":37.149,"end":38.59,"text":"for causes and risk."},{"start":39.023,"end":42.05,"text":"Both ask whether two things are linked,"},{"start":42.05,"end":44.068,"text":"not whether something works."},{"start":45.12,"end":46.879,"text":"This is Maya's version."},{"start":47.338,"end":50.704,"text":"Among undergraduates, is frequent, self"},{"start":50.704,"end":54.07,"text":"initiated chatbot use, compared with rare"},{"start":54.07,"end":57.283,"text":"or no use, associated with writing self"},{"start":57.283,"end":57.971,"text":"efficacy?"},{"start":59.1,"end":61.893,"text":"Every element she keeps becomes an"},{"start":61.893,"end":65.004,"text":"eligibility clause, a rule for which"},{"start":65.004,"end":66.201,"text":"studies get in."},{"start":66.68,"end":70.111,"text":"P and E also become search blocks, words"},{"start":70.111,"end":71.866,"text":"typed into a database."},{"start":72.345,"end":75.855,"text":"C and O stay screen only, since abstracts"},{"start":75.855,"end":77.371,"text":"can leave them out."},{"start":79.45,"end":81.613,"text":"The comparator is the hard part."},{"start":82.019,"end":84.858,"text":"The environmental health group lists five"},{"start":84.858,"end":85.872,"text":"ways to set it."},{"start":86.278,"end":87.765,"text":"Maya picks the second."},{"start":88.171,"end":91.01,"text":"She'll compare the highest and lowest use"},{"start":91.01,"end":93.984,"text":"her studies report, fixed in her protocol."},{"start":95.02,"end":96.534,"text":"One slip to avoid."},{"start":97.039,"end":100.236,"text":"Saying chatbots improve self efficacy"},{"start":100.236,"end":101.835,"text":"assumes the answer."},{"start":102.34,"end":105.621,"text":"JBI says to state outcomes without a"},{"start":105.621,"end":106.462,"text":"direction."},{"start":106.967,"end":109.575,"text":"Just say writing self efficacy."},{"start":110.74,"end":111.457,"text":"Your turn."},{"start":111.887,"end":114.971,"text":"Paid jobs over fifteen hours a week, and"},{"start":114.971,"end":117.767,"text":"whether students stay in their courses."},{"start":118.197,"end":119.99,"text":"Intervention or exposure?"},{"start":126.23,"end":127.088,"text":"An exposure."},{"start":127.517,"end":129.447,"text":"Nobody assigned those jobs."},{"start":129.876,"end":132.878,"text":"No comparison is named, so it's a PEO"},{"start":132.878,"end":133.521,"text":"question."},{"start":134.57,"end":135.292,"text":"To recap."},{"start":135.773,"end":136.495,"text":"Assigned?"},{"start":136.976,"end":138.018,"text":"Intervention."},{"start":138.499,"end":139.943,"text":"Done on their own?"},{"start":140.424,"end":141.146,"text":"Exposure."},{"start":141.627,"end":143.792,"text":"PECO names a comparison."},{"start":144.273,"end":145.396,"text":"PEO doesn't."},{"start":145.877,"end":149.646,"text":"Either way, you get a link, not proof that"},{"start":149.646,"end":150.929,"text":"something works."},{"start":152.04,"end":155.318,"text":"The full Question Frameworks video covers"},{"start":155.318,"end":156.02,"text":"them all."},{"start":156.488,"end":159.844,"text":"For experience questions, try the SPIDER"},{"start":159.844,"end":160.312,"text":"short."}]},"es-short-framework-spider":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0.03,"end":2.721,"text":"Meet Omar, Maya's made up screening"},{"start":2.721,"end":3.288,"text":"partner."},{"start":3.713,"end":6.121,"text":"He asks how undergraduate writers"},{"start":6.121,"end":8.812,"text":"experience chatbot feedback on drafts."},{"start":9.237,"end":11.928,"text":"There's no comparison and no measured"},{"start":11.928,"end":14.265,"text":"outcome, so PICO doesn't fit."},{"start":15.3,"end":17.951,"text":"SPIDER comes from three researchers."},{"start":18.393,"end":20.824,"text":"They saw search tools focused on"},{"start":20.824,"end":22.444,"text":"quantitative research."},{"start":22.886,"end":25.684,"text":"So they built one for qualitative and"},{"start":25.684,"end":27.378,"text":"mixed methods research."},{"start":28.6,"end":31.884,"text":"S is the sample, here undergraduate"},{"start":31.884,"end":32.575,"text":"writers."},{"start":33.093,"end":36.809,"text":"PI is the phenomenon of interest, their"},{"start":36.809,"end":39.488,"text":"experience of chatbot feedback."},{"start":40.006,"end":42.685,"text":"D is design, like interviews."},{"start":43.204,"end":45.796,"text":"E is evaluation, like trust."},{"start":46.315,"end":50.03,"text":"R is research type, qualitative or mixed"},{"start":50.03,"end":50.722,"text":"methods."},{"start":52,"end":54.448,"text":"Every letter he keeps becomes an"},{"start":54.448,"end":57.34,"text":"eligibility clause, a rule for which"},{"start":57.34,"end":58.452,"text":"studies get in."},{"start":58.898,"end":62.235,"text":"Which also become search blocks, the words"},{"start":62.235,"end":63.125,"text":"you type in?"},{"start":69.39,"end":71.962,"text":"Just the sample and the phenomenon."},{"start":72.403,"end":75.858,"text":"Design, evaluation, and research type stay"},{"start":75.858,"end":76.74,"text":"screen only."},{"start":77.181,"end":79.459,"text":"That's a default, so test it."},{"start":80.487,"end":81.421,"text":"Why only two?"},{"start":81.852,"end":84.656,"text":"One team searched the same topic three"},{"start":84.656,"end":85.015,"text":"ways."},{"start":85.447,"end":88.394,"text":"PICO pulled about twenty four thousand"},{"start":88.394,"end":88.969,"text":"records."},{"start":89.4,"end":92.06,"text":"PICOS, about four hundred fifty."},{"start":92.491,"end":94.935,"text":"SPIDER, about two hundred forty."},{"start":95.927,"end":97.93,"text":"Eighteen studies belonged."},{"start":98.392,"end":100.318,"text":"PICO found all of them."},{"start":100.781,"end":103.4,"text":"The other two found thirteen each."},{"start":103.863,"end":106.328,"text":"SPIDER's hits were more precise."},{"start":106.79,"end":108.254,"text":"But it missed five."},{"start":109.227,"end":110.33,"text":"What went wrong?"},{"start":110.743,"end":113.707,"text":"In SPIDER's search, research type had to"},{"start":113.707,"end":114.397,"text":"match too."},{"start":114.81,"end":117.016,"text":"Methley's team thinks requiring"},{"start":117.016,"end":119.98,"text":"qualitative plus a named method might have"},{"start":119.98,"end":121.083,"text":"been too strict."},{"start":121.497,"end":124.323,"text":"Some missed studies just said interviews."},{"start":125.277,"end":126.283,"text":"Some cautions."},{"start":126.714,"end":129.516,"text":"It was one health topic, untested in"},{"start":129.516,"end":130.235,"text":"education."},{"start":130.666,"end":133.612,"text":"The tools also used different numbers of"},{"start":133.612,"end":134.618,"text":"search blocks."},{"start":135.05,"end":138.068,"text":"SPIDER's own authors say it needs testing"},{"start":138.068,"end":139.146,"text":"on more topics."},{"start":140.553,"end":141.189,"text":"To recap."},{"start":141.613,"end":144.581,"text":"SPIDER is a good checklist for experience"},{"start":144.581,"end":145.287,"text":"questions."},{"start":145.711,"end":148.537,"text":"Search the sample and phenomenon, and"},{"start":148.537,"end":149.668,"text":"screen the rest."},{"start":150.092,"end":151.575,"text":"And test your search."},{"start":151.999,"end":154.189,"text":"SPIDER still needs testing too."},{"start":155.153,"end":157.991,"text":"The full Question Frameworks video goes"},{"start":157.991,"end":158.487,"text":"deeper."},{"start":158.913,"end":161.892,"text":"For exposure questions, see the PECO"},{"start":161.892,"end":162.318,"text":"short."}]},"es-short-framework-pcc-pico":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.62,"text":"Before Maya tests if chatbot feedback"},{"start":2.62,"end":5.48,"text":"works, she wants a map of the research."},{"start":5.76,"end":7.38,"text":"That's a scoping question."},{"start":8.06,"end":11,"text":"It's broader, and can spark ideas to test."},{"start":11.28,"end":14.54,"text":"For this, JBI suggests PCC."},{"start":16.233,"end":20.013,"text":"Population is who, with details like age."},{"start":20.553,"end":24.773,"text":"Concept is the core idea, a big bucket for"},{"start":24.773,"end":27.613,"text":"interventions, phenomena, even outcomes."},{"start":28.433,"end":31.873,"text":"Context could be a culture, place, or"},{"start":31.873,"end":32.253,"text":"setting."},{"start":33.067,"end":35.887,"text":"AJBI paper repeats that advice."},{"start":36.577,"end":39.347,"text":"And a scoping map can include theses,"},{"start":39.347,"end":41.247,"text":"reports, even blogs."},{"start":42.167,"end":44.037,"text":"Let's build Maya's."},{"start":44.037,"end":46.207,"text":"Every element you keep becomes an"},{"start":46.207,"end":48.747,"text":"eligibility clause, a rule for which"},{"start":48.747,"end":49.607,"text":"studies get in."},{"start":50.167,"end":53.027,"text":"Population becomes undergraduate writers."},{"start":53.547,"end":57.107,"text":"Concept becomes any study or report on"},{"start":57.107,"end":58.067,"text":"chatbot feedback."},{"start":58.967,"end":62.207,"text":"Some also become search blocks, words you"},{"start":62.207,"end":63.147,"text":"type into a database."},{"start":64.147,"end":67.607,"text":"Population gives one, concept gives two."},{"start":68.377,"end":70.157,"text":"She leaves context open."},{"start":70.657,"end":71.617,"text":"That's fine."},{"start":71.617,"end":76.117,"text":"JBI says one element may not be needed."},{"start":76.833,"end":79.853,"text":"Now Omar asks how students experience"},{"start":79.853,"end":81.093,"text":"chatbot feedback."},{"start":81.093,"end":85.593,"text":"For qualitative reviews, JBI uses PICo"},{"start":85.593,"end":86.993,"text":"with a small o."},{"start":86.993,"end":90.693,"text":"Population, phenomenon of interest, and"},{"start":90.693,"end":93.193,"text":"context, with no outcome slot."},{"start":94.003,"end":95.543,"text":"He'd search the first two."},{"start":96.003,"end":98.563,"text":"His first context said undergraduate"},{"start":98.563,"end":99.763,"text":"writing courses."},{"start":100.483,"end":103.903,"text":"But JBI says elements shouldn't repeat"},{"start":103.903,"end":104.383,"text":"each other."},{"start":104.523,"end":107.803,"text":"So he trims it to first year writing"},{"start":107.803,"end":108.203,"text":"courses."},{"start":109.1,"end":109.7,"text":"Your turn."},{"start":110.04,"end":113.26,"text":"Should his context be a search block, or"},{"start":113.26,"end":114.14,"text":"screen only?"},{"start":120.2,"end":122.56,"text":"Screen only is a safe default."},{"start":123.5,"end":125.52,"text":"Abstracts may not name the setting."},{"start":125.74,"end":129.44,"text":"If they reliably do, test it as a block."},{"start":130.25,"end":133.69,"text":"Honestly, I found no study testing either"},{"start":133.69,"end":135.11,"text":"framework for searching."},{"start":135.9,"end":136.48,"text":"To recap."},{"start":136.48,"end":140.92,"text":"PCC maps a field, and the small o"},{"start":140.92,"end":142.88,"text":"version explores experiences."},{"start":143.72,"end":146.82,"text":"Every element you keep becomes a clause."},{"start":147.28,"end":150.46,"text":"Search people and concept, and usually"},{"start":150.46,"end":151.78,"text":"screen context."},{"start":152.68,"end":154.94,"text":"The full Question Frameworks video"},{"start":154.94,"end":158.54,"text":"compares them, and the SPIDER short covers"},{"start":158.54,"end":159.3,"text":"experiences."}]},"es-short-framework-spice-eclipse":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.18,"text":"Some questions aren't about a treatment."},{"start":2.36,"end":5.46,"text":"They're about a service, and whose view"},{"start":5.46,"end":5.94,"text":"counts."},{"start":6.72,"end":9.4,"text":"Say Maya's writing center adds a chatbot"},{"start":9.4,"end":10.82,"text":"for first pass feedback."},{"start":11.58,"end":13.42,"text":"SPICE is built for that."},{"start":14.133,"end":15.693,"text":"Setting asks where."},{"start":16.413,"end":18.713,"text":"Perspective asks for whom."},{"start":19.253,"end":21.433,"text":"Intervention asks what."},{"start":22.033,"end":25.073,"text":"Comparison asks, compared with what?"},{"start":25.683,"end":29.073,"text":"And evaluation asks, with what result?"},{"start":29.9,"end":33.485,"text":"Booth made it for library work, not health"},{"start":33.485,"end":33.99,"text":"care."},{"start":33.99,"end":37.18,"text":"He split population into setting and"},{"start":37.18,"end":37.66,"text":"perspective."},{"start":38.27,"end":41.14,"text":"He also swapped outcomes for evaluation."},{"start":41.97,"end":45.68,"text":"That covers outputs, impact, and less"},{"start":45.68,"end":46.58,"text":"tangible effects."},{"start":47.5,"end":49.2,"text":"This is Maya's question."},{"start":50,"end":52.46,"text":"Every element you keep becomes an"},{"start":52.46,"end":55.6,"text":"eligibility clause, a rule for which"},{"start":55.6,"end":56.56,"text":"studies get in."},{"start":57.12,"end":58.8,"text":"Each letter gets one."},{"start":59.6,"end":62.5,"text":"Some also become search blocks, words you"},{"start":62.5,"end":63.38,"text":"type into a database."},{"start":63.8,"end":66.74,"text":"The rest are screen only, checked while"},{"start":66.74,"end":67.06,"text":"reading."},{"start":67.5,"end":69.42,"text":"Which two would you search?"},{"start":75.39,"end":77.63,"text":"Setting and intervention are a safe"},{"start":77.63,"end":80.17,"text":"default, since authors usually name them."},{"start":80.35,"end":82.23,"text":"The other three get screened."},{"start":82.47,"end":84.99,"text":"That's advice, not Booth's rule."},{"start":85.733,"end":86.173,"text":"One trap."},{"start":86.833,"end":88.813,"text":"Perspective isn't just population."},{"start":89.693,"end":92.013,"text":"Booth says evaluation is usually"},{"start":92.013,"end":92.493,"text":"subjective."},{"start":93.233,"end":95.413,"text":"So name whose view counts."},{"start":96.333,"end":99.893,"text":"For policy requests, SPICE's sibling is"},{"start":99.893,"end":100.253,"text":"ECLIPSE."},{"start":100.963,"end":104.453,"text":"Two health policy librarians found PICO"},{"start":104.453,"end":105.513,"text":"didn't fit."},{"start":105.713,"end":108.553,"text":"By the end of two thousand one, their"},{"start":108.553,"end":111.313,"text":"earlier CLIP had become ECLIPSE."},{"start":112.063,"end":115.523,"text":"Its first E, expectation, asks what the"},{"start":115.523,"end":116.563,"text":"information is for."},{"start":116.943,"end":120.363,"text":"Then five more, from client group to"},{"start":120.363,"end":120.743,"text":"service."},{"start":121.523,"end":124.143,"text":"About CLIP, they wrote that not every"},{"start":124.143,"end":127.083,"text":"element fits every search, but consider"},{"start":127.083,"end":128.423,"text":"each at the start."},{"start":129.133,"end":131.813,"text":"Honestly, I couldn't find a study testing"},{"start":131.813,"end":132.433,"text":"either one."},{"start":132.793,"end":135.733,"text":"Booth even admits cynics may see little"},{"start":135.733,"end":137.253,"text":"reason for a separate variant."},{"start":138.1,"end":138.68,"text":"To recap."},{"start":138.98,"end":142.74,"text":"SPICE judges a service through one group's"},{"start":142.74,"end":143,"text":"eyes."},{"start":143.56,"end":145.42,"text":"ECLIPSE handles policy."},{"start":146.2,"end":148.54,"text":"Every element you keep becomes a clause."},{"start":149.38,"end":151.72,"text":"Search setting and intervention, and"},{"start":151.72,"end":153.2,"text":"usually screen the rest."},{"start":154.03,"end":156.29,"text":"The full Question Frameworks video"},{"start":156.29,"end":159.31,"text":"compares them, and another short adds"},{"start":159.31,"end":161.19,"text":"environment and time."}]},"es-short-framework-cimo":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.58,"text":"PICO asks if something works."},{"start":3.46,"end":7.14,"text":"Maya's committee keeps asking how, and in"},{"start":7.14,"end":8.02,"text":"what circumstances."},{"start":8.94,"end":10.78,"text":"That's a question for CIMO."},{"start":12.7,"end":16.26,"text":"C is the context, the people, settings, or"},{"start":16.26,"end":17.1,"text":"systems studied."},{"start":17.62,"end":20.98,"text":"I is the intervention, the action whose"},{"start":20.98,"end":22.08,"text":"effects you're studying."},{"start":22.68,"end":24.24,"text":"M is the mechanism."},{"start":24.42,"end":27.4,"text":"It's why the intervention leads to the"},{"start":27.4,"end":28.68,"text":"outcome, and when."},{"start":29.26,"end":32.62,"text":"O is the outcomes, intended and"},{"start":32.62,"end":33.08,"text":"unintended."},{"start":34.1,"end":35.82,"text":"It comes from management research."},{"start":36.76,"end":39.3,"text":"Three researchers used it for design"},{"start":39.3,"end":40.18,"text":"propositions."},{"start":40.94,"end":43.2,"text":"These suggest what to try in a given"},{"start":43.2,"end":45.54,"text":"setting, and how it should lead to an"},{"start":45.54,"end":45.9,"text":"outcome."},{"start":46.48,"end":50.46,"text":"Here, design means designing a fix, not"},{"start":50.46,"end":51.32,"text":"study design."},{"start":51.84,"end":55.46,"text":"Later, building on Pawson, two of them"},{"start":55.46,"end":57.52,"text":"reworked PICO into CIMO."},{"start":59.1,"end":60.46,"text":"This is Maya's version."},{"start":60.66,"end":64.42,"text":"In big first year sections, feedback comes"},{"start":64.42,"end":65.08,"text":"too late."},{"start":65.6,"end":68.44,"text":"Chatbot feedback plus a short reflection"},{"start":68.44,"end":71.7,"text":"task may prompt self regulated revision."},{"start":72.12,"end":74.66,"text":"That may lead to more substantive"},{"start":74.66,"end":75.46,"text":"revisions."},{"start":76.3,"end":77.5,"text":"What does each letter become?"},{"start":78.34,"end":81.26,"text":"Context, intervention, and outcome become"},{"start":81.26,"end":84.12,"text":"eligibility clauses, rules for which"},{"start":84.12,"end":84.88,"text":"studies get in."},{"start":85.56,"end":88.14,"text":"The first two usually become search blocks"},{"start":88.14,"end":90.44,"text":"too, words you type into a database."},{"start":91.24,"end":94.4,"text":"The outcome usually stays screen only,"},{"start":94.4,"end":95.82,"text":"checked while reading."},{"start":96.533,"end":97.133,"text":"And the mechanism?"},{"start":97.693,"end":100.673,"text":"Should self regulation go in her search?"},{"start":106.653,"end":108.613,"text":"Usually not, as a default."},{"start":109.553,"end":111.933,"text":"Mechanisms are usually explained in full"},{"start":111.933,"end":114.393,"text":"texts, not named in abstracts."},{"start":114.693,"end":117.593,"text":"So she reads for it and writes it down."},{"start":117.973,"end":121.633,"text":"Two other researchers found theory hides"},{"start":121.633,"end":122.513,"text":"the same way."},{"start":123.233,"end":125.893,"text":"One of its authors warns against unfocused"},{"start":125.893,"end":128.593,"text":"questions, like what is known about"},{"start":128.593,"end":129.053,"text":"leadership."},{"start":129.693,"end":132.993,"text":"You don't need CIMO at all, but keep"},{"start":132.993,"end":135.193,"text":"your question clear and answerable."},{"start":135.553,"end":138.573,"text":"Honestly, we found no study testing it."},{"start":139.233,"end":139.853,"text":"To recap."},{"start":140.093,"end":144.953,"text":"Use CIMO when how and where matter."},{"start":145.783,"end":149.053,"text":"Search context and intervention, screen"},{"start":149.053,"end":149.973,"text":"the outcome."},{"start":150.843,"end":152.253,"text":"Read for the mechanism."},{"start":152.903,"end":155.073,"text":"The full video has the rest."}]},"es-short-framework-perspectif-behemoth":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.34,"text":"Does it work isn't the only question."},{"start":2.86,"end":5.82,"text":"Maya's committee asks whose view counts,"},{"start":5.82,"end":8.7,"text":"where, and when, and which theories"},{"start":8.7,"end":9.58,"text":"explain it."},{"start":10.06,"end":12.02,"text":"Two Booth frameworks help."},{"start":12.867,"end":14.067,"text":"First, PerSPEcTiF."},{"start":14.527,"end":16.567,"text":"Booth's team checked thirty eight"},{"start":16.567,"end":18.827,"text":"frameworks against four needs."},{"start":19.627,"end":21.227,"text":"None met all four."},{"start":21.407,"end":24.527,"text":"So they built one for qualitative reviews"},{"start":24.527,"end":26.327,"text":"of complex interventions."},{"start":27.433,"end":28.693,"text":"Whose view counts?"},{"start":29.473,"end":31.573,"text":"Writing instructors, in community"},{"start":31.573,"end":32.133,"text":"colleges."},{"start":32.493,"end":36.093,"text":"The phenomenon is how they adopt chatbot"},{"start":36.093,"end":39.433,"text":"feedback, under an AI policy that changed"},{"start":39.433,"end":40.173,"text":"mid year."},{"start":40.733,"end":42.753,"text":"She skips the optional comparison."},{"start":43.393,"end":45.413,"text":"Timing is the first semester."},{"start":46.193,"end":49.133,"text":"Findings are their views and workload."},{"start":50.133,"end":52.713,"text":"The team listed search words for most"},{"start":52.713,"end":53.173,"text":"letters."},{"start":53.813,"end":55.813,"text":"Should Maya search all seven?"},{"start":61.783,"end":62.063,"text":"No."},{"start":62.243,"end":65.363,"text":"Their table never says to combine all"},{"start":65.363,"end":65.803,"text":"seven."},{"start":65.923,"end":68.983,"text":"And every search block can lose studies."},{"start":69.673,"end":72.483,"text":"So by default she searches the phenomenon"},{"start":72.483,"end":73.683,"text":"and setting."},{"start":73.823,"end":76.623,"text":"The rest stay screen only."},{"start":77.473,"end":79.873,"text":"Every letter she keeps becomes an"},{"start":79.873,"end":83.333,"text":"eligibility clause, a rule for what gets"},{"start":83.333,"end":83.573,"text":"in."},{"start":84.123,"end":86.953,"text":"For environment, the study must describe"},{"start":86.953,"end":88.773,"text":"the college's AI policy."},{"start":89.667,"end":92.227,"text":"Now BeHEMoTh, for finding theory."},{"start":92.227,"end":95.047,"text":"Of thirty four reviews Booth's group"},{"start":95.047,"end":98.167,"text":"checked, only twelve said how they found"},{"start":98.167,"end":98.447,"text":"theirs."},{"start":99.3,"end":102.4,"text":"Be is the behaviour, students taking up"},{"start":102.4,"end":102.76,"text":"feedback."},{"start":103.57,"end":107.04,"text":"H is the context, originally health, here"},{"start":107.04,"end":108.86,"text":"chatbot feedback on writing."},{"start":109.75,"end":112.9,"text":"Then come theory words, like model or"},{"start":112.9,"end":113.28,"text":"framework."},{"start":113.7,"end":116,"text":"E is for exclusions."},{"start":116.63,"end":116.89,"text":"Why?"},{"start":117.39,"end":120.57,"text":"Model often means a statistical model."},{"start":120.67,"end":123.79,"text":"In AI papers, it can mean the chatbot"},{"start":123.79,"end":124.11,"text":"itself."},{"start":124.93,"end":128.35,"text":"So she searches behaviour, context, and"},{"start":128.35,"end":130.23,"text":"theory, minus exclusions."},{"start":130.933,"end":133.253,"text":"Keywords alone still miss theory."},{"start":133.773,"end":136.913,"text":"It often isn't in titles and abstracts."},{"start":136.913,"end":140.153,"text":"So the authors add citation searching."},{"start":140.373,"end":143.613,"text":"And we found neither formally evaluated."},{"start":146.233,"end":146.853,"text":"To recap."},{"start":147.053,"end":151.273,"text":"Use PerSPEcTiF when context, timing, and"},{"start":151.273,"end":152.793,"text":"whose view counts matter."},{"start":153.253,"end":156.053,"text":"Use BeHEMoTh when you need theory."},{"start":156.313,"end":159.193,"text":"Treat both as checklists first."},{"start":159.493,"end":161.913,"text":"The full video has the rest."}]},"cscl-the-minimal-guidance-debate":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.96,"text":"This paper's title sounds like a verdict:"},{"start":2.96,"end":5.34,"text":"minimal guidance doesn't work."},{"start":5.56,"end":8.68,"text":"People often retell it as: inquiry"},{"start":8.68,"end":10.14,"text":"learning is dead."},{"start":10.34,"end":12.92,"text":"The real story is richer."},{"start":13.7,"end":16.38,"text":"Kirschner, Sweller and Clark made the"},{"start":16.38,"end":16.68,"text":"case."},{"start":17.4,"end":20.34,"text":"In minimal guidance, learners find the key"},{"start":20.34,"end":21.42,"text":"information themselves."},{"start":22.38,"end":25.62,"text":"That ignores how minds work, they said,"},{"start":25.62,"end":27.08,"text":"and the evidence."},{"start":27.46,"end":30.72,"text":"So it's less effective and less efficient"},{"start":30.72,"end":32.28,"text":"than strong guidance."},{"start":33.24,"end":34.88,"text":"They also set a limit."},{"start":35.18,"end":38.72,"text":"Once learners know enough, guidance helps"},{"start":38.72,"end":39.14,"text":"less."},{"start":39.38,"end":42.9,"text":"And they lumped discovery, problem based"},{"start":42.9,"end":44.54,"text":"and inquiry learning together."},{"start":44.96,"end":47.14,"text":"That started the fight."},{"start":47.933,"end":50.373,"text":"A year later, the replies came in."},{"start":51.473,"end":54.013,"text":"Hmelo-Silver's team called that lumping a"},{"start":54.013,"end":54.353,"text":"mistake."},{"start":55.153,"end":58.413,"text":"Those methods give lots of support, like"},{"start":58.413,"end":61.133,"text":"prompts and well-timed short lectures."},{"start":61.633,"end":63.813,"text":"That's called scaffolding."},{"start":64.343,"end":67.663,"text":"A second team said problem based learning"},{"start":67.663,"end":69.363,"text":"adjusts its guidance."},{"start":69.863,"end":73.043,"text":"Then Deanna Kuhn asked a different"},{"start":73.043,"end":77.183,"text":"question: not how to teach, but what to"},{"start":77.183,"end":77.443,"text":"teach."},{"start":78.273,"end":79.673,"text":"People skip this part."},{"start":80.143,"end":83.133,"text":"The first two teams agreed: there's little"},{"start":83.133,"end":85.133,"text":"evidence for unguided learning."},{"start":85.553,"end":88.653,"text":"Kuhn wrote she wasn't arguing for"},{"start":88.653,"end":90.913,"text":"discovery over direct instruction."},{"start":91.867,"end":92.907,"text":"Let's make up an example."},{"start":93.487,"end":96.207,"text":"Two seventh grade classes learn to run"},{"start":96.207,"end":96.907,"text":"fair tests."},{"start":97.647,"end":101.127,"text":"Class A studies two worked examples, then"},{"start":101.127,"end":101.627,"text":"practices."},{"start":102.427,"end":105.347,"text":"Class B tries ramps first, with a"},{"start":105.347,"end":106.847,"text":"whiteboard and teacher prompts."},{"start":107.527,"end":110.207,"text":"Then a five minute lecture, and they try"},{"start":110.207,"end":110.507,"text":"again."},{"start":111.267,"end":113.387,"text":"Is Class B minimal guidance?"},{"start":114.347,"end":116.007,"text":"Decide before we go on."},{"start":120.897,"end":123.977,"text":"By Kirschner's definition, partly, because"},{"start":123.977,"end":125.417,"text":"students search first."},{"start":126.097,"end":129.577,"text":"By Hmelo-Silver's, no: it's full of"},{"start":129.577,"end":129.937,"text":"support."},{"start":130.657,"end":132.617,"text":"Kuhn would ask about the goal."},{"start":133.337,"end":136.397,"text":"Can they design fair tests alone next"},{"start":136.397,"end":136.757,"text":"month?"},{"start":137.117,"end":140.137,"text":"So much of this fight is about what to"},{"start":140.137,"end":141.237,"text":"call Class B."},{"start":142.167,"end":144.267,"text":"The first three authors wrote back."},{"start":144.747,"end":147.907,"text":"Both replies back them up, they said:"},{"start":147.907,"end":149.347,"text":"guidance is vital."},{"start":149.507,"end":152.627,"text":"They just stop short of making explicit"},{"start":152.627,"end":154.527,"text":"instruction the main focus."},{"start":155.427,"end":158.562,"text":"Later, one review pooled one hundred sixty"},{"start":158.562,"end":159.287,"text":"four studies."},{"start":160.027,"end":163.467,"text":"Discovery with no help lost to explicit"},{"start":163.467,"end":166.547,"text":"instruction, by about four tenths of a"},{"start":166.547,"end":167.267,"text":"standard deviation."},{"start":168.107,"end":171.227,"text":"Discovery with support, like being asked"},{"start":171.227,"end":173.907,"text":"to explain, came out ahead of the other"},{"start":173.907,"end":176.267,"text":"methods, by about three tenths."},{"start":176.777,"end":178.977,"text":"But results varied a lot."},{"start":179.717,"end":182.397,"text":"In unpublished studies and dissertations,"},{"start":182.397,"end":185.297,"text":"discovery with support didn't come out"},{"start":185.297,"end":185.557,"text":"ahead."},{"start":186.017,"end":189.497,"text":"And the comparison group was a mix, so"},{"start":189.497,"end":192.217,"text":"this isn't guided discovery beating direct"},{"start":192.217,"end":192.697,"text":"instruction."},{"start":193.633,"end":196.233,"text":"In twenty twenty two, it flared up again."},{"start":196.233,"end":199.873,"text":"De Jong's team said inquiry beats direct"},{"start":199.873,"end":201.753,"text":"instruction for learning concepts."},{"start":202.353,"end":205.353,"text":"A mix with direct instruction may often be"},{"start":205.353,"end":205.633,"text":"best."},{"start":206.213,"end":209.313,"text":"Sweller's team pushed back, but saw common"},{"start":209.313,"end":211.313,"text":"ground on explicit instruction."},{"start":211.793,"end":215.893,"text":"Still open: when and how to combine them."},{"start":216.633,"end":218.113,"text":"Reading a guidance study?"},{"start":218.453,"end":220.033,"text":"Ask three things."},{"start":220.393,"end":222.193,"text":"What was it compared with?"},{"start":222.513,"end":225.293,"text":"One change, or a whole program?"},{"start":225.713,"end":227.293,"text":"Who were the learners?"},{"start":227.853,"end":229.713,"text":"Beginners, or experts?"},{"start":230.093,"end":232.993,"text":"And what did they measure, and when?"},{"start":233.833,"end":234.673,"text":"So where are we?"},{"start":234.673,"end":237.313,"text":"Kirschner's team and both scaffolding"},{"start":237.313,"end":240.533,"text":"teams agree pure discovery is a poor bet"},{"start":240.533,"end":241.153,"text":"for beginners."},{"start":241.533,"end":244.473,"text":"What counts as guidance is about words."},{"start":244.993,"end":247.693,"text":"Which outcomes matter is about goals."},{"start":248.093,"end":250.913,"text":"And how to mix the two is still open."},{"start":251.533,"end":252.533,"text":"One last question."},{"start":252.913,"end":255.473,"text":"Think of a lesson you've taught or taken."},{"start":255.853,"end":258.673,"text":"Which parts were guidance, which were"},{"start":258.673,"end":260.753,"text":"discovery, and who decided?"}]},"cscl-cognitive-vs-situative":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":3.14,"text":"Some researchers say what you learn sticks"},{"start":3.14,"end":4.54,"text":"to where you learned it."},{"start":4.84,"end":7.2,"text":"That's called situated learning."},{"start":7.7,"end":10.3,"text":"In the nineties, three cognitive"},{"start":10.3,"end":11.7,"text":"scientists pushed back."},{"start":12.52,"end":15.5,"text":"Greeno's reply said they'd answered the"},{"start":15.5,"end":16.36,"text":"wrong questions."},{"start":17.267,"end":19.867,"text":"They picked out four claims tied to"},{"start":19.867,"end":20.827,"text":"situated learning."},{"start":21.527,"end":24.427,"text":"One says knowledge doesn't carry over to"},{"start":24.427,"end":25.047,"text":"new tasks."},{"start":25.247,"end":26.527,"text":"That's called transfer."},{"start":27.027,"end":30.067,"text":"Another says abstract training is of"},{"start":30.067,"end":30.567,"text":"little use."},{"start":31.267,"end":33.947,"text":"Each claim, they said, goes too far."},{"start":34.727,"end":36.767,"text":"But they agreed with part of it."},{"start":36.867,"end":39.827,"text":"You can't fully describe what someone can"},{"start":39.827,"end":41.607,"text":"do apart from the situation."},{"start":42.047,"end":44.627,"text":"Their summary splits the difference."},{"start":45.147,"end":48.547,"text":"Thinking is partly tied to context, and"},{"start":48.547,"end":49.487,"text":"partly not."},{"start":50.333,"end":52.833,"text":"Greeno replied that those weren't really"},{"start":52.833,"end":54.473,"text":"situated learning's claims."},{"start":55.033,"end":58.153,"text":"The real split, he said, is where each"},{"start":58.153,"end":59.013,"text":"side starts."},{"start":60.053,"end":62.553,"text":"The cognitive side starts from one"},{"start":62.553,"end":63.533,"text":"person's mind."},{"start":64.113,"end":67.173,"text":"The situative side starts from people and"},{"start":67.173,"end":68.313,"text":"tools interacting."},{"start":68.813,"end":72.313,"text":"The other side's evidence, he said, fits"},{"start":72.313,"end":73.273,"text":"his view too."},{"start":73.873,"end":76.593,"text":"He still found his side more promising,"},{"start":76.593,"end":78.753,"text":"but wanted both developed."},{"start":79.7,"end":80.8,"text":"Let's make up an example."},{"start":80.8,"end":84.44,"text":"Ana is twelve, and runs her family's fruit"},{"start":84.44,"end":85.28,"text":"stall on weekends."},{"start":85.94,"end":88.3,"text":"She makes change fast and right."},{"start":88.68,"end":91.76,"text":"Then comes Monday's worksheet: three"},{"start":91.76,"end":93.92,"text":"apples at forty five cents each."},{"start":94.3,"end":95.54,"text":"She freezes."},{"start":96.27,"end":99.67,"text":"A cognitive reading might say her skill is"},{"start":99.67,"end":101.29,"text":"tied to the stall's cues."},{"start":101.57,"end":104.55,"text":"So teach when it applies, plus the"},{"start":104.55,"end":105.41,"text":"abstract math."},{"start":106.03,"end":108.95,"text":"A situative reading might see two"},{"start":108.95,"end":111.93,"text":"different activities, and ask how class"},{"start":111.93,"end":113.13,"text":"could connect them."},{"start":113.82,"end":115.36,"text":"Does Ana know the math?"},{"start":116.2,"end":118.18,"text":"Decide before we go on."},{"start":123.07,"end":125.67,"text":"We think both sides would say she can"},{"start":125.67,"end":127.49,"text":"learn to use it in both places."},{"start":128.09,"end":131.19,"text":"Later, all four wrote that learning can"},{"start":131.19,"end":131.95,"text":"carry over."},{"start":132.57,"end":135.45,"text":"Where they split is how to describe her."},{"start":136.03,"end":138.33,"text":"Is math in her head the right description?"},{"start":139.2,"end":140.8,"text":"Anderson's team wrote back."},{"start":141.6,"end":144.14,"text":"Much of the argument, they said, is about"},{"start":144.14,"end":144.54,"text":"wording."},{"start":144.8,"end":147.54,"text":"But they admitted one real split."},{"start":148.22,"end":150.88,"text":"Do you study the group, or the individual?"},{"start":151.66,"end":154.34,"text":"They called it a clash of two methods."},{"start":155.23,"end":156.99,"text":"Then the story took a turn."},{"start":157.17,"end":161.11,"text":"All four, Greeno included, wrote one paper"},{"start":161.11,"end":161.47,"text":"together."},{"start":162.3,"end":165.27,"text":"They agreed learning can be general, and"},{"start":165.27,"end":168.67,"text":"abstract ideas can work, but sometimes"},{"start":168.67,"end":169.51,"text":"don't."},{"start":169.61,"end":172.53,"text":"And both approaches should be pursued"},{"start":172.53,"end":173.55,"text":"vigorously."},{"start":174.3,"end":176.88,"text":"One researcher, Sfard, zoomed out."},{"start":177.14,"end":179.7,"text":"She named two metaphors for learning."},{"start":180.38,"end":182.6,"text":"In one, you acquire something."},{"start":183.02,"end":185.34,"text":"In the other, you take part."},{"start":186.08,"end":189.48,"text":"Lean too hard on either, she warned, and"},{"start":189.48,"end":191.54,"text":"theory and teaching can suffer."},{"start":192.06,"end":193.86,"text":"She wasn't picking a side."},{"start":194.18,"end":198.74,"text":"For Ana, is it math she has, or math she"},{"start":198.74,"end":199.54,"text":"takes part in?"},{"start":200.2,"end":201.44,"text":"Reading a study on this?"},{"start":201.44,"end":203.22,"text":"Ask two things."},{"start":203.22,"end":206.58,"text":"First, what is the thing that learns?"},{"start":207.08,"end":210.28,"text":"A person, a group, or a whole system?"},{"start":210.28,"end":213.18,"text":"That's called the unit of analysis."},{"start":213.18,"end":216.6,"text":"Second, what do the measures assume?"},{"start":216.6,"end":219.88,"text":"Something acquired, or a way of taking"},{"start":219.88,"end":220.22,"text":"part?"},{"start":221.1,"end":221.74,"text":"To sum up."},{"start":221.78,"end":225.5,"text":"In their joint paper, all four agreed that"},{"start":225.5,"end":227.9,"text":"transfer and abstraction can work,"},{"start":227.9,"end":228.64,"text":"sometimes."},{"start":229.24,"end":231.28,"text":"Whether those were really situated"},{"start":231.28,"end":233.72,"text":"learning's claims stayed disputed."},{"start":233.86,"end":236.84,"text":"And the unit of analysis is still open."},{"start":237.28,"end":240.04,"text":"That's about starting points, not data."},{"start":240.8,"end":241.96,"text":"One last question."},{"start":242.42,"end":245.58,"text":"When you say someone learned, what are you"},{"start":245.58,"end":246.36,"text":"really looking at?"},{"start":246.88,"end":249.54,"text":"Something they have, or something they"},{"start":249.54,"end":250.22,"text":"take part in?"}]},"cscl-is-childrens-knowledge-coherent":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":3.02,"text":"Meet Theo, a made-up ten year old."},{"start":3.42,"end":5.5,"text":"Why does a thrown ball fall?"},{"start":6.02,"end":8.78,"text":"His hand's force runs out, he says."},{"start":9.2,"end":10.64,"text":"A puck on ice?"},{"start":11.48,"end":14.12,"text":"Nothing's pushing it, so it keeps going."},{"start":14.99,"end":17.11,"text":"Same kid, same afternoon."},{"start":17.29,"end":21.19,"text":"One theory in his head, or a box of loose"},{"start":21.19,"end":21.59,"text":"pieces?"},{"start":22.25,"end":25.07,"text":"Researchers have argued this for decades."},{"start":26.067,"end":29.347,"text":"Andrea diSessa says knowledge comes in"},{"start":29.347,"end":29.687,"text":"pieces."},{"start":30.227,"end":33.047,"text":"Kids carry lots of small hunches."},{"start":33.087,"end":35.227,"text":"He calls them p-prims."},{"start":35.427,"end":38.827,"text":"Each switches on in some situations, not"},{"start":38.827,"end":39.147,"text":"others."},{"start":39.407,"end":42.107,"text":"He calls the misconceptions label"},{"start":42.107,"end":42.947,"text":"misleading."},{"start":43.917,"end":46.757,"text":"His team says the theory side seems to"},{"start":46.757,"end":49.397,"text":"make kids look far tidier than they are."},{"start":50.027,"end":52.757,"text":"But kids' ideas aren't random or chaotic"},{"start":52.757,"end":54.137,"text":"either, they add."},{"start":54.867,"end":57.587,"text":"Stella Vosniadou sees it the other way."},{"start":58.327,"end":61.527,"text":"Kids build an everyday physics that mostly"},{"start":61.527,"end":62.327,"text":"hangs together."},{"start":63.027,"end":65.547,"text":"She calls it a framework theory."},{"start":66.367,"end":67.967,"text":"Theory is a modest word."},{"start":68.287,"end":72.047,"text":"She means a rough skeleton of ideas, less"},{"start":72.047,"end":74.207,"text":"tight than a scientist's theory."},{"start":74.947,"end":77.087,"text":"She doesn't say kids are always"},{"start":77.087,"end":77.647,"text":"consistent."},{"start":78.387,"end":81.547,"text":"The loose bits, she says, often come from"},{"start":81.547,"end":82.327,"text":"early teaching."},{"start":83.167,"end":84.227,"text":"Back to Theo."},{"start":84.667,"end":87.807,"text":"A book on a table has no force, he says."},{"start":88.227,"end":91.387,"text":"A rock on a hill has a bit, since it could"},{"start":91.387,"end":91.667,"text":"fall."},{"start":92.367,"end":96.167,"text":"Vosniadou's side sees one frame: objects"},{"start":96.167,"end":97.847,"text":"pick up force and lose it."},{"start":98.007,"end":98.847,"text":"The puck?"},{"start":99.107,"end":102.247,"text":"A loose spot in the frame, or school talk."},{"start":103.047,"end":106.007,"text":"diSessa's side sees a different small idea"},{"start":106.007,"end":107.367,"text":"for each situation."},{"start":108.127,"end":111.287,"text":"Both readings fit everything Theo said."},{"start":112.167,"end":114.527,"text":"In two thousand four, diSessa's team"},{"start":114.527,"end":116.287,"text":"copied a Greek force study."},{"start":116.887,"end":119.227,"text":"It had counted about nine in ten kids"},{"start":119.227,"end":119.787,"text":"consistent."},{"start":120.447,"end":123.247,"text":"The copy's scoring even leaned toward the"},{"start":123.247,"end":123.887,"text":"Greek result."},{"start":128.917,"end":132.437,"text":"Only five of thirty fully fit any meaning"},{"start":132.437,"end":133.057,"text":"of force."},{"start":133.637,"end":136.757,"text":"With a looser rule, ten of twenty one fit,"},{"start":136.757,"end":139.217,"text":"nearly all in the vaguest group."},{"start":140.033,"end":142.873,"text":"The authors admitted they don't know why."},{"start":143.673,"end":146.673,"text":"A later study in two Turkish cities found"},{"start":146.673,"end":149.173,"text":"about one in ten fully consistent."},{"start":149.493,"end":152.913,"text":"A looser rule gave fifty five percent."},{"start":153.813,"end":156.773,"text":"Astronomers and astronomy researchers took"},{"start":156.773,"end":158.493,"text":"the children's earth-shape interview."},{"start":159.253,"end":162.313,"text":"Only eighteen of forty two scored as"},{"start":162.313,"end":164.653,"text":"scientific, even at their best."},{"start":165.443,"end":167.183,"text":"Method cuts both ways."},{"start":167.183,"end":171.143,"text":"Vosniadou's team tried two ways of asking."},{"start":171.603,"end":174.403,"text":"Forced choice questions got more right"},{"start":174.403,"end":176.583,"text":"answers, but less consistency."},{"start":177.353,"end":180.183,"text":"Open questions mostly showed consistent"},{"start":180.183,"end":180.683,"text":"models."},{"start":181.493,"end":183.773,"text":"So method shapes the verdict."},{"start":184.613,"end":187.413,"text":"Setting the bar for coherent is a choice"},{"start":187.413,"end":188.433,"text":"about definitions."},{"start":189.273,"end":192.413,"text":"Who clears it is a question for data."},{"start":193.167,"end":195.107,"text":"They agree more than you'd think."},{"start":195.107,"end":198.727,"text":"Vosniadou doesn't expect one fixed idea"},{"start":198.727,"end":199.747,"text":"that works everywhere."},{"start":199.747,"end":203.287,"text":"diSessa's team says the Greek study's"},{"start":203.287,"end":204.847,"text":"meanings have merit."},{"start":205.667,"end":208.387,"text":"What's still open is where coherence comes"},{"start":208.387,"end":208.707,"text":"from."},{"start":209.287,"end":211.967,"text":"Do kids start with it, or does teaching"},{"start":211.967,"end":212.567,"text":"build it?"},{"start":213.267,"end":216.507,"text":"Our advice: ask three things of any paper"},{"start":216.507,"end":217.067,"text":"like this."},{"start":217.067,"end":220.707,"text":"What counted as consistent, and how"},{"start":220.707,"end":221.147,"text":"strictly?"},{"start":221.147,"end":224.107,"text":"How many situations did they ask about?"},{"start":224.107,"end":227.387,"text":"Open questions, or forced choice?"},{"start":228.367,"end":228.947,"text":"To sum up."},{"start":228.987,"end":232.007,"text":"Neither side thinks kids' ideas are"},{"start":232.007,"end":234.207,"text":"random, or one tidy theory."},{"start":234.787,"end":238.467,"text":"How coherent kids look depends on task and"},{"start":238.467,"end":238.887,"text":"scoring."},{"start":239.627,"end":242.767,"text":"Where coherence comes from is still open."},{"start":243.533,"end":244.453,"text":"One last question."},{"start":244.893,"end":247.513,"text":"If a student's answer changes when you"},{"start":247.513,"end":250.213,"text":"change the question, is there no theory,"},{"start":250.213,"end":252.753,"text":"or one you haven't asked about yet?"}]},"cscl-is-transfer-real":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.96,"text":"Every school bets that what you learn here"},{"start":2.96,"end":4.52,"text":"helps somewhere else."},{"start":4.82,"end":6.52,"text":"That's called transfer."},{"start":7.28,"end":9.72,"text":"In nineteen ninety three, Douglas"},{"start":9.72,"end":12.02,"text":"Detterman put the bet on trial."},{"start":12.85,"end":16.21,"text":"His title calls transfer an epiphenomenon."},{"start":16.73,"end":18.93,"text":"That's a by-product of more basic"},{"start":18.93,"end":19.47,"text":"abilities."},{"start":20.27,"end":22.15,"text":"Not that transfer never happens."},{"start":23,"end":24.68,"text":"His definition is strict."},{"start":25.5,"end":28.88,"text":"Transfer means you repeat a behavior in a"},{"start":28.88,"end":29.6,"text":"new situation."},{"start":30.57,"end":34.31,"text":"By that yardstick, most studies find no"},{"start":34.31,"end":34.89,"text":"transfer."},{"start":35.23,"end":38.93,"text":"The rest, he says, pass only by the most"},{"start":38.93,"end":40.01,"text":"generous standards."},{"start":40.43,"end":44.01,"text":"And if people get a hint, he says, it"},{"start":44.01,"end":44.81,"text":"doesn't count."},{"start":45.61,"end":47.11,"text":"His advice is blunt."},{"start":47.55,"end":49.83,"text":"If you want people to learn something,"},{"start":49.83,"end":51.11,"text":"teach it to them."},{"start":51.45,"end":54.49,"text":"But his word is rare, not never."},{"start":55.267,"end":58.327,"text":"Six years later, John Bransford and Daniel"},{"start":58.327,"end":59.167,"text":"Schwartz replied."},{"start":59.647,"end":63.027,"text":"They agreed transfer is rare, by his rule."},{"start":63.607,"end":66.047,"text":"Then they questioned the rule."},{"start":66.767,"end":70.367,"text":"Classic tests leave you alone: no books,"},{"start":70.367,"end":72.267,"text":"no help, one shot."},{"start":72.807,"end":75.667,"text":"That's called sequestered problem solving."},{"start":76.227,"end":79.987,"text":"Fine for experts, they said, but too blunt"},{"start":79.987,"end":82.387,"text":"a tool for the small steps toward"},{"start":82.387,"end":82.807,"text":"expertise."},{"start":83.907,"end":85.667,"text":"So ask a different question."},{"start":86.147,"end":88.167,"text":"Are you ready to learn the new thing"},{"start":88.167,"end":89.587,"text":"faster, or better?"},{"start":90.367,"end":92.347,"text":"Joanne Lobato pushed further."},{"start":92.787,"end":95.787,"text":"Researchers usually decide ahead what"},{"start":95.787,"end":96.667,"text":"should carry over."},{"start":97.307,"end":100.827,"text":"She asks how the learner's own past shaped"},{"start":100.827,"end":103.047,"text":"the task, right or wrong."},{"start":103.287,"end":106.787,"text":"She admits small samples limit this."},{"start":107.533,"end":110.873,"text":"Meet Sam, a made-up fifteen year old who"},{"start":110.873,"end":111.793,"text":"aced percentages."},{"start":112.553,"end":115.533,"text":"A store offers thirty percent off, then"},{"start":115.533,"end":116.593,"text":"twenty more."},{"start":116.833,"end":118.573,"text":"He guesses fifty."},{"start":118.913,"end":120.053,"text":"It's forty four."},{"start":121.093,"end":123.833,"text":"The clerk shows him one receipt, and he"},{"start":123.833,"end":125.173,"text":"nails the next item."},{"start":125.433,"end":128.793,"text":"Then he says, it's like Mom figuring the"},{"start":128.793,"end":129.013,"text":"tip."},{"start":129.693,"end":132.593,"text":"For Detterman, that's no transfer: the"},{"start":132.593,"end":135.313,"text":"first try failed, the rest had help."},{"start":135.973,"end":138.353,"text":"For Bransford and Schwartz, he learned"},{"start":138.353,"end":139.813,"text":"fast, so yes."},{"start":140.313,"end":143.073,"text":"For Lobato, his own link counts."},{"start":144.033,"end":146.513,"text":"A later study made this an experiment."},{"start":147.073,"end":149.673,"text":"Ninth graders learned statistics by"},{"start":149.673,"end":153.253,"text":"inventing methods, or by being told, then"},{"start":153.253,"end":153.773,"text":"practicing."},{"start":154.393,"end":158.073,"text":"On a test with no worked example, who did"},{"start":158.073,"end":158.473,"text":"better?"},{"start":163.443,"end":164.103,"text":"Neither, really."},{"start":164.383,"end":167.043,"text":"The authors call it the same result."},{"start":167.383,"end":170.523,"text":"The groups were small: about two students"},{"start":170.523,"end":171.403,"text":"versus one."},{"start":171.743,"end":175.103,"text":"But add a worked example to the test, and"},{"start":175.103,"end":177.843,"text":"inventors got over twice as many right."},{"start":178.7,"end":180.92,"text":"Much of this fight is about definitions."},{"start":181.48,"end":184.76,"text":"Count repeated behavior, and transfer is"},{"start":184.76,"end":185.02,"text":"rare."},{"start":185.75,"end":188.5,"text":"Count faster learning, or the learner's"},{"start":188.5,"end":191.42,"text":"own links, and it shows up much more"},{"start":191.42,"end":191.8,"text":"often."},{"start":192.47,"end":194.01,"text":"Some of it is about evidence."},{"start":194.25,"end":196.95,"text":"The test format changed the verdict."},{"start":197.15,"end":200.57,"text":"And big reviews of brain training, like"},{"start":200.57,"end":204.63,"text":"chess or memory drills, find no gains on"},{"start":204.63,"end":205.67,"text":"untrained skills."},{"start":206.21,"end":209.75,"text":"That holds once placebo and biased"},{"start":209.75,"end":211.41,"text":"publishing are controlled for."},{"start":211.99,"end":215.13,"text":"That's training programs, not school"},{"start":215.13,"end":215.51,"text":"learning."},{"start":216.28,"end":220.16,"text":"Both sides, Lobato notes, agree on one"},{"start":220.16,"end":220.5,"text":"thing."},{"start":221.26,"end":223.38,"text":"Transfer depends on similarity."},{"start":224.1,"end":227.28,"text":"The fight is over who decides what's"},{"start":227.28,"end":227.56,"text":"similar."},{"start":228.333,"end":231.273,"text":"Our advice for any paper that says no"},{"start":231.273,"end":231.733,"text":"transfer."},{"start":232.093,"end":234.573,"text":"Could anyone learn during the test?"},{"start":234.733,"end":237.553,"text":"Who decided what counted as similar?"},{"start":237.793,"end":240.013,"text":"Which definition was used?"},{"start":240.867,"end":241.667,"text":"To sum up."},{"start":241.707,"end":245.207,"text":"By the strict yardstick, transfer is rare,"},{"start":245.207,"end":247.247,"text":"and nobody here disputes that."},{"start":247.907,"end":251.107,"text":"Let people learn during the test, and a"},{"start":251.107,"end":252.267,"text":"difference can show up."},{"start":252.687,"end":255.127,"text":"Much of the fight is about definitions."},{"start":256.167,"end":256.987,"text":"One last question."},{"start":257.147,"end":260.747,"text":"If a test shows no transfer, what would"},{"start":260.747,"end":263.067,"text":"you change to be sure nothing carried"},{"start":263.067,"end":263.427,"text":"over?"}]},"cscl-design-based-research-answer-to-what":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.682,"text":"Imagine a research team improving a"},{"start":2.682,"end":4.545,"text":"classroom app for a year."},{"start":4.992,"end":7.824,"text":"They tweak, test, and tweak again."},{"start":8.271,"end":9.24,"text":"Scores go up."},{"start":9.687,"end":13.04,"text":"Is that science, or just a well documented"},{"start":13.04,"end":14.083,"text":"success story?"},{"start":16.08,"end":18.937,"text":"Two journals ran special issues on this."},{"start":19.365,"end":22.293,"text":"Some hard questions came from inside the"},{"start":22.293,"end":22.722,"text":"field."},{"start":23.93,"end":27.816,"text":"The idea: improve a real classroom design"},{"start":27.816,"end":30.628,"text":"in cycles, while testing theory."},{"start":31.124,"end":34.514,"text":"That's design-based research, or DBR."},{"start":35.011,"end":38.566,"text":"Backers said it helps us understand how,"},{"start":38.566,"end":41.874,"text":"when, and why new teaching ideas work."},{"start":43.9,"end":45.8,"text":"Their big reason is context."},{"start":46.207,"end":49.396,"text":"What happens in class, they wrote, depends"},{"start":49.396,"end":50.753,"text":"on where you try it."},{"start":51.72,"end":54.578,"text":"Randomized trials aren't necessarily the"},{"start":54.578,"end":56.111,"text":"end goal, they said."},{"start":56.53,"end":58.342,"text":"But the two can be linked."},{"start":59.96,"end":63.253,"text":"Richard Shavelson and colleagues asked:"},{"start":63.253,"end":66.107,"text":"can these studies back up their claims?"},{"start":66.546,"end":68.96,"text":"That backing is called a warrant."},{"start":69.4,"end":72.619,"text":"With so many moving parts, that's hard,"},{"start":72.619,"end":73.351,"text":"they said."},{"start":74.3,"end":76.413,"text":"And a good story isn't proof."},{"start":76.85,"end":80.056,"text":"A story's form doesn't make it true, they"},{"start":80.056,"end":80.493,"text":"wrote."},{"start":81.567,"end":84.221,"text":"Chris Dede wrote a commentary with our"},{"start":84.221,"end":85.243,"text":"title question."},{"start":85.651,"end":88.033,"text":"We only have others' reports of it."},{"start":88.442,"end":91.233,"text":"What standards does the method answer to?"},{"start":91.641,"end":94.568,"text":"When would you stop, or drop, a design?"},{"start":95.617,"end":98.837,"text":"Eamonn Kelly asked if DBR has a clear"},{"start":98.837,"end":101.252,"text":"logic linking methods to data."},{"start":101.735,"end":104.794,"text":"He called it an argumentative grammar."},{"start":105.933,"end":106.5,"text":"Take Ms."},{"start":106.925,"end":109.546,"text":"Ortiz's writing class, made up for"},{"start":109.546,"end":110.184,"text":"teaching."},{"start":110.609,"end":113.584,"text":"In cycle two, the team added a feedback"},{"start":113.584,"end":114.08,"text":"rubric."},{"start":114.505,"end":117.48,"text":"She also started modelling feedback aloud."},{"start":117.905,"end":120.738,"text":"Scores rose from two point one to three."},{"start":122.173,"end":125.052,"text":"The design team sees tool, teacher and"},{"start":125.052,"end":126.808,"text":"setting working together."},{"start":127.229,"end":130.178,"text":"A critic sees two changes at once, plus"},{"start":130.178,"end":131.442,"text":"kids a year older."},{"start":132.433,"end":135.635,"text":"So can the team say the rubric caused the"},{"start":135.635,"end":136.016,"text":"gain?"},{"start":141.313,"end":144.059,"text":"Not from these data alone, and the"},{"start":144.059,"end":146.211,"text":"method's backers would agree."},{"start":146.656,"end":149.846,"text":"Their own manifesto says cause can be hard"},{"start":149.846,"end":150.737,"text":"to untangle."},{"start":151.182,"end":154.373,"text":"It warns DBR should not become an excuse"},{"start":154.373,"end":155.708,"text":"for anything goes."},{"start":156.93,"end":158.928,"text":"Both sides wanted standards."},{"start":159.356,"end":162.424,"text":"Insiders asked the field to take charge of"},{"start":162.424,"end":163.423,"text":"creating them."},{"start":163.851,"end":166.634,"text":"Dede later praised a growing number of"},{"start":166.634,"end":168.632,"text":"high quality design studies."},{"start":170.54,"end":173.828,"text":"Later, a review of forty seven of the most"},{"start":173.828,"end":176.751,"text":"cited papers found limited evidence for"},{"start":176.751,"end":179.82,"text":"guarded optimism that the method delivers."},{"start":180.258,"end":183.254,"text":"A reply said you need full papers, not"},{"start":183.254,"end":184.862,"text":"abstracts, to judge."},{"start":185.95,"end":188.905,"text":"Sandoval offered simple diagrams called"},{"start":188.905,"end":190.087,"text":"conjecture maps."},{"start":190.53,"end":193.485,"text":"They cover part of what Kelly asked for."},{"start":193.928,"end":197.178,"text":"But no grammar alone guarantees rigor, he"},{"start":197.178,"end":197.695,"text":"warned."},{"start":198.139,"end":201.315,"text":"Twenty years on, a review still found no"},{"start":201.315,"end":203.827,"text":"shared way to argue from the data."},{"start":204.9,"end":207.506,"text":"So what counts as a backed-up claim is"},{"start":207.506,"end":209.177,"text":"partly about definitions."},{"start":209.578,"end":212.452,"text":"Whether the method delivered is a question"},{"start":212.452,"end":214.724,"text":"for data, still weakly measured."},{"start":215.125,"end":216.929,"text":"When to stop is still open."},{"start":218,"end":220.375,"text":"Our advice: ask three things."},{"start":220.794,"end":223.588,"text":"What was the question before the design?"},{"start":224.007,"end":226.801,"text":"What changed between cycles, and were"},{"start":226.801,"end":228.687,"text":"other explanations checked?"},{"start":229.106,"end":231.551,"text":"What would have counted as failure?"},{"start":232.467,"end":233.218,"text":"To sum up."},{"start":233.668,"end":237.198,"text":"Critics asked for warrants, a grammar, and"},{"start":237.198,"end":238.625,"text":"rules for stopping."},{"start":239.075,"end":242.079,"text":"Supporters agreed standards were needed."},{"start":242.53,"end":245.684,"text":"A recent review still finds no shared way"},{"start":245.684,"end":247.636,"text":"to argue from design data."},{"start":249.037,"end":250.251,"text":"One last question."},{"start":250.656,"end":253.288,"text":"What would a design study need to show"},{"start":253.288,"end":256.19,"text":"before you'd believe the design, not the"},{"start":256.19,"end":258.282,"text":"context, made the difference?"}]},"cscl-will-media-influence-learning":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.7,"text":"Richard Clark once compared media to a"},{"start":2.7,"end":3.42,"text":"grocery truck."},{"start":4,"end":6.74,"text":"The truck brings food, but doesn't change"},{"start":6.74,"end":7.34,"text":"your nutrition."},{"start":8.02,"end":10.56,"text":"Robert Kozma answered in ninety one."},{"start":11.34,"end":14.82,"text":"By ninety four, he was asking: will media"},{"start":14.82,"end":16,"text":"influence learning?"},{"start":16.8,"end":19.7,"text":"Clark said media studies mixed in two"},{"start":19.7,"end":20.52,"text":"other things."},{"start":21.1,"end":23.52,"text":"One was the teaching method: what's"},{"start":23.52,"end":24.48,"text":"taught, and how."},{"start":24.76,"end":28.2,"text":"The other was novelty, the buzz of"},{"start":28.2,"end":30.18,"text":"something new, which fades."},{"start":31.12,"end":33.86,"text":"He cited one analysis that pooled computer"},{"start":33.86,"end":34.66,"text":"course studies."},{"start":35.35,"end":38.08,"text":"In studies of four weeks or less, the"},{"start":38.08,"end":40.64,"text":"effect was over half a standard deviation."},{"start":41.69,"end":44.66,"text":"At five to eight weeks, it was about three"},{"start":44.66,"end":45.2,"text":"tenths."},{"start":45.6,"end":48.36,"text":"Longer studies, about two tenths."},{"start":48.94,"end":52.44,"text":"Media still matter for cost and reach, he"},{"start":52.44,"end":52.7,"text":"said."},{"start":53.2,"end":54.44,"text":"They don't cause learning."},{"start":55.02,"end":57.76,"text":"He even allowed that zooming might help"},{"start":57.76,"end":60.1,"text":"learners who lack the skill being shown."},{"start":60.9,"end":62.4,"text":"Kozma changed the question."},{"start":62.8,"end":66.52,"text":"Not do media influence learning, but will"},{"start":66.52,"end":66.74,"text":"they?"},{"start":66.98,"end":70.38,"text":"He called the field a design science, one"},{"start":70.38,"end":71.52,"text":"that builds things."},{"start":71.92,"end":75.64,"text":"He added: if there's no link yet, maybe we"},{"start":75.64,"end":76.34,"text":"haven't made one."},{"start":77.06,"end":80.18,"text":"Splitting medium from method, he wrote, is"},{"start":80.18,"end":82.34,"text":"unnecessary and undesirable."},{"start":82.84,"end":86.14,"text":"A medium can show motion, or let you drag"},{"start":86.14,"end":86.54,"text":"a model."},{"start":87,"end":90.44,"text":"In good designs, those capabilities make"},{"start":90.44,"end":91.86,"text":"the method possible."},{"start":92.54,"end":95.14,"text":"Take ThinkerTools, a computer physics"},{"start":95.14,"end":95.6,"text":"world."},{"start":96.2,"end":99.28,"text":"Its students beat high schoolers about six"},{"start":99.28,"end":100,"text":"years older."},{"start":100.8,"end":102.34,"text":"Now, a made up example."},{"start":102.98,"end":105.78,"text":"A district swaps paper fraction worksheets"},{"start":105.78,"end":106.94,"text":"for a tablet app."},{"start":107.58,"end":109.54,"text":"Scores rise eight points."},{"start":109.7,"end":112.2,"text":"But four things changed at once."},{"start":112.9,"end":113.72,"text":"Instant feedback."},{"start":113.98,"end":115.42,"text":"Twice the practice."},{"start":115.68,"end":117.88,"text":"A number line you can stretch."},{"start":118.02,"end":119.92,"text":"And shiny new devices."},{"start":120.92,"end":122.88,"text":"Did the tablets cause the gain?"},{"start":123.44,"end":124.96,"text":"Pause and decide."},{"start":130.07,"end":132.47,"text":"From this study, we can't tell."},{"start":132.79,"end":135.29,"text":"Clark would want a paper version with the"},{"start":135.29,"end":136.73,"text":"same feedback and practice."},{"start":136.73,"end":140.35,"text":"Kozma would ask which design used the"},{"start":140.35,"end":141.31,"text":"number line well."},{"start":142.18,"end":145.22,"text":"Sort the four changes as each side might."},{"start":145.48,"end":147.92,"text":"Even the sorting is part of the fight."},{"start":148.7,"end":150.42,"text":"Clark replied with a challenge."},{"start":151,"end":153.72,"text":"Find a medium that can't be swapped for"},{"start":153.72,"end":155.32,"text":"another with similar results."},{"start":156.08,"end":159.22,"text":"If you can swap it, the cause is something"},{"start":159.22,"end":160.18,"text":"both share."},{"start":160.86,"end":163.82,"text":"Studies like ThinkerTools, he said, hadn't"},{"start":163.82,"end":165.24,"text":"kept the method the same."},{"start":165.96,"end":166.76,"text":"Where do they agree?"},{"start":166.76,"end":170.3,"text":"Kozma himself wrote that no link had been"},{"start":170.3,"end":170.84,"text":"shown yet."},{"start":171.14,"end":174.28,"text":"They still disagree about what a medium"},{"start":174.28,"end":177.7,"text":"is, and whether it can be split from"},{"start":177.7,"end":178.04,"text":"method."},{"start":178.833,"end":181.773,"text":"Later reviews pooled hundreds of studies,"},{"start":181.773,"end":183.573,"text":"then over a thousand."},{"start":184.453,"end":187.013,"text":"Distance versus classroom teaching came"},{"start":187.013,"end":189.633,"text":"out close to zero, with wide swings."},{"start":190.533,"end":193.373,"text":"Forty years of technology studies put"},{"start":193.373,"end":196.573,"text":"classes with technology ahead, by about a"},{"start":196.573,"end":197.973,"text":"third of a standard deviation."},{"start":198.713,"end":201.213,"text":"We think each side can claim these"},{"start":201.213,"end":204.153,"text":"numbers, since such comparisons usually"},{"start":204.153,"end":205.593,"text":"change the method too."},{"start":206.333,"end":210.393,"text":"Say a study finds an app, VR, or an AI"},{"start":210.393,"end":211.833,"text":"tutor improved learning."},{"start":212.173,"end":213.833,"text":"Ask what else changed."},{"start":214.333,"end":215.073,"text":"The method?"},{"start":215.173,"end":216.413,"text":"The amount of practice?"},{"start":216.793,"end":217.753,"text":"The novelty?"},{"start":218.293,"end":219.373,"text":"The time on task?"},{"start":220.267,"end":221.407,"text":"So, to sum up."},{"start":221.507,"end":224.667,"text":"They mostly agree the old studies didn't"},{"start":224.667,"end":226.187,"text":"show media causing learning."},{"start":226.817,"end":229.427,"text":"They disagree about what a medium is."},{"start":229.627,"end":232.387,"text":"And whether any medium could ever be"},{"start":232.387,"end":234.407,"text":"irreplaceable is still open."},{"start":235.267,"end":236.027,"text":"A last question."},{"start":236.547,"end":239.347,"text":"Think of a recent claim that technology"},{"start":239.347,"end":240.467,"text":"improved learning."},{"start":241.177,"end":243.627,"text":"What changed besides the technology?"},{"start":244.087,"end":246.587,"text":"Could another tool have done the same?"}]},"cscl-who-learns-when-a-group-learns":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":3,"text":"Three made-up students solve a dice puzzle"},{"start":3,"end":4.26,"text":"together in a chat."},{"start":4.6,"end":7.78,"text":"The next day, only one of them does well"},{"start":7.78,"end":9.14,"text":"on a new one alone."},{"start":9.68,"end":10.92,"text":"So who learned?"},{"start":11.22,"end":13.56,"text":"The group, or one person?"},{"start":14.5,"end":17.12,"text":"The question is whose learning you"},{"start":17.12,"end":17.48,"text":"measure."},{"start":17.84,"end":20.44,"text":"That's called the unit of analysis."},{"start":20.88,"end":23.22,"text":"It isn't one famous exchange."},{"start":23.62,"end":27.48,"text":"The split shows up in how papers measure."},{"start":28.333,"end":31.393,"text":"On one side is a researcher named Gerry"},{"start":31.393,"end":31.893,"text":"Stahl."},{"start":32.573,"end":36.253,"text":"He says that in CSCL, the group, more"},{"start":36.253,"end":38.713,"text":"than the single student, is what learns"},{"start":38.713,"end":39.593,"text":"and thinks."},{"start":40.453,"end":41.153,"text":"But he's careful."},{"start":41.333,"end":44.513,"text":"He says it's a question of method, not of"},{"start":44.513,"end":45.073,"text":"what exists."},{"start":45.413,"end":48.153,"text":"He isn't claiming that a group mind"},{"start":48.153,"end":48.733,"text":"exists."},{"start":49.703,"end":51.903,"text":"Your own thoughts stay hidden in your"},{"start":51.903,"end":52.203,"text":"head."},{"start":52.543,"end":55.283,"text":"A group's thinking has to be out in the"},{"start":55.283,"end":58.463,"text":"open, in the chat and on the whiteboard."},{"start":59.167,"end":61.087,"text":"On the other side is the cognitive"},{"start":61.087,"end":61.527,"text":"tradition."},{"start":62.027,"end":65.447,"text":"Here, members share a hard task across"},{"start":65.447,"end":66.687,"text":"their working memories."},{"start":67.287,"end":69.947,"text":"That's called collective working memory."},{"start":70.667,"end":73.407,"text":"They link it closely to group cognition."},{"start":74.357,"end":77.077,"text":"But the focus stays on what each member"},{"start":77.077,"end":77.537,"text":"learns."},{"start":78.127,"end":81.837,"text":"On complex tasks, the group is a scaffold"},{"start":81.837,"end":84.877,"text":"for each person, like a worked example."},{"start":85.767,"end":86.787,"text":"Back to our chat."},{"start":86.787,"end":89.927,"text":"Ana draws a tree that's half wrong."},{"start":90.427,"end":93.207,"text":"Chloe asks why there are only six"},{"start":93.207,"end":93.747,"text":"branches."},{"start":94.227,"end":96.667,"text":"Then Ben types the key move."},{"start":97.247,"end":100.467,"text":"It's thirty-six, because order matters."},{"start":101.497,"end":103.077,"text":"The group's answer is right."},{"start":103.757,"end":106.577,"text":"But the next day, working alone, Ana"},{"start":106.577,"end":108.357,"text":"scores nine out of ten."},{"start":108.837,"end":112.317,"text":"Ben gets five, and Chloe six."},{"start":112.837,"end":114.377,"text":"Did this group learn?"},{"start":115.117,"end":116.777,"text":"Decide before we go on."},{"start":121.667,"end":124.187,"text":"Both sides are right, about different"},{"start":124.187,"end":124.647,"text":"things."},{"start":124.807,"end":128.347,"text":"In Stahl's view, the group built an answer"},{"start":128.347,"end":129.967,"text":"none of them had alone."},{"start":130.677,"end":133.747,"text":"The uneven scores tell you about each"},{"start":133.747,"end":134.207,"text":"person."},{"start":134.987,"end":137.347,"text":"So the data aren't really in dispute."},{"start":137.607,"end":141.127,"text":"The fight is over which of those counts as"},{"start":141.127,"end":141.547,"text":"learning."},{"start":141.807,"end":144.927,"text":"And no experiment can settle a definition."},{"start":145.833,"end":148.813,"text":"A review by authors from both camps says"},{"start":148.813,"end":151.273,"text":"the fight is no longer about individual"},{"start":151.273,"end":152.453,"text":"versus group."},{"start":153.033,"end":156.513,"text":"The confusion now is how a person and the"},{"start":156.513,"end":158.293,"text":"social world fit together."},{"start":159.113,"end":161.233,"text":"Both sides keep the individual."},{"start":161.533,"end":165.093,"text":"And both now ask for more than one level"},{"start":165.093,"end":165.633,"text":"of analysis."},{"start":166.723,"end":168.323,"text":"One thing is settled."},{"start":168.903,"end":171.563,"text":"Students in the same group affect each"},{"start":171.563,"end":174.323,"text":"other, so their scores aren't independent."},{"start":174.763,"end":178.463,"text":"The analysis has to build that in, for"},{"start":178.463,"end":180.303,"text":"example with multilevel models."},{"start":181.203,"end":183.423,"text":"What's still open is which level comes"},{"start":183.423,"end":183.823,"text":"first."},{"start":184.203,"end":187.823,"text":"The main CSCL journal's editors list"},{"start":187.823,"end":190.543,"text":"the right units of analysis as an open"},{"start":190.543,"end":190.903,"text":"question."},{"start":191.8,"end":195,"text":"So when you read a paper, ask three"},{"start":195,"end":195.48,"text":"things."},{"start":196.12,"end":200.12,"text":"Is the claim about a person, a group, or a"},{"start":200.12,"end":200.38,"text":"community?"},{"start":201.24,"end":203.36,"text":"Does the evidence come from that same"},{"start":203.36,"end":203.76,"text":"level?"},{"start":204.06,"end":207.04,"text":"And if students worked in groups, did the"},{"start":207.04,"end":208.5,"text":"analysis account for it?"},{"start":209.18,"end":212.36,"text":"Say a paper claims a group learned, but"},{"start":212.36,"end":214.3,"text":"only shows averaged test scores."},{"start":214.82,"end":216.08,"text":"That's a mismatch."},{"start":216.5,"end":217.74,"text":"So is the reverse."},{"start":218.633,"end":221.073,"text":"This card sums up the debate."},{"start":222.6,"end":223.66,"text":"One last question."},{"start":224.28,"end":226.84,"text":"Think of a group project you studied or"},{"start":226.84,"end":227.1,"text":"taught."},{"start":227.62,"end":230.62,"text":"What would you have to record to show the"},{"start":230.62,"end":233.46,"text":"group learned, not just its members?"}]},"cscl-collaborative-cognitive-load":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":3.2,"text":"You juggle new ideas in a small mental"},{"start":3.2,"end":3.64,"text":"space."},{"start":4.32,"end":6,"text":"That's working memory."},{"start":6.7,"end":9.58,"text":"Do three people together get a bigger one?"},{"start":10.26,"end":12.9,"text":"Collaborative cognitive load theory bets"},{"start":12.9,"end":13.46,"text":"yes."},{"start":13.94,"end":17.8,"text":"It also asks when a teacher shouldn't use"},{"start":17.8,"end":18.44,"text":"group work."},{"start":19.233,"end":21.333,"text":"Nobody wrote one famous rebuttal."},{"start":21.353,"end":23.933,"text":"The pushback comes from three places."},{"start":25.533,"end":28.013,"text":"Paul Kirschner, John Sweller and"},{"start":28.013,"end":30.833,"text":"colleagues turned about ten years of work"},{"start":30.833,"end":32.713,"text":"into a theory of groups."},{"start":33.333,"end":36.433,"text":"On a complex task, members spread the"},{"start":36.433,"end":38.733,"text":"pieces across their working memories."},{"start":39.633,"end":41.573,"text":"But coordinating takes effort."},{"start":42.193,"end":44.693,"text":"They call that transaction costs."},{"start":45.553,"end":48.693,"text":"Those costs can cancel out the gain."},{"start":49.493,"end":52.993,"text":"Group work pays off only when the task is"},{"start":52.993,"end":53.933,"text":"complex enough."},{"start":54.573,"end":57.833,"text":"The paper ends bluntly: the choice could"},{"start":57.833,"end":60.453,"text":"very well be to skip group work."},{"start":61.2,"end":64.1,"text":"First, the journal's own editors pushed"},{"start":64.1,"end":64.48,"text":"back."},{"start":64.8,"end":67.38,"text":"They said it treats learning as pure"},{"start":67.38,"end":68.54,"text":"information processing."},{"start":68.9,"end":72.12,"text":"They saw no clear fit with the main CSC"},{"start":72.12,"end":74.1,"text":"L theories, which see learning"},{"start":74.1,"end":74.58,"text":"differently."},{"start":75.4,"end":78.52,"text":"Still, they published it, saying a mix of"},{"start":78.52,"end":80.38,"text":"theories and methods is essential."},{"start":81.21,"end":83.73,"text":"Second, the group-cognition camp."},{"start":84.35,"end":87.01,"text":"Even before this theory, they saw the"},{"start":87.01,"end":90.67,"text":"group's talk as the learning itself, not a"},{"start":90.67,"end":91.53,"text":"cost on top."},{"start":92.26,"end":95.92,"text":"Third, experiments, some co-written by"},{"start":95.92,"end":96.56,"text":"Sweller himself."},{"start":96.84,"end":100.22,"text":"With worked examples, or when students"},{"start":100.22,"end":103.52,"text":"already knew enough, individuals beat"},{"start":103.52,"end":103.92,"text":"groups."},{"start":104.833,"end":106.673,"text":"Picture a made-up French class."},{"start":107.353,"end":110.693,"text":"Task A is simple: memorize fifty word"},{"start":110.693,"end":110.993,"text":"pairs."},{"start":111.853,"end":115.473,"text":"Task B is complex: write sentences with"},{"start":115.473,"end":115.693,"text":"them."},{"start":116.353,"end":119.353,"text":"In one group's Task B chat, about a third"},{"start":119.353,"end":120.733,"text":"is just who's typing."},{"start":121.093,"end":124.933,"text":"The rest is a fight over le chat versus la"},{"start":124.933,"end":125.173,"text":"chat."},{"start":126.053,"end":127.513,"text":"Overhead, or learning?"},{"start":127.893,"end":129.773,"text":"Pick one before we go on."},{"start":134.633,"end":138.133,"text":"By the theory's own rules, it depends what"},{"start":138.133,"end":138.933,"text":"the talk does."},{"start":139.633,"end":142.113,"text":"Fixing someone's understanding is"},{"start":142.113,"end":142.493,"text":"productive."},{"start":143.213,"end":145.773,"text":"Spreading errors is wasted load."},{"start":146.373,"end":149.873,"text":"The group-cognition side says the fight is"},{"start":149.873,"end":150.353,"text":"the learning."},{"start":150.353,"end":154.093,"text":"Who's typing is pure overhead, in the"},{"start":154.093,"end":154.733,"text":"theory's terms."},{"start":155.563,"end":157.603,"text":"So the data aren't the problem."},{"start":157.743,"end":161.303,"text":"The split is whether cost is even the"},{"start":161.303,"end":162.663,"text":"right word for talk."},{"start":163.533,"end":166.313,"text":"On average, group work in computer-based"},{"start":166.313,"end":167.433,"text":"settings helps."},{"start":168.213,"end":170.493,"text":"One review pooled four hundred twenty-five"},{"start":170.493,"end":171.073,"text":"studies."},{"start":171.833,"end":174.793,"text":"In it, the effect on knowledge gains was"},{"start":174.793,"end":177.733,"text":"about zero point four standard deviations."},{"start":178.373,"end":181.933,"text":"But that's an average, not a test of the"},{"start":181.933,"end":182.653,"text":"theory's conditions."},{"start":183.613,"end":186.433,"text":"An early experiment backed the complexity"},{"start":186.433,"end":186.993,"text":"prediction."},{"start":187.853,"end":189.713,"text":"Now it looks shakier."},{"start":190.173,"end":193.733,"text":"A recent online study found partly the"},{"start":193.733,"end":194.633,"text":"opposite pattern."},{"start":195.193,"end":198.653,"text":"But its hard tasks didn't feel very hard,"},{"start":198.653,"end":201.653,"text":"and it tested fewer people than planned."},{"start":202.513,"end":205.873,"text":"Both sides agree group work isn't"},{"start":205.873,"end":206.813,"text":"automatically good."},{"start":207.213,"end":211.273,"text":"And how a group works matters, not just"},{"start":211.273,"end":211.853,"text":"its scores."},{"start":212.733,"end":214.373,"text":"So check three things."},{"start":215.093,"end":218.613,"text":"Was the task really complex, and how did"},{"start":218.613,"end":219.033,"text":"they check?"},{"start":219.783,"end":222.643,"text":"Was the outcome a group product, or a"},{"start":222.643,"end":224.163,"text":"later test of each person?"},{"start":224.283,"end":228.183,"text":"In one study, experienced teams led after"},{"start":228.183,"end":230.943,"text":"a day, but not after a week."},{"start":231.543,"end":234.303,"text":"And did they look at the talk itself, or"},{"start":234.303,"end":236.143,"text":"just ask for one effort rating?"},{"start":236.933,"end":239.373,"text":"This card sums up the debate."},{"start":240.9,"end":242.76,"text":"A question to take with you."},{"start":243.12,"end":245.28,"text":"Think of a group task you know."},{"start":245.72,"end":248.5,"text":"Which part of the talk was overhead, and"},{"start":248.5,"end":249.88,"text":"which was the learning?"},{"start":250.26,"end":253.12,"text":"Would both camps draw that line in the"},{"start":253.12,"end":253.74,"text":"same place?"}]},"cscl-scripts-guidance-or-straitjacket":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":1.8,"text":"This form has three boxes."},{"start":2.54,"end":4.74,"text":"It's called a collaboration script."},{"start":5.22,"end":8.32,"text":"Is it a ladder for arguing, or a cage?"},{"start":8.94,"end":11.1,"text":"Researchers in computer-supported"},{"start":11.1,"end":13.18,"text":"collaborative learning still disagree."},{"start":14.1,"end":16.46,"text":"Picture a made-up ninth grade class"},{"start":16.46,"end":19.26,"text":"debating phones at lunch online."},{"start":20.36,"end":21.9,"text":"Leo's on the debate team."},{"start":22.16,"end":26.22,"text":"Soon he types see above in the Because"},{"start":26.22,"end":26.88,"text":"box."},{"start":27.87,"end":29.87,"text":"Jun rarely speaks up."},{"start":30.11,"end":32.95,"text":"Now he writes his first counter-argument."},{"start":33.7,"end":36.14,"text":"Dillenbourg called the cage worry"},{"start":36.14,"end":37.54,"text":"over-scripting."},{"start":37.58,"end":41.04,"text":"As two later authors put it, scripts can"},{"start":41.04,"end":43.98,"text":"drain motivation and turn talk into"},{"start":43.98,"end":44.74,"text":"box-ticking."},{"start":44.88,"end":47.6,"text":"They can even block good moves."},{"start":48.38,"end":51.82,"text":"Those authors also invented a voice, the"},{"start":51.82,"end":52.64,"text":"Provocateur."},{"start":52.64,"end":55.78,"text":"It asks: when productive group talk"},{"start":55.78,"end":59.38,"text":"clashes with a class's own choices, which"},{"start":59.38,"end":60.16,"text":"matters more?"},{"start":60.967,"end":63.687,"text":"Side B comes from Fischer and colleagues."},{"start":64.507,"end":67.527,"text":"Their idea: you already carry know-how for"},{"start":67.527,"end":68.027,"text":"group work."},{"start":68.367,"end":71.767,"text":"It runs from the whole task down to single"},{"start":71.767,"end":72.207,"text":"moves."},{"start":73.097,"end":76.097,"text":"A good script aims at the highest level"},{"start":76.097,"end":79.377,"text":"you can't yet manage alone, building on"},{"start":79.377,"end":81.257,"text":"moves you already have."},{"start":82.047,"end":85.047,"text":"To them, over-scripting means more than"},{"start":85.047,"end":85.847,"text":"too much script."},{"start":86.327,"end":89.387,"text":"It's a script aimed at the wrong level for"},{"start":89.387,"end":89.967,"text":"this learner."},{"start":90.7,"end":93.2,"text":"Side A sees Leo going through the motions."},{"start":93.72,"end":97.08,"text":"Side B sees the wrong level for him, so"},{"start":97.08,"end":99.08,"text":"raise it or fade his boxes."},{"start":99.08,"end":101.52,"text":"Jun still needs his."},{"start":102.4,"end":104.76,"text":"A third researcher, Tchounikine, would"},{"start":104.76,"end":108.48,"text":"call see above Leo's appropriation of the"},{"start":108.48,"end":108.84,"text":"script."},{"start":109.16,"end":111.52,"text":"That means his own take on it."},{"start":111.78,"end":115.78,"text":"On this view, it's a clue to how Leo read"},{"start":115.78,"end":116.24,"text":"the task."},{"start":117.133,"end":119.933,"text":"Week five: the teacher takes the boxes"},{"start":119.933,"end":120.213,"text":"away."},{"start":120.453,"end":122.973,"text":"Will Jun keep writing counter-arguments?"},{"start":128.033,"end":130.973,"text":"Probably not, if the boxes just vanish."},{"start":131.683,"end":134.693,"text":"In one lab study with university students,"},{"start":134.693,"end":137.153,"text":"fading alone wasn't enough."},{"start":138.163,"end":140.553,"text":"Fading plus a partner checking the steps"},{"start":140.553,"end":141.733,"text":"worked best."},{"start":142.6,"end":145.48,"text":"One review pooled two dozen studies."},{"start":146.28,"end":149.08,"text":"Scripts gave a small gain in subject"},{"start":149.08,"end":152.04,"text":"knowledge, and a much bigger one in"},{"start":152.04,"end":155.6,"text":"collaboration skills, still clearly bigger"},{"start":155.6,"end":157.96,"text":"without two extreme results."},{"start":158.89,"end":162.01,"text":"It found no sign of over-scripting for"},{"start":162.01,"end":163.13,"text":"collaboration skills."},{"start":163.85,"end":166.61,"text":"But it couldn't confirm Side B's"},{"start":166.61,"end":167.99,"text":"right-level rule either."},{"start":168.65,"end":171.91,"text":"Few studies reported what learners already"},{"start":171.91,"end":172.35,"text":"knew."},{"start":173.09,"end":175.49,"text":"A second review checked self-reported"},{"start":175.49,"end":175.75,"text":"motivation."},{"start":176.54,"end":179.75,"text":"The effect was slightly positive, but the"},{"start":179.75,"end":183.17,"text":"likely range includes zero, from only nine"},{"start":183.17,"end":183.63,"text":"results."},{"start":184.46,"end":187.71,"text":"No average harm found, but not proven"},{"start":187.71,"end":188.13,"text":"harmless."},{"start":189.07,"end":192.75,"text":"Both reviews share authors with Side B's"},{"start":192.75,"end":193.11,"text":"theory."},{"start":193.57,"end":196.07,"text":"Normal, but keep it in mind."},{"start":196.8,"end":198.32,"text":"Where do the sides meet?"},{"start":198.32,"end":201.66,"text":"Dillenbourg himself, with Tchounikine,"},{"start":201.66,"end":203.18,"text":"named both risks."},{"start":203.66,"end":206.42,"text":"Too rigid spoils the back and forth."},{"start":207,"end":209.62,"text":"Too loose misses the talk you wanted."},{"start":210.32,"end":212.98,"text":"The sides also define over-scripting"},{"start":212.98,"end":216.26,"text":"differently, so one study can be read both"},{"start":216.26,"end":216.6,"text":"ways."},{"start":217.42,"end":219.62,"text":"Steering your own learning is called"},{"start":219.62,"end":220.34,"text":"agency."},{"start":221.16,"end":224.44,"text":"Is it a path to learning, or a goal in"},{"start":224.44,"end":224.72,"text":"itself?"},{"start":225.7,"end":226.98,"text":"Reading a scripts paper?"},{"start":227.5,"end":230.12,"text":"Ask which outcome did they measure?"},{"start":230.44,"end":232.66,"text":"What level does the script aim at?"},{"start":233.02,"end":236.1,"text":"Does it fade, or let learners change it?"},{"start":236.8,"end":237.5,"text":"To sum up."},{"start":237.5,"end":240.78,"text":"On average, scripts help a little with"},{"start":240.78,"end":243.34,"text":"content, and more with teamwork."},{"start":243.34,"end":247.54,"text":"Over-scripting can mean too rigid, or the"},{"start":247.54,"end":248.18,"text":"wrong level."},{"start":248.18,"end":252.06,"text":"And what agency is worth is a values call."},{"start":252.933,"end":253.813,"text":"A last question."},{"start":254.253,"end":257.033,"text":"A structure helps a quiet student speak"},{"start":257.033,"end":260.233,"text":"up, but makes a confident one go through"},{"start":260.233,"end":260.713,"text":"the motions."},{"start":261.293,"end":263.953,"text":"When would you remove it, and who should"},{"start":263.953,"end":264.253,"text":"decide?"}]},"cscl-eight-provocations-for-cscl":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.88,"text":"In twenty seventeen, a journal printed an"},{"start":2.88,"end":5.08,"text":"argument between two made-up characters."},{"start":5.8,"end":8.24,"text":"The field is computer-supported"},{"start":8.24,"end":12.02,"text":"collaborative learning, or CSCL."},{"start":12.02,"end":15.06,"text":"Who are these two, and why make them up?"},{"start":15.8,"end":18.88,"text":"Two researchers, Wise and Schwarz, wrote"},{"start":18.88,"end":19.08,"text":"it."},{"start":19.62,"end":22.14,"text":"They drew on twenty three email answers"},{"start":22.14,"end":25.14,"text":"from researchers, plus two public"},{"start":25.14,"end":25.96,"text":"conference sessions."},{"start":26.81,"end":30.13,"text":"From that came eight provocations, extreme"},{"start":30.13,"end":31.11,"text":"on purpose."},{"start":31.81,"end":33.25,"text":"Each is a dialogue."},{"start":33.75,"end":36.91,"text":"A Provocateur wants to shake the field up."},{"start":37.03,"end":40.37,"text":"A Conciliator builds on what works."},{"start":41.23,"end":43.33,"text":"Neither voice is a real person."},{"start":43.88,"end":46.95,"text":"Each blends many views, so neither stands"},{"start":46.95,"end":48.15,"text":"for one researcher."},{"start":48.78,"end":51.73,"text":"And the paper says it offers no answers."},{"start":52.6,"end":53.56,"text":"These are the eight."},{"start":54.16,"end":58.28,"text":"Six push the field to do more, and two ask"},{"start":58.28,"end":60.3,"text":"whether it should perhaps stop."},{"start":61.23,"end":65.19,"text":"We'll test three: numbers three, six and"},{"start":65.19,"end":65.41,"text":"eight."},{"start":65.83,"end":68.93,"text":"Picture a made-up eighth grade class, Room"},{"start":68.93,"end":69.27,"text":"twelve."},{"start":69.77,"end":72.65,"text":"They use ThinkBoard, a chat with a"},{"start":72.65,"end":72.95,"text":"dashboard."},{"start":73.933,"end":76.533,"text":"The team's press release calls Room twelve"},{"start":76.533,"end":78.433,"text":"a thriving learning community."},{"start":79.093,"end":82.873,"text":"Provocation three asks: was that shown, or"},{"start":82.873,"end":83.773,"text":"just assumed?"},{"start":84.413,"end":86.973,"text":"It says collaboration should be checked,"},{"start":86.973,"end":88.473,"text":"not taken on faith."},{"start":89.283,"end":90.943,"text":"Room twelve shares a culture."},{"start":91.083,"end":94.063,"text":"But nothing carries over to next year's"},{"start":94.063,"end":94.303,"text":"class."},{"start":95.023,"end":97.583,"text":"The Provocateur would call that community"},{"start":97.583,"end":100.683,"text":"pro tem: a community for now."},{"start":101.503,"end":103.263,"text":"The Conciliator pushes back."},{"start":103.783,"end":106.063,"text":"If every study first had to prove"},{"start":106.063,"end":108.923,"text":"community was there, that would be all we"},{"start":108.923,"end":109.383,"text":"ever did."},{"start":110.133,"end":113.333,"text":"Provocation six is about tools that turn"},{"start":113.333,"end":115.053,"text":"group data into feedback."},{"start":115.433,"end":117.733,"text":"They're called learning analytics."},{"start":118.113,"end":121.093,"text":"The Provocateur wants them as a top"},{"start":121.093,"end":123.153,"text":"priority, even if imperfect."},{"start":124.043,"end":127.673,"text":"So ThinkBoard tells Group B: strong groups"},{"start":127.673,"end":129.293,"text":"write longer turns than you."},{"start":129.783,"end":132.193,"text":"Will Group B now work together better?"},{"start":137.183,"end":138.003,"text":"Probably not."},{"start":138.263,"end":141.243,"text":"The Conciliator says you'd mostly just get"},{"start":141.243,"end":142.083,"text":"longer turns."},{"start":142.303,"end":145.843,"text":"Its reason: good arguing makes turns"},{"start":145.843,"end":149.583,"text":"longer, but longer turns don't make good"},{"start":149.583,"end":149.943,"text":"arguing."},{"start":150.743,"end":153.383,"text":"In a later reply, Tchounikine went"},{"start":153.383,"end":153.803,"text":"further."},{"start":154.313,"end":157.483,"text":"He wrote that self-adjusting systems clash"},{"start":157.483,"end":159.203,"text":"with setting learners free."},{"start":159.363,"end":162.843,"text":"In plain words, a system that steers"},{"start":162.843,"end":166.003,"text":"learners works against learners steering"},{"start":166.003,"end":166.403,"text":"themselves."},{"start":167.533,"end":170.613,"text":"In June the researchers leave, taking"},{"start":170.613,"end":171.853,"text":"ThinkBoard with them."},{"start":172.513,"end":175.193,"text":"Provocation eight says the field should"},{"start":175.193,"end":177.873,"text":"admit it has stopped trying to change"},{"start":177.873,"end":178.353,"text":"education."},{"start":179.363,"end":182.923,"text":"The Conciliator answers: you go too far."},{"start":183.363,"end":187.023,"text":"Later it admits the field's real impact on"},{"start":187.023,"end":189.743,"text":"teaching is very small so far."},{"start":189.863,"end":194.283,"text":"But that calls for better aim, not giving"},{"start":194.283,"end":195.743,"text":"up the field's purpose."},{"start":196.603,"end":197.923,"text":"Then, a twist."},{"start":198.243,"end":200.883,"text":"By the end, the Provocateur calls"},{"start":200.883,"end":203.483,"text":"partnership work with schools worth it."},{"start":203.663,"end":207.023,"text":"A later reply from three researchers backs"},{"start":207.023,"end":207.983,"text":"the Conciliator."},{"start":208.163,"end":211.003,"text":"For Room twelve, that would mean building"},{"start":211.003,"end":213.903,"text":"ThinkBoard with the school from day one."},{"start":214.767,"end":217.327,"text":"Of the replies we checked, only"},{"start":217.327,"end":220.567,"text":"provocation two, on scripts, got a direct"},{"start":220.567,"end":221.707,"text":"test with data."},{"start":222.307,"end":225.327,"text":"The rest live on in short position papers."},{"start":226.207,"end":227.807,"text":"Reading a paper in this field?"},{"start":228.287,"end":231.307,"text":"Ask: which provocation does it take a side"},{"start":231.307,"end":231.587,"text":"on?"},{"start":231.867,"end":234.187,"text":"And is each claim about evidence,"},{"start":234.187,"end":236.347,"text":"definitions, or values?"},{"start":237.267,"end":237.867,"text":"To sum up."},{"start":237.907,"end":240.807,"text":"Two invented voices argue eight"},{"start":240.807,"end":243.367,"text":"provocations, and nobody wins."},{"start":244.167,"end":247.667,"text":"Some fights are about evidence, some about"},{"start":247.667,"end":251.207,"text":"definitions, and some about what the field"},{"start":251.207,"end":251.727,"text":"is for."},{"start":252.567,"end":253.207,"text":"Now you try."},{"start":253.707,"end":255.547,"text":"Pick a study you read recently."},{"start":256.087,"end":258.667,"text":"Which side of which provocation does it"},{"start":258.667,"end":260.367,"text":"take, without saying so?"}]},"cscl-does-the-jigsaw-classroom-work":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":3.18,"text":"Picture four made-up kids learning how a"},{"start":3.18,"end":3.76,"text":"bike works."},{"start":4.4,"end":6.66,"text":"Each kid masters one part."},{"start":7.22,"end":8.94,"text":"That's the jigsaw classroom."},{"start":9.84,"end":13.08,"text":"Supporters report big gains, but one"},{"start":13.08,"end":15.54,"text":"careful test found almost none."},{"start":16.467,"end":19.227,"text":"First, all the brakes kids from different"},{"start":19.227,"end":20.587,"text":"groups study together."},{"start":21.147,"end":24.127,"text":"Then each kid goes home and teaches their"},{"start":24.127,"end":24.347,"text":"part."},{"start":25.167,"end":27.067,"text":"Nobody gets the whole bike alone."},{"start":27.747,"end":30.587,"text":"That's called positive interdependence."},{"start":31.207,"end":34.487,"text":"And since each kid owns a piece, in theory"},{"start":34.487,"end":35.807,"text":"nobody can hide."},{"start":36.533,"end":38.963,"text":"It started in Texas in nineteen seventy"},{"start":38.963,"end":42.993,"text":"one, in newly desegregated, tense schools."},{"start":43.593,"end":46.153,"text":"Its inventor, a psychologist named"},{"start":46.153,"end":49.033,"text":"Aronson, blamed classroom competition."},{"start":50.013,"end":52.273,"text":"So the first goals were social."},{"start":52.713,"end":55.533,"text":"The first study found higher self-esteem,"},{"start":55.533,"end":58.193,"text":"and kids liked their groupmates more."},{"start":58.773,"end":61.453,"text":"Its summary reports no test scores."},{"start":62.293,"end":65.013,"text":"Later, Aronson and a colleague said it"},{"start":65.013,"end":67.113,"text":"also lifts minority students' grades."},{"start":67.933,"end":71.373,"text":"His web memoir recalls exam gains, but"},{"start":71.373,"end":73.713,"text":"that's his account, not a checked result."},{"start":74.583,"end":77.583,"text":"One synthesis puts the gain at one point"},{"start":77.583,"end":80.483,"text":"two on a common scale, which would be"},{"start":80.483,"end":81.183,"text":"enormous."},{"start":82.3,"end":85.3,"text":"Then a French team ran a stricter test."},{"start":85.92,"end":88.513,"text":"In five experiments with about eight"},{"start":88.513,"end":91.88,"text":"hundred fifty sixth graders, chance picked"},{"start":91.88,"end":93.02,"text":"the jigsaw classes."},{"start":93.74,"end":96.71,"text":"They expected an effect of about point"},{"start":96.71,"end":97.04,"text":"four."},{"start":97.76,"end":100.14,"text":"They found an effect of about zero."},{"start":100.8,"end":104.18,"text":"In their words, there was no evidence that"},{"start":104.18,"end":106.06,"text":"jigsaw increased learning."},{"start":106.83,"end":109.55,"text":"Their tests were short-term and not"},{"start":109.55,"end":112.95,"text":"validated, and the regular classes already"},{"start":112.95,"end":114.57,"text":"had some loose group work."},{"start":115.3,"end":117.6,"text":"A recent review gathered sixty nine"},{"start":117.6,"end":118.24,"text":"studies."},{"start":118.94,"end":122.8,"text":"About six in ten found academic gains, and"},{"start":122.8,"end":124.5,"text":"social results were mixed."},{"start":125.32,"end":127.58,"text":"Gains were more common in language than"},{"start":127.58,"end":128.12,"text":"science."},{"start":129,"end":131.6,"text":"It counted studies instead of pooling"},{"start":131.6,"end":134.06,"text":"effects, which is called vote counting."},{"start":134.2,"end":137.34,"text":"That tells you how often a gain shows up,"},{"start":137.34,"end":138.36,"text":"not how big."},{"start":138.8,"end":142.16,"text":"Many screened studies were weak, and most"},{"start":142.16,"end":143.76,"text":"tested college students."},{"start":144.667,"end":147.227,"text":"Back to our class, six weeks later."},{"start":147.827,"end":150.427,"text":"Kids like their groupmates more than kids"},{"start":150.427,"end":153.467,"text":"next door do, but quiz scores are the"},{"start":153.467,"end":153.767,"text":"same."},{"start":154.487,"end":155.547,"text":"Did jigsaw work?"},{"start":156.407,"end":158.887,"text":"Decide for yourself before we go on."},{"start":163.697,"end":165.717,"text":"It depends on the goal you grade."},{"start":166.277,"end":169.437,"text":"For getting along, it looks like yes, and"},{"start":169.437,"end":170.677,"text":"for the quiz, no."},{"start":171.317,"end":173.937,"text":"Both of those can be true at once."},{"start":174.727,"end":177.767,"text":"In my reading, social goals and learning"},{"start":177.767,"end":181.447,"text":"are separate claims, and each needs its"},{"start":181.447,"end":182.307,"text":"own evidence."},{"start":183.2,"end":184.74,"text":"Which number should you trust?"},{"start":185.16,"end":188.22,"text":"The one point two rests on eleven small"},{"start":188.22,"end":189.9,"text":"studies from one country."},{"start":190.06,"end":193.78,"text":"An older review found small effects, and"},{"start":193.78,"end":196.32,"text":"the randomized trials found about zero."},{"start":197.133,"end":199.673,"text":"One reviewer found the original jigsaw"},{"start":199.673,"end":201.273,"text":"rarely raised scores."},{"start":201.613,"end":204.893,"text":"A version adding team goals and individual"},{"start":204.893,"end":208.153,"text":"quizzes did better, though he designed it"},{"start":208.153,"end":208.393,"text":"himself."},{"start":209.413,"end":212.773,"text":"Effects on getting along are mixed, and"},{"start":212.773,"end":215.553,"text":"few studies tested memory later, though"},{"start":215.553,"end":217.673,"text":"most of those found a benefit."},{"start":218.467,"end":221.267,"text":"Ask three things of any jigsaw paper."},{"start":221.897,"end":224.127,"text":"Is the outcome social, or learning?"},{"start":224.427,"end":228.007,"text":"Did the class really use expert groups and"},{"start":228.007,"end":228.567,"text":"teaching back?"},{"start":229.367,"end":232.007,"text":"And what was it compared with, in how many"},{"start":232.007,"end":232.447,"text":"students?"},{"start":232.747,"end":235.687,"text":"A zero against classes with some group"},{"start":235.687,"end":238.687,"text":"work isn't the same as a zero against"},{"start":238.687,"end":239.067,"text":"lecture."},{"start":239.933,"end":243.733,"text":"This card sums up both sides, and what"},{"start":243.733,"end":244.833,"text":"each one measured."},{"start":246.3,"end":247.4,"text":"One last question."},{"start":247.98,"end":250.98,"text":"Say jigsaw helped your students get along"},{"start":250.98,"end":252.66,"text":"but didn't raise their scores."},{"start":253.24,"end":256,"text":"Would you still give it class time, and"},{"start":256,"end":256.2,"text":"why?"}]},"cscl-when-is-hard-helpful":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.88,"text":"Two made-up siblings study for the same"},{"start":2.88,"end":3.78,"text":"geometry test."},{"start":4.66,"end":7.46,"text":"Leo rereads his notes and drills ten"},{"start":7.46,"end":8.7,"text":"triangles in a row."},{"start":9.46,"end":12.62,"text":"Mia quizzes herself on mixed problems over"},{"start":12.62,"end":13.36,"text":"three days."},{"start":14.23,"end":17.69,"text":"Leo feels ready, and Mia feels worse."},{"start":18.09,"end":21.81,"text":"So when does struggle pay off, and when"},{"start":21.81,"end":22.47,"text":"doesn't it?"},{"start":23.133,"end":26.133,"text":"One side says some kinds of hard practice"},{"start":26.133,"end":27.193,"text":"pay off later."},{"start":27.823,"end":30.513,"text":"How you do during practice is performance."},{"start":31.073,"end":34.893,"text":"What sticks for later is learning, and the"},{"start":34.893,"end":36.113,"text":"two can split."},{"start":37.003,"end":39.763,"text":"A psychologist named Robert Bjork called"},{"start":39.763,"end":41.663,"text":"these desirable difficulties."},{"start":42.553,"end":44.803,"text":"Three of them are testing yourself,"},{"start":44.803,"end":48.023,"text":"spacing sessions out, and mixing problem"},{"start":48.023,"end":48.463,"text":"types."},{"start":49.323,"end":51.923,"text":"In one study, students read a short"},{"start":51.923,"end":52.403,"text":"passage."},{"start":53.083,"end":55.643,"text":"Some reread it again and again."},{"start":56.383,"end":59.163,"text":"Others read it once, then tested"},{"start":59.163,"end":61.023,"text":"themselves three times."},{"start":61.793,"end":64.413,"text":"After five minutes, rereading won."},{"start":64.833,"end":68.853,"text":"After a week, testing won easily, though"},{"start":68.853,"end":71.413,"text":"they read the passage far fewer times."},{"start":72.283,"end":75.603,"text":"The rereaders also felt more confident."},{"start":75.843,"end":79.123,"text":"In a small math study, mixed practice"},{"start":79.123,"end":82.703,"text":"looked worse at first, but scored about"},{"start":82.703,"end":85.163,"text":"three times higher a week later."},{"start":85.967,"end":88.427,"text":"The other side asks where this stops"},{"start":88.427,"end":88.887,"text":"working."},{"start":89.477,"end":92.067,"text":"Two cognitive load researchers worried"},{"start":92.067,"end":95.187,"text":"about complex material, where many pieces"},{"start":95.187,"end":96.867,"text":"depend on each other."},{"start":97.517,"end":99.877,"text":"They called it a potential limit."},{"start":100.537,"end":103.217,"text":"The benefit may even disappear with"},{"start":103.217,"end":106.597,"text":"complex material, and much of school is"},{"start":106.597,"end":107.117,"text":"like that."},{"start":107.847,"end":110.387,"text":"Two memory researchers called this wrong"},{"start":110.387,"end":111.887,"text":"on several grounds."},{"start":112.727,"end":115.707,"text":"Complexity, they said, was never defined"},{"start":115.707,"end":117.107,"text":"in a measurable way."},{"start":117.387,"end":121.427,"text":"Their re-analysis found a small gain four"},{"start":121.427,"end":123.347,"text":"times likelier than none."},{"start":124.087,"end":126.567,"text":"Notice how the reply sums up the other"},{"start":126.567,"end":126.887,"text":"side."},{"start":127.167,"end":130.807,"text":"It says they claimed no testing effect for"},{"start":130.807,"end":133.507,"text":"complex material, stronger than their"},{"start":133.507,"end":135.007,"text":"abstract's hedged wording."},{"start":135.8,"end":136.56,"text":"Back to Mia."},{"start":137.28,"end":139.8,"text":"Quizzing on formulas she's been taught is"},{"start":139.8,"end":140.56,"text":"the easy case."},{"start":141.1,"end":144.42,"text":"Now give her a long proof where every step"},{"start":144.42,"end":145.42,"text":"depends on the others."},{"start":145.76,"end":147.44,"text":"Will quizzing still help?"},{"start":147.98,"end":150.52,"text":"Decide for yourself before we go on."},{"start":155.43,"end":158.69,"text":"Both sides would likely expect quizzing to"},{"start":158.69,"end":159.77,"text":"help with the formulas."},{"start":160.23,"end":163.41,"text":"On the proof they split, and the data"},{"start":163.41,"end":164.47,"text":"can't settle it yet."},{"start":165.16,"end":167.88,"text":"Part of the fight is about evidence, which"},{"start":167.88,"end":168.62,"text":"studies count."},{"start":169.14,"end":172.92,"text":"Part is about definitions, what counts as"},{"start":172.92,"end":173.38,"text":"complex."},{"start":174.4,"end":177.14,"text":"The idea came with a limit built in."},{"start":177.22,"end":180.68,"text":"A difficulty only helps if the learner can"},{"start":180.68,"end":183.96,"text":"eventually meet it, otherwise it becomes"},{"start":183.96,"end":185.44,"text":"an undesirable one."},{"start":186.16,"end":188.4,"text":"Spacing has a long track record."},{"start":188.58,"end":191,"text":"Across two hundred seventy one"},{"start":191,"end":194.42,"text":"comparisons, spaced study almost always"},{"start":194.42,"end":195.76,"text":"beat crammed study."},{"start":196.06,"end":200.38,"text":"But most tests came within a day, mostly"},{"start":200.38,"end":201.56,"text":"with young adults."},{"start":202.35,"end":205.33,"text":"Making things hard isn't enough, though."},{"start":205.33,"end":207.91,"text":"Hard-to-read fonts helped memory in one"},{"start":207.91,"end":210.65,"text":"early study, but careful replications"},{"start":210.65,"end":211.91,"text":"found no effect."},{"start":212.58,"end":216.13,"text":"And for word lists, mixing did worse than"},{"start":216.13,"end":216.73,"text":"blocking."},{"start":217.52,"end":221.66,"text":"What's still open is complex material, and"},{"start":221.66,"end":224.36,"text":"how spacing works for young children in"},{"start":224.36,"end":224.6,"text":"school."},{"start":225.4,"end":228.66,"text":"When you read a study on this, ask three"},{"start":228.66,"end":229.18,"text":"things."},{"start":229.88,"end":232.64,"text":"How long after practice was the test?"},{"start":233.26,"end":235.64,"text":"Could these learners meet the challenge?"},{"start":236.46,"end":239.66,"text":"And what was the material, words, a"},{"start":239.66,"end":242.62,"text":"passage, math, or something complex?"},{"start":243.5,"end":245.96,"text":"Results may not carry over from one kind"},{"start":245.96,"end":246.64,"text":"to another."},{"start":247.4,"end":250.54,"text":"This card sums up both sides, and the"},{"start":250.54,"end":251.42,"text":"limit they share."},{"start":252.867,"end":253.747,"text":"One last question."},{"start":254.247,"end":256.567,"text":"Think of a struggle you've asked learners"},{"start":256.567,"end":257.127,"text":"to face."},{"start":257.527,"end":260.667,"text":"How would you tell a useful struggle from"},{"start":260.667,"end":261.447,"text":"a useless one?"}]},"cscl-can-you-script-people-to-build-on-each-other":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":3.06,"text":"Two made-up kids race ice cubes on a metal"},{"start":3.06,"end":4.52,"text":"tray and a wooden board."},{"start":4.88,"end":8.08,"text":"In the first chat, each one just says what"},{"start":8.08,"end":10.72,"text":"they think, and the other says okay."},{"start":11.51,"end":14.37,"text":"In the second chat, Leo takes Ana's idea"},{"start":14.37,"end":15.73,"text":"and reshapes it."},{"start":16.21,"end":19.15,"text":"Metal feels cold because it pulls heat"},{"start":19.15,"end":22.93,"text":"fast, he says, so it should push heat into"},{"start":22.93,"end":24.45,"text":"the ice fast too."},{"start":25.16,"end":27.22,"text":"Building on a partner's reasoning like"},{"start":27.22,"end":29.68,"text":"that is called transactivity."},{"start":30.16,"end":32.98,"text":"Some lessons give pairs prompts for how to"},{"start":32.98,"end":34.36,"text":"talk, called a script."},{"start":34.78,"end":37.68,"text":"Can a script get them to do it, and does"},{"start":37.68,"end":38.5,"text":"it help them learn?"},{"start":39.267,"end":41.787,"text":"The idea began with students discussing"},{"start":41.787,"end":43.047,"text":"moral dilemmas."},{"start":43.567,"end":46.567,"text":"One early researcher defined it as working"},{"start":46.567,"end":48.247,"text":"on someone else's reasoning."},{"start":48.907,"end":52.267,"text":"Just saying okay, or I see what you mean,"},{"start":52.267,"end":53.527,"text":"doesn't count."},{"start":54.267,"end":56.247,"text":"In one small study of twenty four"},{"start":56.247,"end":59.667,"text":"students, more of these moves went with"},{"start":59.667,"end":60.467,"text":"more learning."},{"start":60.847,"end":63.827,"text":"That's a correlation, though, not proof of"},{"start":63.827,"end":64.087,"text":"cause."},{"start":64.787,"end":67.167,"text":"Script theory turned this into a"},{"start":67.167,"end":67.507,"text":"principle."},{"start":68.137,"end":70.927,"text":"The more an activity requires building on"},{"start":70.927,"end":73.387,"text":"each other's knowledge, the better that"},{"start":73.387,"end":74.527,"text":"knowledge is learned."},{"start":75.287,"end":78.607,"text":"So scripts that prompt these moves should"},{"start":78.607,"end":80.247,"text":"beat scripts that don't."},{"start":80.567,"end":83.107,"text":"That's a prediction a review of studies"},{"start":83.107,"end":83.827,"text":"can check."},{"start":84.633,"end":87.293,"text":"Then the same research group pooled the"},{"start":87.293,"end":87.693,"text":"studies."},{"start":88.333,"end":90.693,"text":"For subject knowledge, scripts that"},{"start":90.693,"end":93.053,"text":"prompted these moves averaged a small"},{"start":93.053,"end":96.173,"text":"effect, and scripts that didn't averaged"},{"start":96.173,"end":96.853,"text":"close to zero."},{"start":97.663,"end":100.643,"text":"For collaboration skills, the gap went the"},{"start":100.643,"end":101.243,"text":"other way."},{"start":101.923,"end":104.523,"text":"Scripts without these prompts did better,"},{"start":104.523,"end":107.583,"text":"though only three results were in that"},{"start":107.583,"end":107.863,"text":"group."},{"start":108.613,"end":111.393,"text":"So the authors suggested revising their"},{"start":111.393,"end":113.773,"text":"own principle, to say which kind of"},{"start":113.773,"end":115.033,"text":"learning it predicts."},{"start":115.667,"end":118.9,"text":"Look again at subject knowledge, point two"},{"start":118.9,"end":120.607,"text":"two against point oh five."},{"start":121.387,"end":122.567,"text":"Did prompting win?"},{"start":123.247,"end":125.927,"text":"Decide for yourself before we go on."},{"start":130.757,"end":131.717,"text":"We can't tell yet."},{"start":132.137,"end":134.917,"text":"The gap between the two groups wasn't"},{"start":134.917,"end":135.897,"text":"statistically significant."},{"start":136.517,"end":139.797,"text":"If a gap that size were real, this test"},{"start":139.797,"end":142.497,"text":"would catch it only about one time in"},{"start":142.497,"end":142.757,"text":"twelve."},{"start":143.637,"end":146.337,"text":"So a non-significant difference with low"},{"start":146.337,"end":148.837,"text":"power isn't evidence of no effect."},{"start":149.357,"end":151.857,"text":"It just means this test couldn't tell"},{"start":151.857,"end":152.537,"text":"either way."},{"start":153.267,"end":154.767,"text":"One gap is clear."},{"start":155.687,"end":158.607,"text":"Studies prompted these moves but rarely"},{"start":158.607,"end":161.007,"text":"reported whether students made them."},{"start":161.567,"end":165.247,"text":"The authors asked for one standard way to"},{"start":165.247,"end":165.807,"text":"measure it."},{"start":166.497,"end":168.217,"text":"Even measuring is debated."},{"start":169.017,"end":171.997,"text":"Some researchers warn that preset codes"},{"start":171.997,"end":174.677,"text":"can replace the very thing you're"},{"start":174.677,"end":174.977,"text":"studying."},{"start":175.807,"end":178.347,"text":"One study of a hundred and one future math"},{"start":178.347,"end":179.927,"text":"teachers found a twist."},{"start":180.787,"end":183.387,"text":"The moves you make yourself seemed to"},{"start":183.387,"end":185.367,"text":"matter, not your partner's."},{"start":186.007,"end":188.267,"text":"What's still open is scope."},{"start":188.507,"end":191.987,"text":"The principle talks about knowledge, but"},{"start":191.987,"end":195.007,"text":"the surprise came in collaboration skills."},{"start":195.767,"end":199.547,"text":"Part of this is wording, and part needs"},{"start":199.547,"end":200.407,"text":"better data."},{"start":201.133,"end":203.853,"text":"When you read a paper on this, ask three"},{"start":203.853,"end":204.273,"text":"things."},{"start":204.953,"end":207.813,"text":"Did students actually build on each other,"},{"start":207.813,"end":209.693,"text":"or were they only prompted to?"},{"start":210.293,"end":213.013,"text":"Does the abstract match the results"},{"start":213.013,"end":213.413,"text":"tables?"},{"start":214.253,"end":216.773,"text":"And when two groups differ, was the gap"},{"start":216.773,"end":218.873,"text":"itself tested, with enough power?"},{"start":219.213,"end":221.973,"text":"A star on one group and not the other"},{"start":221.973,"end":223.513,"text":"doesn't prove a difference."},{"start":224.4,"end":227.52,"text":"This card sums up the theory, the"},{"start":227.52,"end":229.98,"text":"evidence, and what's still open."},{"start":231.433,"end":232.433,"text":"One last question."},{"start":233.013,"end":235.453,"text":"Say you wrote a script to get students"},{"start":235.453,"end":236.573,"text":"building on each other."},{"start":236.873,"end":239.513,"text":"How would you check that they really did?"}]},"cscl-can-you-see-a-group-regulate-itself":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.74,"text":"Three made-up students have half an hour"},{"start":2.74,"end":5.7,"text":"to make a podcast, and twenty minutes in,"},{"start":5.7,"end":7.34,"text":"they're still on topic one."},{"start":7.86,"end":10.92,"text":"She suggests dropping the interview, and"},{"start":10.92,"end":12.06,"text":"the other two agree."},{"start":12.97,"end":15.79,"text":"Now the whole group is steering its own"},{"start":15.79,"end":18.99,"text":"work, and researchers call this socially"},{"start":18.99,"end":23.31,"text":"shared regulation, or SSRL."},{"start":23.31,"end":26.45,"text":"But can you actually see a group regulate"},{"start":26.45,"end":26.87,"text":"itself?"},{"start":27.767,"end":30.827,"text":"Regulation means planning, checking and"},{"start":30.827,"end":33.827,"text":"adjusting how you learn, and groups do it"},{"start":33.827,"end":34.827,"text":"at three levels."},{"start":35.567,"end":38.887,"text":"First, you can steer yourself, and second,"},{"start":38.887,"end":42.067,"text":"a teammate or a tool can nudge you, which"},{"start":42.067,"end":43.627,"text":"is called co-regulation."},{"start":43.627,"end":47.427,"text":"Third, the whole group can steer its"},{"start":47.427,"end":48.107,"text":"shared work."},{"start":48.933,"end":52.113,"text":"A twenty fifteen review made a bold claim,"},{"start":52.113,"end":54.893,"text":"saying there's enough data to treat shared"},{"start":54.893,"end":58.133,"text":"regulation as separate from co-regulation."},{"start":58.933,"end":61.293,"text":"And the people behind the three levels"},{"start":61.293,"end":65.673,"text":"call regulation the key skill in learning"},{"start":65.673,"end":66.213,"text":"together."},{"start":67.133,"end":69.513,"text":"We found no published rebuttal from a"},{"start":69.513,"end":72.153,"text":"rival camp, only doubts from the same"},{"start":72.153,"end":75.133,"text":"research group, some from that very"},{"start":75.133,"end":75.593,"text":"review."},{"start":76.423,"end":79.043,"text":"Teams define and measure it in different"},{"start":79.043,"end":79.403,"text":"ways."},{"start":80.013,"end":82.143,"text":"And two of the framework's own authors"},{"start":82.143,"end":85.103,"text":"said studies couldn't yet tell it from"},{"start":85.103,"end":86.943,"text":"simply building knowledge together."},{"start":87.733,"end":90.653,"text":"The review proposes a truce about names."},{"start":91.293,"end":93.993,"text":"If a study only looks at thinking and"},{"start":93.993,"end":96.713,"text":"planning, call it socially shared"},{"start":96.713,"end":97.993,"text":"metacognition."},{"start":98.813,"end":101.913,"text":"Save SSRL for studies that cover"},{"start":101.913,"end":104.153,"text":"motivation and feelings too."},{"start":105.013,"end":108.173,"text":"Say a study only coded talk like Chloé's,"},{"start":108.173,"end":109.793,"text":"about time and plans."},{"start":110.613,"end":113.793,"text":"By that rule, it's shared metacognition,"},{"start":113.793,"end":117.693,"text":"which is a choice of words, not a finding."},{"start":118.467,"end":120.147,"text":"Now to that review's evidence."},{"start":120.487,"end":124.607,"text":"Of seventeen articles, thirteen had data"},{"start":124.607,"end":125.827,"text":"on shared regulation."},{"start":126.607,"end":129.807,"text":"All were descriptive, and none was an"},{"start":129.807,"end":131.407,"text":"experiment with a control group."},{"start":132.077,"end":134.037,"text":"Another study followed a hundred and three"},{"start":134.037,"end":136.577,"text":"future teachers in small groups."},{"start":137.457,"end":140.077,"text":"Groups with the best essays showed shared"},{"start":140.077,"end":143.617,"text":"regulation growing over time, and the"},{"start":143.617,"end":145.077,"text":"weakest didn't."},{"start":145.7,"end":148.38,"text":"So did shared regulation make those groups"},{"start":148.38,"end":148.92,"text":"do better?"},{"start":149.62,"end":152,"text":"Decide for yourself before we go on."},{"start":156.87,"end":158.51,"text":"Honestly, we can't tell."},{"start":158.93,"end":161.45,"text":"Strong and weak groups were compared side"},{"start":161.45,"end":163.67,"text":"by side, with no control group."},{"start":164.25,"end":166.77,"text":"And the data were what students reported,"},{"start":166.77,"end":168.15,"text":"not what they did."},{"start":168.81,"end":171.89,"text":"Another team, studying co-regulation,"},{"start":171.89,"end":174.27,"text":"worried that stronger students may have"},{"start":174.27,"end":175.85,"text":"worked this way all along."},{"start":176.667,"end":179.627,"text":"Still, both readings agree on a lot."},{"start":179.787,"end":182.347,"text":"The three levels aren't separate boxes,"},{"start":182.347,"end":184.527,"text":"because they're built into each other."},{"start":184.627,"end":187.487,"text":"And three studies found a tendency for"},{"start":187.487,"end":189.807,"text":"shared regulation to raise group"},{"start":189.807,"end":190.247,"text":"performance."},{"start":191.297,"end":193.897,"text":"Two questions are still open, and both"},{"start":193.897,"end":194.977,"text":"need new data."},{"start":195.497,"end":198.097,"text":"The review warns of side effects that"},{"start":198.097,"end":199.797,"text":"nobody has identified yet."},{"start":199.977,"end":202.797,"text":"And a much newer review of a hundred and"},{"start":202.797,"end":206.217,"text":"ten studies still flags unvalidated"},{"start":206.217,"end":206.437,"text":"measures."},{"start":207.333,"end":210.193,"text":"When you read a paper on this, ask three"},{"start":210.193,"end":210.653,"text":"things."},{"start":211.013,"end":214.133,"text":"Did they measure what the group did, or"},{"start":214.133,"end":215.873,"text":"only what members said?"},{"start":216.133,"end":219.373,"text":"Was there a comparison group, or only"},{"start":219.373,"end":222.153,"text":"strong and weak groups side by side?"},{"start":222.883,"end":225.983,"text":"And which definition did they use, with"},{"start":225.983,"end":227.683,"text":"feelings or only thinking?"},{"start":228.603,"end":231.423,"text":"Also check the date, since newer studies"},{"start":231.423,"end":232.943,"text":"weren't in that review."},{"start":233.8,"end":237.44,"text":"This card puts the whole debate in one"},{"start":237.44,"end":237.86,"text":"place."},{"start":239.4,"end":242.42,"text":"Before you go, think of your last group"},{"start":242.42,"end":242.9,"text":"project."},{"start":243.48,"end":246.12,"text":"What would you need to see to say the"},{"start":246.12,"end":248.98,"text":"group, not one person, was steering?"}]},"cscl-cooperation-or-collaboration":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.52,"text":"Three made-up students make a group"},{"start":2.52,"end":4.22,"text":"slideshow about volcanoes."},{"start":5.06,"end":8.16,"text":"They split it, three slides each, and"},{"start":8.16,"end":10.16,"text":"paste it together the night before."},{"start":10.95,"end":14.09,"text":"Slide five says thick magma traps gas."},{"start":14.92,"end":17.87,"text":"Slide eight says Hawaii erupts gently"},{"start":17.87,"end":21.19,"text":"because it's small, and nobody notices the"},{"start":21.19,"end":22.21,"text":"two don't fit."},{"start":23,"end":24.22,"text":"Was that collaboration?"},{"start":25.2,"end":28.34,"text":"Researchers argue about the word, and the"},{"start":28.34,"end":30.58,"text":"answer changes what you'd measure."},{"start":31.3,"end":34.5,"text":"One pair of researchers drew a sharp line."},{"start":35.18,"end":37.7,"text":"When each person owns one piece of the"},{"start":37.7,"end":39.68,"text":"problem, that's cooperation."},{"start":40.93,"end":44.61,"text":"Collaboration is working on it together, a"},{"start":44.61,"end":48.21,"text":"steady effort to build and keep one shared"},{"start":48.21,"end":49.73,"text":"picture of the problem."},{"start":50.5,"end":53.2,"text":"Their evidence was one teenage pair,"},{"start":53.2,"end":55.46,"text":"picked as one of their most collaborative."},{"start":56.1,"end":58.76,"text":"It shows how shared understanding gets"},{"start":58.76,"end":61.24,"text":"built, not how often."},{"start":61.9,"end":64.74,"text":"Another researcher, Dillenbourg, says the"},{"start":64.74,"end":66,"text":"line is blurrier."},{"start":66.71,"end":69.66,"text":"Even people who really work together split"},{"start":69.66,"end":72.04,"text":"some tasks without planning to."},{"start":72.78,"end":76.1,"text":"Look closely enough and you'll always find"},{"start":76.1,"end":77.04,"text":"some split."},{"start":77.4,"end":81.22,"text":"So he asks what kind of split it is."},{"start":81.96,"end":85.2,"text":"In cooperation, the split is fixed and"},{"start":85.2,"end":86.64,"text":"spelled out at the start."},{"start":86.76,"end":90.98,"text":"In collaboration, it's woven together, and"},{"start":90.98,"end":93.7,"text":"roles can shift every few minutes."},{"start":94.55,"end":97.59,"text":"He notes that some writers use the two"},{"start":97.59,"end":99.23,"text":"words for the same thing."},{"start":99.49,"end":103.05,"text":"He also finds a gap in the famous"},{"start":103.05,"end":103.55,"text":"definition."},{"start":104.47,"end":106.73,"text":"A teacher and a pupil build shared"},{"start":106.73,"end":109.53,"text":"understanding too, and that isn't a"},{"start":109.53,"end":110.41,"text":"collaborative setting."},{"start":110.79,"end":113.91,"text":"Still, he says he's often used it himself."},{"start":114.9,"end":118.28,"text":"As we read it, neither side ran a test to"},{"start":118.28,"end":118.84,"text":"settle this."},{"start":119.42,"end":121.84,"text":"It's an argument about where to draw the"},{"start":121.84,"end":122.16,"text":"line."},{"start":122.867,"end":124.707,"text":"Now a second made-up version."},{"start":124.947,"end":128.247,"text":"The three split the slides again, but Jun"},{"start":128.247,"end":130.767,"text":"reads slide eight and pushes back."},{"start":131.617,"end":134.397,"text":"Mia checks the magma, and they rewrite the"},{"start":134.397,"end":135.117,"text":"slide together."},{"start":135.517,"end":138.257,"text":"Is this cooperation or collaboration?"},{"start":139.237,"end":141.777,"text":"Decide for yourself before we go on."},{"start":146.677,"end":149.177,"text":"It depends on how closely you look."},{"start":149.597,"end":152.857,"text":"Across the whole project, they split the"},{"start":152.857,"end":153.117,"text":"work."},{"start":153.727,"end":157.057,"text":"At slide eight, they built one shared"},{"start":157.057,"end":157.697,"text":"explanation."},{"start":158.697,"end":161.797,"text":"His test asks if the split stayed fixed."},{"start":162.237,"end":164.917,"text":"In our reading it broke open at slide"},{"start":164.917,"end":167.037,"text":"eight, which makes that moment"},{"start":167.037,"end":167.797,"text":"collaboration."},{"start":169.1,"end":170.56,"text":"Does the word matter?"},{"start":171.32,"end":174.56,"text":"One history of the field says yes, for"},{"start":174.56,"end":174.98,"text":"research."},{"start":175.18,"end":178.84,"text":"In cooperation, the learning is done by"},{"start":178.84,"end":179.32,"text":"individuals."},{"start":180.41,"end":182.85,"text":"In collaboration, it happens between"},{"start":182.85,"end":185.57,"text":"people, as they build knowledge together."},{"start":186.24,"end":189.29,"text":"Who learns in a group gets its own video"},{"start":189.29,"end":190.37,"text":"in this series."},{"start":191.22,"end":194.1,"text":"Both sides agree that building shared"},{"start":194.1,"end":195.92,"text":"understanding is central."},{"start":196.12,"end":199.82,"text":"He adds that what counts is how much"},{"start":199.82,"end":203.08,"text":"partners change each other's thinking, not"},{"start":203.08,"end":204.48,"text":"how often they talk."},{"start":205.22,"end":207.28,"text":"A group setup makes collaboration"},{"start":207.28,"end":210.4,"text":"possible, but nothing guarantees it."},{"start":210.86,"end":214.12,"text":"In our reading, the open part is seeing"},{"start":214.12,"end":216.04,"text":"the split in real data."},{"start":216.8,"end":219.94,"text":"When you read a paper on group work, ask"},{"start":219.94,"end":220.92,"text":"three things."},{"start":221.56,"end":224.88,"text":"Which meaning does it use, split work or"},{"start":224.88,"end":225.76,"text":"shared work?"},{"start":226.3,"end":229.1,"text":"Did it look at what the group said, or"},{"start":229.1,"end":231.06,"text":"only at how it was set up?"},{"start":231.67,"end":234.69,"text":"And if it says cooperative, check what it"},{"start":234.69,"end":237.91,"text":"means, and don't take a message count as"},{"start":237.91,"end":239.03,"text":"proof of collaboration."},{"start":240.133,"end":243.593,"text":"This card sums up both definitions, and"},{"start":243.593,"end":245.233,"text":"why the choice matters."},{"start":246.933,"end":248.073,"text":"One last question."},{"start":248.733,"end":250.853,"text":"Think of your last group project."},{"start":251.353,"end":254.273,"text":"Where did you split the work, and where"},{"start":254.273,"end":256.053,"text":"did you actually think together?"}]},"cscl-do-experts-just-remember-more":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.64,"text":"Picture a chess board from a real game."},{"start":2.84,"end":6.36,"text":"You see it for five seconds, then it's"},{"start":6.36,"end":6.66,"text":"covered."},{"start":7.12,"end":10.04,"text":"Now put the pieces back from memory."},{"start":10.87,"end":13.87,"text":"In a classic study, a master put back"},{"start":13.87,"end":16.71,"text":"about sixteen pieces, a middle player"},{"start":16.71,"end":19.21,"text":"eight, and a beginner four."},{"start":20.13,"end":22.59,"text":"Then the researchers scattered the pieces"},{"start":22.59,"end":23.45,"text":"at random."},{"start":24.01,"end":26.79,"text":"On those boards, all three players did"},{"start":26.79,"end":29.55,"text":"worse than the beginner had on real games."},{"start":30.29,"end":32.83,"text":"So do experts just remember more?"},{"start":33.6,"end":36.74,"text":"Side A is that classic study, with just"},{"start":36.74,"end":37.66,"text":"three players."},{"start":38.18,"end":41.24,"text":"On random boards, the authors found no"},{"start":41.24,"end":44.06,"text":"link at all between memory and playing"},{"start":44.06,"end":44.44,"text":"strength."},{"start":45.25,"end":47.69,"text":"So masters aren't working with bigger"},{"start":47.69,"end":48.09,"text":"memories."},{"start":48.7,"end":51.39,"text":"They see familiar groups of pieces at a"},{"start":51.39,"end":54.03,"text":"glance, which researchers call chunks."},{"start":55.03,"end":57.97,"text":"A physics study found the same pattern"},{"start":57.97,"end":59.35,"text":"with problem cards."},{"start":59.89,"end":62.85,"text":"Experts sorted by the principle that"},{"start":62.85,"end":66.51,"text":"solves a problem, while novices sorted by"},{"start":66.51,"end":68.35,"text":"springs and ramps."},{"start":68.933,"end":71.593,"text":"Side B came from a later review of"},{"start":71.593,"end":72.953,"text":"thirteen chess experiments."},{"start":73.573,"end":76.353,"text":"Strong players kept some edge on random"},{"start":76.353,"end":78.833,"text":"boards, though a much smaller one."},{"start":79.483,"end":82.543,"text":"The strongest group beat the weakest in"},{"start":82.543,"end":83.923,"text":"twelve of the thirteen."},{"start":84.643,"end":87.803,"text":"The one exception was the classic study,"},{"start":87.803,"end":91.123,"text":"where the master did worse than the"},{"start":91.123,"end":91.423,"text":"beginner."},{"start":92.073,"end":95.653,"text":"Simon co-wrote both papers, so this is a"},{"start":95.653,"end":97.633,"text":"self-correction, not a feud."},{"start":98.433,"end":101.133,"text":"On real game positions, every four hundred"},{"start":101.133,"end":104.073,"text":"extra rating points bought about five more"},{"start":104.073,"end":104.473,"text":"pieces."},{"start":104.793,"end":107.633,"text":"How much did the same strength buy on"},{"start":107.633,"end":108.493,"text":"random boards?"},{"start":108.693,"end":111.013,"text":"Pick a number before we go on."},{"start":115.923,"end":119.703,"text":"About one piece, so the edge is real but"},{"start":119.703,"end":120.023,"text":"small."},{"start":120.403,"end":122.983,"text":"The review explains it with chunks, too."},{"start":123.623,"end":126.643,"text":"Masters know so many patterns that they"},{"start":126.643,"end":129.163,"text":"spot rare ones, even in a mess."},{"start":129.967,"end":132.587,"text":"Both sides agree on the big point."},{"start":133.047,"end":136.647,"text":"Meaning drives most of the expert edge,"},{"start":136.647,"end":138.687,"text":"not raw memory."},{"start":139.477,"end":141.537,"text":"What got revised is the mechanism."},{"start":142.457,"end":144.857,"text":"Experts recalled more than the first chunk"},{"start":144.857,"end":148.137,"text":"theory predicts, one master up to nine"},{"start":148.137,"end":148.657,"text":"boards."},{"start":149.397,"end":151.977,"text":"So the team added a second kind of memory"},{"start":151.977,"end":154.457,"text":"structure on top of chunks, called"},{"start":154.457,"end":155.257,"text":"templates."},{"start":156.327,"end":159.367,"text":"In physics, the line between expert and"},{"start":159.367,"end":161.247,"text":"novice is blurrier, too."},{"start":162.047,"end":165.007,"text":"Novices who sorted by principle also"},{"start":165.007,"end":166.867,"text":"solved problems better."},{"start":167.787,"end":170.327,"text":"Other critics say novices look less"},{"start":170.327,"end":173.567,"text":"abstract mostly because of how the studies"},{"start":173.567,"end":174.427,"text":"were set up."},{"start":175.127,"end":177.447,"text":"So there are two kinds of question here."},{"start":177.787,"end":180.587,"text":"Whether the edge is zero or small is"},{"start":180.587,"end":181.867,"text":"something data can settle."},{"start":182.187,"end":185.287,"text":"What counts as deep is partly a matter of"},{"start":185.287,"end":186.867,"text":"definition, in our reading."},{"start":187.6,"end":190.36,"text":"When you read a paper on this, ask three"},{"start":190.36,"end":190.82,"text":"things."},{"start":191.36,"end":193.08,"text":"How many people were tested?"},{"start":193.56,"end":195.72,"text":"And who counted as an expert?"},{"start":196.5,"end":199.38,"text":"Then check whether a claim says the edge"},{"start":199.38,"end":201.48,"text":"vanishes or just shrinks."},{"start":201.84,"end":205.92,"text":"One tiny study is never the last word, so"},{"start":205.92,"end":207.24,"text":"look for later reviews."},{"start":208.233,"end":211.473,"text":"This card sums up both sides, where they"},{"start":211.473,"end":213.613,"text":"agree, and what's still open."},{"start":215,"end":215.96,"text":"One last question."},{"start":216.64,"end":218.64,"text":"Think of something you're good at."},{"start":219.1,"end":221.8,"text":"What would a scrambled version look like,"},{"start":221.8,"end":223.54,"text":"and would you still have an edge?"}]},"cscl-evidence-for-knowledge-building":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.8,"text":"A fifth grader read a classmate's work and"},{"start":2.8,"end":5.5,"text":"said, Mendel worked on Karen's problem."},{"start":6.18,"end":8.86,"text":"Mendel was a famous biologist from long"},{"start":8.86,"end":9.14,"text":"ago."},{"start":9.84,"end":12.5,"text":"The child meant Karen faced the same"},{"start":12.5,"end":15.22,"text":"problem he did, not that she should look"},{"start":15.22,"end":15.88,"text":"up his answer."},{"start":16.59,"end":19.01,"text":"Classrooms built for that kind of talk"},{"start":19.01,"end":21.77,"text":"follow an approach called knowledge"},{"start":21.77,"end":22.25,"text":"building."},{"start":22.61,"end":25.49,"text":"We didn't find a published back-and-forth"},{"start":25.49,"end":26.05,"text":"about it."},{"start":26.53,"end":30.37,"text":"The tension sits inside the evidence, and"},{"start":30.37,"end":32.29,"text":"in what counts as success."},{"start":33.3,"end":36.44,"text":"Its founders want to remake school into a"},{"start":36.44,"end":39.02,"text":"place where students create knowledge."},{"start":39.3,"end":43.7,"text":"The goal is improving ideas, not just"},{"start":43.7,"end":45.14,"text":"reaching the right answer."},{"start":45.82,"end":49.06,"text":"One founder lists twelve ideas that work"},{"start":49.06,"end":49.56,"text":"together."},{"start":50.12,"end":53.92,"text":"Two matter most for us: every idea can be"},{"start":53.92,"end":57.46,"text":"improved, and a class should rise above to"},{"start":57.46,"end":58.5,"text":"bigger explanations."},{"start":59.6,"end":62.44,"text":"In a made-up class, kids post theories"},{"start":62.44,"end":64.66,"text":"about why their tomatoes split."},{"start":65.2,"end":68.86,"text":"One note says too much sun, and another"},{"start":68.86,"end":71.94,"text":"says the covered tomatoes didn't split."},{"start":72.83,"end":74.97,"text":"So the sun theory can't explain it."},{"start":75.39,"end":77.45,"text":"Then they write a rise-above note"},{"start":77.45,"end":80.49,"text":"together, with a better idea and a new"},{"start":80.49,"end":80.93,"text":"question."},{"start":81.68,"end":84.34,"text":"Real classes do this in software now"},{"start":84.34,"end":87.24,"text":"called Knowledge Forum, which started in"},{"start":87.24,"end":88.94,"text":"the eighties under another name."},{"start":89.7,"end":92.98,"text":"An early study compared two classes using"},{"start":92.98,"end":96.08,"text":"the software with one class that didn't."},{"start":96.62,"end":99.5,"text":"The comparison class came from a suburban"},{"start":99.5,"end":102.66,"text":"school with similar test scores, because"},{"start":102.66,"end":105.74,"text":"no similar inner-city class was available."},{"start":106.68,"end":109.52,"text":"The authors themselves said rigorous"},{"start":109.52,"end":111.36,"text":"controls weren't possible."},{"start":111.96,"end":114.78,"text":"The software classes gained more on"},{"start":114.78,"end":118.26,"text":"language tests, and no more in math, where"},{"start":118.26,"end":119.28,"text":"they hadn't used it."},{"start":119.967,"end":122.167,"text":"The two software classes ran it"},{"start":122.167,"end":122.507,"text":"differently."},{"start":123.247,"end":125.867,"text":"One did collaborative knowledge building,"},{"start":125.867,"end":128.707,"text":"and one did independent research."},{"start":129.507,"end":131.227,"text":"Which gained more on vocabulary?"},{"start":132.127,"end":134.627,"text":"Decide for yourself before we go on."},{"start":139.427,"end":142.287,"text":"The independent research class gained more"},{"start":142.287,"end":143.147,"text":"on vocabulary."},{"start":143.887,"end":146.547,"text":"The knowledge building class scored higher"},{"start":146.547,"end":148.827,"text":"on asking questions that seek"},{"start":148.827,"end":149.447,"text":"explanations."},{"start":150.577,"end":153.417,"text":"In our reading, the standard test and the"},{"start":153.417,"end":156.477,"text":"approach's own goals didn't line up."},{"start":157.2,"end":159.44,"text":"The founders share an example about"},{"start":159.44,"end":159.86,"text":"gravity."},{"start":160.78,"end":163.32,"text":"Afterward, most kids still thought of"},{"start":163.32,"end":167.36,"text":"gravity as a kind of stuff, so by distance"},{"start":167.36,"end":169.98,"text":"from the answer there was little progress."},{"start":170.94,"end":173.72,"text":"But they were less sure of their old idea,"},{"start":173.72,"end":175.88,"text":"and knew other ideas existed."},{"start":176.4,"end":179.66,"text":"The founders say improvement is the right"},{"start":179.66,"end":182.76,"text":"yardstick, and we'd call that a choice"},{"start":182.76,"end":184.02,"text":"about what counts."},{"start":184.8,"end":187.3,"text":"One study redesigned a teacher's class"},{"start":187.3,"end":188.72,"text":"over three years."},{"start":189.4,"end":191.68,"text":"Its summary reports the most shared"},{"start":191.68,"end":194.42,"text":"responsibility when students formed and"},{"start":194.42,"end":196.1,"text":"broke up their own teams."},{"start":196.5,"end":200.22,"text":"But each year brought new kids, so, in our"},{"start":200.22,"end":203.2,"text":"reading, kids and design can't be pulled"},{"start":203.2,"end":203.44,"text":"apart."},{"start":204.25,"end":206.99,"text":"We found no meta-analysis pooling its"},{"start":206.99,"end":207.27,"text":"effects."},{"start":208.09,"end":210.51,"text":"Every study we read here has a founder"},{"start":210.51,"end":211.51,"text":"among its authors."},{"start":212.15,"end":214.97,"text":"And the founders call keeping ideas at the"},{"start":214.97,"end":217.53,"text":"center the largest single challenge."},{"start":218.367,"end":221.387,"text":"When you read a paper on this, ask three"},{"start":221.387,"end":221.847,"text":"things."},{"start":222.547,"end":223.947,"text":"What was it compared with?"},{"start":224.567,"end":228.387,"text":"Was success a standard test, or how far"},{"start":228.387,"end":229.467,"text":"ideas improved?"},{"start":230.427,"end":232.667,"text":"And who ran it, in which schools?"},{"start":232.667,"end":236.827,"text":"A good case shows that it can work, not"},{"start":236.827,"end":238.127,"text":"how often it works."},{"start":239,"end":242.34,"text":"This card sums up the aim, the evidence,"},{"start":242.34,"end":243.96,"text":"and what's still open."},{"start":245.367,"end":246.507,"text":"One last question."},{"start":247.247,"end":249.667,"text":"What evidence would convince you that a"},{"start":249.667,"end":251.987,"text":"class got better at improving its own"},{"start":251.987,"end":252.387,"text":"ideas?"}]},"cscl-how-much-effort-should-common-ground-take":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.46,"text":"Two made-up siblings build the same"},{"start":2.46,"end":3.98,"text":"bookshelf over the phone."},{"start":4.48,"end":8.14,"text":"Lena describes a long silver screw, like a"},{"start":8.14,"end":11.7,"text":"nail with a hat, and Tomi checks which one"},{"start":11.7,"end":12.22,"text":"she means."},{"start":13.06,"end":15.46,"text":"By the fourth shelf, they just say"},{"start":15.46,"end":17.48,"text":"nail-hat, and it works."},{"start":17.7,"end":20.84,"text":"That shared understanding is their common"},{"start":20.84,"end":23.64,"text":"ground, and building it is called"},{"start":23.64,"end":24.3,"text":"grounding."},{"start":25.2,"end":28.88,"text":"Now imagine an app that labels every part"},{"start":28.88,"end":29.42,"text":"for them."},{"start":29.88,"end":31.14,"text":"It would be faster."},{"start":31.74,"end":34.8,"text":"But is faster always better when people"},{"start":34.8,"end":35.8,"text":"are learning together?"},{"start":36.633,"end":39.133,"text":"Side A comes from Clark and his"},{"start":39.133,"end":39.553,"text":"colleagues."},{"start":40.383,"end":43.233,"text":"Partners keep checking until both believe"},{"start":43.233,"end":45.733,"text":"they understood well enough for now."},{"start":46.473,"end":49.153,"text":"And they try to keep the joint work as"},{"start":49.153,"end":50.333,"text":"small as they can."},{"start":50.893,"end":54.373,"text":"In a classic lab task, pairs described the"},{"start":54.373,"end":56.653,"text":"same odd shapes six times."},{"start":57.393,"end":60.253,"text":"Words per shape fell from about forty one"},{"start":60.253,"end":61.393,"text":"to eight."},{"start":62.213,"end":65.233,"text":"One shape went from a long description of"},{"start":65.233,"end":68.613,"text":"a person ice skating to just, the ice"},{"start":68.613,"end":69.073,"text":"skater."},{"start":69.733,"end":72.573,"text":"Side B comes from collaborative learning"},{"start":72.573,"end":73.073,"text":"research."},{"start":73.763,"end":76.433,"text":"The extra effort of grounding may slow"},{"start":76.433,"end":79.813,"text":"people down, but it may lead to better"},{"start":79.813,"end":80.233,"text":"results."},{"start":81.203,"end":83.843,"text":"So designers should leave some room for"},{"start":83.843,"end":86.783,"text":"misunderstanding, though not too much, or"},{"start":86.783,"end":87.563,"text":"learning suffers."},{"start":88.283,"end":91.663,"text":"That's a design idea, not a tested law."},{"start":92.403,"end":94.263,"text":"These aren't letters back and forth."},{"start":94.803,"end":97.883,"text":"Later researchers took Clark's idea in a"},{"start":97.883,"end":98.523,"text":"different direction."},{"start":99.4,"end":102.14,"text":"Back to the app that labels every part."},{"start":102.9,"end":105.46,"text":"Side A's view predicts the siblings will"},{"start":105.46,"end":106.48,"text":"happily use it."},{"start":107.14,"end":109.72,"text":"Side B asks whether it removes the"},{"start":109.72,"end":111.62,"text":"explaining that helps them learn."},{"start":112.06,"end":113.16,"text":"Who's right here?"},{"start":113.84,"end":116.56,"text":"Decide for yourself before we go on."},{"start":121.46,"end":124.26,"text":"In our reading, both are, because they"},{"start":124.26,"end":125.64,"text":"answer different questions."},{"start":126.57,"end":129.72,"text":"Side A describes what people do when they"},{"start":129.72,"end":130.06,"text":"talk."},{"start":130.81,"end":133.8,"text":"Side B says what designers of learning"},{"start":133.8,"end":135,"text":"should aim for."},{"start":135.7,"end":138.66,"text":"Two other researchers studied talk in a"},{"start":138.66,"end":140,"text":"hospital operating room."},{"start":140.18,"end":143.42,"text":"They called common ground a confusing"},{"start":143.42,"end":146.12,"text":"metaphor, not an explanation."},{"start":147.06,"end":149.64,"text":"In their view, only an all-knowing"},{"start":149.64,"end":151.6,"text":"outsider could actually see it."},{"start":151.78,"end":155.1,"text":"Still, they granted that experiments have"},{"start":155.1,"end":157.18,"text":"measured it, if only indirectly."},{"start":157.7,"end":160.6,"text":"In our reading, their quarrel is about"},{"start":160.6,"end":163.7,"text":"everyday talk, and what counts as an"},{"start":163.7,"end":164.08,"text":"explanation."},{"start":165.067,"end":165.527,"text":"What survived?"},{"start":166.527,"end":169.147,"text":"Grounding matters, but it isn't enough on"},{"start":169.147,"end":169.527,"text":"its own."},{"start":170.067,"end":173.007,"text":"One team called it necessary but clearly"},{"start":173.007,"end":175.167,"text":"not sufficient for learning together."},{"start":175.987,"end":179.007,"text":"The classic evidence comes from lab tasks"},{"start":179.007,"end":182.047,"text":"with strangers, and it measures"},{"start":182.047,"end":184.407,"text":"understanding, not learning."},{"start":184.887,"end":188.667,"text":"Whether extra effort helps people learn is"},{"start":188.667,"end":190.267,"text":"still an open question."},{"start":191.1,"end":193.78,"text":"When you read a paper on this, ask three"},{"start":193.78,"end":194.2,"text":"things."},{"start":194.66,"end":197.18,"text":"Did they measure understanding, or"},{"start":197.18,"end":197.62,"text":"learning?"},{"start":197.86,"end":200.32,"text":"And what medium were people talking"},{"start":200.32,"end":200.66,"text":"through?"},{"start":201.35,"end":204.51,"text":"Finally, is common ground something they"},{"start":204.51,"end":207.41,"text":"actually observed, or just a name for"},{"start":207.41,"end":208.31,"text":"things going well?"},{"start":209.067,"end":212.187,"text":"This card sums up both sides, the critics,"},{"start":212.187,"end":213.767,"text":"and what's still open."},{"start":215.133,"end":216.173,"text":"One last question."},{"start":216.673,"end":219.613,"text":"In your group chats, what counts as"},{"start":219.613,"end":222.433,"text":"evidence that someone understood you, and"},{"start":222.433,"end":224.093,"text":"what do you just assume?"}]},"cscl-is-it-the-explaining-or-the-extra-time":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":3.24,"text":"Two made-up students study the same worked"},{"start":3.24,"end":5.06,"text":"example, a pancake recipe."},{"start":5.68,"end":9.26,"text":"Pat reads each step and says, okay, got"},{"start":9.26,"end":9.46,"text":"it."},{"start":9.46,"end":13.82,"text":"Jun stops and asks why you divide by four"},{"start":13.82,"end":14.32,"text":"first."},{"start":15.32,"end":18.72,"text":"He works out that step one gives eggs for"},{"start":18.72,"end":19.5,"text":"one person."},{"start":20.02,"end":23.56,"text":"On a new flour problem, Jun reuses that"},{"start":23.56,"end":26.9,"text":"idea, while Pat hunts for steps to copy."},{"start":27.63,"end":30.37,"text":"But Jun also spent more time on the card."},{"start":30.91,"end":33.43,"text":"So was it the explaining that helped him,"},{"start":33.43,"end":34.77,"text":"or the extra minutes?"},{"start":35.667,"end":39.107,"text":"Side A says the explaining itself does the"},{"start":39.107,"end":39.367,"text":"work."},{"start":39.567,"end":42.247,"text":"In the first study, strong physics"},{"start":42.247,"end":45.507,"text":"students explained each example far more"},{"start":45.507,"end":46.507,"text":"than weak ones."},{"start":47.217,"end":50.347,"text":"They also noticed their own confusion more"},{"start":50.347,"end":50.767,"text":"often."},{"start":51.487,"end":54.167,"text":"But there were only four students per"},{"start":54.167,"end":56.787,"text":"group, sorted after seeing their scores."},{"start":57.107,"end":59.987,"text":"The authors warned that another reading"},{"start":59.987,"end":61.047,"text":"was possible."},{"start":61.837,"end":65.557,"text":"Five years later, the same lab had eighth"},{"start":65.557,"end":68.717,"text":"graders explain each sentence of a text on"},{"start":68.717,"end":69.377,"text":"blood flow."},{"start":69.657,"end":72.637,"text":"They gained more than classmates who read"},{"start":72.637,"end":73.037,"text":"it twice."},{"start":73.933,"end":75.953,"text":"Side B has two doubts."},{"start":76.173,"end":78.173,"text":"The first is time."},{"start":78.853,"end":81.753,"text":"In that second study, the prompted kids"},{"start":81.753,"end":83.993,"text":"studied about twice as long."},{"start":84.733,"end":87.533,"text":"A later review found that most studies"},{"start":87.533,"end":90.673,"text":"didn't report whether study time differed."},{"start":91.303,"end":93.503,"text":"The second doubt is about content."},{"start":93.963,"end":96.723,"text":"Maybe explaining just adds information"},{"start":96.723,"end":98.523,"text":"that a teacher could have given you."},{"start":98.743,"end":101.683,"text":"Two researchers call this the coverage"},{"start":101.683,"end":102.103,"text":"hypothesis."},{"start":103.233,"end":105.773,"text":"This isn't one paper answering another."},{"start":106.073,"end":108.773,"text":"It's a tension running through nearly"},{"start":108.773,"end":110.913,"text":"thirty years of studies."},{"start":111.767,"end":114.587,"text":"That review pooled sixty nine results."},{"start":114.947,"end":118.507,"text":"On average, prompting people to explain"},{"start":118.507,"end":122.267,"text":"helped by point five five, about half a"},{"start":122.267,"end":123.027,"text":"standard deviation."},{"start":124.127,"end":127.467,"text":"Where explainers took longer, it was about"},{"start":127.467,"end":128.067,"text":"point seven."},{"start":128.687,"end":131.867,"text":"Now look only at studies that gave both"},{"start":131.867,"end":133.367,"text":"groups the same time."},{"start":133.887,"end":135.867,"text":"Does explaining still help?"},{"start":136.507,"end":139.227,"text":"Decide for yourself before we go on."},{"start":144.127,"end":148.267,"text":"Yes, but less, about point four, and from"},{"start":148.267,"end":149.207,"text":"only five results."},{"start":149.447,"end":152.387,"text":"The gap between the two wasn't"},{"start":152.387,"end":152.867,"text":"significant."},{"start":153.187,"end":156.447,"text":"The authors warn that its efficiency may"},{"start":156.447,"end":159.767,"text":"be exaggerated, since time often wasn't"},{"start":159.767,"end":161.067,"text":"controlled or reported."},{"start":161.967,"end":163.247,"text":"Now the second doubt."},{"start":163.847,"end":167.087,"text":"Against nothing extra, explaining averaged"},{"start":167.087,"end":168.167,"text":"about point seven."},{"start":168.687,"end":171.027,"text":"Against a good explanation given to"},{"start":171.027,"end":173.427,"text":"learners, it was only point three five,"},{"start":173.427,"end":175.187,"text":"from six results."},{"start":176.017,"end":177.817,"text":"The authors say two things."},{"start":177.997,"end":181.597,"text":"Explaining beat being told, against the"},{"start":181.597,"end":182.357,"text":"coverage idea."},{"start":183.057,"end":185.897,"text":"Yet a big part of the benefit could also"},{"start":185.897,"end":187.977,"text":"come from a teacher's explanation."},{"start":189.017,"end":191.697,"text":"A study of thirty six students adds a"},{"start":191.697,"end":191.957,"text":"clue."},{"start":192.557,"end":195.517,"text":"The kind of explaining predicted learning,"},{"start":195.517,"end":198.257,"text":"even after taking time into account."},{"start":199.097,"end":201.257,"text":"What's still open is mostly about"},{"start":201.257,"end":201.677,"text":"evidence."},{"start":202.517,"end":205.637,"text":"Only five results held time equal, and"},{"start":205.637,"end":208.137,"text":"only six compared a given explanation."},{"start":209.157,"end":211.217,"text":"One point is about definitions."},{"start":212.337,"end":215.157,"text":"Explaining to yourself isn't the same as"},{"start":215.157,"end":217.257,"text":"summarizing, or teaching a friend."},{"start":218.033,"end":221.273,"text":"When you read a paper on this, ask three"},{"start":221.273,"end":221.773,"text":"things."},{"start":222.153,"end":225.413,"text":"Was study time equal, or at least"},{"start":225.413,"end":225.873,"text":"reported?"},{"start":226.473,"end":230.253,"text":"What did the other group get: nothing,"},{"start":230.253,"end":232.593,"text":"rereading, or a good explanation?"},{"start":233.563,"end":236.463,"text":"And were the groups assigned, or sorted"},{"start":236.463,"end":238.103,"text":"after the scores came in?"},{"start":238.823,"end":242.743,"text":"Sorting after the fact shows a link, not a"},{"start":242.743,"end":243.063,"text":"cause."},{"start":243.9,"end":246.76,"text":"This card sums up both sides, the numbers,"},{"start":246.76,"end":248.22,"text":"and what's still open."},{"start":249.6,"end":250.52,"text":"One last question."},{"start":251.1,"end":253.68,"text":"Say your students explain worked examples"},{"start":253.68,"end":254.78,"text":"and do better."},{"start":255.2,"end":257.58,"text":"How would you show it wasn't just the"},{"start":257.58,"end":258.18,"text":"extra time?"}]},"cscl-smart-dashboards-or-modest-tools":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.32,"text":"Picture a made-up class of twenty eight"},{"start":2.32,"end":4.28,"text":"students in seven teams."},{"start":4.86,"end":7.38,"text":"Eighteen minutes in, one tablet dies."},{"start":7.92,"end":10.92,"text":"By minute twenty five, two teams are done,"},{"start":10.92,"end":14.04,"text":"three have hands up, and one keeps"},{"start":14.04,"end":15.24,"text":"rerunning the simulation."},{"start":16.28,"end":19.62,"text":"Juggling all that live, under real limits,"},{"start":19.62,"end":22.98,"text":"is what researchers call orchestration."},{"start":23.54,"end":26.22,"text":"So should the teacher's technology show"},{"start":26.22,"end":27.98,"text":"her more, or less?"},{"start":28.867,"end":32.047,"text":"This debate played out in print, in one"},{"start":32.047,"end":32.847,"text":"journal issue."},{"start":33.507,"end":36.167,"text":"One researcher's position paper drew"},{"start":36.167,"end":39.367,"text":"several replies, and then a synthesis"},{"start":39.367,"end":40.767,"text":"pulled them together."},{"start":41.047,"end":44.447,"text":"We read those replies only through the"},{"start":44.447,"end":44.767,"text":"synthesis."},{"start":45.733,"end":48.973,"text":"Side A, from that researcher's team in an"},{"start":48.973,"end":52.293,"text":"earlier paper, says keep classroom tools"},{"start":52.293,"end":53.073,"text":"modest."},{"start":53.893,"end":56.933,"text":"Every menu a teacher pulls down adds to"},{"start":56.933,"end":59.693,"text":"her load, with twenty or thirty students"},{"start":59.693,"end":60.353,"text":"watching."},{"start":61.263,"end":64.123,"text":"That paper lists four design principles,"},{"start":64.123,"end":67.143,"text":"and two are keeping things minimal and"},{"start":67.143,"end":68.803,"text":"keeping the teacher in control."},{"start":69.667,"end":72.147,"text":"The same researchers tried this in"},{"start":72.147,"end":74.267,"text":"first-year physics exercise sessions."},{"start":74.957,"end":77.547,"text":"While waiting for help, students spent"},{"start":77.547,"end":80.447,"text":"sixty two percent of that time watching"},{"start":80.447,"end":81.927,"text":"for the teaching assistant."},{"start":82.857,"end":85.737,"text":"Each team then got a small lamp showing"},{"start":85.737,"end":88.717,"text":"its exercise, which blinked faster the"},{"start":88.717,"end":89.997,"text":"longer the team waited."},{"start":90.517,"end":93.817,"text":"A shared screen, tried first, cut the"},{"start":93.817,"end":97.197,"text":"estimated time to sixteen percent, and the"},{"start":97.197,"end":98.797,"text":"lamp cut it to six."},{"start":99.637,"end":102.237,"text":"The lamp also got teams helping each"},{"start":102.237,"end":105.437,"text":"other, while the shared screen stirred up"},{"start":105.437,"end":106.077,"text":"some competition."},{"start":107.067,"end":109.987,"text":"So does this show that modest tools beat"},{"start":109.987,"end":110.607,"text":"smart ones?"},{"start":111.367,"end":113.847,"text":"Decide for yourself before we go on."},{"start":118.717,"end":121.657,"text":"Not yet, going by how the paper describes"},{"start":121.657,"end":122.317,"text":"the design."},{"start":122.697,"end":125.297,"text":"The sixty two percent came from earlier"},{"start":125.297,"end":128.137,"text":"observations, not a comparison class"},{"start":128.137,"end":129.477,"text":"running at the same time."},{"start":129.717,"end":132.677,"text":"The screen always came before the lamp,"},{"start":132.677,"end":135.037,"text":"and no learning results were reported."},{"start":135.197,"end":137.737,"text":"And no smart tool was part of the"},{"start":137.737,"end":137.997,"text":"comparison."},{"start":138.937,"end":142.037,"text":"Even the authors said minimalism was only"},{"start":142.037,"end":143.797,"text":"a hypothesis at that point."},{"start":144.533,"end":147.333,"text":"Side B comes from the synthesis authors,"},{"start":147.333,"end":150.213,"text":"who asked if modest tools miss what the"},{"start":150.213,"end":152.833,"text":"data students leave behind could add."},{"start":153.673,"end":156.433,"text":"A later experiment gave teachers smart"},{"start":156.433,"end":159.553,"text":"glasses showing live data from a tutoring"},{"start":159.553,"end":160.013,"text":"program."},{"start":160.633,"end":163.793,"text":"A summary says students learned more than"},{"start":163.793,"end":166.153,"text":"with plain monitoring or business as"},{"start":166.153,"end":166.513,"text":"usual."},{"start":166.693,"end":170.253,"text":"We only read the abstract and summary, so"},{"start":170.253,"end":172.653,"text":"the effect sizes are unchecked."},{"start":173.267,"end":175.927,"text":"The synthesis says the replies all agree"},{"start":175.927,"end":178.647,"text":"that classrooms are complex and the"},{"start":178.647,"end":180.407,"text":"teacher's say really matters."},{"start":180.607,"end":183.947,"text":"One reply even warned that orchestration"},{"start":183.947,"end":186.947,"text":"technology may add new, unneeded"},{"start":186.947,"end":187.307,"text":"complications."},{"start":188.507,"end":191.927,"text":"One open question needs data, which is how"},{"start":191.927,"end":194.907,"text":"much a tool should show and how much it"},{"start":194.907,"end":195.527,"text":"should decide."},{"start":196.167,"end":199.607,"text":"Another critique says design alone may not"},{"start":199.607,"end":202.567,"text":"be enough, since power and politics in"},{"start":202.567,"end":204.707,"text":"schools deserve equal attention."},{"start":205.667,"end":208.547,"text":"When you read a paper on this, ask three"},{"start":208.547,"end":209.107,"text":"things."},{"start":210.017,"end":213.027,"text":"Was there a comparison group, or only a"},{"start":213.027,"end":214.147,"text":"before and after?"},{"start":214.707,"end":218.087,"text":"Did they measure learning, or only time"},{"start":218.087,"end":218.767,"text":"and use?"},{"start":219.637,"end":222.217,"text":"And what does the tool decide, and what"},{"start":222.217,"end":223.397,"text":"stays with the teacher?"},{"start":223.797,"end":227.377,"text":"Remember, a big drop in one design study"},{"start":227.377,"end":231.037,"text":"shows what's possible, not how big the"},{"start":231.037,"end":231.677,"text":"effect is."},{"start":232.467,"end":236.107,"text":"This card puts the whole debate in one"},{"start":236.107,"end":236.527,"text":"place."},{"start":238.067,"end":240.867,"text":"Before you go, picture a classroom tool"},{"start":240.867,"end":241.707,"text":"you know well."},{"start":242.417,"end":245.007,"text":"What's one thing it could stop showing, or"},{"start":245.007,"end":247.847,"text":"start showing, to make the teacher's next"},{"start":247.847,"end":249.027,"text":"decision easier?"}]},"cscl-group-awareness-mirror-or-nudge":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.86,"text":"Four made-up students write a lab report"},{"start":2.86,"end":4.06,"text":"in a shared chat."},{"start":4.3,"end":8.04,"text":"A bar shows how many messages each one has"},{"start":8.04,"end":8.74,"text":"sent so far."},{"start":9.48,"end":12.62,"text":"A second display shows who got which quiz"},{"start":12.62,"end":13.34,"text":"question right."},{"start":13.84,"end":17.44,"text":"Only Jun, one of the quieter ones, knows"},{"start":17.44,"end":18.64,"text":"the viscosity answer."},{"start":19.44,"end":21.56,"text":"Tools like these are called group"},{"start":21.56,"end":22.54,"text":"awareness tools."},{"start":23.15,"end":26.48,"text":"One kind shows who talks, and the other"},{"start":26.48,"end":28.24,"text":"shows who knows."},{"start":29.14,"end":32.2,"text":"Is a display like this a mirror, or a"},{"start":32.2,"end":32.56,"text":"nudge?"},{"start":32.92,"end":35.36,"text":"Both answers come from the same lead"},{"start":35.36,"end":38.16,"text":"author, so think of it as a refinement."},{"start":38.967,"end":41.987,"text":"One view says their strength is that these"},{"start":41.987,"end":43.527,"text":"tools don't give orders."},{"start":44.147,"end":47.247,"text":"They just show information, and the group"},{"start":47.247,"end":49.147,"text":"decides what to do with it."},{"start":49.737,"end":52.837,"text":"Good displays make differences stand out,"},{"start":52.837,"end":55.917,"text":"so they steer the talk without any"},{"start":55.917,"end":56.377,"text":"instructions."},{"start":57.4,"end":59.44,"text":"The same sentence goes on, though."},{"start":60,"end":63.06,"text":"It relies on learners having the skills to"},{"start":63.06,"end":65.04,"text":"use that information well."},{"start":65.86,"end":68.6,"text":"Students are often free to ignore the"},{"start":68.6,"end":72.02,"text":"tool, so the effect depends on the choices"},{"start":72.02,"end":72.68,"text":"they make."},{"start":73.41,"end":76.31,"text":"A later paper says these tools aren't"},{"start":76.31,"end":76.97,"text":"neutral mirrors."},{"start":77.59,"end":79.99,"text":"They shape the information to steer"},{"start":79.99,"end":82.07,"text":"learners toward good habits."},{"start":82.967,"end":85.587,"text":"A Dutch study gave eleventh graders a"},{"start":85.587,"end":88.667,"text":"display like Mia's bar, for eight history"},{"start":88.667,"end":89.027,"text":"lessons."},{"start":89.887,"end":93.347,"text":"Whole classes were randomly assigned, and"},{"start":93.347,"end":94.527,"text":"there were only three."},{"start":95.327,"end":97.827,"text":"Students opened it about once every five"},{"start":97.827,"end":99.747,"text":"minutes, so they did look."},{"start":100.207,"end":102.767,"text":"Did participation become more equal?"},{"start":103.527,"end":106.007,"text":"Decide for yourself before we go on."},{"start":110.947,"end":111.187,"text":"No."},{"start":111.687,"end":114.387,"text":"Long messages rose a little, though that"},{"start":114.387,"end":116.767,"text":"result was borderline, and the authors"},{"start":116.767,"end":118.887,"text":"report more talk about working together."},{"start":119.327,"end":122.847,"text":"But equality didn't improve, and neither"},{"start":122.847,"end":123.847,"text":"did the group grade."},{"start":124.567,"end":127.247,"text":"The authors note the tool was optional,"},{"start":127.247,"end":130.147,"text":"and participation was already fairly"},{"start":130.147,"end":132.767,"text":"equal, with few free riders."},{"start":133.667,"end":136.027,"text":"A recent meta-analysis of forty six"},{"start":136.027,"end":139.107,"text":"studies reports a moderate average effect"},{"start":139.107,"end":139.767,"text":"on learning."},{"start":139.987,"end":143.227,"text":"We've only read its summary, which also"},{"start":143.227,"end":145.327,"text":"calls past findings inconsistent."},{"start":146.537,"end":149.557,"text":"An earlier review found that social"},{"start":149.557,"end":152.797,"text":"displays mostly change how groups"},{"start":152.797,"end":155.617,"text":"interact, with effects on achievement"},{"start":155.617,"end":158.557,"text":"rarely tested or not shown."},{"start":159.387,"end":162.767,"text":"Relying on students to steer themselves is"},{"start":162.767,"end":163.767,"text":"part of the definition."},{"start":164.527,"end":166.687,"text":"Whether making them use the tool works"},{"start":166.687,"end":170.407,"text":"better is still open, with no direct test"},{"start":170.407,"end":171.367,"text":"we could find."},{"start":172.077,"end":174.277,"text":"And researchers rarely measure the"},{"start":174.277,"end":177.297,"text":"awareness itself, the very thing these"},{"start":177.297,"end":178.937,"text":"tools are meant to create."},{"start":179.733,"end":182.713,"text":"When you read a paper on these tools, ask"},{"start":182.713,"end":183.613,"text":"three things."},{"start":184.303,"end":186.833,"text":"Is the outcome how the group talks, or"},{"start":186.833,"end":187.593,"text":"what they learned?"},{"start":188.133,"end":191.553,"text":"Did students have to use the tool, and did"},{"start":191.553,"end":191.793,"text":"they?"},{"start":192.503,"end":195.663,"text":"And was it compared with no tool, or with"},{"start":195.663,"end":196.783,"text":"another version of it?"},{"start":197.303,"end":200.083,"text":"One review reports that a running total"},{"start":200.083,"end":203.323,"text":"drew more posts than a count per time"},{"start":203.323,"end":203.643,"text":"period."},{"start":204.467,"end":207.587,"text":"This card sums up both readings, the one"},{"start":207.587,"end":209.687,"text":"test, and what's still open."},{"start":211.067,"end":212.087,"text":"One last question."},{"start":212.527,"end":215.047,"text":"If your group could see one thing about"},{"start":215.047,"end":218.527,"text":"each member, would you show who talks or"},{"start":218.527,"end":221.667,"text":"who knows, and what might backfire?"}]},"irt-basic":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.9,"end":4.58,"text":"Lena and Sam each scored six out of ten on a fractions quiz."},{"start":5.78,"end":7.24,"text":"But Lena took the easy version,"},{"start":7.64,"end":8.84,"text":"and Sam took the hard one."},{"start":9.74,"end":11.16,"text":"So did they show the same ability?"},{"start":11.64,"end":13.06,"text":"A raw score can't tell you,"},{"start":13.28,"end":15.5,"text":"because it depends on which items you happened to get."},{"start":16.381,"end":18.441,"text":"Item response theory, or IRT,"},{"start":18.921,"end":21.961,"text":"handles this by putting people and items on one shared scale."},{"start":23.583,"end":26.363,"text":"Picture a single ruler, measured in units called logits."},{"start":26.863,"end":28.463,"text":"Each student sits at a point on it."},{"start":28.983,"end":30.863,"text":"That point is their ability, written theta."},{"start":31.705,"end":33.385,"text":"Each item sits on the same ruler."},{"start":33.805,"end":36.045,"text":"That point is its difficulty, written b."},{"start":36.885,"end":39.485,"text":"Easy items sit low, and hard items sit high."},{"start":40.341,"end":43.261,"text":"In the basic models, the rule that ties them together is simple."},{"start":44.121,"end":46.141,"text":"When a student's ability equals an item's difficulty,"},{"start":46.141,"end":49.381,"text":"the chance of a correct answer is fifty percent."},{"start":51.004,"end":53.584,"text":"Now plot that chance against ability for one item."},{"start":54.324,"end":55.524,"text":"You get an S-shaped curve,"},{"start":55.884,"end":57.424,"text":"called the item characteristic curve."},{"start":58.248,"end":60.588,"text":"Students with low ability rarely get it right,"},{"start":61.128,"end":63.568,"text":"students with high ability almost always do,"},{"start":64.168,"end":67.188,"text":"and the curve crosses one half exactly at the item's difficulty."},{"start":68.27,"end":71.15,"text":"Make the item harder, and the whole curve slides to the right."},{"start":72.744,"end":74.944,"text":"The steepness of the curve in the middle is called"},{"start":74.944,"end":76.844,"text":"discrimination, written a."},{"start":77.672,"end":80.332,"text":"A steep item sharply separates students just below"},{"start":80.332,"end":82.412,"text":"its difficulty from students just above it."},{"start":83.072,"end":84.892,"text":"A flat item barely tells them apart."},{"start":85.837,"end":88.977,"text":"The Rasch model gives every item the same slope."},{"start":88.977,"end":91.057,"text":"The two-parameter model lets the slopes differ."},{"start":91.617,"end":93.337,"text":"The three-parameter model adds a floor,"},{"start":93.337,"end":94.617,"text":"c, for lucky guesses."},{"start":96.29,"end":99.49,"text":"Now let ability run along one axis and difficulty along"},{"start":99.49,"end":101.87,"text":"another, and the curves join into a surface."},{"start":102.841,"end":105.161,"text":"The surface rises as ability passes difficulty,"},{"start":105.541,"end":107.821,"text":"and the fifty percent line runs along the diagonal,"},{"start":108.221,"end":109.221,"text":"where the two are equal."},{"start":110.714,"end":111.814,"text":"Back to Lena and Sam."},{"start":112.474,"end":115.034,"text":"If both versions were calibrated on the same scale,"},{"start":115.534,"end":116.934,"text":"IRT can compare them directly,"},{"start":117.474,"end":120.074,"text":"and six out of ten on the hard version places Sam higher."},{"start":121,"end":122,"text":"Two cautions."},{"start":122.08,"end":124.7,"text":"In the Rasch model, students who answer the same items"},{"start":124.7,"end":126.74,"text":"with the same total get the same estimate."},{"start":127.46,"end":130.1,"text":"The pattern of answers adds information only in models"},{"start":130.1,"end":131.28,"text":"that weight items differently."},{"start":132.264,"end":134.784,"text":"And IRT treats ability as fixed during a test,"},{"start":135.184,"end":137.324,"text":"while knowledge tracing, from an earlier video,"},{"start":137.324,"end":139.484,"text":"follows knowledge as it changes with practice."},{"start":140.59,"end":142.97,"text":"Lena, Sam, and every number here are made up."},{"start":143.69,"end":146.37,"text":"Real IRT scales need many responses per item,"},{"start":146.37,"end":148.09,"text":"and a model that fits the data."},{"start":149.705,"end":150.705,"text":"Pause and consider."},{"start":150.825,"end":153.505,"text":"On a test you know well, which item would you expect"},{"start":153.505,"end":155.785,"text":"to discriminate best, and why?"}]},"cognitive-apprenticeship":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.9,"end":2.28,"text":"In a traditional apprenticeship,"},{"start":2.56,"end":5.34,"text":"a tailor's apprentice can watch every cut and every stitch."},{"start":6.06,"end":7.44,"text":"The process is out in the open."},{"start":8.405,"end":10.765,"text":"In school, the most important process is thinking,"},{"start":11.125,"end":12.305,"text":"and thinking is invisible."},{"start":13.625,"end":16.045,"text":"Students see the answer, not how the expert got there."},{"start":16.895,"end":19.095,"text":"Cognitive apprenticeship, described by Collins,"},{"start":19.435,"end":20.995,"text":"Brown, and Newman in 1989,"},{"start":20.995,"end":23.075,"text":"is a way to make that thinking visible."},{"start":24.768,"end":25.768,"text":"Take a word problem."},{"start":26.468,"end":28.448,"text":"A five meter ladder leans against a wall,"},{"start":28.848,"end":30.368,"text":"with its foot three meters out."},{"start":31.768,"end":32.768,"text":"How high does it reach?"},{"start":33.668,"end":35.768,"text":"In modeling, the teacher solves it out loud."},{"start":36.708,"end":37.708,"text":"What do I know?"},{"start":38.428,"end":39.428,"text":"Let me sketch it."},{"start":40.548,"end":43.548,"text":"That's a right triangle, so I can use the Pythagorean theorem."},{"start":44.55,"end":47.69,"text":"The answer, four meters, matters less than the questions"},{"start":47.69,"end":49.29,"text":"the expert asks along the way."},{"start":50.855,"end":53.435,"text":"In coaching, students try a similar problem while the"},{"start":53.435,"end":55.775,"text":"teacher watches and offers hints at the right moments."},{"start":56.8,"end":59.36,"text":"Scaffolding is support for the parts students cannot"},{"start":59.36,"end":62.34,"text":"yet do alone, such as a prompt card listing the questions"},{"start":62.34,"end":63.34,"text":"the expert asked."},{"start":64.212,"end":65.272,"text":"Then the support fades."},{"start":66.132,"end":68.612,"text":"As students succeed, the teacher removes the prompts,"},{"start":68.872,"end":71.452,"text":"one at a time, and students take on more of the work."},{"start":73.067,"end":75.727,"text":"In articulation, students explain their own reasoning,"},{"start":76.127,"end":79.407,"text":"out loud or in writing, so their thinking becomes visible too."},{"start":80.269,"end":82.689,"text":"In reflection, they compare their process with the"},{"start":82.689,"end":84.469,"text":"expert's, and with other students',"},{"start":84.469,"end":86.109,"text":"to see what they did differently."},{"start":87.107,"end":90.067,"text":"And in exploration, students pose and solve problems"},{"start":90.067,"end":92.287,"text":"of their own, with no prompt card at all."},{"start":93.829,"end":95.409,"text":"The tasks themselves are ordered."},{"start":96.129,"end":98.389,"text":"Complexity increases, diversity increases,"},{"start":98.869,"end":100.709,"text":"and the whole task comes before its parts."},{"start":101.738,"end":104.598,"text":"Seeing the whole task done first gives each practiced"},{"start":104.598,"end":105.598,"text":"part a purpose."},{"start":107.03,"end":109.19,"text":"Put together, the methods have three jobs."},{"start":109.67,"end":112.43,"text":"To build the skill: modeling, coaching, and scaffolding."},{"start":112.99,"end":115.51,"text":"To make it visible: articulation and reflection."},{"start":116.23,"end":118.11,"text":"To hand over control: exploration."},{"start":119.26,"end":120.26,"text":"A caution."},{"start":120.56,"end":123.22,"text":"This is a design framework, not one tested program."},{"start":124.04,"end":126.14,"text":"Its methods came from earlier work in reading,"},{"start":126.4,"end":129.36,"text":"writing, and mathematics, and each needs its own evaluation"},{"start":129.36,"end":130.36,"text":"in a new setting."},{"start":131.215,"end":132.795,"text":"The ladder problem, the teacher,"},{"start":133.175,"end":135.275,"text":"and the students in this video are made up for teaching."},{"start":136.942,"end":137.942,"text":"Pause and consider."},{"start":139.062,"end":141.602,"text":"In a skill you teach, which part of the expert's thinking"},{"start":141.602,"end":144.842,"text":"stays invisible, and how could you make it visible?"}]},"4cid-basic":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.9,"end":3.26,"text":"Some skills can't be learned one piece at a time."},{"start":3.9,"end":6.1,"text":"Searching the research literature well means choosing"},{"start":6.1,"end":8.96,"text":"terms, combining them, and judging what comes back,"},{"start":8.96,"end":9.96,"text":"all at once."},{"start":10.712,"end":12.472,"text":"The four-component instructional design model,"},{"start":13.072,"end":15.392,"text":"or 4C/ID, developed by Jeroen van Merriënboer,"},{"start":15.392,"end":18.012,"text":"is built for complex skills like this."},{"start":18.972,"end":20.972,"text":"It has four parts: learning tasks,"},{"start":21.792,"end":24.232,"text":"supportive information, procedural information,"},{"start":24.232,"end":25.232,"text":"and part-task practice."},{"start":26.844,"end":29.244,"text":"Learning tasks are whole, realistic tasks,"},{"start":29.484,"end":31.804,"text":"such as running a complete search for a real question,"},{"start":31.804,"end":32.844,"text":"from start to finish."},{"start":33.838,"end":35.418,"text":"They are grouped into task classes,"},{"start":35.418,"end":36.818,"text":"from simple to complex."},{"start":37.778,"end":40.618,"text":"An early class searches one database for a narrow question."},{"start":41.438,"end":44.138,"text":"A later class searches several databases for a broad one."},{"start":45.716,"end":48.456,"text":"Within each class, support starts high and fades:"},{"start":49.016,"end":51.576,"text":"first a worked example, then a task to complete,"},{"start":51.936,"end":53.136,"text":"then the whole task alone."},{"start":54.074,"end":56.254,"text":"Then the next class begins with high support again,"},{"start":56.714,"end":59.094,"text":"so the support drawn over time looks like a saw."},{"start":59.969,"end":61.729,"text":"Tasks within a class also vary,"},{"start":61.969,"end":64.449,"text":"so learners meet the same skill in different situations."},{"start":66.258,"end":68.678,"text":"Supportive information helps with the parts that call"},{"start":68.678,"end":71.398,"text":"for reasoning, such as judging whether a study is relevant."},{"start":72.238,"end":74.358,"text":"These parts are never done quite the same way twice."},{"start":75.391,"end":78.171,"text":"It explains how the field is organized and how experts"},{"start":78.171,"end":81.031,"text":"approach the problem, and it comes before and alongside"},{"start":81.031,"end":82.091,"text":"each task class."},{"start":83.745,"end":86.325,"text":"Procedural information covers the parts done the same"},{"start":86.325,"end":89.705,"text":"way every time, such as the syntax for combining search terms."},{"start":90.668,"end":94.008,"text":"It is given just in time, at the moment a step is needed,"},{"start":94.008,"end":97.268,"text":"as a short how-to, and it disappears as learners stop needing it."},{"start":98.703,"end":101.203,"text":"Part-task practice is extra practice for routine steps"},{"start":101.203,"end":102.903,"text":"that must become automatic,"},{"start":103.223,"end":105.203,"text":"like writing a search string quickly and correctly."},{"start":106.18,"end":107.82,"text":"It is added only when it is needed,"},{"start":107.82,"end":110.68,"text":"and mixed in with the whole tasks rather than done first."},{"start":112.397,"end":115.017,"text":"Put together, the blueprint has task classes of whole"},{"start":115.017,"end":118.377,"text":"tasks, supportive information for each class,"},{"start":118.377,"end":120.737,"text":"procedural information attached to single steps,"},{"start":120.737,"end":122.237,"text":"and part-task practice where it is needed."},{"start":123.171,"end":124.171,"text":"A caution."},{"start":124.671,"end":127.871,"text":"4C/ID is a detailed design model, not a quick recipe."},{"start":128.691,"end":131.391,"text":"A full blueprint needs a careful analysis of the skill,"},{"start":131.811,"end":134.471,"text":"and each design still has to be tried out with its own learners."},{"start":135.484,"end":137.044,"text":"The search course, its tasks,"},{"start":137.344,"end":139.764,"text":"and its learners in this video are made up for teaching."},{"start":141.431,"end":142.431,"text":"Pause and consider."},{"start":143.531,"end":144.871,"text":"In a complex skill you teach,"},{"start":145.331,"end":147.211,"text":"which parts are done the same way every time,"},{"start":147.611,"end":149.151,"text":"and which call for reasoning?"}]},"first-principles":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.9,"end":3.12,"text":"There are many instructional design theories and models."},{"start":3.68,"end":6.74,"text":"In 2002, David Merrill compared a wide range of them"},{"start":6.74,"end":8.3,"text":"and asked what they had in common."},{"start":9.25,"end":10.91,"text":"He distilled five first principles."},{"start":11.41,"end":13.85,"text":"Each one names a condition under which learning is promoted."},{"start":15.519,"end":16.419,"text":"The first is problem-centered:"},{"start":16.419,"end":19.819,"text":"learning is promoted when learners work on real-world"},{"start":19.819,"end":20.759,"text":"problems or tasks."},{"start":20.759,"end":24.399,"text":"Picture a workshop that teaches new teaching assistants"},{"start":24.399,"end":25.519,"text":"to write quiz questions."},{"start":26.523,"end":28.223,"text":"Instead of opening with a list of rules,"},{"start":28.603,"end":30.863,"text":"it opens with a real task:"},{"start":30.863,"end":33.523,"text":"write one good multiple-choice question for your own class."},{"start":35.221,"end":39.081,"text":"Second, activation: learning is promoted when learners"},{"start":39.081,"end":40.541,"text":"recall relevant experience."},{"start":41.841,"end":42.961,"text":"Leo, one of the assistants,"},{"start":43.521,"end":45.901,"text":"remembers a trick question that once cost him points."},{"start":46.835,"end":49.335,"text":"That memory becomes a foundation for what comes next."},{"start":50.971,"end":54.631,"text":"Third, demonstration: learning is promoted when learners"},{"start":54.631,"end":56.731,"text":"see the skill shown, not just described."},{"start":57.717,"end":60.157,"text":"The trainer puts a weak question next to a strong one,"},{"start":60.157,"end":61.717,"text":"and points out the vague stem,"},{"start":61.717,"end":63.817,"text":"and the choice, all of the above."},{"start":65.365,"end":69.065,"text":"Fourth, application: learning is promoted when learners"},{"start":69.065,"end":71.245,"text":"use the new skill themselves, with feedback."},{"start":72.279,"end":73.559,"text":"Leo writes his own question."},{"start":74.279,"end":76.599,"text":"The trainer notes that two of the choices could both"},{"start":76.599,"end":78.499,"text":"be right, and Leo revises it."},{"start":80.035,"end":83.735,"text":"Fifth, integration: learning is promoted when learners"},{"start":83.735,"end":85.675,"text":"carry the new skill into their own world."},{"start":86.605,"end":88.665,"text":"Leo uses the question with his own students,"},{"start":88.665,"end":91.245,"text":"and then shares what he learned with the other assistants."},{"start":93.012,"end":95.492,"text":"Merrill drew the four phases as a cycle around the"},{"start":95.492,"end":97.692,"text":"problem: activation, demonstration,"},{"start":98.292,"end":99.712,"text":"application, and integration."},{"start":100.797,"end":103.117,"text":"And the problems themselves can grow from simple to"},{"start":103.117,"end":105.757,"text":"complex, so the cycle repeats at each step."},{"start":107.345,"end":108.345,"text":"A caution."},{"start":109.765,"end":112.025,"text":"Merrill drew these principles from existing theories,"},{"start":112.445,"end":113.445,"text":"not from one experiment."},{"start":114.865,"end":116.245,"text":"Treat them as a design guide,"},{"start":116.685,"end":118.305,"text":"and check how they work with your own learners."},{"start":119.377,"end":121.857,"text":"The workshop, Leo, and his questions in this video"},{"start":121.857,"end":122.857,"text":"are made up for teaching."},{"start":124.558,"end":125.558,"text":"Pause and consider."},{"start":126.018,"end":127.898,"text":"In a course you know, which of the five principles"},{"start":127.898,"end":130.678,"text":"is missing, and what would it take to add it?"}]},"backward-design":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.9,"end":2.3,"text":"Many units are planned forward:"},{"start":2.9,"end":4.06,"text":"pick interesting activities,"},{"start":4.5,"end":6.6,"text":"teach them, and write a test at the end."},{"start":7.68,"end":10.08,"text":"The test can end up measuring something no activity"},{"start":10.08,"end":11.2,"text":"prepared students for."},{"start":12.768,"end":15.368,"text":"Backward design, described by Grant Wiggins and Jay"},{"start":15.488,"end":17.108,"text":"McTighe, reverses the order."},{"start":17.908,"end":20.188,"text":"Start from the destination, then plan the road."},{"start":21.046,"end":24.346,"text":"It has three stages: identify the desired results,"},{"start":24.846,"end":27.626,"text":"determine the evidence, and then plan the learning experiences."},{"start":29.426,"end":32.046,"text":"Picture Nadia, a teacher planning a unit on charts"},{"start":32.046,"end":33.046,"text":"in the news."},{"start":34.466,"end":37.346,"text":"Stage one: what should students be able to do at the end?"},{"start":38.231,"end":41.811,"text":"Her answer: judge whether a news chart actually supports its headline."},{"start":43.528,"end":46.588,"text":"Stage two: what would convince her that they can?"},{"start":47.868,"end":50.128,"text":"A vocabulary quiz on chart terms would not."},{"start":51.057,"end":53.617,"text":"Instead, students get a real news chart and explain"},{"start":53.617,"end":54.857,"text":"whether it supports the claim."},{"start":56.017,"end":57.797,"text":"This one starts its axis at fifty,"},{"start":58.557,"end":60.137,"text":"so a small difference looks huge."},{"start":61.867,"end":64.987,"text":"Only now, stage three: plan the activities."},{"start":66.807,"end":69.447,"text":"Students practice spotting axes that don't start at"},{"start":69.447,"end":71.927,"text":"zero, and they redraw charts to compare."},{"start":72.84,"end":74.56,"text":"When the axis is redrawn from zero,"},{"start":74.88,"end":76.6,"text":"the dramatic gap shrinks to a small one."},{"start":78.164,"end":80.644,"text":"Wiggins and McTighe named two common traps."},{"start":81.464,"end":82.804,"text":"In activity-focused design,"},{"start":83.264,"end":85.904,"text":"students stay busy, but the activities don't lead anywhere."},{"start":86.871,"end":87.631,"text":"In coverage-focused design,"},{"start":87.631,"end":90.871,"text":"the class marches through the material page by page,"},{"start":90.871,"end":91.871,"text":"without a clear goal."},{"start":93.428,"end":96.068,"text":"John Biggs called a closely related idea constructive"},{"start":96.068,"end":98.148,"text":"alignment: the intended outcomes,"},{"start":98.608,"end":100.968,"text":"the learning activities, and the assessment all point"},{"start":100.968,"end":101.968,"text":"at the same thing."},{"start":102.632,"end":104.692,"text":"If the assessment drifts away from the outcomes,"},{"start":105.272,"end":107.712,"text":"students learn to pass the test rather than reach the goal."},{"start":108.603,"end":110.963,"text":"Bring it back into line, and studying for the test"},{"start":110.963,"end":112.283,"text":"becomes practice for the goal."},{"start":113.837,"end":114.837,"text":"A caution."},{"start":115.257,"end":117.257,"text":"Alignment is a design check, not a guarantee."},{"start":118.557,"end":121.657,"text":"An aligned unit still needs evidence that students actually learn."},{"start":122.563,"end":125.243,"text":"Nadia, her unit, and the chart in this video are made"},{"start":125.243,"end":126.243,"text":"up for teaching."},{"start":127.477,"end":128.477,"text":"Pause and consider."},{"start":128.957,"end":131.477,"text":"In a course you teach, does every assessment match"},{"start":131.477,"end":134.337,"text":"an outcome you stated, and does every activity prepare"},{"start":134.337,"end":135.617,"text":"students for it?"}]},"gagne-nine-events":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.9,"end":4.34,"text":"In 1965, Robert Gagné published The Conditions of Learning."},{"start":5.88,"end":8.32,"text":"He argued that a lesson works when the events outside"},{"start":8.32,"end":10.2,"text":"the learner support the processes inside."},{"start":11.179,"end":12.839,"text":"He listed nine events of instruction,"},{"start":13.179,"end":15.479,"text":"from gaining attention to helping learners carry a"},{"start":15.479,"end":16.699,"text":"skill into new situations."},{"start":18.53,"end":22.03,"text":"Picture Priya, who trains new lab assistants to use a micropipette."},{"start":22.57,"end":23.93,"text":"Event one: gain attention."},{"start":24.73,"end":26.45,"text":"She shows two samples that should match,"},{"start":26.71,"end":27.75,"text":"but one is clearly larger."},{"start":28.74,"end":30.48,"text":"Same steps, different results."},{"start":31.16,"end":32.46,"text":"Now everyone wants to know why."},{"start":34.054,"end":36.474,"text":"Event two: inform learners of the objective."},{"start":37.094,"end":39.674,"text":"By the end, each of them will measure an exact volume,"},{"start":39.674,"end":41.634,"text":"and a scale will show whether it is right."},{"start":42.537,"end":45.277,"text":"Event three: stimulate recall of prior learning."},{"start":46.077,"end":47.957,"text":"She asks how they read a measuring cylinder:"},{"start":47.957,"end":50.037,"text":"at eye level, at the bottom of the curve."},{"start":51.591,"end":53.331,"text":"Event four: present the content."},{"start":54.291,"end":55.851,"text":"She shows the plunger's two stops."},{"start":56.691,"end":58.351,"text":"Press to the first stop to draw liquid in,"},{"start":58.351,"end":61.351,"text":"and to the second stop to push the last drop out."},{"start":62.235,"end":64.215,"text":"Event five: provide learning guidance."},{"start":65.135,"end":66.495,"text":"She adds a cue they can repeat:"},{"start":67.315,"end":69.435,"text":"first stop to fill, second stop to empty."},{"start":71.07,"end":73.25,"text":"Event six: elicit performance."},{"start":74.35,"end":77.11,"text":"Each assistant measures colored water, again and again."},{"start":78.033,"end":79.753,"text":"Event seven: provide feedback."},{"start":80.753,"end":82.133,"text":"The scale shows every result,"},{"start":82.653,"end":85.593,"text":"and Priya points out an air bubble that left one sample short."},{"start":87.226,"end":89.086,"text":"Event eight: assess performance."},{"start":90.066,"end":92.706,"text":"At the end, each assistant measures three samples with"},{"start":92.706,"end":94.266,"text":"no hints, and the scale decides."},{"start":95.339,"end":97.959,"text":"Event nine: enhance retention and transfer."},{"start":99.359,"end":102.119,"text":"The next week, they use the skill in a real experiment,"},{"start":102.119,"end":104.219,"text":"with different volumes and different liquids."},{"start":105.955,"end":108.735,"text":"Gagné paired each event with a process inside the learner,"},{"start":108.895,"end":111.475,"text":"from attention and expectancy at the start to retrieval,"},{"start":111.875,"end":113.655,"text":"encoding, and finally generalization."},{"start":115.369,"end":116.369,"text":"A caution."},{"start":116.669,"end":118.709,"text":"The nine events are a checklist of conditions,"},{"start":119.089,"end":120.089,"text":"not a fixed script."},{"start":120.789,"end":123.629,"text":"Their order can change, and not every lesson needs all nine."},{"start":124.562,"end":127.122,"text":"Priya, her lab, and the samples in this video are made"},{"start":127.122,"end":128.122,"text":"up for teaching."},{"start":129.308,"end":130.308,"text":"Pause and consider."},{"start":131.428,"end":133.628,"text":"In a lesson you teach, which of the nine events is"},{"start":133.628,"end":136.768,"text":"missing, and which one could you drop without losing anything?"}]},"addie-sam":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.9,"end":4.2,"text":"Most instructional design models describe what a lesson should contain."},{"start":5.1,"end":7.58,"text":"Process models describe how a design team gets from"},{"start":7.58,"end":9.04,"text":"a request to a finished course."},{"start":10.047,"end":11.747,"text":"The best known is ADDIE: analysis,"},{"start":12.147,"end":14.907,"text":"design, development, implementation, and evaluation."},{"start":16.737,"end":19.737,"text":"Picture Omar, a designer asked to build a short safety"},{"start":19.737,"end":21.077,"text":"course for warehouse staff."},{"start":21.797,"end":24.117,"text":"In analysis, he asks who the learners are,"},{"start":24.337,"end":26.677,"text":"what they must do, and why accidents happen now."},{"start":28.22,"end":31.82,"text":"In design, he writes objectives and plans the assessments and activities."},{"start":32.98,"end":34.94,"text":"In development, the team builds the videos,"},{"start":35.24,"end":36.24,"text":"quizzes, and job aids."},{"start":37.194,"end":39.734,"text":"Implementation puts the course in front of real staff."},{"start":40.474,"end":42.094,"text":"Evaluation asks whether it worked,"},{"start":42.494,"end":44.014,"text":"and it can happen in every phase,"},{"start":44.314,"end":45.314,"text":"not only at the end."},{"start":46.674,"end":48.934,"text":"When the phases run strictly one after another,"},{"start":49.434,"end":51.134,"text":"a problem found late is expensive."},{"start":52.474,"end":54.734,"text":"Omar's first test with staff comes months in,"},{"start":54.734,"end":57.174,"text":"and the forklift scenario confuses everyone."},{"start":58.879,"end":62.279,"text":"Michael Molenda pointed out that ADDIE has no single original author."},{"start":62.879,"end":65.059,"text":"It is a label for a family of systems approaches,"},{"start":65.579,"end":67.879,"text":"and many teams already loop back between phases."},{"start":69.644,"end":71.984,"text":"Michael Allen proposed the Successive Approximation"},{"start":71.984,"end":74.924,"text":"Model, or SAM, to make those loops the main idea."},{"start":75.807,"end":78.327,"text":"It begins with preparation and a short meeting called"},{"start":78.327,"end":80.127,"text":"the savvy start, where designers,"},{"start":80.527,"end":83.327,"text":"experts, and a few learners sketch rough prototypes together."},{"start":84.988,"end":86.568,"text":"Then come quick cycles of design,"},{"start":86.948,"end":89.668,"text":"prototype, and review, each version a little closer"},{"start":89.668,"end":90.668,"text":"to the goal."},{"start":91.073,"end":94.513,"text":"In the first week, Omar shows a paper sketch of the forklift scenario."},{"start":95.533,"end":97.773,"text":"A staff member says the warning signs are wrong,"},{"start":97.773,"end":99.433,"text":"and he fixes them in an hour."},{"start":101.059,"end":102.959,"text":"Iterative development then builds an alpha,"},{"start":103.339,"end":104.759,"text":"a beta, and a gold release,"},{"start":105.179,"end":106.559,"text":"with learners trying each one."},{"start":107.455,"end":108.995,"text":"ADDIE lays out what has to happen."},{"start":110.355,"end":113.515,"text":"SAM changes the rhythm, so feedback arrives early and often."},{"start":115.177,"end":116.177,"text":"A caution."},{"start":116.477,"end":117.997,"text":"Neither process guarantees learning,"},{"start":117.997,"end":120.757,"text":"and fast prototypes can drift without clear objectives."},{"start":121.697,"end":125.237,"text":"Many teams combine them: they analyze carefully, then iterate."},{"start":126.049,"end":128.569,"text":"Omar, the warehouse, and the course in this video are"},{"start":128.569,"end":129.569,"text":"made up for teaching."},{"start":130.938,"end":131.938,"text":"Pause and consider."},{"start":133.518,"end":134.938,"text":"In your last design project,"},{"start":135.398,"end":137.618,"text":"when did the first real learner see a working version,"},{"start":137.978,"end":140.058,"text":"and what would it take to make that sooner?"}]},"theory-model-framework":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.9,"end":2.54,"text":"Theory, model, framework."},{"start":4.32,"end":7.02,"text":"In instructional design, these words are often used"},{"start":7.02,"end":8.38,"text":"as if they meant the same thing."},{"start":9.68,"end":12.92,"text":"They do not, and the difference changes how you use each one."},{"start":13.839,"end":15.919,"text":"A quick test: does it explain why,"},{"start":16.359,"end":18.639,"text":"does it guide what to do, or does it organize what"},{"start":18.639,"end":19.639,"text":"to look at?"},{"start":20.721,"end":22.281,"text":"A theory explains and predicts."},{"start":23.381,"end":24.641,"text":"Cognitive load theory, for example,"},{"start":25.421,"end":28.201,"text":"explains why novices often learn more from worked examples"},{"start":28.201,"end":29.981,"text":"than from solving problems on their own."},{"start":30.86,"end":34.32,"text":"It also predicts that this benefit fades as learners gain expertise."},{"start":35.22,"end":36.28,"text":"Because it makes predictions,"},{"start":36.66,"end":39.08,"text":"a theory can be tested, and it can turn out to be wrong."},{"start":40.704,"end":43.424,"text":"A model is a simplified picture of how something is done."},{"start":44.084,"end":46.344,"text":"Some models describe what a lesson should contain,"},{"start":46.804,"end":47.984,"text":"like Gagné's nine events."},{"start":48.704,"end":50.284,"text":"Process models, like ADDIE,"},{"start":50.524,"end":52.224,"text":"describe the steps a design team follows."},{"start":53.308,"end":56.388,"text":"A model guides action, but it rarely says why each step works."},{"start":56.908,"end":58.948,"text":"Its support comes from the theories behind it,"},{"start":59.108,"end":60.108,"text":"or from practice."},{"start":61.545,"end":64.085,"text":"A framework organizes concepts into a structure,"},{"start":64.465,"end":65.645,"text":"so you know what to look at."},{"start":66.945,"end":68.785,"text":"The Community of Inquiry framework,"},{"start":68.785,"end":71.765,"text":"for instance, looks at online courses through three"},{"start":71.765,"end":74.225,"text":"presences: social, cognitive, and teaching."},{"start":75.185,"end":76.265,"text":"It does not give you steps,"},{"start":76.705,"end":78.985,"text":"and on its own, it does not predict an outcome."},{"start":79.565,"end":80.565,"text":"It gives you a lens."},{"start":82.025,"end":85.105,"text":"Picture Lena, who is redesigning an online statistics course."},{"start":86.245,"end":88.705,"text":"Cognitive load theory tells her why to start each topic"},{"start":88.705,"end":89.705,"text":"with worked examples."},{"start":90.629,"end":93.509,"text":"ADDIE guides how her team moves from analysis to evaluation,"},{"start":94.109,"end":96.829,"text":"and a lesson model like the nine events shapes each unit."},{"start":97.751,"end":100.071,"text":"The Community of Inquiry framework tells her what to"},{"start":100.071,"end":101.331,"text":"watch in the discussion forum:"},{"start":101.891,"end":103.451,"text":"are students connecting, reasoning,"},{"start":103.911,"end":104.911,"text":"and being guided?"},{"start":106.081,"end":107.521,"text":"Place each one on a triangle:"},{"start":108.461,"end":109.861,"text":"explain, guide, and organize."},{"start":111.301,"end":113.001,"text":"Cognitive load theory sits near explain,"},{"start":113.801,"end":116.901,"text":"ADDIE near guide, and Community of Inquiry near organize."},{"start":117.964,"end":119.284,"text":"Some sit between the corners."},{"start":120.804,"end":122.844,"text":"The 4C/ID model guides design,"},{"start":123.324,"end":125.424,"text":"but it is built on cognitive load theory,"},{"start":125.684,"end":126.944,"text":"so it leans toward explain."},{"start":128.616,"end":129.616,"text":"A caution."},{"start":129.996,"end":131.916,"text":"Authors do not use these labels consistently."},{"start":132.736,"end":136.376,"text":"Charles Reigeluth even called prescriptive guidance instructional-design theory."},{"start":137.016,"end":138.316,"text":"So look at what a work does,"},{"start":138.636,"end":139.816,"text":"not only at what it is called."},{"start":140.658,"end":143.178,"text":"Lena and her course in this video are made up for teaching."},{"start":144.838,"end":145.838,"text":"Pause and consider."},{"start":147.678,"end":150.598,"text":"Pick one theory, model, or framework from your own work."},{"start":151.958,"end":154.058,"text":"Does it explain, guide, or organize,"},{"start":154.718,"end":156.698,"text":"and what else would you need to use it well?"}]},"dick-carey":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.9,"end":4.58,"text":"In 1978, Walter Dick and Lou Carey published The Systematic"},{"start":4.58,"end":5.58,"text":"Design of Instruction."},{"start":6.28,"end":8.32,"text":"Their model treats instruction as a system,"},{"start":8.32,"end":10.02,"text":"where every part depends on the others."},{"start":11.042,"end":14.682,"text":"It lays out ten steps, from identifying a goal to evaluating"},{"start":14.682,"end":15.762,"text":"the finished instruction."},{"start":17.449,"end":20.469,"text":"Picture Tomás, who designs training for new bank tellers."},{"start":20.889,"end":23.169,"text":"Step one: identify the instructional goal."},{"start":23.769,"end":25.109,"text":"Tellers will spot counterfeit bills."},{"start":26.798,"end":30.618,"text":"Step two: conduct an instructional analysis."},{"start":32.698,"end":35.658,"text":"He breaks the goal into the steps an expert follows:"},{"start":37.118,"end":39.678,"text":"feel the paper, check the watermark,"},{"start":40.218,"end":41.678,"text":"tilt the bill to see the ink shift,"},{"start":42.218,"end":43.678,"text":"and find the security thread."},{"start":45.26,"end":47.42,"text":"Step three, done alongside it:"},{"start":47.7,"end":49.64,"text":"analyze the learners and contexts."},{"start":50.34,"end":53.76,"text":"New tellers, a busy counter, and only seconds per bill."},{"start":55.328,"end":57.848,"text":"Step four: write performance objectives."},{"start":59.708,"end":62.708,"text":"Given ten bills, the teller identifies every counterfeit"},{"start":62.708,"end":63.708,"text":"within two minutes."},{"start":64.108,"end":66.488,"text":"That is a condition, a behavior, and a criterion."},{"start":67.588,"end":70.148,"text":"Step five: develop assessment instruments,"},{"start":70.148,"end":71.808,"text":"before any teaching is planned."},{"start":72.608,"end":75.668,"text":"The test is a stack of real and fake bills that matches the objective."},{"start":77.349,"end":80.209,"text":"Steps six and seven: develop the instructional strategy"},{"start":80.209,"end":81.209,"text":"and the materials."},{"start":82.049,"end":84.329,"text":"A demonstration, practice with feedback,"},{"start":84.689,"end":85.929,"text":"and a pocket card for the counter."},{"start":87.567,"end":91.887,"text":"Step eight: design and conduct formative evaluation."},{"start":93.487,"end":95.447,"text":"Tomás tries the training with one teller,"},{"start":95.847,"end":98.207,"text":"then a small group, then a whole branch."},{"start":99.207,"end":100.847,"text":"Step nine: revise."},{"start":102.327,"end":104.387,"text":"The one-to-one session shows that tellers skip the"},{"start":104.387,"end":107.647,"text":"security thread, so he goes back and changes the analysis"},{"start":107.647,"end":108.647,"text":"and the practice."},{"start":110.145,"end":112.045,"text":"That return arrow is the heart of the model."},{"start":112.605,"end":114.285,"text":"Revision can reach back to earlier steps,"},{"start":114.645,"end":115.665,"text":"not just the last one."},{"start":116.535,"end":118.935,"text":"Step ten: summative evaluation,"},{"start":119.455,"end":122.115,"text":"usually later and often by an outside evaluator."},{"start":123.135,"end":125.275,"text":"It asks whether the finished training should be kept."},{"start":126.873,"end":128.453,"text":"Notice two links to other ideas."},{"start":129.113,"end":130.893,"text":"The assessments come before the strategy,"},{"start":131.253,"end":134.153,"text":"as in backward design, and the instructional analysis"},{"start":134.153,"end":136.433,"text":"echoes Gagné's work on learning hierarchies."},{"start":138.014,"end":139.014,"text":"A caution."},{"start":139.514,"end":140.594,"text":"Drawn as boxes and arrows,"},{"start":141.014,"end":144.094,"text":"the model can look rigid, and for small or fast projects,"},{"start":144.474,"end":145.994,"text":"its full form can feel heavy."},{"start":146.934,"end":149.054,"text":"Many designers scale the steps to the project."},{"start":150.026,"end":152.986,"text":"Tomás, the bank, and the training in this video are"},{"start":152.986,"end":153.986,"text":"made up for teaching."},{"start":155.396,"end":156.396,"text":"Pause and consider."},{"start":156.736,"end":159.056,"text":"In a course you designed, which step did you skip,"},{"start":159.456,"end":161.076,"text":"and what did that cost you later?"}]},"kirkpatrick":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.9,"end":3.34,"text":"A training ends, and someone asks: did it work?"},{"start":4.78,"end":8.46,"text":"In 1959, Donald Kirkpatrick proposed four levels for"},{"start":8.46,"end":9.46,"text":"answering that question."},{"start":10.301,"end":13.141,"text":"Reaction, learning, behavior, and results."},{"start":14.661,"end":16.381,"text":"Each level asks a different question,"},{"start":16.721,"end":19.401,"text":"and each is usually harder to measure than the one before."},{"start":21.05,"end":24.39,"text":"Picture Mei, who runs a hand hygiene training for hospital staff."},{"start":25.81,"end":29.15,"text":"Level one, reaction: did the staff find it useful and engaging?"},{"start":30.21,"end":32.05,"text":"A short survey at the end tells her."},{"start":33.587,"end":37.007,"text":"Level two, learning: did they gain the knowledge and skill?"},{"start":37.947,"end":40.147,"text":"A quiz on the moments when hands must be cleaned,"},{"start":40.147,"end":41.447,"text":"and a check of their technique."},{"start":43.12,"end":47.12,"text":"Level three, behavior: do they apply it on the job?"},{"start":48.28,"end":50.74,"text":"Weeks later, observers on the ward count how often"},{"start":50.74,"end":52.58,"text":"staff clean their hands at those moments."},{"start":54.32,"end":58.04,"text":"Level four, results: did the organization's outcomes change?"},{"start":59.44,"end":61.12,"text":"Mei looks at infection rates on the wards."},{"start":62.832,"end":65.352,"text":"The levels form a chain, but not a guaranteed one."},{"start":66.112,"end":68.012,"text":"Staff can enjoy a training and learn little,"},{"start":68.432,"end":70.372,"text":"or learn a lot and change nothing at work."},{"start":71.265,"end":73.685,"text":"In a meta-analysis, George Alliger and colleagues found"},{"start":73.685,"end":76.305,"text":"that reactions were only weakly related to learning"},{"start":76.305,"end":77.445,"text":"and to use on the job."},{"start":78.329,"end":80.989,"text":"So a high satisfaction score at level one says little"},{"start":80.989,"end":82.549,"text":"about levels three and four."},{"start":84.103,"end":86.323,"text":"Later versions of the model suggest planning in the"},{"start":86.323,"end":88.643,"text":"other direction: start from the result you need,"},{"start":88.883,"end":90.343,"text":"then the behavior, then the learning,"},{"start":90.683,"end":91.683,"text":"and the reaction last."},{"start":92.663,"end":95.603,"text":"That echoes backward design: start from the destination."},{"start":97.393,"end":98.393,"text":"A caution."},{"start":98.773,"end":101.313,"text":"Results at level four have many causes besides training,"},{"start":101.733,"end":104.353,"text":"such as new soap dispensers or staffing changes,"},{"start":105.033,"end":107.893,"text":"so a drop in infections does not prove that the training worked."},{"start":108.837,"end":111.777,"text":"Mei, her hospital, and the numbers in this video are"},{"start":111.777,"end":112.777,"text":"made up for teaching."},{"start":114.126,"end":115.126,"text":"Pause and consider."},{"start":115.386,"end":117.966,"text":"For a training you know, which level is actually measured,"},{"start":118.406,"end":120.566,"text":"and what would it take to reach the next one?"}]},"learning-objectives":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.9,"end":2.92,"text":"Many course plans begin with goals like:"},{"start":3.44,"end":5.14,"text":"students will understand first aid."},{"start":5.72,"end":7.96,"text":"It sounds clear, but no one can see understanding."},{"start":8.96,"end":11.24,"text":"A learning objective describes what learners will be"},{"start":11.24,"end":13.52,"text":"able to do, in a form that someone can observe."},{"start":15.134,"end":16.954,"text":"Robert Mager proposed three parts."},{"start":17.554,"end":19.154,"text":"Performance: what the learner does."},{"start":19.814,"end":21.274,"text":"Conditions: under what circumstances."},{"start":22.334,"end":23.535,"text":"Criterion: how well."},{"start":25.076,"end":26.956,"text":"Picture Ana, who teaches a first aid course."},{"start":26.956,"end":30.776,"text":"Understand CPR becomes: given a training manikin,"},{"start":30.776,"end":34.056,"text":"the learner gives thirty chest compressions at a rate"},{"start":34.056,"end":36.396,"text":"of one hundred to one hundred twenty per minute."},{"start":37.323,"end":38.663,"text":"The manikin is the condition,"},{"start":39.263,"end":40.703,"text":"the compressions are the performance,"},{"start":41.183,"end":42.483,"text":"and the rate is the criterion."},{"start":44.248,"end":47.288,"text":"A related format, often called ABCD,"},{"start":47.368,"end":49.168,"text":"adds the audience: who the learners are."},{"start":50.71,"end":52.73,"text":"The verb also signals the kind of thinking."},{"start":53.83,"end":56.59,"text":"Bloom's taxonomy, revised by Lorin Anderson and David"},{"start":56.59,"end":58.45,"text":"Krathwohl, lists six levels:"},{"start":59.05,"end":60.85,"text":"remember, understand, apply,"},{"start":61.29,"end":62.99,"text":"analyze, evaluate, and create."},{"start":63.928,"end":65.788,"text":"Ana's objectives can climb those levels:"},{"start":66.188,"end":68.408,"text":"list the steps, perform the compressions,"},{"start":68.828,"end":71.048,"text":"judge whether a classmate's compressions are deep enough,"},{"start":71.448,"end":73.368,"text":"and plan a response for a crowded scene."},{"start":74.981,"end":76.981,"text":"The revision also adds a second dimension:"},{"start":77.621,"end":81.941,"text":"the kind of knowledge, from facts and concepts to procedures and metacognition."},{"start":82.936,"end":84.916,"text":"Good objectives then guide the rest of the design:"},{"start":85.676,"end":87.276,"text":"the assessment checks the same performance,"},{"start":87.746,"end":89.256,"text":"and the activities practice it."},{"start":90.792,"end":91.792,"text":"A caution."},{"start":92.172,"end":93.412,"text":"Verb lists are rough guides,"},{"start":93.772,"end":96.072,"text":"since the same verb can sit at different levels."},{"start":97.092,"end":99.392,"text":"And objectives that are easy to measure can crowd out"},{"start":99.392,"end":101.232,"text":"goals that matter but are hard to observe."},{"start":102.129,"end":104.769,"text":"Ana and her course in this video are made up for teaching."},{"start":106.489,"end":107.489,"text":"Pause and consider."},{"start":107.809,"end":110.489,"text":"Take one goal from your own course that uses a word"},{"start":110.489,"end":111.849,"text":"like understand or know."},{"start":112.729,"end":114.729,"text":"What would a learner do that would show it?"}]},"task-analysis":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.9,"end":2.74,"text":"Ask an expert how they do their job,"},{"start":3.04,"end":4.54,"text":"and you often get a short answer:"},{"start":4.94,"end":6.3,"text":"that is just how it is done."},{"start":7.78,"end":10,"text":"The hard part is everything they leave out."},{"start":10.78,"end":13.12,"text":"Task analysis breaks a task into the steps,"},{"start":13.46,"end":16.34,"text":"decisions, and knowledge a learner needs to perform it."},{"start":17.7,"end":19.52,"text":"It comes early in most design models,"},{"start":19.54,"end":20.76,"text":"before objectives are written."},{"start":22.371,"end":24.271,"text":"Picture Rosa, who trains new mechanics."},{"start":25.411,"end":27.111,"text":"Changing a tire is easy to analyze."},{"start":27.931,"end":29.591,"text":"She splits the goal into subgoals:"},{"start":30.171,"end":31.671,"text":"loosen the nuts, lift the car,"},{"start":31.991,"end":34.291,"text":"swap the wheel, and tighten the nuts in a star pattern."},{"start":35.196,"end":37.076,"text":"This is hierarchical task analysis,"},{"start":37.076,"end":38.936,"text":"from John Annett and Keith Duncan."},{"start":39.996,"end":41.796,"text":"Each goal breaks into subgoals,"},{"start":41.856,"end":44.096,"text":"with a plan that says in what order they happen."},{"start":45.016,"end":48.296,"text":"Every step can be seen, so Rosa can check it by watching"},{"start":48.296,"end":49.296,"text":"someone do it."},{"start":50.558,"end":52.498,"text":"Diagnosing a strange noise is different."},{"start":52.858,"end":56.498,"text":"An expert mechanic listens for a few seconds and says: wheel bearing."},{"start":57.078,"end":59.518,"text":"Asked how, he says: you just hear it."},{"start":60.242,"end":62.222,"text":"Much expert knowledge has become automatic."},{"start":63.102,"end":65.242,"text":"Richard Clark and colleagues describe studies in which"},{"start":65.242,"end":67.642,"text":"experts left out as much as seventy percent of their"},{"start":67.642,"end":69.462,"text":"decisions when they explained their own work."},{"start":71.037,"end":73.657,"text":"Cognitive task analysis tries to recover that hidden"},{"start":73.657,"end":75.677,"text":"knowledge: the cues experts notice,"},{"start":76.117,"end":78.717,"text":"the decisions they make, and the rules of thumb behind them."},{"start":79.579,"end":82.279,"text":"One method, the critical decision method from Gary"},{"start":82.279,"end":85.919,"text":"Klein and colleagues, asks an expert to retell a real,"},{"start":85.919,"end":88.359,"text":"difficult case, then probes each decision."},{"start":89.019,"end":90.019,"text":"What did you notice?"},{"start":90.159,"end":91.159,"text":"What else could it have been?"},{"start":92.535,"end":94.335,"text":"Rosa's interviews uncover the cues."},{"start":94.895,"end":96.235,"text":"The noise rises with speed,"},{"start":96.635,"end":99.535,"text":"not with braking, and it grows louder in turns to one side."},{"start":100.423,"end":101.783,"text":"Those cues become content."},{"start":102.643,"end":105.003,"text":"New mechanics practice listening for them in recordings"},{"start":105.003,"end":106.603,"text":"before they diagnose real cars."},{"start":108.313,"end":109.313,"text":"A caution."},{"start":109.833,"end":111.433,"text":"Cognitive task analysis takes time,"},{"start":111.853,"end":113.993,"text":"and one expert's account is still incomplete,"},{"start":114.513,"end":117.373,"text":"so analysts often interview several experts and check"},{"start":117.373,"end":118.973,"text":"the result against real performance."},{"start":120.066,"end":122.726,"text":"Rosa, her mechanics, and the cases in this video are"},{"start":122.726,"end":123.726,"text":"made up for teaching."},{"start":125.041,"end":126.041,"text":"Pause and consider."},{"start":126.561,"end":127.921,"text":"Think of a task you could teach."},{"start":128.321,"end":129.681,"text":"Which of its steps can be seen,"},{"start":130.021,"end":133.041,"text":"and which decisions happen only in the expert's head?"}]},"icap":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.9,"end":3.22,"text":"Two classes watch the same video about the heart."},{"start":4.02,"end":5.58,"text":"In one, students just watch."},{"start":6.48,"end":9.3,"text":"In the other, pairs explain to each other why the heart"},{"start":9.3,"end":10.3,"text":"needs four chambers."},{"start":10.98,"end":12.06,"text":"Which class learns more?"},{"start":12.934,"end":15.834,"text":"Michelene Chi and Ruth Wylie's ICAP framework sorts"},{"start":15.834,"end":18.394,"text":"learning activities by what learners actually do:"},{"start":19.374,"end":21.774,"text":"passive, active, constructive, or interactive."},{"start":23.437,"end":26.177,"text":"Passive means receiving information without doing anything"},{"start":26.177,"end":29.197,"text":"else with it, such as watching or listening while paying attention."},{"start":30.195,"end":32.515,"text":"Active means doing something with the material itself:"},{"start":33.055,"end":34.915,"text":"pausing and rewinding, underlining,"},{"start":35.215,"end":36.215,"text":"or copying the steps."},{"start":37.275,"end":39.655,"text":"Attention is focused, but nothing new is produced."},{"start":40.704,"end":43.284,"text":"Constructive means producing something that goes beyond"},{"start":43.284,"end":45.404,"text":"what was given: explaining why,"},{"start":45.924,"end":48.224,"text":"drawing a concept map, or asking a question."},{"start":49.257,"end":51.657,"text":"Interactive means two or more learners building on"},{"start":51.657,"end":53.957,"text":"each other's ideas: one explains,"},{"start":54.337,"end":55.677,"text":"the other challenges or adds,"},{"start":56.017,"end":57.017,"text":"and the idea grows."},{"start":58.529,"end":60.149,"text":"Picture Jun, who teaches biology."},{"start":60.649,"end":62.649,"text":"The video stays the same, but the task changes."},{"start":63.646,"end":64.646,"text":"Watch it."},{"start":64.746,"end":66.166,"text":"Pause and label the four chambers."},{"start":66.846,"end":69.366,"text":"Draw how blood moves and explain why the left ventricle"},{"start":69.366,"end":70.366,"text":"has a thicker wall."},{"start":70.986,"end":73.786,"text":"Then compare drawings with a partner and fix each other's mistakes."},{"start":75.545,"end":78.185,"text":"The ICAP hypothesis predicts that learning increases"},{"start":78.185,"end":81.005,"text":"from passive to active to constructive to interactive."},{"start":81.981,"end":84.101,"text":"The reason is the thinking behind each mode:"},{"start":84.641,"end":87.001,"text":"storing information, then connecting it to what you"},{"start":87.001,"end":88.921,"text":"know, then inferring new ideas,"},{"start":89.441,"end":90.441,"text":"then inferring them together."},{"start":92.102,"end":93.102,"text":"A caution."},{"start":93.382,"end":95.702,"text":"The modes are judged from what learners actually do,"},{"start":96.042,"end":97.342,"text":"not from the task on paper."},{"start":98.342,"end":100.902,"text":"Group work in which one student explains while the"},{"start":100.902,"end":102.402,"text":"others copy is not interactive."},{"start":103.375,"end":106.195,"text":"And the ordering is a general prediction; single studies"},{"start":106.195,"end":107.855,"text":"do not always find every step."},{"start":108.73,"end":111.11,"text":"Jun and his class in this video are made up for teaching."},{"start":112.787,"end":113.787,"text":"Pause and consider."},{"start":114.187,"end":115.707,"text":"Pick one activity you use."},{"start":116.167,"end":117.787,"text":"Which mode do learners actually show,"},{"start":118.227,"end":120.807,"text":"and what small change would move it one step up?"}]},"srl":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.9,"end":4.02,"text":"Two students study for the same exam for the same number of hours."},{"start":4.82,"end":6.6,"text":"One plans, checks, and adjusts."},{"start":7.42,"end":9.7,"text":"The other rereads the notes until time runs out."},{"start":10.488,"end":12.668,"text":"Self-regulated learning describes how learners steer"},{"start":13.008,"end":14.008,"text":"their own learning."},{"start":14.948,"end":17.488,"text":"Barry Zimmerman described it as a cycle with three"},{"start":18.248,"end":20.608,"text":"phases: forethought, performance, and self-reflection."},{"start":22.294,"end":25.654,"text":"Picture Sofia, a nursing student learning to calculate drug doses."},{"start":26.554,"end":28.454,"text":"In the forethought phase, she sets a goal:"},{"start":29.034,"end":30.954,"text":"twenty problems with no errors by Friday."},{"start":31.933,"end":34.953,"text":"She plans a strategy, worked examples first and then"},{"start":34.953,"end":38.633,"text":"mixed practice, and she believes she can do it."},{"start":38.633,"end":40.333,"text":"That belief is called self-efficacy."},{"start":41.955,"end":45.135,"text":"In the performance phase, she uses the strategy and watches herself."},{"start":45.915,"end":48.615,"text":"She talks through each step and keeps a log of every error."},{"start":50.228,"end":51.148,"text":"In the self-reflection phase,"},{"start":51.148,"end":53.328,"text":"she compares her results with her goal."},{"start":54.068,"end":55.968,"text":"Most of her errors come from converting units."},{"start":57.002,"end":58.802,"text":"She explains the errors by her method,"},{"start":59.082,"end":63.462,"text":"not by a lack of ability: I skipped the unit check."},{"start":64.662,"end":66.742,"text":"So she adds a unit check to every problem."},{"start":68.401,"end":70.461,"text":"That change feeds the next round of forethought."},{"start":71.141,"end":73.941,"text":"The phases form a cycle, and each turn can improve"},{"start":73.941,"end":74.941,"text":"the next one."},{"start":75.485,"end":77.905,"text":"Reflection that blames ability tends to lower effort,"},{"start":78.345,"end":80.765,"text":"while reflection that points to strategy gives the"},{"start":80.765,"end":81.805,"text":"learner something to change."},{"start":83.49,"end":84.49,"text":"A caution."},{"start":84.97,"end":86.37,"text":"Self-regulation is not only willpower."},{"start":86.37,"end":90.01,"text":"It depends on knowing strategies, and it can be taught."},{"start":90.828,"end":93.048,"text":"And much of the research relies on questionnaires in"},{"start":93.048,"end":94.828,"text":"which learners describe their own habits,"},{"start":95.268,"end":97.368,"text":"which do not always match what they actually do."},{"start":98.256,"end":100.896,"text":"Sofia and her course in this video are made up for teaching."},{"start":102.589,"end":103.589,"text":"Pause and consider."},{"start":105.129,"end":107.189,"text":"Think of the last time you studied something hard."},{"start":107.909,"end":111.329,"text":"Which phase did you skip, and what would you change next time?"}]}};
